INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'covid-19-antigen-test'), 'Rapid test for SARS-CoV-2 antigens in a nasal or nasopharyngeal swab', 'Brzi test na antigene virusa SARS-CoV-2 u brisu nosa ili nazofarinksa', 'Брзи тест на антигене вируса SARS-CoV-2 у брису носа или назофаринкса', 'Быстрый тест на антигены вируса SARS-CoV-2 в мазке из носа или носоглотки', 'Schnelltest auf Antigene des SARS-CoV-2-Virus in einem Nasen- oder Nasenrachenabstrich', 'Burun veya nazofarenks sürüntüsünde SARS-CoV-2 virüsü antijenlerini arayan hızlı test', 'A swab is taken from the nasal passage or the nasopharynx, takes less than a minute, the result is usually ready during the same visit', 'Uzima se bris štapićem iz nosa ili nazofarinksa, traje manje od minuta, nalaz je obično gotov tokom iste posjete', 'Узима се брис штапићем из носа или назофаринкса, траје мање од минута, налаз је обично готов током исте посјете', 'Мазок тампоном из носового хода или носоглотки, занимает меньше минуты, результат обычно готов в тот же визит', 'Abstrich mit einem Tupfer aus Nase oder Nasenrachenraum, dauert weniger als eine Minute, das Ergebnis liegt meist noch beim selben Termin vor', 'Burundan veya nazofarenksten çubukla sürüntü alınır, bir dakikadan kısa sürer, sonuç genellikle aynı ziyarette hazır olur', 'Symptoms of a respiratory infection, contact with an infected person, requirements for hospital admission or travel', 'Simptomi respiratorne infekcije, kontakt sa oboljelim, zahtjevi prilikom hospitalizacije ili putovanja', 'Симптоми респираторне инфекције, контакт са обољелим, захтјеви приликом хоспитализације или путовања', 'Симптомы респираторной инфекции, контакт с заболевшим, требования при госпитализации или поездке', 'Symptome eines Atemwegsinfekts, Kontakt mit einer erkrankten Person, Vorgaben bei Krankenhausaufnahme oder Reisen', 'Solunum yolu enfeksiyonu belirtileri, hasta biriyle temas, hastaneye yatış veya seyahat koşulları', 'About 15 minutes before the swab, avoid eating, drinking, smoking and using nasal sprays or drops', 'Otprilike 15 minuta prije brisa ne jesti, ne piti, ne pušiti i ne koristiti sprejeve i kapi za nos', 'Отприлике 15 минута прије бриса не јести, не пити, не пушити и не користити спрејеве и капи за нос', 'Примерно за 15 минут до мазка не есть, не пить, не курить и не использовать спреи и капли для носа', 'Etwa 15 Minuten vor dem Abstrich nicht essen, nicht trinken, nicht rauchen und keine Nasensprays oder Nasentropfen verwenden', 'Sürüntüden yaklaşık 15 dakika önce yememek, içmemek, sigara içmemek ve burun spreyi veya damlası kullanmamak gerekir', 'A positive result may be related to a current SARS-CoV-2 infection, a negative one does not rule it out if symptoms persist. Further steps are decided by a doctor', 'Pozitivan nalaz može biti povezan sa aktuelnom infekcijom SARS-CoV-2, a negativan je ne isključuje ako tegobe traju. Dalju taktiku određuje ljekar', 'Позитиван налаз може бити повезан са актуелном инфекцијом SARS-CoV-2, а негативан је не искључује ако тегобе трају. Даљу тактику одређује љекар', 'Положительный результат может быть связан с текущей инфекцией SARS-CoV-2, отрицательный не исключает её при сохраняющихся симптомах. Дальнейшую тактику определяет врач', 'Ein positives Ergebnis kann mit einer aktuellen SARS-CoV-2-Infektion zusammenhängen, ein negatives schließt sie bei anhaltenden Beschwerden nicht aus. Das weitere Vorgehen legt der Arzt fest', 'Pozitif sonuç güncel bir SARS-CoV-2 enfeksiyonuyla ilişkili olabilir, negatif sonuç ise şikayetler sürüyorsa bunu dışlamaz. Sonraki adımları hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'torch-panel'), 'A combined blood test for antibodies to a group of infections relevant in pregnancy: toxoplasma, rubella, cytomegalovirus, herpes and others', 'Objedinjena analiza krvi na antitijela na grupu infekcija značajnih u trudnoći: toksoplazma, rubela, citomegalovirus, herpes i druge', 'Обједињена анализа крви на антитијела на групу инфекција значајних у трудноћи: токсоплазма, рубела, цитомегаловирус, херпес и друге', 'Комплекс анализов крови на антитела к группе инфекций, значимых при беременности: токсоплазма, краснуха, цитомегаловирус, герпес и другие', 'Kombinierte Blutuntersuchung auf Antikörper gegen eine Gruppe von Infektionen mit Bedeutung in der Schwangerschaft: Toxoplasma, Röteln, Zytomegalievirus, Herpes und weitere', 'Gebelikte önem taşıyan bir grup enfeksiyona karşı antikorları birlikte inceleyen kan testi: toksoplazma, kızamıkçık, sitomegalovirüs, herpes ve diğerleri', 'A single venous blood draw, several markers are determined from one sample', 'Jedno uzimanje venske krvi, iz istog uzorka se određuje više pokazatelja', 'Једно узимање венске крви, из истог узорка се одређује више показатеља', 'Однократный забор венозной крови, из одной пробы определяют сразу несколько показателей', 'Eine einzige venöse Blutentnahme, aus derselben Probe werden mehrere Werte bestimmt', 'Tek bir venöz kan alımı yapılır, aynı örnekten birden fazla gösterge çalışılır', 'Pregnancy planning, registration and follow-up during pregnancy, assessment of immune status to these infections', 'Planiranje trudnoće, prijava i praćenje trudnoće, procjena imunskog statusa na ove infekcije', 'Планирање трудноће, пријава и праћење трудноће, процјена имунског статуса на ове инфекције', 'Планирование беременности, постановка на учёт и наблюдение во время беременности, оценка иммунного статуса к этим инфекциям', 'Kinderwunsch, Erstvorstellung und Betreuung in der Schwangerschaft, Beurteilung des Immunstatus gegenüber diesen Infektionen', 'Gebelik planlaması, gebeliğin takibe alınması ve izlemi, bu enfeksiyonlara karşı bağışıklık durumunun değerlendirilmesi', 'No special preparation is usually needed, the timing is confirmed by the referring doctor', 'Posebna priprema obično nije potrebna, vrijeme uzimanja uzorka određuje ljekar koji je uputio na analizu', 'Посебна припрема обично није потребна, вријеме узимања узорка одређује љекар који је упутио на анализу', 'Специальной подготовки обычно не требуется, время сдачи уточняет направивший врач', 'In der Regel keine besondere Vorbereitung, den Zeitpunkt legt der überweisende Arzt fest', 'Genellikle özel bir hazırlık gerekmez, örnek verme zamanını yönlendiren hekim belirler', 'A combination of antibodies of different classes may point to a past infection or to recent contact with a pathogen. The doctor assesses the panel as a whole and may order a repeat or confirmatory test', 'Kombinacija antitijela različitih klasa može ukazivati na ranije preboljelu infekciju ili na skorašnji kontakt sa uzročnikom. Panel u cjelini tumači ljekar i po potrebi traži ponovljenu ili dopunsku analizu', 'Комбинација антитијела различитих класа може указивати на раније пребољелу инфекцију или на скорашњи контакт са узрочником. Панел у цјелини тумачи љекар и по потреби тражи поновљену или допунску анализу', 'Сочетание антител разных классов может говорить о перенесённой ранее инфекции или о недавнем контакте с возбудителем. Панель целиком оценивает врач и при необходимости назначает повторное или уточняющее исследование', 'Eine Kombination von Antikörpern verschiedener Klassen kann auf eine früher durchgemachte Infektion oder einen kürzlichen Kontakt mit einem Erreger hinweisen. Der Arzt beurteilt das Panel als Ganzes und veranlasst bei Bedarf eine Kontroll- oder Zusatzuntersuchung', 'Farklı sınıflardaki antikorların birlikteliği geçirilmiş bir enfeksiyona ya da etkenle yakın zamanda temasa işaret edebilir. Paneli bir bütün olarak hekim değerlendirir ve gerekirse tekrar ya da doğrulama testi ister')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'asto'), 'Blood test for antibodies to streptolysin O, a substance produced by group A beta-haemolytic streptococcus', 'Analiza krvi na antitijela na streptolizin O, materiju koju stvara beta-hemolitički streptokok grupe A', 'Анализа крви на антитијела на стрептолизин О, материју коју ствара бета-хемолитички стрептокок групе А', 'Анализ крови на антитела к стрептолизину O, веществу, которое выделяет бета-гемолитический стрептококк группы A', 'Bluttest auf Antikörper gegen Streptolysin O, einen Stoff, den beta-hämolysierende Streptokokken der Gruppe A bilden', 'A grubu beta-hemolitik streptokokun ürettiği streptolizin O maddesine karşı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Recent tonsillitis or scarlet fever, joint pain, work-up for suspected complications of a streptococcal infection, follow-up of the value over time', 'Nedavna angina ili šarlah, bolovi u zglobovima, ispitivanje kod sumnje na komplikacije streptokokne infekcije, praćenje vrijednosti u dinamici', 'Недавна ангина или шарлах, болови у зглобовима, испитивање код сумње на компликације стрептококне инфекције, праћење вриједности у динамици', 'Недавняя ангина или скарлатина, боли в суставах, обследование при подозрении на осложнения стрептококковой инфекции, контроль показателя в динамике', 'Kürzliche Mandelentzündung oder Scharlach, Gelenkschmerzen, Abklärung bei Verdacht auf Folgen einer Streptokokkeninfektion, Verlaufskontrolle des Werts', 'Yakın zamanda geçirilen bademcik iltihabı veya kızıl, eklem ağrıları, streptokok enfeksiyonu komplikasyonu şüphesinde inceleme, değerin zaman içinde izlenmesi', 'Usually taken in the morning on an empty stomach, specific requirements are confirmed by the referring doctor', 'Obično se uzima ujutru našte, konkretne uslove određuje ljekar koji je uputio na analizu', 'Обично се узима ујутру наште, конкретне услове одређује љекар који је упутио на анализу', 'Обычно сдаётся утром натощак, конкретные требования уточняет направивший врач', 'Wird meist morgens nüchtern abgenommen, konkrete Vorgaben nennt der überweisende Arzt', 'Genellikle sabah aç karnına alınır, ayrıntılı koşulları yönlendiren hekim belirtir', 'An elevated level may be related to a past streptococcal infection and stays for some time after recovery. The result is assessed by a doctor together with symptoms and other tests', 'Povišen nivo može biti povezan sa preboljelom streptokoknom infekcijom i zadržava se izvjesno vrijeme poslije oporavka. Nalaz tumači ljekar zajedno sa tegobama i drugim analizama', 'Повишен ниво може бити повезан са пребољелом стрептококном инфекцијом и задржава се извјесно вријеме послије опоравка. Налаз тумачи љекар заједно са тегобама и другим анализама', 'Повышенный уровень может быть связан с перенесённой стрептококковой инфекцией и сохраняется некоторое время после выздоровления. Результат оценивает врач вместе с жалобами и другими анализами', 'Ein erhöhter Wert kann mit einer durchgemachten Streptokokkeninfektion zusammenhängen und bleibt noch einige Zeit nach der Genesung bestehen. Der Arzt beurteilt das Ergebnis zusammen mit den Beschwerden und weiteren Werten', 'Yüksek değer geçirilmiş bir streptokok enfeksiyonuyla ilişkili olabilir ve iyileşmeden sonra bir süre daha yüksek kalır. Sonucu şikayetler ve diğer testlerle birlikte hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'cytomegalovirus-igg'), 'Blood test for IgG class antibodies to cytomegalovirus', 'Analiza krvi na antitijela klase IgG na citomegalovirus', 'Анализа крви на антитијела класе IgG на цитомегаловирус', 'Анализ крови на антитела класса IgG к цитомегаловирусу', 'Bluttest auf Antikörper der Klasse IgG gegen das Zytomegalievirus', 'Sitomegalovirüse karşı IgG sınıfı antikorları ölçen kan testi', 'Venous blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert einige Minuten', 'Damardan venöz kan alınır, birkaç dakika sürer', 'Pregnancy planning and follow-up, assessment of immune status, work-up before transplantation, prolonged fatigue or enlarged lymph nodes', 'Planiranje i praćenje trudnoće, procjena imunskog statusa, ispitivanje prije transplantacije, dugotrajan umor ili uvećani limfni čvorovi', 'Планирање и праћење трудноће, процјена имунског статуса, испитивање прије трансплантације, дуготрајан умор или увећани лимфни чворови', 'Планирование и ведение беременности, оценка иммунного статуса, обследование перед трансплантацией, длительная утомляемость или увеличение лимфоузлов', 'Kinderwunsch und Schwangerschaftsbetreuung, Beurteilung des Immunstatus, Abklärung vor einer Transplantation, anhaltende Müdigkeit oder geschwollene Lymphknoten', 'Gebelik planlaması ve takibi, bağışıklık durumunun değerlendirilmesi, nakil öncesi inceleme, uzun süren yorgunluk veya lenf bezi büyümesi', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The presence of IgG usually points to contact with the virus in the past, their absence to the fact that there was no such contact. The meaning of the result and the need for further tests are determined by a doctor', 'Prisustvo IgG obično govori o ranijem kontaktu sa virusom, a njihovo odsustvo o tome da takvog kontakta nije bilo. Značenje nalaza i potrebu za dodatnim testovima određuje ljekar', 'Присуство IgG обично говори о ранијем контакту са вирусом, а њихово одсуство о томе да таквог контакта није било. Значење налаза и потребу за додатним тестовима одређује љекар', 'Наличие IgG обычно говорит о контакте с вирусом в прошлом, их отсутствие — о том, что такого контакта не было. Значение результата и необходимость дополнительных тестов определяет врач', 'Nachweisbare IgG sprechen in der Regel für einen früheren Kontakt mit dem Virus, ihr Fehlen dafür, dass es keinen solchen Kontakt gab. Die Bedeutung des Befunds und den Bedarf an weiteren Tests legt der Arzt fest', 'IgG varlığı genellikle virüsle geçmişte temas edildiğini, yokluğu ise böyle bir temasın olmadığını gösterir. Sonucun anlamını ve ek test gerekip gerekmediğini hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'cytomegalovirus-igm'), 'Blood test for IgM class antibodies to cytomegalovirus', 'Analiza krvi na antitijela klase IgM na citomegalovirus', 'Анализа крви на антитијела класе IgM на цитомегаловирус', 'Анализ крови на антитела класса IgM к цитомегаловирусу', 'Bluttest auf Antikörper der Klasse IgM gegen das Zytomegalievirus', 'Sitomegalovirüse karşı IgM sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Fever of unclear origin, enlarged lymph nodes, pregnancy, work-up in case of weakened immunity', 'Povišena temperatura nejasnog uzroka, uvećani limfni čvorovi, trudnoća, ispitivanje kod oslabljenog imuniteta', 'Повишена температура нејасног узрока, увећани лимфни чворови, трудноћа, испитивање код ослабљеног имунитета', 'Повышение температуры неясного происхождения, увеличение лимфоузлов, беременность, обследование при ослабленном иммунитете', 'Fieber unklarer Ursache, geschwollene Lymphknoten, Schwangerschaft, Abklärung bei geschwächter Immunabwehr', 'Nedeni belirsiz ateş, lenf bezi büyümesi, gebelik, bağışıklığı zayıf kişilerde inceleme', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'IgM may appear after recent contact with the virus or during its reactivation, non-specific reactions also occur. The result is assessed by a doctor together with IgG and, if needed, an avidity test', 'IgM se mogu javiti pri skorašnjem kontaktu sa virusom ili pri njegovoj ponovnoj aktivaciji, moguće su i nespecifične reakcije. Nalaz tumači ljekar zajedno sa IgG i po potrebi uz test aviditeta', 'IgM се могу јавити при скорашњем контакту са вирусом или при његовој поновној активацији, могуће су и неспецифичне реакције. Налаз тумачи љекар заједно са IgG и по потреби уз тест авидитета', 'IgM могут появляться при недавнем контакте с вирусом или при его повторной активации, встречаются и неспецифические реакции. Результат оценивает врач вместе с IgG и при необходимости с тестом на авидность', 'IgM können bei kürzlichem Kontakt mit dem Virus oder bei dessen Reaktivierung auftreten, auch unspezifische Reaktionen kommen vor. Der Arzt beurteilt den Befund zusammen mit IgG und bei Bedarf einem Aviditätstest', 'IgM, virüsle yakın zamanda temas ya da virüsün yeniden etkinleşmesi durumunda görülebilir, özgül olmayan reaksiyonlar da olabilir. Sonucu hekim IgG ile ve gerekirse avidite testiyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'epstein-barr-igg'), 'Blood test for IgG class antibodies to the Epstein-Barr virus', 'Analiza krvi na antitijela klase IgG na Epstein-Barr virus', 'Анализа крви на антитијела класе IgG на Epstein-Barr вирус', 'Анализ крови на антитела класса IgG к вирусу Эпштейна-Барр', 'Bluttest auf Antikörper der Klasse IgG gegen das Epstein-Barr-Virus', 'Epstein-Barr virüsüne karşı IgG sınıfı antikorları ölçen kan testi', 'A single venous blood draw, the procedure takes a few minutes', 'Jedno uzimanje venske krvi, postupak traje nekoliko minuta', 'Једно узимање венске крви, поступак траје неколико минута', 'Однократный забор венозной крови, процедура занимает несколько минут', 'Eine einmalige venöse Blutentnahme, der Vorgang dauert einige Minuten', 'Tek seferlik venöz kan alımı, işlem birkaç dakika sürer', 'Prolonged fatigue, enlarged lymph nodes, follow-up after infectious mononucleosis, assessment of immune status', 'Dugotrajan umor, uvećani limfni čvorovi, kontrola poslije preboljele infektivne mononukleoze, procjena imunskog statusa', 'Дуготрајан умор, увећани лимфни чворови, контрола послије пребољеле инфективне мононуклеозе, процјена имунског статуса', 'Длительная утомляемость, увеличение лимфоузлов, обследование после перенесённого инфекционного мононуклеоза, оценка иммунного статуса', 'Anhaltende Müdigkeit, geschwollene Lymphknoten, Kontrolle nach durchgemachter infektiöser Mononukleose, Beurteilung des Immunstatus', 'Uzun süren yorgunluk, lenf bezi büyümesi, geçirilmiş enfeksiyöz mononükleoz sonrası kontrol, bağışıklık durumunun değerlendirilmesi', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The presence of IgG usually points to contact with the virus in the past, which is very common in adults. The result is interpreted by a doctor taking symptoms and other markers into account', 'Prisustvo IgG obično ukazuje na raniji kontakt sa virusom, koji je kod odraslih vrlo čest. Nalaz tumači ljekar uzimajući u obzir tegobe i druge pokazatelje', 'Присуство IgG обично указује на ранији контакт са вирусом, који је код одраслих врло чест. Налаз тумачи љекар узимајући у обзир тегобе и друге показатеље', 'Наличие IgG обычно указывает на контакт с вирусом в прошлом, у взрослых такой контакт очень распространён. Результат трактует врач с учётом жалоб и других показателей', 'Nachweisbare IgG sprechen meist für einen früheren Kontakt mit dem Virus, der bei Erwachsenen sehr häufig ist. Der Arzt deutet den Befund unter Berücksichtigung der Beschwerden und weiterer Werte', 'IgG varlığı genellikle virüsle geçmişte temas edildiğini gösterir, bu temas erişkinlerde çok yaygındır. Sonucu şikayetleri ve diğer göstergeleri dikkate alarak hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'epstein-barr-igm'), 'Blood test for IgM class antibodies to the Epstein-Barr virus', 'Analiza krvi na antitijela klase IgM na Epstein-Barr virus', 'Анализа крви на антитијела класе IgM на Epstein-Barr вирус', 'Анализ крови на антитела класса IgM к вирусу Эпштейна-Барр', 'Bluttest auf Antikörper der Klasse IgM gegen das Epstein-Barr-Virus', 'Epstein-Barr virüsüne karşı IgM sınıfı antikorları ölçen kan testi', 'Venous blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert einige Minuten', 'Damardan venöz kan alınır, birkaç dakika sürer', 'Prolonged sore throat, fever, enlarged lymph nodes and spleen, work-up for suspected infectious mononucleosis', 'Dugotrajna angina, povišena temperatura, uvećani limfni čvorovi i slezena, ispitivanje kod sumnje na infektivnu mononukleozu', 'Дуготрајна ангина, повишена температура, увећани лимфни чворови и слезена, испитивање код сумње на инфективну мононуклеозу', 'Затяжная ангина, повышение температуры, увеличение лимфоузлов и селезёнки, обследование при подозрении на инфекционный мононуклеоз', 'Langwierige Halsentzündung, Fieber, geschwollene Lymphknoten und vergrößerte Milz, Abklärung bei Verdacht auf infektiöse Mononukleose', 'Uzun süren boğaz iltihabı, ateş, lenf bezlerinin ve dalağın büyümesi, enfeksiyöz mononükleoz şüphesinde inceleme', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'IgM is more often related to recent contact with the virus or its activation, cross-reactions with other herpesviruses are possible. The final assessment is made by a doctor together with a complete blood count and IgG', 'IgM su češće povezani sa skorašnjim kontaktom sa virusom ili njegovom aktivacijom, moguće su ukrštene reakcije sa drugim herpes virusima. Konačnu ocjenu daje ljekar uz kompletnu krvnu sliku i IgG', 'IgM су чешће повезани са скорашњим контактом са вирусом или његовом активацијом, могуће су укрштене реакције са другим херпес вирусима. Коначну оцјену даје љекар уз комплетну крвну слику и IgG', 'IgM чаще связаны с недавним контактом с вирусом или его активацией, возможны перекрёстные реакции с другими герпесвирусами. Окончательную оценку даёт врач вместе с общим анализом крови и IgG', 'IgM hängen häufiger mit einem kürzlichen Kontakt mit dem Virus oder dessen Aktivierung zusammen, Kreuzreaktionen mit anderen Herpesviren sind möglich. Die abschließende Beurteilung trifft der Arzt zusammen mit dem Blutbild und den IgG-Werten', 'IgM daha çok virüsle yakın zamanda temas ya da virüsün etkinleşmesiyle ilişkilidir, diğer herpes virüsleriyle çapraz reaksiyonlar olabilir. Son değerlendirmeyi hekim tam kan sayımı ve IgG ile birlikte yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'herpes-simplex-i-igm'), 'Blood test for IgM class antibodies to herpes simplex virus type 1', 'Analiza krvi na antitijela klase IgM na virus herpes simplex tip 1', 'Анализа крви на антитијела класе IgM на вирус херпес симплеx тип 1', 'Анализ крови на антитела класса IgM к вирусу простого герпеса 1 типа', 'Bluttest auf Antikörper der Klasse IgM gegen das Herpes-simplex-Virus Typ 1', 'Herpes simplex virüsü tip 1 için IgM sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'A first episode of blisters on the lips or oral mucosa, work-up during pregnancy, work-up in case of weakened immunity', 'Prvi put nastale promjene na usnama ili sluzokoži usta, ispitivanje u trudnoći, ispitivanje kod oslabljenog imuniteta', 'Први пут настале промјене на уснама или слузокожи уста, испитивање у трудноћи, испитивање код ослабљеног имунитета', 'Впервые возникшие высыпания на губах или слизистой рта, обследование при беременности, обследование при ослабленном иммунитете', 'Erstmals aufgetretene Bläschen an Lippen oder Mundschleimhaut, Abklärung in der Schwangerschaft, Abklärung bei geschwächter Immunabwehr', 'Dudakta veya ağız içi mukozada ilk kez ortaya çıkan lezyonlar, gebelikte inceleme, bağışıklığı zayıf kişilerde inceleme', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'IgM may appear after recent contact with the virus or during its activation, cross-reactions with other herpesviruses are possible. The result is assessed by a doctor together with IgG and the physical examination', 'IgM se mogu javiti pri skorašnjem kontaktu sa virusom ili pri njegovoj aktivaciji, moguće su ukrštene reakcije sa drugim herpes virusima. Nalaz tumači ljekar uz IgG i nalaz pregleda', 'IgM се могу јавити при скорашњем контакту са вирусом или при његовој активацији, могуће су укрштене реакције са другим херпес вирусима. Налаз тумачи љекар уз IgG и налаз прегледа', 'IgM могут появляться при недавнем контакте с вирусом или при его активации, возможны перекрёстные реакции с другими герпесвирусами. Результат оценивает врач вместе с IgG и данными осмотра', 'IgM können bei kürzlichem Kontakt mit dem Virus oder bei dessen Aktivierung auftreten, Kreuzreaktionen mit anderen Herpesviren sind möglich. Der Arzt beurteilt den Befund zusammen mit IgG und der körperlichen Untersuchung', 'IgM, virüsle yakın zamanda temas ya da virüsün etkinleşmesi durumunda görülebilir, diğer herpes virüsleriyle çapraz reaksiyonlar olabilir. Sonucu hekim IgG ve muayene bulgularıyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'herpes-simplex-ii-igm'), 'Blood test for IgM class antibodies to herpes simplex virus type 2', 'Analiza krvi na antitijela klase IgM na virus herpes simplex tip 2', 'Анализа крви на антитијела класе IgM на вирус херпес симплеx тип 2', 'Анализ крови на антитела класса IgM к вирусу простого герпеса 2 типа', 'Bluttest auf Antikörper der Klasse IgM gegen das Herpes-simplex-Virus Typ 2', 'Herpes simplex virüsü tip 2 için IgM sınıfı antikorları ölçen kan testi', 'A single venous blood draw, takes a few minutes', 'Jedno uzimanje venske krvi, traje nekoliko minuta', 'Једно узимање венске крви, траје неколико минута', 'Однократный забор венозной крови, занимает несколько минут', 'Eine einmalige venöse Blutentnahme, dauert einige Minuten', 'Tek seferlik venöz kan alımı, birkaç dakika sürer', 'A first episode of lesions in the anogenital area, work-up during pregnancy planning and follow-up, work-up in case of weakened immunity', 'Prvi put nastale promjene u anogenitalnoj regiji, ispitivanje pri planiranju i praćenju trudnoće, ispitivanje kod oslabljenog imuniteta', 'Први пут настале промјене у аногениталној регији, испитивање при планирању и праћењу трудноће, испитивање код ослабљеног имунитета', 'Впервые возникшие высыпания в аногенитальной области, обследование при планировании и ведении беременности, обследование при ослабленном иммунитете', 'Erstmals aufgetretene Veränderungen im Anogenitalbereich, Abklärung bei Kinderwunsch und in der Schwangerschaft, Abklärung bei geschwächter Immunabwehr', 'Anogenital bölgede ilk kez ortaya çıkan lezyonlar, gebelik planlaması ve takibinde inceleme, bağışıklığı zayıf kişilerde inceleme', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'IgM may be related to recent contact with the virus or its activation, cross-reactions with the type 1 virus occur. The result is interpreted by a doctor together with IgG and the physical examination', 'IgM mogu biti povezani sa skorašnjim kontaktom sa virusom ili njegovom aktivacijom, javljaju se i ukrštene reakcije sa virusom tipa 1. Nalaz tumači ljekar uz IgG i nalaz pregleda', 'IgM могу бити повезани са скорашњим контактом са вирусом или његовом активацијом, јављају се и укрштене реакције са вирусом типа 1. Налаз тумачи љекар уз IgG и налаз прегледа', 'IgM могут быть связаны с недавним контактом с вирусом или его активацией, встречаются перекрёстные реакции с вирусом 1 типа. Результат интерпретирует врач вместе с IgG и данными осмотра', 'IgM können mit einem kürzlichen Kontakt mit dem Virus oder dessen Aktivierung zusammenhängen, Kreuzreaktionen mit dem Typ-1-Virus kommen vor. Der Arzt deutet den Befund zusammen mit IgG und der Untersuchung', 'IgM, virüsle yakın zamanda temas ya da virüsün etkinleşmesiyle ilişkili olabilir, tip 1 virüsle çapraz reaksiyonlar görülebilir. Sonucu hekim IgG ve muayene bulgularıyla birlikte yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'rubella-igg'), 'Blood test for IgG class antibodies to the rubella virus', 'Analiza krvi na antitijela klase IgG na virus rubele', 'Анализа крви на антитијела класе IgG на вирус рубеле', 'Анализ крови на антитела класса IgG к вирусу краснухи', 'Bluttest auf Antikörper der Klasse IgG gegen das Rötelnvirus', 'Kızamıkçık virüsüne karşı IgG sınıfı antikorları ölçen kan testi', 'Venous blood draw from a vein, the procedure takes a few minutes', 'Uzimanje venske krvi iz vene, postupak traje nekoliko minuta', 'Узимање венске крви из вене, поступак траје неколико минута', 'Забор венозной крови из вены, процедура занимает несколько минут', 'Blutentnahme aus einer Vene, der Vorgang dauert einige Minuten', 'Damardan venöz kan alınır, işlem birkaç dakika sürer', 'Pregnancy planning, registration for pregnancy care, assessment of protection after vaccination or a past infection', 'Planiranje trudnoće, prijava trudnoće, procjena zaštite poslije vakcinacije ili preboljele infekcije', 'Планирање трудноће, пријава трудноће, процјена заштите послије вакцинације или пребољеле инфекције', 'Планирование беременности, постановка на учёт по беременности, оценка защиты после вакцинации или перенесённой инфекции', 'Kinderwunsch, Anmeldung zur Schwangerschaftsvorsorge, Beurteilung des Schutzes nach Impfung oder durchgemachter Infektion', 'Gebelik planlaması, gebeliğin takibe alınması, aşı ya da geçirilmiş enfeksiyon sonrası korunmanın değerlendirilmesi', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The presence of IgG usually points to protection after vaccination or a past infection, their absence to the fact that there is no such protection. Further steps, including the question of vaccination, are decided by a doctor', 'Prisustvo IgG obično govori o zaštiti poslije vakcinacije ili preboljele infekcije, a njihovo odsustvo o tome da te zaštite nema. Dalju taktiku, uključujući pitanje vakcinacije, određuje ljekar', 'Присуство IgG обично говори о заштити послије вакцинације или пребољеле инфекције, а њихово одсуство о томе да те заштите нема. Даљу тактику, укључујући питање вакцинације, одређује љекар', 'Наличие IgG обычно говорит о защите после вакцинации или перенесённой инфекции, их отсутствие — о том, что такой защиты нет. Дальнейшую тактику, включая вопрос о вакцинации, определяет врач', 'Nachweisbare IgG sprechen meist für einen Schutz nach Impfung oder durchgemachter Infektion, ihr Fehlen dafür, dass dieser Schutz nicht besteht. Das weitere Vorgehen einschließlich der Impffrage legt der Arzt fest', 'IgG varlığı genellikle aşı veya geçirilmiş enfeksiyon sonrası korunmayı, yokluğu ise böyle bir korunmanın bulunmadığını gösterir. Aşı konusu dahil sonraki adımları hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'rubella-igm'), 'Blood test for IgM class antibodies to the rubella virus', 'Analiza krvi na antitijela klase IgM na virus rubele', 'Анализа крви на антитијела класе IgM на вирус рубеле', 'Анализ крови на антитела класса IgM к вирусу краснухи', 'Bluttest auf Antikörper der Klasse IgM gegen das Rötelnvirus', 'Kızamıkçık virüsüne karşı IgM sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Rash and fever, contact with a person ill with rubella, work-up during pregnancy', 'Osip i povišena temperatura, kontakt sa oboljelim od rubele, ispitivanje tokom trudnoće', 'Осип и повишена температура, контакт са обољелим од рубеле, испитивање током трудноће', 'Сыпь и повышение температуры, контакт с больным краснухой, обследование во время беременности', 'Hautausschlag und Fieber, Kontakt mit einer an Röteln erkrankten Person, Abklärung während der Schwangerschaft', 'Döküntü ve ateş, kızamıkçık geçiren biriyle temas, gebelik sırasında inceleme', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'IgM may appear after recent contact with the virus, non-specific reactions are also possible. The result is assessed by a doctor together with IgG and, if needed, a repeat test after some time', 'IgM se mogu javiti pri skorašnjem kontaktu sa virusom, moguće su i nespecifične reakcije. Nalaz tumači ljekar uz IgG i po potrebi uz ponovljenu analizu poslije izvjesnog vremena', 'IgM се могу јавити при скорашњем контакту са вирусом, могуће су и неспецифичне реакције. Налаз тумачи љекар уз IgG и по потреби уз поновљену анализу послије извјесног времена', 'IgM могут появляться при недавнем контакте с вирусом, возможны и неспецифические реакции. Результат оценивает врач вместе с IgG и при необходимости с повторным исследованием через некоторое время', 'IgM können bei kürzlichem Kontakt mit dem Virus auftreten, auch unspezifische Reaktionen sind möglich. Der Arzt beurteilt den Befund zusammen mit IgG und bei Bedarf einer Kontrolle nach einiger Zeit', 'IgM, virüsle yakın zamanda temas durumunda görülebilir, özgül olmayan reaksiyonlar da olabilir. Sonucu hekim IgG ile ve gerekirse bir süre sonra tekrarlanan testle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'sars-cov-2-igg-spike-protein'), 'Blood test for IgG class antibodies to the spike protein of the SARS-CoV-2 virus', 'Analiza krvi na antitijela klase IgG na spike protein virusa SARS-CoV-2', 'Анализа крви на антитијела класе IgG на spike протеин вируса SARS-CoV-2', 'Анализ крови на антитела класса IgG к шиповидному белку (spike) вируса SARS-CoV-2', 'Bluttest auf Antikörper der Klasse IgG gegen das Spike-Protein des SARS-CoV-2-Virus', 'SARS-CoV-2 virüsünün spike proteinine karşı IgG sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Assessment of the immune response after a past infection or vaccination, retrospective assessment of contact with the virus', 'Procjena imunskog odgovora poslije preboljele infekcije ili vakcinacije, naknadna procjena kontakta sa virusom', 'Процјена имунског одговора послије пребољеле инфекције или вакцинације, накнадна процјена контакта са вирусом', 'Оценка иммунного ответа после перенесённой инфекции или вакцинации, ретроспективная оценка контакта с вирусом', 'Beurteilung der Immunantwort nach durchgemachter Infektion oder Impfung, nachträgliche Einschätzung eines Viruskontakts', 'Geçirilmiş enfeksiyon veya aşı sonrası bağışıklık yanıtının değerlendirilmesi, virüsle temasın geriye dönük değerlendirilmesi', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The presence of antibodies shows that the immune system has met this protein after an infection or vaccination, while the antibody level does not equal guaranteed protection. The result is interpreted by a doctor', 'Prisustvo antitijela govori da se imuni sistem susreo sa ovim proteinom poslije infekcije ili vakcinacije, ali nivo antitijela ne znači zagarantovanu zaštitu. Nalaz tumači ljekar', 'Присуство антитијела говори да се имуни систем сусрео са овим протеином послије инфекције или вакцинације, али ниво антитијела не значи загарантовану заштиту. Налаз тумачи љекар', 'Наличие антител говорит о том, что иммунная система встречалась с этим белком после инфекции или вакцинации, при этом уровень антител не равен гарантированной защите. Результат трактует врач', 'Nachweisbare Antikörper zeigen, dass das Immunsystem diesem Protein nach einer Infektion oder Impfung begegnet ist, die Höhe der Antikörper entspricht dabei keinem garantierten Schutz. Den Befund deutet der Arzt', 'Antikor varlığı, bağışıklık sisteminin enfeksiyon ya da aşı sonrası bu proteinle karşılaştığını gösterir, antikor düzeyi ise garantili korunma anlamına gelmez. Sonucu hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'stool-parasites'), 'Examination of a stool sample for helminth eggs and protozoan cysts', 'Pregled uzorka stolice na jaja crijevnih parazita i ciste protozoa', 'Преглед узорка столице на јаја цријевних паразита и цисте протозоа', 'Исследование образца кала на яйца гельминтов и цисты простейших', 'Untersuchung einer Stuhlprobe auf Wurmeier und Zysten von Einzellern', 'Dışkı örneğinde parazit yumurtaları ve protozoon kistlerinin aranması', 'The patient collects a small stool sample in a container, in the laboratory it is examined under a microscope', 'Pacijent uzima mali uzorak stolice u kontejner, a u laboratoriji se uzorak pregleda pod mikroskopom', 'Пацијент узима мали узорак столице у контејнер, а у лабораторији се узорак прегледа под микроскопом', 'Пациент собирает небольшой образец кала в контейнер, в лаборатории его исследуют под микроскопом', 'Der Patient sammelt eine kleine Stuhlprobe in einem Behälter, im Labor wird sie unter dem Mikroskop untersucht', 'Hasta kaba küçük bir dışkı örneği alır, laboratuvarda örnek mikroskopla incelenir', 'Abdominal pain, diarrhoea, weight loss, itching, screening of children in day care or school, occupational health certificates, check-up after travel', 'Bolovi u stomaku, proliv, gubitak tjelesne težine, svrab, pregled djece u kolektivu, izdavanje sanitarne knjižice, pregled poslije putovanja', 'Болови у стомаку, пролив, губитак тјелесне тежине, свраб, преглед дјеце у колективу, издавање санитарне књижице, преглед послије путовања', 'Боли в животе, диарея, потеря веса, зуд, обследование детей в организованном коллективе, оформление санитарной книжки, обследование после поездок', 'Bauchschmerzen, Durchfall, Gewichtsverlust, Juckreiz, Untersuchung von Kindern in Gemeinschaftseinrichtungen, Gesundheitszeugnis für die Arbeit, Kontrolle nach Reisen', 'Karın ağrısı, ishal, kilo kaybı, kaşıntı, toplu ortamdaki çocukların taranması, portör muayenesi, seyahat sonrası kontrol', 'The sample is collected in a clean container without urine in it and delivered to the laboratory as soon as possible, the use of laxatives, antiparasitic and bismuth-containing medicines is agreed with the doctor in advance', 'Uzorak se uzima u čist kontejner, bez primjese urina, i dostavlja u laboratoriju što prije, a uzimanje laksativa, antiparazitnih lijekova i preparata sa bizmutom prethodno se dogovara sa ljekarom', 'Узорак се узима у чист контејнер, без примјесе урина, и доставља у лабораторију што прије, а узимање лаксатива, антипаразитних лијекова и препарата са бизмутом претходно се договара са љекаром', 'Образец собирают в чистый контейнер без примеси мочи и доставляют в лабораторию как можно быстрее, приём слабительных, противопаразитарных и висмутсодержащих препаратов заранее согласуют с врачом', 'Die Probe wird in einem sauberen Behälter ohne Urinbeimischung gesammelt und möglichst rasch ins Labor gebracht, die Einnahme von Abführmitteln, Antiparasitika und bismuthaltigen Präparaten wird vorher mit dem Arzt abgestimmt', 'Örnek temiz bir kaba, idrar karışmadan alınır ve en kısa sürede laboratuvara ulaştırılır, müshil, antiparaziter ve bizmut içeren ilaçların kullanımı önceden hekimle görüşülür', 'Finding eggs or cysts may be related to a parasitic infection, while a negative result from a single sample does not rule it out, so a doctor sometimes orders repeat testing', 'Nalaz jaja ili cisti može biti povezan sa parazitnom infekcijom, dok negativan nalaz jednog uzorka je ne isključuje, pa ljekar ponekad traži ponovljene preglede', 'Налаз јаја или цисти може бити повезан са паразитном инфекцијом, док негативан налаз једног узорка је не искључује, па љекар понекад тражи поновљене прегледе', 'Обнаружение яиц или цист может быть связано с паразитарной инфекцией, при этом отрицательный результат одного образца её не исключает, поэтому врач иногда назначает повторные исследования', 'Der Nachweis von Eiern oder Zysten kann mit einer parasitären Infektion zusammenhängen, ein negatives Ergebnis einer einzelnen Probe schließt sie dagegen nicht aus, weshalb der Arzt manchmal Wiederholungsuntersuchungen veranlasst', 'Yumurta veya kist bulunması paraziter bir enfeksiyonla ilişkili olabilir, tek örneğin negatif çıkması ise bunu dışlamaz, bu nedenle hekim bazen testin tekrarlanmasını ister')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'toxoplasma-igg'), 'Blood test for IgG class antibodies to the parasite Toxoplasma gondii', 'Analiza krvi na antitijela klase IgG na parazita Toxoplasma gondii', 'Анализа крви на антитијела класе IgG на паразита Toxoplasma gondii', 'Анализ крови на антитела класса IgG к паразиту Toxoplasma gondii', 'Bluttest auf Antikörper der Klasse IgG gegen den Parasiten Toxoplasma gondii', 'Toxoplasma gondii paraziti için IgG sınıfı antikorları ölçen kan testi', 'A single venous blood draw, takes a few minutes', 'Jedno uzimanje venske krvi, traje nekoliko minuta', 'Једно узимање венске крви, траје неколико минута', 'Однократный забор венозной крови, занимает несколько минут', 'Eine einmalige venöse Blutentnahme, dauert einige Minuten', 'Tek seferlik venöz kan alımı, birkaç dakika sürer', 'Pregnancy planning and follow-up, assessment of immune status, work-up in case of weakened immunity, enlarged lymph nodes', 'Planiranje i praćenje trudnoće, procjena imunskog statusa, ispitivanje kod oslabljenog imuniteta, uvećani limfni čvorovi', 'Планирање и праћење трудноће, процјена имунског статуса, испитивање код ослабљеног имунитета, увећани лимфни чворови', 'Планирование и ведение беременности, оценка иммунного статуса, обследование при ослабленном иммунитете, увеличение лимфоузлов', 'Kinderwunsch und Schwangerschaftsbetreuung, Beurteilung des Immunstatus, Abklärung bei geschwächter Immunabwehr, geschwollene Lymphknoten', 'Gebelik planlaması ve takibi, bağışıklık durumunun değerlendirilmesi, bağışıklığı zayıf kişilerde inceleme, lenf bezi büyümesi', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The presence of IgG usually points to contact with the parasite in the past, their absence to the fact that there was no such contact and that preventive measures matter especially during pregnancy. The result is assessed by a doctor', 'Prisustvo IgG obično govori o ranijem kontaktu sa uzročnikom, a njihovo odsustvo o tome da kontakta nije bilo i da su u trudnoći mjere prevencije posebno važne. Nalaz tumači ljekar', 'Присуство IgG обично говори о ранијем контакту са узрочником, а њихово одсуство о томе да контакта није било и да су у трудноћи мјере превенције посебно важне. Налаз тумачи љекар', 'Наличие IgG обычно говорит о контакте с возбудителем в прошлом, их отсутствие — о том, что контакта не было и во время беременности особенно важны меры профилактики. Результат оценивает врач', 'Nachweisbare IgG sprechen meist für einen früheren Kontakt mit dem Erreger, ihr Fehlen dafür, dass es keinen solchen Kontakt gab und vorbeugende Maßnahmen in der Schwangerschaft besonders wichtig sind. Den Befund beurteilt der Arzt', 'IgG varlığı genellikle etkenle geçmişte temas edildiğini, yokluğu ise böyle bir temasın olmadığını ve gebelikte korunma önlemlerinin ayrıca önem taşıdığını gösterir. Sonucu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'toxoplasma-igm'), 'Blood test for IgM class antibodies to the parasite Toxoplasma gondii', 'Analiza krvi na antitijela klase IgM na parazita Toxoplasma gondii', 'Анализа крви на антитијела класе IgM на паразита Toxoplasma gondii', 'Анализ крови на антитела класса IgM к паразиту Toxoplasma gondii', 'Bluttest auf Antikörper der Klasse IgM gegen den Parasiten Toxoplasma gondii', 'Toxoplasma gondii paraziti için IgM sınıfı antikorları ölçen kan testi', 'Venous blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert einige Minuten', 'Damardan venöz kan alınır, birkaç dakika sürer', 'Pregnancy, enlarged lymph nodes, prolonged low-grade fever, work-up in case of weakened immunity', 'Trudnoća, uvećani limfni čvorovi, dugotrajno povišena temperatura, ispitivanje kod oslabljenog imuniteta', 'Трудноћа, увећани лимфни чворови, дуготрајно повишена температура, испитивање код ослабљеног имунитета', 'Беременность, увеличение лимфоузлов, длительно повышенная температура, обследование при ослабленном иммунитете', 'Schwangerschaft, geschwollene Lymphknoten, länger anhaltend erhöhte Temperatur, Abklärung bei geschwächter Immunabwehr', 'Gebelik, lenf bezi büyümesi, uzun süren hafif ateş, bağışıklığı zayıf kişilerde inceleme', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'IgM may be related to recent contact with the parasite, but it sometimes persists for a long time and can be non-specific. To clarify this, a doctor orders IgG and an antibody avidity test', 'IgM mogu biti povezani sa skorašnjim kontaktom sa uzročnikom, ali se ponekad zadržavaju dugo i mogu biti nespecifični. Radi razjašnjenja ljekar traži IgG i test aviditeta antitijela', 'IgM могу бити повезани са скорашњим контактом са узрочником, али се понекад задржавају дуго и могу бити неспецифични. Ради разјашњења љекар тражи IgG и тест авидитета антитијела', 'IgM могут быть связаны с недавним контактом с возбудителем, но иногда сохраняются долго и бывают неспецифическими. Для уточнения врач назначает IgG и тест на авидность антител', 'IgM können mit einem kürzlichen Kontakt mit dem Erreger zusammenhängen, bleiben aber manchmal lange bestehen und können unspezifisch sein. Zur Klärung veranlasst der Arzt IgG und einen Aviditätstest der Antikörper', 'IgM etkenle yakın zamanda temasla ilişkili olabilir, ancak bazen uzun süre kalır ve özgül olmayabilir. Durumu netleştirmek için hekim IgG ve antikor avidite testi ister')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'vdrl'), 'A non-treponemal blood screening test used in the work-up for syphilis', 'Netreponemski skrining test krvi koji se koristi pri ispitivanju na sifilis', 'Нетрепонемски скрининг тест крви који се користи при испитивању на сифилис', 'Нетрепонемный скрининговый тест крови, который применяют при обследовании на сифилис', 'Nicht-treponemaler Bluttest, der als Screening bei der Abklärung auf Syphilis eingesetzt wird', 'Sifiliz araştırmasında tarama amacıyla kullanılan, treponemal olmayan kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Preventive screening, preparation for surgery or blood donation, pregnancy, at personal request', 'Pregled prije operacije, u trudnoći i kod davanja krvi, kontrola nakon liječenja koje je odredio ljekar, dopuna nalaza treponemskog testa', 'Преглед прије операције, у трудноћи и код давања крви, контрола након лијечења које је одредио љекар, допуна налаза трепонемског теста', 'Обследование перед операцией, беременностью и донорством крови, контроль после назначенного врачом лечения, уточнение результата трепонемного теста', 'Vorsorgliches Screening, Vorbereitung auf eine Operation oder Blutspende, Schwangerschaft, auf eigenen Wunsch', 'Koruyucu tarama, ameliyat veya kan bağışı öncesi hazırlık, gebelik, kişisel istek', 'No special preparation is required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'A positive result requires a confirmatory treponemal test and a doctor''s consultation, since false-positive reactions are possible in a number of other conditions', 'Pozitivan nalaz zahtijeva potvrdni treponemski test i konsultaciju sa ljekarom, jer su kod niza drugih stanja moguće lažno pozitivne reakcije', 'Позитиван налаз захтијева потврдни трепонемски тест и консултацију са љекаром, јер су код низа других стања могуће лажно позитивне реакције', 'Положительный результат требует подтверждающего трепонемного теста и консультации врача, так как при ряде других состояний возможны ложноположительные реакции', 'Ein positives Ergebnis erfordert einen bestätigenden treponemalen Test und eine ärztliche Beratung, da bei einer Reihe anderer Zustände falsch positive Reaktionen möglich sind', 'Pozitif sonuç doğrulayıcı treponemal test ve hekim değerlendirmesi gerektirir, çünkü başka birçok durumda yalancı pozitif reaksiyonlar görülebilir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'adenovirus-rotavirus-in-stool'), 'Rapid test of a stool sample for rotavirus and adenovirus antigens', 'Brzi test uzorka stolice na antigene rotavirusa i adenovirusa', 'Брзи тест узорка столице на антигене ротавируса и аденовируса', 'Экспресс-тест образца кала на антигены ротавируса и аденовируса', 'Schnelltest einer Stuhlprobe auf Rotavirus- und Adenovirus-Antigene', 'Dışkı örneğinde rotavirüs ve adenovirüs antijenlerini arayan hızlı test', 'A small stool sample is collected in a container and examined in the laboratory by a rapid immunochromatographic method', 'Mali uzorak stolice uzima se u kontejner, a u laboratoriji se ispituje brzom imunohromatografskom metodom', 'Мали узорак столице узима се у контејнер, а у лабораторији се испитује брзом имунохроматографском методом', 'Небольшой образец кала собирают в контейнер, в лаборатории его исследуют быстрым иммунохроматографическим методом', 'Eine kleine Stuhlprobe wird in einem Behälter gesammelt und im Labor mit einem schnellen immunchromatographischen Verfahren untersucht', 'Kaba küçük bir dışkı örneği alınır, laboratuvarda hızlı immünokromatografik yöntemle incelenir', 'Acute diarrhoea and vomiting, especially in children, cases of intestinal infection in the family or a children''s group, work-up on hospital admission', 'Akutni proliv i povraćanje, naročito kod djece, slučajevi crijevne infekcije u porodici ili dječjem kolektivu, ispitivanje pri prijemu u bolnicu', 'Акутни пролив и повраћање, нарочито код дјеце, случајеви цријевне инфекције у породици или дјечјем колективу, испитивање при пријему у болницу', 'Острая диарея и рвота, особенно у детей, случаи кишечной инфекции в семье или детском коллективе, обследование при госпитализации', 'Akuter Durchfall und Erbrechen, besonders bei Kindern, Fälle von Darminfektionen in der Familie oder in einer Kindergruppe, Abklärung bei Krankenhausaufnahme', 'Özellikle çocuklarda akut ishal ve kusma, ailede veya çocuk topluluğunda bağırsak enfeksiyonu vakaları, hastaneye yatışta inceleme', 'The sample is collected in a clean container without urine in it and delivered to the laboratory the same day, no special diet is needed', 'Uzorak se uzima u čist kontejner, bez primjese urina, i dostavlja u laboratoriju istog dana, posebna dijeta nije potrebna', 'Узорак се узима у чист контејнер, без примјесе урина, и доставља у лабораторију истог дана, посебна дијета није потребна', 'Образец собирают в чистый контейнер без примеси мочи и доставляют в лабораторию в тот же день, специальной диеты не требуется', 'Die Probe wird in einem sauberen Behälter ohne Urinbeimischung gesammelt und am selben Tag ins Labor gebracht, eine besondere Diät ist nicht nötig', 'Örnek temiz bir kaba, idrar karışmadan alınır ve aynı gün laboratuvara ulaştırılır, özel bir diyet gerekmez', 'A positive result may be related to a viral intestinal infection, a negative one does not rule out other causes of diarrhoea. Treatment and follow-up are decided by a doctor', 'Pozitivan nalaz može biti povezan sa virusnom crijevnom infekcijom, a negativan ne isključuje druge uzroke proliva. Liječenje i praćenje određuje ljekar', 'Позитиван налаз може бити повезан са вирусном цријевном инфекцијом, а негативан не искључује друге узроке пролива. Лијечење и праћење одређује љекар', 'Положительный результат может быть связан с вирусной кишечной инфекцией, отрицательный не исключает других причин диареи. Лечение и наблюдение определяет врач', 'Ein positives Ergebnis kann mit einer viralen Darminfektion zusammenhängen, ein negatives schließt andere Ursachen des Durchfalls nicht aus. Behandlung und weitere Kontrolle legt der Arzt fest', 'Pozitif sonuç viral bir bağırsak enfeksiyonuyla ilişkili olabilir, negatif sonuç ise ishalin diğer nedenlerini dışlamaz. Tedaviyi ve izlemi hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'helicobacter-pylori-iga'), 'Blood test for IgA class antibodies against the bacterium Helicobacter pylori', 'Analiza krvi na antitijela klase IgA na bakteriju Helicobacter pylori', 'Анализа крви на антитијела класе IgA на бактерију Helicobacter pylori', 'Анализ крови на антитела класса IgA к бактерии Helicobacter pylori', 'Bluttest auf Antikörper der Klasse IgA gegen das Bakterium Helicobacter pylori', 'Helicobacter pylori bakterisine karşı IgA sınıfı antikorlar için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Stomach pain and heaviness, heartburn, evaluation for gastritis or peptic ulcer, addition to other Helicobacter pylori tests', 'Bolovi i težina u stomaku, žgaravica, pregled kod gastritisa ili čira, dopuna drugim testovima na Helicobacter pylori', 'Болови и тежина у стомаку, жгаравица, преглед код гастритиса или чира, допуна другим тестовима на Helicobacter pylori', 'Боли и тяжесть в желудке, изжога, обследование при гастрите или язвенной болезни, дополнение к другим тестам на Helicobacter pylori', 'Magenschmerzen und Völlegefühl, Sodbrennen, Abklärung bei Gastritis oder Magengeschwür, Ergänzung zu anderen Helicobacter-pylori-Tests', 'Mide ağrısı ve dolgunluk, mide ekşimesi, gastrit veya ülser değerlendirmesi, diğer Helicobacter pylori testlerine ek olarak', 'Usually no special preparation is required, blood is most often taken in the morning on an empty stomach', 'Obično nije potrebna posebna priprema, krv se najčešće uzima ujutru našte', 'Обично није потребна посебна припрема, крв се најчешће узима ујутру наште', 'Обычно специальной подготовки не требуется, кровь чаще сдают утром натощак', 'In der Regel ist keine besondere Vorbereitung nötig, das Blut wird meist morgens nüchtern entnommen', 'Genellikle özel bir hazırlık gerekmez, kan çoğunlukla sabah aç karnına alınır', 'The presence of antibodies may be related to current or past contact with the bacterium and on its own does not show how active the infection is. The result is assessed by a doctor together with other tests', 'Prisustvo antitijela može biti povezano sa sadašnjim ili ranijim kontaktom sa bakterijom i samo po sebi ne pokazuje koliko je infekcija aktivna. Rezultat procjenjuje ljekar zajedno sa drugim testovima', 'Присуство антитијела може бити повезано са садашњим или ранијим контактом са бактеријом и само по себи не показује колико је инфекција активна. Резултат процјењује љекар заједно са другим тестовима', 'Наличие антител может быть связано с нынешним или перенесённым ранее контактом с бактерией и само по себе не показывает, насколько активна инфекция. Результат оценивает врач вместе с другими тестами', 'Nachweisbare Antikörper können mit einem aktuellen oder früheren Kontakt mit dem Bakterium zusammenhängen und zeigen für sich allein nicht, wie aktiv die Infektion ist. Der Arzt beurteilt das Ergebnis zusammen mit weiteren Tests', 'Antikorların saptanması bakteriyle şimdiki veya geçmişteki temasla ilişkili olabilir ve tek başına enfeksiyonun ne kadar aktif olduğunu göstermez. Sonucu hekim diğer testlerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'perianal-impression'), 'Microscopic examination of a skin impression from around the anus for pinworm eggs', 'Mikroskopski pregled otiska kože oko čmara na jaja dječjih glista (oksiura)', 'Микроскопски преглед отиска коже око чмара на јаја дјечјих глиста (оксиура)', 'Микроскопическое исследование отпечатка кожи вокруг заднего прохода на яйца остриц', 'Mikroskopische Untersuchung eines Hautabklatschs aus der Analregion auf Madenwurmeier', 'Anüs çevresindeki deriden alınan örneğin kıl kurdu yumurtaları açısından mikroskopla incelenmesi', 'In the morning, before washing, adhesive tape or a special spatula is pressed to the perianal skin, the sample is transferred to a slide and examined under a microscope', 'Ujutru, prije pranja, na kožu oko čmara se prislanja ljepljiva traka ili posebna špatula, uzorak se prenosi na pločicu i pregleda pod mikroskopom', 'Ујутру, прије прања, на кожу око чмара се прислања љепљива трака или посебна шпатула, узорак се преноси на плочицу и прегледа под микроскопом', 'Утром до подмывания к перианальной коже прикладывают липкую ленту или специальный шпатель, образец переносят на стекло и смотрят под микроскопом', 'Morgens vor dem Waschen wird ein Klebestreifen oder ein spezieller Spatel auf die Haut um den After gedrückt, die Probe wird auf einen Objektträger übertragen und mikroskopiert', 'Sabah yıkanmadan önce anüs çevresindeki deriye yapışkan bant veya özel bir spatula bastırılır, örnek lama aktarılıp mikroskopta incelenir', 'Itching around the anus, especially at night, restless sleep in children, screening in children''s groups, follow-up after treatment', 'Svrab oko čmara, naročito noću, nemiran san kod djece, pregled u dječjim kolektivima, kontrola poslije liječenja', 'Свраб око чмара, нарочито ноћу, немиран сан код дјеце, преглед у дјечјим колективима, контрола послије лијечења', 'Зуд в области заднего прохода, особенно ночной, беспокойный сон у детей, обследование в детских коллективах, контроль после лечения', 'Juckreiz um den After, besonders nachts, unruhiger Schlaf bei Kindern, Untersuchung in Kindereinrichtungen, Kontrolle nach der Behandlung', 'Özellikle geceleri anüs çevresinde kaşıntı, çocuklarda huzursuz uyku, çocuk topluluklarında tarama, tedavi sonrası kontrol', 'The sample is taken in the morning right after waking up, before using the toilet or washing; the evening before, do not apply ointments or powders to this area', 'Uzorak se uzima ujutru odmah po buđenju, prije odlaska u toalet i pranja; prethodno veče na to područje ne stavljati masti ni puder', 'Узорак се узима ујутру одмах по буђењу, прије одласка у тоалет и прања; претходно вече на то подручје не стављати масти ни пудер', 'Материал берут утром сразу после пробуждения, до туалета и подмывания; накануне вечером не наносить на эту область мази и присыпки', 'Die Probe wird morgens unmittelbar nach dem Aufwachen genommen, vor dem Toilettengang und dem Waschen; am Vorabend in diesem Bereich keine Salben oder Puder anwenden', 'Örnek sabah uyanır uyanmaz, tuvalete gitmeden ve yıkanmadan önce alınır; bir önceki akşam bu bölgeye merhem veya pudra sürülmemelidir', 'Finding eggs may be related to enterobiasis, while a negative result does not rule it out and often needs to be repeated on other days. Further steps are decided by a doctor', 'Nalaz jaja može biti povezan sa enterobiozom, dok negativan nalaz ne isključuje infekciju i često se ponavlja drugih dana. Dalje korake određuje ljekar', 'Налаз јаја може бити повезан са ентеробиозом, док негативан налаз не искључује инфекцију и често се понавља других дана. Даље кораке одређује љекар', 'Обнаружение яиц может быть связано с энтеробиозом, при этом отрицательный результат его не исключает и часто требует повтора в другие дни. Дальнейшие шаги определяет врач', 'Der Nachweis von Eiern kann mit einem Madenwurmbefall zusammenhängen, ein negatives Ergebnis schließt ihn nicht aus und wird oft an weiteren Tagen wiederholt. Das weitere Vorgehen bestimmt der Arzt', 'Yumurta saptanması kıl kurdu enfestasyonuyla ilişkili olabilir, negatif sonuç ise bunu dışlamaz ve sıklıkla başka günlerde tekrarlanması gerekir. Sonraki adımları hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'adenovirus-igg'), 'Blood test for IgG class antibodies against adenovirus', 'Analiza krvi na antitijela klase IgG na adenovirus', 'Анализа крви на антитијела класе IgG на аденовирус', 'Анализ крови на антитела класса IgG к аденовирусу', 'Bluttest auf Antikörper der Klasse IgG gegen Adenoviren', 'Adenovirüse karşı IgG sınıfı antikorlar için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert wenige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Assessing past contact with adenovirus, prolonged respiratory or eye symptoms, clarifying the cause of an illness together with other tests', 'Procjena ranijeg kontakta sa adenovirusom, dugotrajni respiratorni ili očni simptomi, razjašnjavanje uzroka oboljenja zajedno sa drugim testovima', 'Процјена ранијег контакта са аденовирусом, дуготрајни респираторни или очни симптоми, разјашњавање узрока обољења заједно са другим тестовима', 'Оценка перенесённого ранее контакта с аденовирусом, затяжные респираторные или глазные симптомы, уточнение причины заболевания вместе с другими тестами', 'Beurteilung eines früheren Kontakts mit Adenoviren, anhaltende Atemwegs- oder Augensymptome, Abklärung der Krankheitsursache zusammen mit anderen Tests', 'Virüsle geçmişteki temasın değerlendirilmesi, uzayan solunum yolu veya göz belirtileri, hastalık nedeninin diğer testlerle birlikte araştırılması', 'No special preparation required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The presence of IgG usually reflects contact with the virus in the past, and a single sample does not show when the infection occurred. A doctor interprets the result, if needed together with a repeat test', 'Prisustvo IgG obično odražava raniji kontakt sa virusom, a iz jednog uzorka se ne može zaključiti kada je do infekcije došlo. Rezultat tumači ljekar, po potrebi uz ponovljenu analizu', 'Присуство IgG обично одражава ранији контакт са вирусом, а из једног узорка се не може закључити када је до инфекције дошло. Резултат тумачи љекар, по потреби уз поновљену анализу', 'Наличие IgG обычно отражает контакт с вирусом в прошлом, а по одному образцу нельзя судить о давности заражения. Результат интерпретирует врач, при необходимости в паре с повторным анализом', 'Nachweisbare IgG sprechen meist für einen früheren Kontakt mit dem Virus, aus einer einzelnen Probe lässt sich der Zeitpunkt der Ansteckung nicht ableiten. Der Arzt interpretiert das Ergebnis, bei Bedarf zusammen mit einer Verlaufskontrolle', 'IgG varlığı genellikle virüsle geçmişteki teması yansıtır, tek bir örnekten enfeksiyonun ne zaman geçirildiği anlaşılamaz. Sonucu hekim, gerekirse tekrar testle birlikte yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'coxsackie-b-igg'), 'Blood test for IgG class antibodies against group B Coxsackie viruses', 'Analiza krvi na antitijela klase IgG na Koksaki viruse grupe B', 'Анализа крви на антитијела класе IgG на Коксаки вирусе групе Б', 'Анализ крови на антитела класса IgG к вирусам Коксаки группы B', 'Bluttest auf Antikörper der Klasse IgG gegen Coxsackie-B-Viren', 'Coxsackie B grubu virüslerine karşı IgG sınıfı antikorlar için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert wenige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Assessing past contact with the virus, prolonged fever of unclear origin, muscle and chest pain, previous inflammation of the heart muscle', 'Procjena ranijeg kontakta sa virusom, dugotrajna povišena temperatura nejasnog uzroka, bolovi u mišićima i grudnom košu, ranije preboljelo zapaljenje srčanog mišića', 'Процјена ранијег контакта са вирусом, дуготрајна повишена температура нејасног узрока, болови у мишићима и грудном кошу, раније пребољело запаљење срчаног мишића', 'Оценка перенесённого ранее контакта с вирусом, длительная лихорадка неясного происхождения, боли в мышцах и грудной клетке, перенесённое воспаление сердечной мышцы', 'Beurteilung eines früheren Kontakts mit dem Virus, länger bestehendes Fieber unklarer Ursache, Muskel- und Brustschmerzen, durchgemachte Herzmuskelentzündung', 'Virüsle geçmişteki temasın değerlendirilmesi, nedeni belirsiz uzun süreli ateş, kas ve göğüs ağrısı, geçirilmiş kalp kası iltihabı', 'No special preparation required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'IgG reflect contact with the virus in the past and on their own do not indicate a current illness. The assessment is made by a doctor taking symptoms and other tests into account', 'IgG odražavaju raniji kontakt sa virusom i sami po sebi ne ukazuju na aktuelno oboljenje. Procjenu vrši ljekar uz uvid u simptome i druge analize', 'IgG одражавају ранији контакт са вирусом и сами по себи не указују на актуелно обољење. Процјену врши љекар уз увид у симптоме и друге анализе', 'IgG отражают контакт с вирусом в прошлом и сами по себе не указывают на текущее заболевание. Оценку проводит врач с учётом симптомов и других анализов', 'IgG spiegeln einen früheren Kontakt mit dem Virus wider und weisen für sich genommen nicht auf eine aktuelle Erkrankung hin. Die Beurteilung erfolgt durch den Arzt unter Berücksichtigung von Beschwerden und weiteren Untersuchungen', 'IgG geçmişteki teması yansıtır ve tek başına güncel bir hastalığı göstermez. Değerlendirmeyi, belirtileri ve diğer testleri dikkate alarak hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'coxsackie-b-igm'), 'Blood test for IgM class antibodies against group B Coxsackie viruses, which appear early after infection', 'Analiza krvi na antitijela klase IgM na Koksaki viruse grupe B, koja se javljaju rano poslije infekcije', 'Анализа крви на антитијела класе IgM на Коксаки вирусе групе Б, која се јављају рано послије инфекције', 'Анализ крови на антитела класса IgM к вирусам Коксаки группы B, которые появляются в ранние сроки после заражения', 'Bluttest auf Antikörper der Klasse IgM gegen Coxsackie-B-Viren, die früh nach einer Ansteckung auftreten', 'Coxsackie B grubu virüslerine karşı, enfeksiyondan sonra erken dönemde ortaya çıkan IgM sınıfı antikorlar için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert wenige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Recent fever of unclear cause, rash on the hands and feet, muscle and chest pain, suspected recent enterovirus infection', 'Nedavna povišena temperatura nejasnog uzroka, osip na šakama i stopalima, bolovi u mišićima i grudnom košu, sumnja na skorašnju enterovirusnu infekciju', 'Недавна повишена температура нејасног узрока, осип на шакама и стопалима, болови у мишићима и грудном кошу, сумња на скорашњу ентеровирусну инфекцију', 'Недавняя лихорадка неясной причины, сыпь на кистях и стопах, боли в мышцах и грудной клетке, подозрение на недавнюю энтеровирусную инфекцию', 'Kürzlich aufgetretenes Fieber unklarer Ursache, Ausschlag an Händen und Füßen, Muskel- und Brustschmerzen, Verdacht auf eine kürzliche Enterovirus-Infektion', 'Yakın zamanda başlayan nedeni belirsiz ateş, el ve ayaklarda döküntü, kas ve göğüs ağrısı, yakın zamanlı enterovirüs enfeksiyonu şüphesi', 'No special preparation required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'IgM may be related to recent contact with the virus, and cross-reactions with other enteroviruses also occur. The result is assessed by a doctor together with symptoms and other tests', 'IgM mogu biti povezana sa skorašnjim kontaktom sa virusom, a javljaju se i unakrsne reakcije sa drugim enterovirusima. Rezultat procjenjuje ljekar uz simptome i druge analize', 'IgM могу бити повезана са скорашњим контактом са вирусом, а јављају се и унакрсне реакције са другим ентеровирусима. Резултат процјењује љекар уз симптоме и друге анализе', 'IgM могут быть связаны с недавним контактом с вирусом, при этом встречаются и перекрёстные реакции с другими энтеровирусами. Результат оценивает врач вместе с симптомами и другими анализами', 'IgM können mit einem kürzlichen Kontakt mit dem Virus zusammenhängen, auch Kreuzreaktionen mit anderen Enteroviren kommen vor. Der Arzt beurteilt das Ergebnis zusammen mit den Beschwerden und weiteren Untersuchungen', 'IgM, virüsle yakın zamanda temasla ilişkili olabilir, ayrıca diğer enterovirüslerle çapraz reaksiyonlar da görülür. Sonucu hekim belirtiler ve diğer testlerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'adenovirus-igm'), 'Blood test for IgM class antibodies against adenovirus, which appear early after infection', 'Analiza krvi na antitijela klase IgM na adenovirus, koja se javljaju rano poslije infekcije', 'Анализа крви на антитијела класе IgM на аденовирус, која се јављају рано послије инфекције', 'Анализ крови на антитела класса IgM к аденовирусу, которые появляются в ранние сроки после заражения', 'Bluttest auf Antikörper der Klasse IgM gegen Adenoviren, die früh nach einer Ansteckung auftreten', 'Adenovirüse karşı, enfeksiyondan sonra erken dönemde ortaya çıkan IgM sınıfı antikorlar için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert wenige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Recent respiratory illness with high fever, conjunctivitis, intestinal symptoms in children, clarifying the cause of an acute infection', 'Skorašnje respiratorno oboljenje sa visokom temperaturom, konjunktivitis, crijevni simptomi kod djece, razjašnjavanje uzroka akutne infekcije', 'Скорашње респираторно обољење са високом температуром, коњунктивитис, цријевни симптоми код дјеце, разјашњавање узрока акутне инфекције', 'Недавнее респираторное заболевание с высокой температурой, конъюнктивит, кишечные симптомы у детей, уточнение причины острой инфекции', 'Kürzliche Atemwegserkrankung mit hohem Fieber, Bindehautentzündung, Darmbeschwerden bei Kindern, Abklärung der Ursache einer akuten Infektion', 'Yakın zamanda yüksek ateşle seyreden solunum yolu hastalığı, konjonktivit, çocuklarda bağırsak belirtileri, akut enfeksiyonun nedeninin araştırılması', 'No special preparation required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'IgM may be related to a recent infection, and in the first days of illness they may not yet be detectable. The result is assessed by a doctor together with the clinical picture', 'IgM mogu biti povezana sa skorašnjom infekcijom, a u prvim danima bolesti još ne moraju biti mjerljiva. Rezultat procjenjuje ljekar uz kliničku sliku', 'IgM могу бити повезана са скорашњом инфекцијом, а у првим данима болести још не морају бити мјерљива. Резултат процјењује љекар уз клиничку слику', 'IgM могут быть связаны с недавней инфекцией, а в первые дни болезни они ещё могут не определяться. Результат оценивает врач вместе с клинической картиной', 'IgM können mit einer kürzlichen Infektion zusammenhängen, in den ersten Krankheitstagen sind sie mitunter noch nicht nachweisbar. Der Arzt beurteilt das Ergebnis zusammen mit dem klinischen Bild', 'IgM yakın zamanlı bir enfeksiyonla ilişkili olabilir, hastalığın ilk günlerinde henüz saptanamayabilir. Sonucu hekim klinik tabloyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'borrelia-burgdorferi-igg'), 'Blood test for IgG class antibodies against Borrelia, the bacteria that cause tick-borne Lyme borreliosis', 'Analiza krvi na antitijela klase IgG na borelije, uzročnike lajmske bolesti koju prenose krpelji', 'Анализа крви на антитијела класе IgG на борелије, узрочнике лајмске болести коју преносе крпељи', 'Анализ крови на антитела класса IgG к боррелиям, возбудителям клещевого боррелиоза (болезни Лайма)', 'Bluttest auf Antikörper der Klasse IgG gegen Borrelien, die Erreger der von Zecken übertragenen Lyme-Borreliose', 'Kene ile bulaşan Lyme hastalığının etkeni Borrelia bakterilerine karşı IgG sınıfı antikorlar için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'A tick bite in the past, long-lasting joint pain, skin and neurological complaints after time spent in natural tick habitats', 'Raniji ubod krpelja, dugotrajni bolovi u zglobovima, kožne i neurološke tegobe poslije boravka u prirodi', 'Ранији убод крпеља, дуготрајни болови у зглобовима, кожне и неуролошке тегобе послије боравка у природи', 'Укус клеща в прошлом, длительные боли в суставах, кожные и неврологические жалобы после пребывания в природных очагах', 'Zeckenstich in der Vorgeschichte, lang anhaltende Gelenkschmerzen, Haut- und Nervenbeschwerden nach Aufenthalt in der Natur', 'Geçmişte kene ısırığı, uzun süren eklem ağrıları, doğada bulunduktan sonra ortaya çıkan deri ve sinir sistemi şikayetleri', 'No special preparation required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The presence of IgG may reflect either a current or a long-past infection and by accepted practice requires a confirmatory test. The result is assessed by a doctor together with symptoms and the history of the bite', 'Prisustvo IgG može odražavati i aktuelnu i davno preboljelu infekciju i po ustaljenoj praksi traži potvrdni test. Rezultat procjenjuje ljekar uz simptome i podatak o ubodu krpelja', 'Присуство IgG може одражавати и актуелну и давно пребољелу инфекцију и по устаљеној пракси тражи потврдни тест. Резултат процјењује љекар уз симптоме и податак о убоду крпеља', 'Наличие IgG может отражать как текущую, так и давно перенесённую инфекцию и по принятой практике требует подтверждающего теста. Результат оценивает врач вместе с симптомами и историей укуса', 'Nachweisbare IgG können sowohl eine aktuelle als auch eine lange zurückliegende Infektion widerspiegeln und erfordern nach üblicher Praxis einen Bestätigungstest. Der Arzt beurteilt das Ergebnis zusammen mit den Beschwerden und dem Zeckenstich in der Vorgeschichte', 'IgG varlığı hem güncel hem de uzun süre önce geçirilmiş bir enfeksiyonu yansıtabilir ve yerleşik uygulamada doğrulayıcı test gerektirir. Sonucu hekim belirtiler ve kene ısırığı öyküsüyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'borrelia-burgdorferi-igm'), 'Blood test for IgM class antibodies against Borrelia, which appear in the first weeks after infection', 'Analiza krvi na antitijela klase IgM na borelije, koja se javljaju u prvim sedmicama poslije infekcije', 'Анализа крви на антитијела класе IgM на борелије, која се јављају у првим седмицама послије инфекције', 'Анализ крови на антитела класса IgM к боррелиям, которые появляются в первые недели после заражения', 'Bluttest auf Antikörper der Klasse IgM gegen Borrelien, die in den ersten Wochen nach einer Ansteckung auftreten', 'Borrelia bakterilerine karşı, enfeksiyondan sonraki ilk haftalarda ortaya çıkan IgM sınıfı antikorlar için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'A recent tick bite, expanding redness around the bite site, fever and malaise after time spent in the forest', 'Skorašnji ubod krpelja, crvenilo koje se širi oko mjesta uboda, povišena temperatura i malaksalost poslije boravka u šumi', 'Скорашњи убод крпеља, црвенило које се шири око мјеста убода, повишена температура и малаксалост послије боравка у шуми', 'Недавний укус клеща, расширяющееся покраснение вокруг места укуса, температура и недомогание после пребывания в лесу', 'Kürzlicher Zeckenstich, sich ausbreitende Rötung um die Stichstelle, Fieber und Abgeschlagenheit nach einem Waldaufenthalt', 'Yakın zamanda kene ısırığı, ısırık yerinin çevresinde genişleyen kızarıklık, ormanda bulunduktan sonra ateş ve halsizlik', 'No special preparation required; in the first weeks after a bite antibodies may not yet be detectable, so the timing of the test is decided by a doctor', 'Nije potrebna posebna priprema; u prvim sedmicama poslije uboda antitijela još ne moraju biti mjerljiva, pa vrijeme vađenja krvi određuje ljekar', 'Није потребна посебна припрема; у првим седмицама послије убода антитијела још не морају бити мјерљива, па вријеме вађења крви одређује љекар', 'Специальной подготовки не требуется; в первые недели после укуса антитела могут ещё не определяться, поэтому срок сдачи уточняет врач', 'Keine besondere Vorbereitung erforderlich; in den ersten Wochen nach dem Stich sind Antikörper mitunter noch nicht nachweisbar, den Zeitpunkt der Blutentnahme legt der Arzt fest', 'Özel bir hazırlık gerekmez; ısırıktan sonraki ilk haftalarda antikorlar henüz saptanamayabilir, bu nedenle kan alma zamanını hekim belirler', 'IgM may be related to a recent infection but also produce false positive reactions, so a confirmatory test is needed. The result is interpreted by a doctor', 'IgM mogu biti povezana sa skorašnjom infekcijom, ali daju i lažno pozitivne reakcije, pa je potreban potvrdni test. Rezultat tumači ljekar', 'IgM могу бити повезана са скорашњом инфекцијом, али дају и лажно позитивне реакције, па је потребан потврдни тест. Резултат тумачи љекар', 'IgM могут быть связаны с недавним заражением, но дают и ложноположительные реакции, поэтому нужен подтверждающий тест. Результат интерпретирует врач', 'IgM können mit einer kürzlichen Ansteckung zusammenhängen, liefern aber auch falsch positive Reaktionen, weshalb ein Bestätigungstest nötig ist. Die Interpretation erfolgt durch den Arzt', 'IgM yakın zamanlı bir enfeksiyonla ilişkili olabilir, ancak yalancı pozitif sonuç da verebildiğinden doğrulayıcı test gerekir. Sonucu hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'demodex-species'), 'Microscopic examination of material from the skin or eyelashes for Demodex mites', 'Mikroskopski pregled materijala sa kože ili trepavica na grinje roda Demodex', 'Микроскопски преглед материјала са коже или трепавица на гриње рода Demodex', 'Микроскопическое исследование материала с кожи или ресниц на клещей рода Demodex', 'Mikroskopische Untersuchung von Material aus der Haut oder von Wimpern auf Demodex-Milben', 'Deriden veya kirpiklerden alınan örneğin Demodex akarları açısından mikroskopla incelenmesi', 'A scraping is taken from the facial skin or several eyelashes are removed, the material is placed on a slide and examined under a microscope', 'Sa kože lica se uzima struganje ili se uklanja nekoliko trepavica, materijal se stavlja na pločicu i pregleda pod mikroskopom', 'Са коже лица се узима стругање или се уклања неколико трепавица, материјал се ставља на плочицу и прегледа под микроскопом', 'С кожи лица берут соскоб или удаляют несколько ресниц, материал помещают на стекло и рассматривают под микроскопом', 'Von der Gesichtshaut wird ein Hautgeschabsel entnommen oder es werden einige Wimpern gezogen, das Material wird auf einen Objektträger gebracht und mikroskopiert', 'Yüz derisinden kazıntı alınır veya birkaç kirpik çıkarılır, örnek lama konularak mikroskopta incelenir', 'Persistent redness and flaking of facial skin, rosacea-like eruptions, itching and crusts along the eyelid margin, chronic blepharitis', 'Uporno crvenilo i ljuštenje kože lica, promjene nalik rozacei, svrab i kraste uz rub kapaka, hronični blefaritis', 'Упорно црвенило и љуштење коже лица, промјене налик розацеи, свраб и красте уз руб капака, хронични блефаритис', 'Стойкое покраснение и шелушение кожи лица, высыпания по типу розацеа, зуд и корочки по краю век, хронический блефарит', 'Anhaltende Rötung und Schuppung der Gesichtshaut, rosazeaähnliche Hautveränderungen, Juckreiz und Krusten am Lidrand, chronische Lidrandentzündung', 'Yüz derisinde inatçı kızarıklık ve pullanma, rozaseye benzer döküntüler, göz kapağı kenarında kaşıntı ve kabuklanma, kronik blefarit', 'For one day before the test do not use cleansing cosmetics, creams or make-up on the area examined and do not apply eyelid ointments', 'Dan prije pregleda na ispitivanom području ne koristiti kozmetiku za umivanje, kreme i šminku, niti stavljati masti za kapke', 'Дан прије прегледа на испитиваном подручју не користити козметику за умивање, креме и шминку, нити стављати масти за капке', 'За сутки до исследования не использовать на исследуемой области косметику для умывания, кремы и декоративную косметику, не наносить мази для век', 'Am Tag vor der Untersuchung im betroffenen Bereich keine Reinigungskosmetik, Cremes oder Make-up verwenden und keine Lidsalben auftragen', 'İncelemeden bir gün önce ilgili bölgede temizleyici kozmetik, krem ve makyaj malzemesi kullanılmamalı, göz kapağı merhemleri sürülmemelidir', 'Finding mites may be related to their excessive growth alongside an existing skin condition, while single mites also occur in healthy people. The meaning of the result is assessed by a dermatologist', 'Nalaz grinja može biti povezan sa njihovim prekomjernim razmnožavanjem uz postojeće stanje kože, dok se pojedinačne grinje nalaze i kod zdravih ljudi. Značenje nalaza procjenjuje dermatolog', 'Налаз гриња може бити повезан са њиховим прекомјерним размножавањем уз постојеће стање коже, док се појединачне гриње налазе и код здравих људи. Значење налаза процјењује дерматолог', 'Обнаружение клещей может быть связано с их избыточным размножением на фоне состояния кожи, при этом единичные особи встречаются и у здоровых людей. Значение результата оценивает дерматолог', 'Der Nachweis von Milben kann mit einer übermäßigen Vermehrung bei einer bestehenden Hauterkrankung zusammenhängen, einzelne Milben kommen auch bei Gesunden vor. Die Bedeutung des Befunds beurteilt der Hautarzt', 'Akarların saptanması, mevcut bir deri durumuna eşlik eden aşırı çoğalmayla ilişkili olabilir, tek tük akar sağlıklı kişilerde de bulunur. Sonucun anlamını dermatolog değerlendirir')
