INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'hsv1-igg'), 'Type-specific blood test for IgG to the herpes virus HSV1, distinguishing them from antibodies to HSV2', 'Tipski specifična analiza krvi na IgG na herpes virus HSV1, koja ih razlikuje od antitijela na HSV2', 'Типски специфична анализа крви на IgG на херпес вирус HSV1, која их разликује од антитијела на HSV2', 'Типоспецифический анализ крови на IgG к вирусу герпеса HSV1, отличающий их от антител к HSV2', 'Typspezifischer Bluttest auf IgG gegen das Herpesvirus HSV1, der diese von Antikörpern gegen HSV2 unterscheidet', 'HSV1 herpes virüsüne karşı IgG antikorlarını, HSV2 antikorlarından ayırt edecek şekilde ölçen tipe özgü kan testi', 'A single venous blood draw, the procedure itself takes a couple of minutes', 'Jednokratno uzimanje venske krvi, sam postupak traje par minuta', 'Једнократно узимање венске крви, сам поступак траје пар минута', 'Однократный забор венозной крови, сама процедура занимает пару минут', 'Einmalige venöse Blutentnahme, der Eingriff selbst dauert ein paar Minuten', 'Tek seferlik venöz kan alımı, işlemin kendisi birkaç dakika sürer', 'Clarifying the virus type in herpetic lesions, assessing immune status before pregnancy, check-up before treatment that lowers immunity, epidemiological studies', 'Utvrđivanje tipa virusa kod herpetičnih promjena, procjena imunskog statusa prije trudnoće, pregled prije terapije koja smanjuje imunitet, epidemiološka ispitivanja', 'Утврђивање типа вируса код херпетичних промјена, процјена имунског статуса прије трудноће, преглед прије терапије која смањује имунитет, епидемиолошка испитивања', 'Уточнение типа вируса при герпетических высыпаниях, оценка иммунного статуса до беременности, обследование перед лечением, снижающим иммунитет, эпидемиологические исследования', 'Klärung des Virustyps bei Herpesbläschen, Beurteilung des Immunstatus vor einer Schwangerschaft, Untersuchung vor einer immunschwächenden Therapie, epidemiologische Studien', 'Herpes döküntülerinde virüs tipinin belirlenmesi, gebelik öncesi bağışıklık durumunun değerlendirilmesi, bağışıklığı azaltan tedavi öncesi inceleme, salgın araştırmaları', 'No preparation required, the time of day does not matter', 'Priprema nije potrebna, doba dana nije važno', 'Припрема није потребна, доба дана није важно', 'Подготовка не требуется, время суток значения не имеет', 'Keine Vorbereitung nötig, die Tageszeit spielt keine Rolle', 'Hazırlık gerekmez, günün saati önemli değildir', 'A positive IgG reflects an encounter with HSV1 at some point in the past rather than an active flare-up. Whether it is related to current complaints is assessed by a doctor', 'Pozitivan IgG odražava raniji susret sa virusom HSV1, a ne aktivno pogoršanje. Vezu nalaza sa aktuelnim tegobama procjenjuje ljekar', 'Позитиван IgG одражава ранији сусрет са вирусом HSV1, а не активно погоршање. Везу налаза са актуелним тегобама процјењује љекар', 'Положительный IgG отражает встречу с вирусом HSV1 когда-то в прошлом, а не активное обострение. Связь результата с текущими жалобами оценивает врач', 'Ein positives IgG spiegelt einen früheren Kontakt mit HSV1 wider und keinen aktiven Schub. Ob es mit aktuellen Beschwerden zusammenhängt, beurteilt der Arzt', 'Pozitif IgG, HSV1 ile geçmişte kurulan teması yansıtır, aktif bir alevlenmeyi değil. Güncel şikayetlerle ilişkisini hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'hsv2-igg'), 'Type-specific blood test for IgG to the herpes virus HSV2, distinguishing them from antibodies to HSV1', 'Tipski specifična analiza krvi na IgG na herpes virus HSV2, koja ih razlikuje od antitijela na HSV1', 'Типски специфична анализа крви на IgG на херпес вирус HSV2, која их разликује од антитијела на HSV1', 'Типоспецифический анализ крови на IgG к вирусу герпеса HSV2, отличающий их от антител к HSV1', 'Typspezifischer Bluttest auf IgG gegen das Herpesvirus HSV2, der diese von Antikörpern gegen HSV1 unterscheidet', 'HSV2 herpes virüsüne karşı IgG antikorlarını, HSV1 antikorlarından ayırt edecek şekilde ölçen tipe özgü kan testi', 'A single venous blood draw, the procedure itself takes a couple of minutes', 'Jednokratno uzimanje venske krvi, sam postupak traje par minuta', 'Једнократно узимање венске крви, сам поступак траје пар минута', 'Однократный забор венозной крови, сама процедура занимает пару минут', 'Einmalige venöse Blutentnahme, der Eingriff selbst dauert ein paar Minuten', 'Tek seferlik venöz kan alımı, işlemin kendisi birkaç dakika sürer', 'Clarifying the virus type in recurring lesions, examination before and during pregnancy, examination of both partners, preparation for treatment that lowers immunity', 'Utvrđivanje tipa virusa kod ponavljanih promjena, pregled prije i tokom trudnoće, pregled oba partnera, priprema za terapiju koja smanjuje imunitet', 'Утврђивање типа вируса код понављаних промјена, преглед прије и током трудноће, преглед оба партнера, припрема за терапију која смањује имунитет', 'Уточнение типа вируса при повторяющихся высыпаниях, обследование до и во время беременности, обследование обоих партнёров, подготовка к терапии, снижающей иммунитет', 'Klärung des Virustyps bei wiederkehrenden Veränderungen, Untersuchung vor und während einer Schwangerschaft, Untersuchung beider Partner, Vorbereitung auf eine immunschwächende Therapie', 'Tekrarlayan döküntülerde virüs tipinin belirlenmesi, gebelik öncesinde ve gebelik sırasında inceleme, iki eşin birlikte incelenmesi, bağışıklığı azaltan tedavi öncesi hazırlık', 'No preparation required, the time of day does not matter', 'Priprema nije potrebna, doba dana nije važno', 'Припрема није потребна, доба дана није важно', 'Подготовка не требуется, время суток значения не имеет', 'Keine Vorbereitung nötig, die Tageszeit spielt keine Rolle', 'Hazırlık gerekmez, günün saati önemli değildir', 'A positive IgG reflects a past contact with HSV2 and says nothing about its activity now. Further steps and the need for other tests are determined by a doctor', 'Pozitivan IgG odražava raniji kontakt sa virusom HSV2 i ne govori o njegovoj aktivnosti sada. Dalje korake i potrebu za drugim testovima određuje ljekar', 'Позитиван IgG одражава ранији контакт са вирусом HSV2 и не говори о његовој активности сада. Даље кораке и потребу за другим тестовима одређује љекар', 'Положительный IgG отражает контакт с вирусом HSV2 в прошлом и не говорит о его активности сейчас. Дальнейшие шаги и необходимость других тестов определяет врач', 'Ein positives IgG spiegelt einen früheren Kontakt mit HSV2 wider und sagt nichts über dessen derzeitige Aktivität aus. Die weiteren Schritte und den Bedarf an zusätzlichen Tests legt der Arzt fest', 'Pozitif IgG, HSV2 ile geçmişteki teması yansıtır ve virüsün şu anki etkinliği hakkında bilgi vermez. Sonraki adımları ve ek test gerekliliğini hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'influenza-a-plus-b-iht'), 'Rapid immunochromatographic test that detects influenza A and B virus antigens', 'Brzi imunohromatografski test koji otkriva antigene virusa gripa A i B', 'Брзи имунохроматографски тест који открива антигене вируса грипа А и Б', 'Быстрый иммунохроматографический тест, определяющий антигены вирусов гриппа A и B', 'Immunchromatographischer Schnelltest, der Antigene der Influenzaviren A und B nachweist', 'İnfluenza A ve B virüsü antijenlerini saptayan hızlı immünokromatografik test', 'A nasal or nasopharyngeal swab, the test cassette gives a result in about 15 minutes', 'Bris nosa ili nazofarinksa, test kaseta daje rezultat za oko 15 minuta', 'Брис носа или назофаринкса, тест касета даје резултат за око 15 минута', 'Мазок из носа или носоглотки, тест-кассета даёт результат примерно за 15 минут', 'Abstrich aus Nase oder Nasenrachen, die Testkassette liefert das Ergebnis in etwa 15 Minuten', 'Burun veya nazofarenks sürüntüsü alınır, test kaseti sonucu yaklaşık 15 dakikada verir', 'Acute onset of illness with high fever during the flu season, telling influenza apart from other respiratory infections, examination in closed communities, patients from risk groups', 'Naglo započeta bolest sa visokom temperaturom u sezoni gripa, razlikovanje gripa od drugih respiratornih infekcija, ispitivanje u kolektivima, pacijenti iz rizičnih grupa', 'Нагло започета болест са високом температуром у сезони грипа, разликовање грипа од других респираторних инфекција, испитивање у колективима, пацијенти из ризичних група', 'Острое начало болезни с высокой температурой в сезон гриппа, различение гриппа и других респираторных инфекций, обследование в закрытых коллективах, пациенты из групп риска', 'Plötzlicher Krankheitsbeginn mit hohem Fieber in der Grippesaison, Abgrenzung der Grippe von anderen Atemwegsinfekten, Untersuchung in Gemeinschaftseinrichtungen, Patienten aus Risikogruppen', 'Grip mevsiminde yüksek ateşle ani başlayan hastalık, gribin diğer solunum yolu enfeksiyonlarından ayrılması, toplu yaşam alanlarında inceleme, risk grubundaki hastalar', 'The test is most informative in the first days of illness; before the swab do not rinse the nose or use nasal sprays unless the doctor says otherwise', 'Test je najinformativniji u prvim danima bolesti; prije brisa ne ispirati nos i ne koristiti sprejeve za nos, osim ako ljekar ne kaže drugačije', 'Тест је најинформативнији у првим данима болести; прије бриса не испирати нос и не користити спрејеве за нос, осим ако љекар не каже другачије', 'Тест информативнее в первые дни болезни; перед мазком не промывать нос и не использовать назальные спреи, если врач не сказал иначе', 'Der Test ist in den ersten Krankheitstagen am aussagekräftigsten; vor dem Abstrich die Nase nicht spülen und keine Nasensprays verwenden, sofern der Arzt nichts anderes sagt', 'Test hastalığın ilk günlerinde daha bilgi vericidir; sürüntüden önce burun yıkanmamalı ve hekim aksini söylemedikçe burun spreyi kullanılmamalıdır', 'A positive result may be related to a current influenza A or B infection, while a negative one does not rule it out. The decision on further examination is made by a doctor', 'Pozitivan nalaz može biti povezan sa aktuelnom infekcijom virusom gripa A ili B, dok negativan ne isključuje bolest. Odluku o daljoj obradi donosi ljekar', 'Позитиван налаз може бити повезан са актуелном инфекцијом вирусом грипа А или Б, док негативан не искључује болест. Одлуку о даљој обради доноси љекар', 'Положительный результат может быть связан с текущей инфекцией вирусом гриппа A или B, отрицательный её не исключает. Решение о дальнейшем обследовании принимает врач', 'Ein positives Ergebnis kann mit einer aktuellen Infektion durch Influenza A oder B zusammenhängen, ein negatives schließt sie nicht aus. Über das weitere Vorgehen entscheidet der Arzt', 'Pozitif sonuç güncel influenza A veya B enfeksiyonu ile ilişkili olabilir, negatif sonuç ise hastalığı dışlamaz. İleri inceleme kararını hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'neisseria-gonorrhoeae-real-time-pcr'), 'Molecular test that detects DNA of the bacterium Neisseria gonorrhoeae by real-time PCR', 'Molekularni test koji otkriva DNK bakterije Neisseria gonorrhoeae metodom PCR u realnom vremenu', 'Молекуларни тест који открива ДНК бактерије Neisseria gonorrhoeae методом ПЦР у реалном времену', 'Молекулярный тест, выявляющий ДНК бактерии Neisseria gonorrhoeae методом ПЦР в реальном времени', 'Molekularer Test, der DNA des Bakteriums Neisseria gonorrhoeae mittels Real-Time-PCR nachweist', 'Neisseria gonorrhoeae bakterisini gerçek zamanlı PCR yöntemiyle saptayan moleküler test', 'Swab from the urethra, cervical canal, throat or rectum, or a urine portion, the analysis is performed in the laboratory', 'Bris uretre, cervikalnog kanala, ždrijela ili rektuma ili uzorak mokraće, analizu radi laboratorija', 'Брис уретре, цервикалног канала, ждријела или ректума или узорак мокраће, анализу ради лабораторија', 'Мазок из уретры, цервикального канала, глотки или прямой кишки либо порция мочи, анализ выполняет лаборатория', 'Abstrich aus Harnröhre, Gebärmutterhalskanal, Rachen oder Enddarm oder eine Urinprobe, die Analyse führt das Labor durch', 'Üretra, servikal kanal, boğaz veya rektumdan sürüntü ya da idrar örneği alınır, analiz laboratuvarda yapılır', 'Discharge, burning when urinating, preventive check-up, examination of a partner, preparation for gynaecological or urological procedures, follow-up after treatment', 'Sekret, peckanje pri mokrenju, preventivni pregled, pregled partnera, priprema za ginekološke ili urološke zahvate, kontrola poslije terapije', 'Секрет, пецкање при мокрењу, превентивни преглед, преглед партнера, припрема за гинеколошке или уролошке захвате, контрола послије терапије', 'Выделения, жжение при мочеиспускании, профилактическое обследование, обследование партнёра, подготовка к гинекологическим или урологическим вмешательствам, контроль после лечения', 'Ausfluss, Brennen beim Wasserlassen, Vorsorgeuntersuchung, Untersuchung des Partners, Vorbereitung auf gynäkologische oder urologische Eingriffe, Kontrolle nach einer Behandlung', 'Akıntı, idrar yaparken yanma, koruyucu inceleme, eşin incelenmesi, jinekolojik veya ürolojik girişim öncesi hazırlık, tedavi sonrası kontrol', 'Do not urinate for 2–3 hours before the sample, women outside menstruation days; the timing after antibacterial medicines is set by the doctor', 'Ne mokriti 2–3 sata prije uzimanja uzorka, žene van dana menstruacije; rok poslije antibakterijskih lijekova određuje ljekar', 'Не мокрити 2–3 сата прије узимања узорка, жене ван дана менструације; рок послије антибактеријских лијекова одређује љекар', 'Не мочиться 2–3 часа перед сдачей, женщинам — вне дней менструации; сроки после антибактериальных препаратов уточняет врач', '2–3 Stunden vor der Probenentnahme nicht Wasser lassen, Frauen außerhalb der Menstruationstage; den Abstand zu antibakteriellen Medikamenten legt der Arzt fest', 'Örnek vermeden 2–3 saat önce idrara çıkılmamalı, kadınlarda adet günleri dışında alınmalıdır; antibakteriyel ilaçlardan sonraki süreyi hekim belirler', 'Detection of DNA means the bacterium is present in the sample. Further examination, treatment and examination of a partner are prescribed by a doctor', 'Nalaz DNK znači da je bakterija prisutna u uzorku. Dalju obradu, terapiju i pregled partnera određuje ljekar', 'Налаз ДНК значи да је бактерија присутна у узорку. Даљу обраду, терапију и преглед партнера одређује љекар', 'Обнаружение ДНК означает присутствие бактерии в пробе. Дальнейшее обследование, лечение и обследование партнёра назначает врач', 'Ein DNA-Nachweis bedeutet, dass das Bakterium in der Probe vorhanden ist. Weitere Abklärung, Behandlung und die Untersuchung des Partners veranlasst der Arzt', 'DNA saptanması bakterinin örnekte bulunduğunu gösterir. İleri tetkikleri, tedaviyi ve eşin incelenmesini hekim planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'quantiferon'), 'Blood test that measures the response of immune cells to antigens of the tuberculosis mycobacterium (an IGRA test)', 'Analiza krvi koja procjenjuje reakciju imunskih ćelija na antigene bacila tuberkuloze (IGRA test)', 'Анализа крви која процјењује реакцију имунских ћелија на антигене бацила туберкулозе (IGRA тест)', 'Анализ крови, оценивающий реакцию иммунных клеток на антигены микобактерии туберкулёза (тест IGRA)', 'Bluttest, der die Reaktion der Immunzellen auf Antigene des Tuberkulosebakteriums misst (IGRA-Test)', 'Bağışıklık hücrelerinin tüberküloz basili antijenlerine verdiği yanıtı ölçen kan testi (IGRA testi)', 'Venous blood is drawn into special tubes that are mixed and delivered to the laboratory promptly, the draw itself takes a few minutes', 'Uzimanje venske krvi u posebne epruvete koje se promiješaju i brzo šalju u laboratoriju, samo uzimanje traje nekoliko minuta', 'Узимање венске крви у посебне епрувете које се промијешају и брзо шаљу у лабораторију, само узимање траје неколико минута', 'Забор венозной крови в специальные пробирки, которые перемешивают и быстро передают в лабораторию, сам забор занимает несколько минут', 'Venöses Blut wird in spezielle Röhrchen abgenommen, die gemischt und zügig ins Labor gebracht werden, die Entnahme selbst dauert einige Minuten', 'Venöz kan özel tüplere alınır, tüpler karıştırılıp kısa sürede laboratuvara ulaştırılır, kan alımı birkaç dakika sürer', 'Screening for latent tuberculosis infection, examination before immunosuppressive and biological therapy, contact with a person ill with tuberculosis, examination of healthcare workers, requirements for employment and paperwork', 'Skrining na latentnu tuberkuloznu infekciju, pregled prije imunosupresivne i biološke terapije, kontakt sa oboljelim od tuberkuloze, pregled zdravstvenih radnika, zahtjevi pri zapošljavanju i sređivanju dokumenata', 'Скрининг на латентну туберкулозну инфекцију, преглед прије имуносупресивне и биолошке терапије, контакт са обољелим од туберкулозе, преглед здравствених радника, захтјеви при запошљавању и сређивању докумената', 'Скрининг на латентную туберкулёзную инфекцию, обследование перед иммуносупрессивной и биологической терапией, контакт с больным туберкулёзом, обследование медицинских работников, требования при трудоустройстве и оформлении документов', 'Screening auf eine latente Tuberkuloseinfektion, Untersuchung vor immunsuppressiver und biologischer Therapie, Kontakt zu einer an Tuberkulose erkrankten Person, Untersuchung von medizinischem Personal, Anforderungen bei Anstellung und Behördengängen', 'Latent tüberküloz enfeksiyonu taraması, bağışıklığı baskılayan ve biyolojik tedavi öncesi inceleme, tüberkülozlu biriyle temas, sağlık çalışanlarının taranması, işe giriş ve resmi belge gereklilikleri', 'No special preparation required, but the appointment time is agreed with the laboratory: the tubes must be processed within a few hours', 'Nije potrebna posebna priprema, ali se termin dogovara sa laboratorijom: epruvete moraju biti obrađene u roku od nekoliko sati', 'Није потребна посебна припрема, али се термин договара са лабораторијом: епрувете морају бити обрађене у року од неколико сати', 'Специальной подготовки не требуется, но время сдачи согласуют с лабораторией: пробирки должны быть обработаны в течение нескольких часов', 'Keine besondere Vorbereitung nötig, der Termin wird jedoch mit dem Labor abgestimmt: die Röhrchen müssen innerhalb weniger Stunden verarbeitet werden', 'Özel bir hazırlık gerekmez, ancak randevu saati laboratuvarla birlikte belirlenir: tüplerin birkaç saat içinde işlenmesi gerekir', 'A positive result may be related to contact with the tuberculosis mycobacterium and does not distinguish latent infection from active disease. Further examination, including a chest image, is ordered by a doctor', 'Pozitivan nalaz može biti povezan sa kontaktom sa bacilom tuberkuloze i ne razlikuje latentnu infekciju od aktivne bolesti. Dalju obradu, uključujući snimak pluća, određuje ljekar', 'Позитиван налаз може бити повезан са контактом са бацилом туберкулозе и не разликује латентну инфекцију од активне болести. Даљу обраду, укључујући снимак плућа, одређује љекар', 'Положительный результат может быть связан с контактом с микобактерией туберкулёза и не различает латентную инфекцию и активное заболевание. Дальнейшее обследование, включая снимок лёгких, назначает врач', 'Ein positives Ergebnis kann mit einem Kontakt mit dem Tuberkulosebakterium zusammenhängen und unterscheidet nicht zwischen latenter Infektion und aktiver Erkrankung. Die weitere Abklärung, einschließlich einer Lungenaufnahme, veranlasst der Arzt', 'Pozitif sonuç tüberküloz basili ile temas ile ilişkili olabilir ve latent enfeksiyonu aktif hastalıktan ayırmaz. Akciğer görüntülemesi dahil ileri incelemeleri hekim planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'cervical-swab-bacteria'), 'Bacteriological examination of material from the cervical canal to identify bacterial flora', 'Bakteriološko ispitivanje materijala iz cervikalnog kanala radi utvrđivanja bakterijske flore', 'Бактериолошко испитивање материјала из цервикалног канала ради утврђивања бактеријске флоре', 'Бактериологическое исследование материала из канала шейки матки для выявления бактериальной флоры', 'Bakteriologische Untersuchung von Material aus dem Gebärmutterhalskanal zum Nachweis der bakteriellen Flora', 'Bakteriyel florayı belirlemek için servikal kanaldan alınan örneğin bakteriyolojik incelemesi', 'The doctor inserts a speculum and collects secretions from the cervical canal with a sterile swab, takes a few minutes', 'Ljekar postavlja ginekološki spekulum i sterilnim štapićem uzima sekret iz cervikalnog kanala, traje nekoliko minuta', 'Љекар поставља гинеколошки спекулум и стерилним штапићем узима секрет из цервикалног канала, траје неколико минута', 'Врач вводит гинекологическое зеркало и стерильным тампоном берёт отделяемое из цервикального канала, занимает несколько минут', 'Der Arzt führt ein Spekulum ein und entnimmt mit einem sterilen Tupfer Sekret aus dem Zervikalkanal, dauert wenige Minuten', 'Hekim spekulum yerleştirir ve steril çubukla servikal kanaldan salgı alır, işlem birkaç dakika sürer', 'Discharge, itching or discomfort, pregnancy planning, preparation for gynaecological procedures, follow-up after treatment, preventive examination', 'Pojačan sekret, svrab ili nelagodnost, planiranje trudnoće, priprema za ginekološke zahvate, kontrola poslije liječenja, preventivni pregled', 'Појачан секрет, свраб или нелагодност, планирање трудноће, припрема за гинеколошке захвате, контрола послије лијечења, превентивни преглед', 'Выделения, зуд или дискомфорт, планирование беременности, подготовка к гинекологическим вмешательствам, контроль после лечения, профилактический осмотр', 'Ausfluss, Juckreiz oder Beschwerden, Kinderwunsch, Vorbereitung auf gynäkologische Eingriffe, Kontrolle nach einer Behandlung, Vorsorgeuntersuchung', 'Akıntı, kaşıntı veya rahatsızlık hissi, gebelik planlaması, jinekolojik girişimlere hazırlık, tedavi sonrası kontrol, koruyucu muayene', 'Taken outside menstrual bleeding; for one day before avoid sexual intercourse, douching, vaginal suppositories and creams; tell the doctor about any recent antibiotics', 'Uzima se van menstrualnog krvarenja; dan ranije izbjegavati seksualne odnose, ispiranja, vaginalete i kreme; obavijestiti ljekara o nedavnom uzimanju antibiotika', 'Узима се ван менструалног крварења; дан раније избјегавати сексуалне односе, испирања, вагиналете и креме; обавијестити љекара о недавном узимању антибиотика', 'Забор вне менструального кровотечения; за сутки исключить половые контакты, спринцевания, вагинальные свечи и кремы; о недавнем приёме антибиотиков сообщить врачу', 'Entnahme außerhalb der Menstruationsblutung; einen Tag zuvor auf Geschlechtsverkehr, Spülungen sowie Vaginalzäpfchen und -cremes verzichten; kürzlich eingenommene Antibiotika dem Arzt mitteilen', 'Adet kanaması dışında alınır; bir gün öncesinden cinsel ilişki, vajinal duş, vajinal fitil ve kremlerden kaçınılmalı; yakın zamanda antibiyotik kullanıldıysa hekime bildirilmelidir', 'Growth of bacteria may be related to a disturbed balance of the microflora, an inflammatory process or symptom-free carriage. The significance of the finding and antibiotic susceptibility are assessed by a doctor', 'Porast bakterija može biti povezan sa poremećajem sastava mikroflore, upalnim procesom ili nosilaštvom bez tegoba. Značaj nalaza i osjetljivost na antibiotike procjenjuje ljekar', 'Пораст бактерија може бити повезан са поремећајем састава микрофлоре, упалним процесом или носилаштвом без тегоба. Значај налаза и осјетљивост на антибиотике процјењује љекар', 'Рост бактерий может быть связан с нарушением состава микрофлоры, воспалительным процессом или бессимптомным носительством. Значимость находки и чувствительность к антибиотикам оценивает врач', 'Ein Nachweis von Bakterien kann mit einer gestörten Zusammensetzung der Mikroflora, einem entzündlichen Prozess oder einer beschwerdefreien Besiedlung zusammenhängen. Die Bedeutung des Befunds und die Antibiotikaempfindlichkeit beurteilt der Arzt', 'Bakteri üremesi mikroflora dengesindeki bozulmayla, iltihabi bir süreçle veya belirtisiz taşıyıcılıkla ilişkili olabilir. Bulgunun önemini ve antibiyotik duyarlılığını hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'glans-swab-bacteria'), 'Bacteriological examination of secretions from the skin of the glans penis', 'Bakteriološko ispitivanje sekreta sa kože glansa penisa', 'Бактериолошко испитивање секрета са коже гланса пениса', 'Бактериологическое исследование отделяемого с кожи головки полового члена', 'Bakteriologische Untersuchung des Sekrets von der Haut der Eichel', 'Penis başının derisinden alınan salgının bakteriyolojik incelemesi', 'A sterile swab is wiped over the surface of the glans and the material is cultured on nutrient media, collection takes about a minute', 'Sterilnim štapićem prelazi se preko površine glansa, materijal se zasijava na hranljive podloge, uzimanje traje oko minut', 'Стерилним штапићем прелази се преко површине гланса, материјал се засијава на хранљиве подлоге, узимање траје око минут', 'Стерильным тампоном проводят по поверхности головки, материал засевают на питательные среды, забор занимает около минуты', 'Mit einem sterilen Tupfer wird über die Oberfläche der Eichel gestrichen, das Material wird auf Nährböden angezüchtet, die Entnahme dauert etwa eine Minute', 'Steril çubuk glans yüzeyinde gezdirilir, örnek besiyerine ekilir, alım yaklaşık bir dakika sürer', 'Redness, itching, coating or discharge around the glans, discomfort when urinating, recurring inflammation, follow-up after treatment', 'Crvenilo, svrab, naslage ili sekret u predjelu glansa, nelagodnost pri mokrenju, ponavljane upale, kontrola poslije liječenja', 'Црвенило, свраб, наслаге или секрет у предјелу гланса, нелагодност при мокрењу, понављане упале, контрола послије лијечења', 'Покраснение, зуд, налёт или выделения в области головки, дискомфорт при мочеиспускании, повторяющиеся воспаления, контроль после лечения', 'Rötung, Juckreiz, Belag oder Ausfluss im Bereich der Eichel, Beschwerden beim Wasserlassen, wiederkehrende Entzündungen, Kontrolle nach einer Behandlung', 'Glans bölgesinde kızarıklık, kaşıntı, beyaz tabaka veya akıntı, idrar yaparken rahatsızlık, tekrarlayan iltihaplar, tedavi sonrası kontrol', 'Do not apply ointments or antiseptics to the area and do not wash it immediately before the sample is taken; tell the doctor about any antibiotics you are taking', 'Ne nanositi masti i antiseptike na to područje i ne prati ga neposredno prije uzimanja uzorka; obavijestiti ljekara o uzimanju antibiotika', 'Не наносити масти и антисептике на то подручје и не прати га непосредно прије узимања узорка; обавијестити љекара о узимању антибиотика', 'Не наносить на область мази и антисептики и не мыть её непосредственно перед забором; о приёме антибиотиков сообщить врачу', 'Vor der Entnahme keine Salben oder Antiseptika auftragen und die Stelle nicht unmittelbar davor waschen; eingenommene Antibiotika dem Arzt mitteilen', 'Bölgeye merhem ve antiseptik uygulanmamalı, örnek alınmadan hemen önce yıkanmamalıdır; kullanılan antibiyotikler hekime bildirilmelidir', 'Growth of bacteria may be related to inflammation of the skin of the glans, hygiene conditions or accompanying conditions, and also occurs in people without complaints. The significance of the finding and antibiotic susceptibility are assessed by a doctor', 'Porast bakterija može biti povezan sa upalom kože glansa, uslovima higijene ili pratećim stanjima, a nalazi se i kod osoba bez tegoba. Značaj nalaza i osjetljivost na antibiotike procjenjuje ljekar', 'Пораст бактерија може бити повезан са упалом коже гланса, условима хигијене или пратећим стањима, а налази се и код особа без тегоба. Значај налаза и осјетљивост на антибиотике процјењује љекар', 'Рост бактерий может быть связан с воспалением кожи головки, особенностями гигиены или сопутствующими состояниями, а также встречается у людей без жалоб. Значимость находки и чувствительность к антибиотикам оценивает врач', 'Ein Nachweis von Bakterien kann mit einer Entzündung der Eichelhaut, den Hygienebedingungen oder Begleiterkrankungen zusammenhängen und kommt auch bei Menschen ohne Beschwerden vor. Die Bedeutung des Befunds und die Antibiotikaempfindlichkeit beurteilt der Arzt', 'Bakteri üremesi glans derisinin iltihabıyla, hijyen koşullarıyla veya eşlik eden durumlarla ilişkili olabilir ve şikayeti olmayan kişilerde de görülür. Bulgunun önemini ve antibiyotik duyarlılığını hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'glans-swab-fungi'), 'Mycological examination of material from the skin of the glans penis for yeast-like fungi', 'Mikološko ispitivanje materijala sa kože glansa penisa na kvasnice', 'Миколошко испитивање материјала са коже гланса пениса на кваснице', 'Микологическое исследование материала с кожи головки полового члена на дрожжеподобные грибы', 'Mykologische Untersuchung von Material der Eichelhaut auf Hefepilze', 'Penis başı derisinden alınan örnekte maya mantarlarının araştırılması', 'A sterile swab collects coating and secretions from the surface of the glans, which are cultured on a medium for fungi', 'Sterilnim štapićem uzimaju se naslage i sekret sa površine glansa i zasijavaju na podlogu za gljivice', 'Стерилним штапићем узимају се наслаге и секрет са површине гланса и засијавају на подлогу за гљивице', 'Стерильным тампоном берут налёт и отделяемое с поверхности головки и засевают на среду для грибов', 'Mit einem sterilen Tupfer werden Belag und Sekret von der Oberfläche der Eichel entnommen und auf einem Pilznährboden angezüchtet', 'Steril çubukla glans yüzeyindeki tabaka ve salgı alınır ve mantar besiyerine ekilir', 'Itching, burning, redness, white coating, recurring complaints, follow-up after a course of treatment', 'Svrab, peckanje, crvenilo, bijele naslage, ponavljane tegobe, kontrola poslije završenog liječenja', 'Свраб, пецкање, црвенило, бијеле наслаге, понављане тегобе, контрола послије завршеног лијечења', 'Зуд, жжение, покраснение, белый налёт, повторяющиеся жалобы, контроль после курса лечения', 'Juckreiz, Brennen, Rötung, weißer Belag, wiederkehrende Beschwerden, Kontrolle nach einer Behandlung', 'Kaşıntı, yanma, kızarıklık, beyaz tabaka, tekrarlayan şikayetler, tedavi sonrası kontrol', 'Do not use antifungal creams for several days before the test and do not wash the area immediately before the procedure; the exact interval is specified by the doctor', 'Nekoliko dana prije uzimanja ne koristiti antimikotske kreme, područje ne prati neposredno prije zahvata; tačan razmak određuje ljekar', 'Неколико дана прије узимања не користити антимикотске креме, подручје не прати непосредно прије захвата; тачан размак одређује љекар', 'За несколько дней до забора не применять противогрибковые кремы, область не мыть непосредственно перед процедурой; точный интервал уточняет врач', 'Einige Tage vor der Entnahme keine Antipilzcremes anwenden und die Stelle nicht unmittelbar vor der Untersuchung waschen; den genauen Abstand legt der Arzt fest', 'Örnekten birkaç gün önce antifungal kremler kullanılmamalı, bölge işlemden hemen önce yıkanmamalıdır; süreyi hekim belirler', 'Detection of fungi may be related to changes in the local microflora, moisture and skin irritation, or accompanying conditions including disorders of carbohydrate metabolism. The result is interpreted by a doctor', 'Nalaz gljivica može biti povezan sa promjenom lokalne mikroflore, vlagom i nadražajem kože ili pratećim stanjima, uključujući poremećaje metabolizma ugljenih hidrata. Nalaz tumači ljekar', 'Налаз гљивица може бити повезан са промјеном локалне микрофлоре, влагом и надражајем коже или пратећим стањима, укључујући поремећаје метаболизма угљених хидрата. Налаз тумачи љекар', 'Обнаружение грибов может быть связано с изменением местной микрофлоры, влажностью и раздражением кожи или сопутствующими состояниями, включая нарушения углеводного обмена. Результат трактует врач', 'Ein Pilznachweis kann mit Veränderungen der lokalen Mikroflora, Feuchtigkeit und Hautreizung oder Begleiterkrankungen einschließlich Störungen des Kohlenhydratstoffwechsels zusammenhängen. Den Befund beurteilt der Arzt', 'Mantar saptanması yerel mikrofloranın değişmesiyle, nem ve deri tahrişiyle ya da karbonhidrat metabolizması bozuklukları dahil eşlik eden durumlarla ilişkili olabilir. Sonucu hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'nose-swab-bacteria'), 'Bacteriological examination of secretions from the nasal mucosa', 'Bakteriološko ispitivanje sekreta sa sluznice nosa', 'Бактериолошко испитивање секрета са слузнице носа', 'Бактериологическое исследование отделяемого слизистой носа', 'Bakteriologische Untersuchung des Sekrets der Nasenschleimhaut', 'Burun içinden alınan salgının bakteriyolojik incelemesi', 'A sterile swab is inserted into the nostril and wiped over the mucosa, the procedure takes less than a minute and is usually painless', 'Sterilni štapić se uvodi u nosni hodnik i prelazi preko sluznice, postupak traje manje od minuta i obično je bezbolan', 'Стерилни штапић се уводи у носни ходник и прелази преко слузнице, поступак траје мање од минута и обично је безболан', 'Стерильный тампон вводят в носовой ход и проводят по слизистой, процедура занимает меньше минуты и обычно безболезненна', 'Ein steriler Tupfer wird in den Nasengang eingeführt und über die Schleimhaut gestrichen, der Vorgang dauert weniger als eine Minute und ist meist schmerzfrei', 'Steril çubuk burun deliğine yerleştirilip mukoza üzerinde gezdirilir, işlem bir dakikadan kısa sürer ve genellikle ağrısızdır', 'Prolonged runny nose, purulent discharge, sinusitis, examination before surgery or hospital admission, carrier screening for healthcare and food industry workers', 'Dugotrajna sekrecija iz nosa, gnojav sekret, sinusitis, ispitivanje prije operacije ili prijema u bolnicu, provjera nosilaštva kod zdravstvenih radnika i radnika u proizvodnji hrane', 'Дуготрајна секреција из носа, гнојав секрет, синуситис, испитивање прије операције или пријема у болницу, провјера носилаштва код здравствених радника и радника у производњи хране', 'Затяжной насморк, гнойные выделения, синусит, обследование перед операцией или госпитализацией, проверка носительства у медицинских работников и работников пищевой сферы', 'Anhaltender Schnupfen, eitriges Sekret, Nasennebenhöhlenentzündung, Untersuchung vor Operationen oder Krankenhausaufnahme, Trägerprüfung bei Beschäftigten im Gesundheitswesen und in der Lebensmittelbranche', 'Uzun süren burun akıntısı, iltihaplı akıntı, sinüzit, ameliyat veya hastaneye yatış öncesi inceleme, sağlık ve gıda sektörü çalışanlarında taşıyıcılık taraması', 'On the day of the test do not use nasal drops, sprays or ointments and do not rinse the nose; tell the doctor about any antibiotics you are taking', 'Na dan uzimanja ne koristiti kapi, sprejeve i masti za nos i ne ispirati nos; obavijestiti ljekara o uzimanju antibiotika', 'На дан узимања не користити капи, спрејеве и масти за нос и не испирати нос; обавијестити љекара о узимању антибиотика', 'В день забора не использовать капли, спреи и мази для носа, нос не промывать; о приёме антибиотиков сообщить врачу', 'Am Tag der Entnahme keine Nasentropfen, -sprays oder -salben verwenden und die Nase nicht spülen; eingenommene Antibiotika dem Arzt mitteilen', 'Örnek alınacağı gün burun damlası, sprey ve merhem kullanılmamalı, burun yıkanmamalıdır; kullanılan antibiyotikler hekime bildirilmelidir', 'Growth of micro-organisms may reflect symptom-free carriage or the involvement of bacteria in inflammation. The significance of the result and antibiotic susceptibility are determined by a doctor', 'Porast mikroorganizama može odražavati nosilaštvo bez tegoba, ali i učešće bakterija u upali. Značaj nalaza i osjetljivost na antibiotike određuje ljekar', 'Пораст микроорганизама може одражавати носилаштво без тегоба, али и учешће бактерија у упали. Значај налаза и осјетљивост на антибиотике одређује љекар', 'Рост микроорганизмов может отражать как бессимптомное носительство, так и участие бактерий в воспалении. Значимость результата и чувствительность к антибиотикам определяет врач', 'Der Nachweis von Mikroorganismen kann eine beschwerdefreie Besiedlung widerspiegeln, aber auch eine Beteiligung von Bakterien an einer Entzündung. Die Bedeutung des Ergebnisses und die Antibiotikaempfindlichkeit bestimmt der Arzt', 'Mikroorganizma üremesi belirtisiz taşıyıcılığı da, bakterilerin iltihaba katılımını da yansıtabilir. Sonucun önemini ve antibiyotik duyarlılığını hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'nose-swab-fungi'), 'Examination of nasal mucosa secretions for the presence of fungi', 'Ispitivanje sekreta sa sluznice nosa na prisustvo gljivica', 'Испитивање секрета са слузнице носа на присуство гљивица', 'Исследование отделяемого слизистой носа на наличие грибов', 'Untersuchung des Sekrets der Nasenschleimhaut auf Pilze', 'Burun içinden alınan salgıda mantar varlığının araştırılması', 'A sterile swab collects material from the nasal passage and it is cultured on a medium for fungi, collection takes less than a minute', 'Sterilnim štapićem uzima se materijal iz nosnog hodnika i zasijava na hranljivu podlogu za gljivice, uzimanje traje manje od minuta', 'Стерилним штапићем узима се материјал из носног ходника и засијава на хранљиву подлогу за гљивице, узимање траје мање од минута', 'Стерильным тампоном берут материал из носового хода и засевают на питательную среду для грибов, забор занимает меньше минуты', 'Mit einem sterilen Tupfer wird Material aus dem Nasengang entnommen und auf einem Pilznährboden angezüchtet, die Entnahme dauert weniger als eine Minute', 'Steril çubukla burun yolundan örnek alınır ve mantar besiyerine ekilir, alım bir dakikadan kısa sürer', 'Long-lasting congestion and discharge that does not improve with usual treatment, chronic sinusitis, conditions with reduced immunity, monitoring after antibacterial therapy', 'Dugotrajna zapušenost i sekrecija bez poboljšanja uz uobičajeno liječenje, hronični sinusitis, stanja sa smanjenim imunitetom, praćenje poslije antibiotske terapije', 'Дуготрајна запушеност и секреција без побољшања уз уобичајено лијечење, хронични синуситис, стања са смањеним имунитетом, праћење послије антибиотске терапије', 'Длительная заложенность и выделения без улучшения на обычном лечении, хронический синусит, состояния со сниженным иммунитетом, наблюдение после антибактериальной терапии', 'Anhaltende Verstopfung und Sekretion ohne Besserung unter der üblichen Behandlung, chronische Nasennebenhöhlenentzündung, Zustände mit geschwächter Immunabwehr, Verlaufskontrolle nach antibakterieller Therapie', 'Alışılmış tedaviye rağmen geçmeyen tıkanıklık ve akıntı, kronik sinüzit, bağışıklığın azaldığı durumlar, antibiyotik tedavisi sonrası izlem', 'On the day of the test do not use nasal sprays, drops or ointments and do not rinse the nose; tell the doctor about any recent antifungal medicines', 'Na dan uzimanja ne koristiti nazalne sprejeve, kapi i masti i ne ispirati nos; obavijestiti ljekara o nedavnom uzimanju antimikotskih lijekova', 'На дан узимања не користити назалне спрејеве, капи и масти и не испирати нос; обавијестити љекара о недавном узимању антимикотских лијекова', 'В день забора не использовать назальные спреи, капли и мази, нос не промывать; о недавнем приёме противогрибковых средств сообщить врачу', 'Am Tag der Entnahme keine Nasensprays, -tropfen oder -salben verwenden und die Nase nicht spülen; kürzlich eingenommene Antipilzmittel dem Arzt mitteilen', 'Örnek alınacağı gün burun spreyi, damla ve merhem kullanılmamalı, burun yıkanmamalıdır; yakın zamanda antifungal ilaç kullanıldıysa hekime bildirilmelidir', 'Detection of fungi may reflect their usual presence on the mucosa or their involvement in an inflammatory process, especially when immunity is reduced. The result is assessed by a doctor', 'Nalaz gljivica može odražavati njihovo uobičajeno prisustvo na sluznici, ali i učešće u upalnom procesu, naročito kod smanjenog imuniteta. Nalaz procjenjuje ljekar', 'Налаз гљивица може одражавати њихово уобичајено присуство на слузници, али и учешће у упалном процесу, нарочито код смањеног имунитета. Налаз процјењује љекар', 'Находка грибов может отражать как их обычное присутствие на слизистой, так и участие в воспалительном процессе, особенно при сниженном иммунитете. Результат оценивает врач', 'Ein Pilznachweis kann das übliche Vorkommen auf der Schleimhaut widerspiegeln, aber auch eine Beteiligung an einem entzündlichen Prozess, vor allem bei geschwächter Immunabwehr. Den Befund beurteilt der Arzt', 'Mantar saptanması mukozadaki olağan varlığı kadar, özellikle bağışıklığın azaldığı durumlarda iltihabi sürece katılımı da yansıtabilir. Sonucu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'oral-cavity-swab-bacteria'), 'Bacteriological examination of material from the mucosa of the oral cavity', 'Bakteriološko ispitivanje materijala sa sluznice usne duplje', 'Бактериолошко испитивање материјала са слузнице усне дупље', 'Бактериологическое исследование материала со слизистой полости рта', 'Bakteriologische Untersuchung von Material der Mundschleimhaut', 'Ağız içi mukozasından alınan örneğin bakteriyolojik incelemesi', 'A sterile swab is wiped over the mucosa of the cheeks, gums and palate and the material is cultured on nutrient media', 'Sterilnim štapićem prelazi se preko sluznice obraza, desni i nepca, materijal se zasijava na hranljive podloge', 'Стерилним штапићем прелази се преко слузнице образа, десни и непца, материјал се засијава на хранљиве подлоге', 'Стерильным тампоном проводят по слизистой щёк, дёсен и нёба, материал засевают на питательные среды', 'Mit einem sterilen Tupfer wird über die Schleimhaut von Wangen, Zahnfleisch und Gaumen gestrichen, das Material wird auf Nährböden angezüchtet', 'Steril çubuk yanak, diş eti ve damak mukozasında gezdirilir, örnek besiyerlerine ekilir', 'Inflammation of the mucosa and gums, coating and small ulcers in the mouth, persistent bad breath, preparation for dental procedures, follow-up after treatment', 'Upala sluznice i desni, naslage i ranice u ustima, uporan neprijatan zadah, priprema za stomatološke zahvate, kontrola poslije liječenja', 'Упала слузнице и десни, наслаге и ранице у устима, упоран непријатан задах, припрема за стоматолошке захвате, контрола послије лијечења', 'Воспаление слизистой и дёсен, налёт и язвочки во рту, стойкий неприятный запах, подготовка к стоматологическим вмешательствам, контроль после лечения', 'Entzündung der Schleimhaut und des Zahnfleischs, Belag und kleine Wunden im Mund, anhaltender Mundgeruch, Vorbereitung auf zahnärztliche Eingriffe, Kontrolle nach einer Behandlung', 'Mukoza ve diş eti iltihabı, ağızda tabaka ve küçük yaralar, geçmeyen ağız kokusu, diş hekimliği girişimlerine hazırlık, tedavi sonrası kontrol', 'Taken in the morning before eating: do not brush your teeth, rinse your mouth, drink or smoke for 2–3 hours before the procedure', 'Uzima se ujutru prije jela: ne prati zube, ne ispirati usta, ne piti i ne pušiti 2–3 sata prije zahvata', 'Узима се ујутру прије јела: не прати зубе, не испирати уста, не пити и не пушити 2–3 сата прије захвата', 'Забор утром до еды: не чистить зубы, не полоскать рот, не пить и не курить за 2–3 часа до процедуры', 'Entnahme morgens vor dem Essen: 2–3 Stunden vorher nicht Zähne putzen, nicht spülen, nicht trinken und nicht rauchen', 'Sabah aç karnına alınır: işlemden 2–3 saat önce diş fırçalanmamalı, ağız çalkalanmamalı, bir şey içilmemeli ve sigara kullanılmamalıdır', 'Growth of bacteria may be related to inflammation of the mucosa, the condition of teeth and gums, or a temporary change of the microflora after treatment. The meaning of the finding is assessed by a doctor', 'Porast bakterija može biti povezan sa upalom sluznice, stanjem zuba i desni ili privremenom promjenom mikroflore poslije liječenja. Značenje nalaza procjenjuje ljekar', 'Пораст бактерија може бити повезан са упалом слузнице, стањем зуба и десни или привременом промјеном микрофлоре послије лијечења. Значење налаза процјењује љекар', 'Рост бактерий может быть связан с воспалением слизистой, состоянием зубов и дёсен или временным изменением микрофлоры после лечения. Значение находки оценивает врач', 'Ein Nachweis von Bakterien kann mit einer Schleimhautentzündung, dem Zustand von Zähnen und Zahnfleisch oder einer vorübergehenden Veränderung der Mikroflora nach einer Behandlung zusammenhängen. Die Bedeutung des Befunds beurteilt der Arzt', 'Bakteri üremesi mukoza iltihabıyla, diş ve diş eti durumuyla ya da tedavi sonrası mikrofloranın geçici değişimiyle ilişkili olabilir. Bulgunun anlamını hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'prepuce-swab-bacteria'), 'Bacteriological examination of secretions from the inner surface of the foreskin', 'Bakteriološko ispitivanje sekreta sa unutrašnje površine prepucijuma', 'Бактериолошко испитивање секрета са унутрашње површине препуцијума', 'Бактериологическое исследование отделяемого с внутренней поверхности крайней плоти', 'Bakteriologische Untersuchung des Sekrets von der Innenseite der Vorhaut', 'Prepusyumun iç yüzeyinden alınan salgının bakteriyolojik incelemesi', 'The foreskin is gently retracted and a sterile swab collects material from the preputial sac, takes about a minute', 'Prepucijum se pažljivo povuče unazad i sterilnim štapićem se uzima materijal iz prepucijalne kese, traje oko minut', 'Препуцијум се пажљиво повуче уназад и стерилним штапићем се узима материјал из препуцијалне кесе, траје око минут', 'Крайнюю плоть аккуратно отводят и стерильным тампоном берут материал из препуциального мешка, занимает около минуты', 'Die Vorhaut wird vorsichtig zurückgezogen und mit einem sterilen Tupfer Material aus dem Vorhautsack entnommen, dauert etwa eine Minute', 'Sünnet derisi dikkatlice geri çekilir ve steril çubukla prepusyum boşluğundan örnek alınır, yaklaşık bir dakika sürer', 'Redness and swelling of the foreskin, coating and unpleasant odour, pain on retraction, recurring inflammation, follow-up after treatment', 'Crvenilo i otok prepucijuma, naslage i neprijatan miris, bol pri povlačenju, ponavljane upale, kontrola poslije liječenja', 'Црвенило и оток препуцијума, наслаге и непријатан мирис, бол при повлачењу, понављане упале, контрола послије лијечења', 'Покраснение и отёк крайней плоти, налёт и неприятный запах, боль при отведении, повторяющиеся воспаления, контроль после лечения', 'Rötung und Schwellung der Vorhaut, Belag und unangenehmer Geruch, Schmerzen beim Zurückziehen, wiederkehrende Entzündungen, Kontrolle nach einer Behandlung', 'Sünnet derisinde kızarıklık ve şişlik, tabaka ve kötü koku, geri çekerken ağrı, tekrarlayan iltihaplar, tedavi sonrası kontrol', 'Do not wash the area and do not use antiseptics or ointments immediately before the sample is taken; tell the doctor about any antibiotics you are taking', 'Ne prati područje i ne koristiti antiseptike i masti neposredno prije uzimanja uzorka; obavijestiti ljekara o uzimanju antibiotika', 'Не прати подручје и не користити антисептике и масти непосредно прије узимања узорка; обавијестити љекара о узимању антибиотика', 'Не мыть область и не применять антисептики и мази непосредственно перед забором; о приёме антибиотиков сообщить врачу', 'Die Stelle unmittelbar vor der Entnahme nicht waschen und keine Antiseptika oder Salben anwenden; eingenommene Antibiotika dem Arzt mitteilen', 'Örnek alınmadan hemen önce bölge yıkanmamalı, antiseptik ve merhem kullanılmamalıdır; kullanılan antibiyotikler hekime bildirilmelidir', 'Growth of bacteria may be related to inflammation of the foreskin, difficult hygiene with a narrow preputial ring, or accompanying conditions. Further steps are decided by a doctor', 'Porast bakterija može biti povezan sa upalom prepucijuma, otežanom higijenom kod uskog prepucijalnog prstena ili pratećim stanjima. Dalje korake određuje ljekar', 'Пораст бактерија може бити повезан са упалом препуцијума, отежаном хигијеном код уског препуцијалног прстена или пратећим стањима. Даље кораке одређује љекар', 'Рост бактерий может быть связан с воспалением крайней плоти, затруднённой гигиеной при узком препуциальном кольце или сопутствующими состояниями. Дальнейшие шаги определяет врач', 'Ein Nachweis von Bakterien kann mit einer Entzündung der Vorhaut, erschwerter Hygiene bei enger Vorhaut oder Begleiterkrankungen zusammenhängen. Das weitere Vorgehen legt der Arzt fest', 'Bakteri üremesi sünnet derisi iltihabıyla, dar prepusyum halkası nedeniyle güçleşen hijyenle veya eşlik eden durumlarla ilişkili olabilir. Sonraki adımları hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'prepuce-swab-fungi'), 'Examination of material from the inner surface of the foreskin for yeast-like fungi', 'Ispitivanje materijala sa unutrašnje površine prepucijuma na kvasnice', 'Испитивање материјала са унутрашње површине препуцијума на кваснице', 'Исследование материала с внутренней поверхности крайней плоти на дрожжеподобные грибы', 'Untersuchung von Material der Vorhautinnenseite auf Hefepilze', 'Prepusyumun iç yüzeyinden alınan örnekte maya mantarlarının araştırılması', 'The foreskin is retracted, a sterile swab collects coating and secretions, and the material is cultured on a medium for fungi', 'Prepucijum se povuče unazad, sterilnim štapićem se skupljaju naslage i sekret, materijal se zasijava na podlogu za gljivice', 'Препуцијум се повуче уназад, стерилним штапићем се скупљају наслаге и секрет, материјал се засијава на подлогу за гљивице', 'Крайнюю плоть отводят, стерильным тампоном собирают налёт и отделяемое, материал засевают на среду для грибов', 'Die Vorhaut wird zurückgezogen, mit einem sterilen Tupfer werden Belag und Sekret entnommen und auf einem Pilznährboden angezüchtet', 'Sünnet derisi geri çekilir, steril çubukla tabaka ve salgı toplanır, örnek mantar besiyerine ekilir', 'Itching, white curd-like coating, redness, burning, recurring inflammation, follow-up after a course of treatment', 'Svrab, bijele sirevite naslage, crvenilo, peckanje, ponavljane upale, kontrola poslije završenog liječenja', 'Свраб, бијеле сиревите наслаге, црвенило, пецкање, понављане упале, контрола послије завршеног лијечења', 'Зуд, белый творожистый налёт, покраснение, жжение, повторяющиеся воспаления, контроль после курса лечения', 'Juckreiz, weißlich-krümeliger Belag, Rötung, Brennen, wiederkehrende Entzündungen, Kontrolle nach einer Behandlung', 'Kaşıntı, beyaz kesilmiş süt görünümünde tabaka, kızarıklık, yanma, tekrarlayan iltihaplar, tedavi sonrası kontrol', 'Do not use antifungal creams for several days before the test and do not wash the area immediately before the procedure; the interval is specified by the doctor', 'Nekoliko dana prije uzimanja ne koristiti antimikotske kreme, područje ne prati neposredno prije zahvata; razmak određuje ljekar', 'Неколико дана прије узимања не користити антимикотске креме, подручје не прати непосредно прије захвата; размак одређује љекар', 'За несколько дней до забора не применять противогрибковые кремы, область не мыть непосредственно перед процедурой; интервал уточняет врач', 'Einige Tage vor der Entnahme keine Antipilzcremes anwenden und die Stelle nicht unmittelbar vor der Untersuchung waschen; den Abstand legt der Arzt fest', 'Örnekten birkaç gün önce antifungal krem kullanılmamalı, bölge işlemden hemen önce yıkanmamalıdır; süreyi hekim belirler', 'Fungi are often found without any complaints: moisture is retained longer under the foreskin, and growth increases with skin irritation or a narrow foreskin. The doctor decides what the finding means', 'Gljivice se često nalaze i bez tegoba: ispod prepucijuma se duže zadržava vlaga, a rast je izraženiji uz nadražaj kože ili uzak prepucijum. Značaj nalaza procjenjuje ljekar', 'Гљивице се често налазе и без тегоба: испод препуцијума се дуже задржава влага, а раст је израженији уз надражај коже или узак препуцијум. Значај налаза процјењује љекар', 'Грибы нередко находят и без жалоб: под крайней плотью дольше сохраняется влага, и рост усиливается при раздражении кожи или узкой крайней плоти. Значение находки определяет врач', 'Pilze werden häufig auch ohne Beschwerden gefunden: unter der Vorhaut bleibt Feuchtigkeit länger bestehen, und das Wachstum nimmt bei Hautreizung oder enger Vorhaut zu. Was der Befund bedeutet, entscheidet der Arzt', 'Mantarlar çoğu zaman şikâyet olmadan da bulunur: sünnet derisinin altında nem daha uzun süre kalır ve ciltte tahriş ya da dar sünnet derisi varsa üreme artar. Bulgunun anlamını hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'skin-swab-bacteria'), 'Bacteriological examination of discharge from an affected area of skin', 'Bakteriološko ispitivanje sekreta sa promijenjenog dijela kože', 'Бактериолошко испитивање секрета са промијењеног дијела коже', 'Бактериологическое исследование отделяемого с поражённого участка кожи', 'Bakteriologische Untersuchung von Sekret aus einer betroffenen Hautstelle', 'Etkilenen deri bölgesinden alınan akıntının bakteriyolojik incelemesi', 'A sterile swab is wiped over the surface of the lesion, wound or blister content and the material is cultured on nutrient media', 'Sterilnim štapićem prelazi se preko površine promjene, rane ili sadržaja mjehurića, materijal se zasijava na hranljive podloge', 'Стерилним штапићем прелази се преко површине промјене, ране или садржаја мјехурића, материјал се засијава на хранљиве подлоге', 'Стерильным тампоном проводят по поверхности очага, раны или содержимого пузырька, материал засевают на питательные среды', 'Mit einem sterilen Tupfer wird über die Oberfläche des Herdes, der Wunde oder den Blaseninhalt gestrichen, das Material wird auf Nährböden angezüchtet', 'Steril çubuk lezyon, yara yüzeyi veya kabarcık içeriği üzerinde gezdirilir, örnek besiyerlerine ekilir', 'Pustules, weeping and slow-healing sores, inflammation around stitches, boils, signs of an infected burn or bite, follow-up after treatment', 'Gnojne promjene, vlažne i sporo zarastajuće ranice, upala oko šavova, čirevi, znaci infekcije opekotine ili ujeda, kontrola poslije liječenja', 'Гнојне промјене, влажне и споро зарастајуће ранице, упала око шавова, чиреви, знаци инфекције опекотине или уједа, контрола послије лијечења', 'Гнойнички, мокнущие и долго не заживающие ранки, воспаление вокруг швов, фурункулы, признаки инфицирования ожога или укуса, контроль после лечения', 'Eitrige Hautveränderungen, nässende und schlecht heilende Wunden, Entzündung um Nähte, Furunkel, Anzeichen einer infizierten Verbrennung oder Bisswunde, Kontrolle nach einer Behandlung', 'İrinli kabarcıklar, sulanan ve geç iyileşen yaralar, dikiş çevresinde iltihap, çıban, yanık veya ısırık yerinde enfeksiyon belirtileri, tedavi sonrası kontrol', 'Do not apply ointments, creams or antiseptics to the area and do not wash it immediately before the sample is taken; tell the doctor about any antibiotics you are taking', 'Ne nanositi masti, kreme i antiseptike na to mjesto i ne prati ga neposredno prije uzimanja uzorka; obavijestiti ljekara o uzimanju antibiotika', 'Не наносити масти, креме и антисептике на то мјесто и не прати га непосредно прије узимања узорка; обавијестити љекара о узимању антибиотика', 'Не наносить на участок мази, кремы и антисептики и не мыть его непосредственно перед забором; о приёме антибиотиков сообщить врачу', 'Keine Salben, Cremes oder Antiseptika auf die Stelle auftragen und sie nicht unmittelbar vor der Entnahme waschen; eingenommene Antibiotika dem Arzt mitteilen', 'Bölgeye merhem, krem ve antiseptik uygulanmamalı, örnek alınmadan hemen önce yıkanmamalıdır; kullanılan antibiyotikler hekime bildirilmelidir', 'Growth of bacteria may reflect infection of the lesion or the presence of the usual skin flora. The significance of the finding and antibiotic susceptibility are assessed by a doctor', 'Porast bakterija može odražavati infekciju promjene ili prisustvo uobičajene kožne flore. Značaj nalaza i osjetljivost na antibiotike procjenjuje ljekar', 'Пораст бактерија може одражавати инфекцију промјене или присуство уобичајене кожне флоре. Значај налаза и осјетљивост на антибиотике процјењује љекар', 'Рост бактерий может отражать инфицирование очага или присутствие обычной кожной флоры. Значимость находки и чувствительность к антибиотикам оценивает врач', 'Ein Nachweis von Bakterien kann eine Infektion des Herdes oder das Vorhandensein der üblichen Hautflora widerspiegeln. Die Bedeutung des Befunds und die Antibiotikaempfindlichkeit beurteilt der Arzt', 'Bakteri üremesi lezyonun enfekte olduğunu da, derinin olağan florasının varlığını da yansıtabilir. Bulgunun önemini ve antibiyotik duyarlılığını hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'skin-swab-fungi'), 'Examination of material from an affected area of skin for fungi', 'Ispitivanje materijala sa promijenjenog dijela kože na gljivice', 'Испитивање материјала са промијењеног дијела коже на гљивице', 'Исследование материала с поражённого участка кожи на грибы', 'Untersuchung von Material einer betroffenen Hautstelle auf Pilze', 'Etkilenen deri bölgesinden alınan örnekte mantar araştırması', 'Skin scales are taken from the edge of the lesion or a sterile swab is used, the material is examined under a microscope and cultured on a medium for fungi', 'Sa ivice promjene uzimaju se ljuspice kože ili se prelazi sterilnim štapićem, materijal se gleda pod mikroskopom i zasijava na podlogu za gljivice', 'Са ивице промјене узимају се љуспице коже или се прелази стерилним штапићем, материјал се гледа под микроскопом и засијава на подлогу за гљивице', 'С края очага берут чешуйки кожи или проводят стерильным тампоном, материал смотрят под микроскопом и засевают на среду для грибов', 'Am Rand des Herdes werden Hautschuppen entnommen oder ein steriler Tupfer verwendet, das Material wird mikroskopisch untersucht und auf einem Pilznährboden angezüchtet', 'Lezyonun kenarından deri pulları kazınır veya steril çubuk kullanılır, örnek mikroskopta incelenir ve mantar besiyerine ekilir', 'Scaly patches with a clear border, itching, skin changes between the toes and in skin folds, patches on the scalp, follow-up after treatment', 'Ljuskave promjene sa jasnom ivicom, svrab, promjene kože među prstima i u pregibima, žarišta na vlasištu, kontrola poslije liječenja', 'Љускаве промјене са јасном ивицом, свраб, промјене коже међу прстима и у прегибима, жаришта на власишту, контрола послије лијечења', 'Шелушащиеся пятна с чётким краем, зуд, изменения кожи между пальцами и в складках, очаги на волосистой части головы, контроль после лечения', 'Schuppende Flecken mit deutlichem Rand, Juckreiz, Hautveränderungen zwischen den Zehen und in Hautfalten, Herde auf der Kopfhaut, Kontrolle nach einer Behandlung', 'Sınırı belirgin pullanan lekeler, kaşıntı, parmak araları ve kıvrım bölgelerinde deri değişiklikleri, saçlı deride odaklar, tedavi sonrası kontrol', 'Do not use antifungal creams for several days before the test and do not wash the area immediately before the procedure; the exact interval is specified by the doctor', 'Nekoliko dana prije uzimanja ne koristiti antimikotske kreme i ne prati to mjesto neposredno prije zahvata; tačan razmak određuje ljekar', 'Неколико дана прије узимања не користити антимикотске креме и не прати то мјесто непосредно прије захвата; тачан размак одређује љекар', 'За несколько дней до забора не применять противогрибковые кремы и не мыть участок непосредственно перед процедурой; конкретный интервал уточняет врач', 'Einige Tage vor der Entnahme keine Antipilzcremes anwenden und die Stelle nicht unmittelbar vor der Untersuchung waschen; den genauen Abstand legt der Arzt fest', 'Örnekten birkaç gün önce antifungal krem kullanılmamalı, bölge işlemden hemen önce yıkanmamalıdır; süreyi hekim belirler', 'Detection of fungi may be related to a fungal skin condition, and also to surface contamination of the sample. The culture and microscopy results are interpreted by a dermatologist', 'Nalaz gljivica može biti povezan sa gljivičnom promjenom kože, ali i sa površinskim zagađenjem uzorka. Rezultat kulture i mikroskopije tumači ljekar dermatolog', 'Налаз гљивица може бити повезан са гљивичном промјеном коже, али и са површинским загађењем узорка. Резултат културе и микроскопије тумачи љекар дерматолог', 'Обнаружение грибов может быть связано с грибковым поражением кожи, а также с поверхностным загрязнением материала. Результат посева и микроскопии интерпретирует врач-дерматолог', 'Ein Pilznachweis kann mit einer Pilzerkrankung der Haut, aber auch mit einer oberflächlichen Verunreinigung des Materials zusammenhängen. Kultur- und Mikroskopiebefund beurteilt der Hautarzt', 'Mantar saptanması derinin mantar hastalığıyla olduğu kadar örneğin yüzeysel kirlenmesiyle de ilişkili olabilir. Kültür ve mikroskopi sonucunu dermatoloji uzmanı yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'stool-fungi'), 'Examination of stool for yeast-like and mould fungi', 'Ispitivanje stolice na kvasnice i plijesni', 'Испитивање столице на кваснице и плијесни', 'Исследование кала на дрожжеподобные и плесневые грибы', 'Untersuchung des Stuhls auf Hefe- und Schimmelpilze', 'Dışkıda maya ve küf mantarlarının araştırılması', 'The patient collects a small portion of stool into a sterile container and the laboratory cultures the material on a medium for fungi', 'Pacijent sam sakuplja manju količinu stolice u sterilnu posudu, a u laboratoriji se materijal zasijava na hranljivu podlogu za gljivice', 'Пацијент сам сакупља мању количину столице у стерилну посуду, а у лабораторији се материјал засијава на хранљиву подлогу за гљивице', 'Пациент сам собирает небольшую порцию кала в стерильный контейнер, в лаборатории материал засевают на питательную среду для грибов', 'Der Patient sammelt selbst eine kleine Stuhlprobe in einem sterilen Behälter, im Labor wird das Material auf einem Pilznährboden angezüchtet', 'Hasta küçük bir gaita örneğini steril kaba kendisi toplar, laboratuvarda örnek mantar besiyerine ekilir', 'Long-lasting bowel disturbances and bloating, complaints after a course of antibiotics, conditions with reduced immunity, monitoring as prescribed by a doctor', 'Dugotrajne promjene stolice i nadutost, tegobe poslije terapije antibioticima, stanja sa smanjenim imunitetom, praćenje po preporuci ljekara', 'Дуготрајне промјене столице и надутост, тегобе послије терапије антибиотицима, стања са смањеним имунитетом, праћење по препоруци љекара', 'Длительные нарушения стула и вздутие, жалобы после курса антибиотиков, состояния со сниженным иммунитетом, наблюдение по назначению врача', 'Anhaltende Stuhlveränderungen und Blähungen, Beschwerden nach einer Antibiotikatherapie, Zustände mit geschwächter Immunabwehr, Verlaufskontrolle auf ärztliche Anordnung', 'Uzun süren dışkılama düzensizlikleri ve şişkinlik, antibiyotik tedavisi sonrası şikayetler, bağışıklığın azaldığı durumlar, hekim önerisiyle izlem', 'Collect stool into a sterile container without urine or water mixed in, avoid laxatives and enemas the day before, and deliver the sample within the time the laboratory specifies', 'Stolicu sakupiti u sterilnu posudu bez primjese mokraće i vode, dan ranije ne koristiti laksative i klizme, uzorak dostaviti u laboratoriju u roku koji ona navodi', 'Столицу сакупити у стерилну посуду без примјесе мокраће и воде, дан раније не користити лаксативе и клизме, узорак доставити у лабораторију у року који она наводи', 'Собрать кал в стерильный контейнер без примеси мочи и воды, накануне не использовать слабительные и клизмы, доставить материал в лабораторию в указанные ею сроки', 'Stuhl in einem sterilen Behälter ohne Beimengung von Urin oder Wasser sammeln, am Vortag keine Abführmittel und Einläufe anwenden und die Probe innerhalb der vom Labor genannten Frist abgeben', 'Gaita, idrar ve su karışmadan steril kaba toplanmalı, bir gün öncesinden müshil ve lavman kullanılmamalı, örnek laboratuvarın belirttiği süre içinde teslim edilmelidir', 'Growth of fungi may reflect their usual presence in the bowel or a change of the microflora, for example after antibacterial therapy. The significance of the result is assessed by a doctor', 'Porast gljivica može odražavati njihovo uobičajeno prisustvo u crijevima, ali i promjenu mikroflore, na primjer poslije antibiotske terapije. Značaj nalaza procjenjuje ljekar', 'Пораст гљивица може одражавати њихово уобичајено присуство у цријевима, али и промјену микрофлоре, на примјер послије антибиотске терапије. Значај налаза процјењује љекар', 'Рост грибов может отражать как их обычное присутствие в кишечнике, так и изменение микрофлоры, например после антибактериальной терапии. Значимость результата оценивает врач', 'Ein Pilzwachstum kann das übliche Vorkommen im Darm widerspiegeln, aber auch eine Veränderung der Mikroflora, zum Beispiel nach einer antibakteriellen Therapie. Die Bedeutung des Ergebnisses beurteilt der Arzt', 'Mantar üremesi bağırsaktaki olağan varlığı kadar, örneğin antibiyotik tedavisi sonrası mikrofloranın değişmesini de yansıtabilir. Sonucun önemini hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'throat-swab-fungi'), 'Examination of material from the pharyngeal mucosa and tonsils for fungi', 'Ispitivanje materijala sa sluznice ždrijela i krajnika na gljivice', 'Испитивање материјала са слузнице ждријела и крајника на гљивице', 'Исследование материала со слизистой глотки и миндалин на грибы', 'Untersuchung von Material der Rachenschleimhaut und der Mandeln auf Pilze', 'Yutak mukozası ve bademciklerden alınan örnekte mantar araştırması', 'A sterile swab is wiped over the back wall of the throat and the tonsils and the material is cultured on a medium for fungi, takes less than a minute', 'Sterilnim štapićem prelazi se preko zadnjeg zida ždrijela i krajnika, materijal se zasijava na podlogu za gljivice, traje manje od minuta', 'Стерилним штапићем прелази се преко задњег зида ждријела и крајника, материјал се засијава на подлогу за гљивице, траје мање од минута', 'Стерильным тампоном проводят по задней стенке глотки и миндалинам, материал засевают на среду для грибов, занимает меньше минуты', 'Mit einem sterilen Tupfer wird über Rachenhinterwand und Mandeln gestrichen und das Material auf einem Pilznährboden angezüchtet, dauert weniger als eine Minute', 'Steril çubuk yutağın arka duvarı ve bademcikler üzerinde gezdirilir, örnek mantar besiyerine ekilir, işlem bir dakikadan kısa sürer', 'White coating in the mouth and on the tonsils, burning and discomfort in the throat, prolonged complaints after antibiotics or inhaled medicines, conditions with reduced immunity', 'Bijele naslage u ustima i na krajnicima, peckanje i nelagodnost u grlu, dugotrajne tegobe poslije antibiotika ili inhalacionih lijekova, stanja sa smanjenim imunitetom', 'Бијеле наслаге у устима и на крајницима, пецкање и нелагодност у грлу, дуготрајне тегобе послије антибиотика или инхалационих лијекова, стања са смањеним имунитетом', 'Белый налёт во рту и на миндалинах, жжение и дискомфорт в горле, длительные жалобы после антибиотиков или ингаляционных препаратов, состояния со сниженным иммунитетом', 'Weißer Belag im Mund und auf den Mandeln, Brennen und Missempfindungen im Hals, anhaltende Beschwerden nach Antibiotika oder Inhalationsmitteln, Zustände mit geschwächter Immunabwehr', 'Ağızda ve bademciklerde beyaz tabaka, boğazda yanma ve rahatsızlık, antibiyotik veya inhaler ilaç kullanımı sonrası uzayan şikayetler, bağışıklığın azaldığı durumlar', 'Taken in the morning before eating: do not brush your teeth, gargle, drink or use sprays for 2–3 hours before the procedure', 'Uzima se ujutru prije jela: ne prati zube, ne ispirati grlo, ne piti i ne koristiti sprejeve 2–3 sata prije zahvata', 'Узима се ујутру прије јела: не прати зубе, не испирати грло, не пити и не користити спрејеве 2–3 сата прије захвата', 'Забор утром до еды: не чистить зубы, не полоскать горло, не пить и не использовать спреи за 2–3 часа до процедуры', 'Entnahme morgens vor dem Essen: 2–3 Stunden vorher nicht Zähne putzen, nicht gurgeln, nicht trinken und keine Sprays anwenden', 'Sabah aç karnına alınır: işlemden 2–3 saat önce diş fırçalanmamalı, gargara yapılmamalı, bir şey içilmemeli ve sprey kullanılmamalıdır', 'Detection of fungi may be related to a change of the mucosal microflora, the use of certain medicines, or reduced immunity. The result is assessed by a doctor', 'Nalaz gljivica može biti povezan sa promjenom mikroflore sluznice, primjenom pojedinih lijekova ili smanjenim imunitetom. Nalaz procjenjuje ljekar', 'Налаз гљивица може бити повезан са промјеном микрофлоре слузнице, примјеном појединих лијекова или смањеним имунитетом. Налаз процјењује љекар', 'Обнаружение грибов может быть связано с изменением микрофлоры слизистой, применением некоторых препаратов или сниженным иммунитетом. Результат оценивает врач', 'Ein Pilznachweis kann mit einer Veränderung der Schleimhautflora, der Anwendung bestimmter Medikamente oder einer geschwächten Immunabwehr zusammenhängen. Den Befund beurteilt der Arzt', 'Mantar saptanması mukoza florasının değişmesiyle, bazı ilaçların kullanımıyla veya bağışıklığın azalmasıyla ilişkili olabilir. Sonucu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'tongue-swab-bacteria'), 'Bacteriological examination of coating and secretions from the surface of the tongue', 'Bakteriološko ispitivanje naslaga i sekreta sa površine jezika', 'Бактериолошко испитивање наслага и секрета са површине језика', 'Бактериологическое исследование налёта и отделяемого с поверхности языка', 'Bakteriologische Untersuchung von Belag und Sekret der Zungenoberfläche', 'Dilin yüzeyindeki tabaka ve salgının bakteriyolojik incelemesi', 'A sterile swab is wiped over the back of the tongue and the material is cultured on nutrient media', 'Sterilnim štapićem prelazi se preko gornje strane jezika, materijal se zasijava na hranljive podloge', 'Стерилним штапићем прелази се преко горње стране језика, материјал се засијава на хранљиве подлоге', 'Стерильным тампоном проводят по спинке языка, материал засевают на питательные среды', 'Mit einem sterilen Tupfer wird über den Zungenrücken gestrichen, das Material wird auf Nährböden angezüchtet', 'Steril çubuk dilin sırt kısmında gezdirilir, örnek besiyerlerine ekilir', 'Persistent coating on the tongue, burning and altered taste, inflammation of the oral mucosa, bad breath, follow-up after treatment', 'Uporne naslage na jeziku, peckanje i promjena ukusa, upala sluznice usta, neprijatan zadah, kontrola poslije liječenja', 'Упорне наслаге на језику, пецкање и промјена укуса, упала слузнице уста, непријатан задах, контрола послије лијечења', 'Стойкий налёт на языке, жжение и изменение вкуса, воспаление слизистой рта, неприятный запах, контроль после лечения', 'Hartnäckiger Zungenbelag, Brennen und Geschmacksveränderungen, Entzündung der Mundschleimhaut, Mundgeruch, Kontrolle nach einer Behandlung', 'Dilde geçmeyen tabaka, yanma ve tat değişikliği, ağız mukozası iltihabı, ağız kokusu, tedavi sonrası kontrol', 'Taken in the morning before eating: do not brush your teeth, use mouthwash, drink or smoke for 2–3 hours before the procedure', 'Uzima se ujutru prije jela: ne prati zube, ne koristiti vodicu za ispiranje usta, ne piti i ne pušiti 2–3 sata prije zahvata', 'Узима се ујутру прије јела: не прати зубе, не користити водицу за испирање уста, не пити и не пушити 2–3 сата прије захвата', 'Забор утром до еды: не чистить зубы, не пользоваться ополаскивателем, не пить и не курить за 2–3 часа до процедуры', 'Entnahme morgens vor dem Essen: 2–3 Stunden vorher nicht Zähne putzen, keine Mundspülung verwenden, nicht trinken und nicht rauchen', 'Sabah aç karnına alınır: işlemden 2–3 saat önce diş fırçalanmamalı, ağız suyu kullanılmamalı, bir şey içilmemeli ve sigara kullanılmamalıdır', 'Growth of bacteria may be related to inflammation of the mucosa, the condition of the teeth and oral hygiene, or a temporary change of the microflora. The meaning of the finding is determined by a doctor', 'Porast bakterija može biti povezan sa upalom sluznice, stanjem zuba i higijenom usne duplje ili privremenom promjenom mikroflore. Značenje nalaza određuje ljekar', 'Пораст бактерија може бити повезан са упалом слузнице, стањем зуба и хигијеном усне дупље или привременом промјеном микрофлоре. Значење налаза одређује љекар', 'Рост бактерий может быть связан с воспалением слизистой, состоянием зубов и гигиеной полости рта или временным изменением микрофлоры. Значение находки определяет врач', 'Ein Nachweis von Bakterien kann mit einer Schleimhautentzündung, dem Zustand der Zähne und der Mundhygiene oder einer vorübergehenden Veränderung der Mikroflora zusammenhängen. Die Bedeutung des Befunds bestimmt der Arzt', 'Bakteri üremesi mukoza iltihabıyla, diş durumu ve ağız hijyeniyle ya da mikrofloranın geçici değişimiyle ilişkili olabilir. Bulgunun anlamını hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urethral-swab-bacteria'), 'Bacteriological examination of discharge from the urethra', 'Bakteriološko ispitivanje sekreta mokraćne cijevi', 'Бактериолошко испитивање секрета мокраћне цијеви', 'Бактериологическое исследование отделяемого мочеиспускательного канала', 'Bakteriologische Untersuchung des Sekrets der Harnröhre', 'İdrar kanalı salgısının bakteriyolojik incelemesi', 'A thin sterile probe is inserted a short way into the opening of the urethra, collection takes a few seconds and may be uncomfortable', 'Tanka sterilna sonda se uvodi plitko u spoljašnji otvor uretre, uzimanje traje nekoliko sekundi i može biti neprijatno', 'Танка стерилна сонда се уводи плитко у спољашњи отвор уретре, узимање траје неколико секунди и може бити непријатно', 'Тонкий стерильный зонд вводят в наружное отверстие уретры на небольшую глубину, забор занимает несколько секунд и может быть неприятным', 'Eine dünne sterile Sonde wird ein kurzes Stück in die Harnröhrenöffnung eingeführt, die Entnahme dauert wenige Sekunden und kann unangenehm sein', 'İnce steril bir çubuk üretranın dış ağzından kısa bir mesafe ilerletilir, alım birkaç saniye sürer ve rahatsızlık verebilir', 'Discharge from the urethra, burning and pain when urinating, frequent urge to urinate, examination when planning a pregnancy or before procedures, follow-up after treatment', 'Sekret iz uretre, peckanje i bol pri mokrenju, učestali nagon za mokrenjem, ispitivanje pri planiranju trudnoće ili prije zahvata, kontrola poslije liječenja', 'Секрет из уретре, пецкање и бол при мокрењу, учестали нагон за мокрењем, испитивање при планирању трудноће или прије захвата, контрола послије лијечења', 'Выделения из уретры, жжение и боль при мочеиспускании, учащённые позывы, обследование при планировании беременности или перед вмешательствами, контроль после лечения', 'Ausfluss aus der Harnröhre, Brennen und Schmerzen beim Wasserlassen, häufiger Harndrang, Untersuchung bei Kinderwunsch oder vor Eingriffen, Kontrolle nach einer Behandlung', 'Üretradan akıntı, idrar yaparken yanma ve ağrı, sık idrara çıkma isteği, gebelik planlaması veya girişim öncesi inceleme, tedavi sonrası kontrol', 'Do not urinate for 2–3 hours before the test, avoid sexual intercourse and local antiseptics the day before; tell the doctor about any antibiotics you are taking', 'Ne mokriti 2–3 sata prije uzimanja, dan ranije izbjegavati seksualne odnose i lokalne antiseptike; obavijestiti ljekara o uzimanju antibiotika', 'Не мокрити 2–3 сата прије узимања, дан раније избјегавати сексуалне односе и локалне антисептике; обавијестити љекара о узимању антибиотика', 'Не мочиться 2–3 часа до забора, накануне исключить половые контакты и местные антисептики; о приёме антибиотиков сообщить врачу', '2–3 Stunden vor der Entnahme nicht Wasser lassen, am Vortag auf Geschlechtsverkehr und örtliche Antiseptika verzichten; eingenommene Antibiotika dem Arzt mitteilen', 'Örnekten önce 2–3 saat idrara çıkılmamalı, bir gün öncesinden cinsel ilişki ve bölgesel antiseptiklerden kaçınılmalıdır; kullanılan antibiyotikler hekime bildirilmelidir', 'Growth of bacteria may be related to inflammation of the urethra or to the presence of the usual flora of the outer part. The significance of the result and antibiotic susceptibility are assessed by a doctor', 'Porast bakterija može biti povezan sa upalom mokraćne cijevi ili sa prisustvom uobičajene flore spoljašnjeg dijela. Značaj nalaza i osjetljivost na antibiotike procjenjuje ljekar', 'Пораст бактерија може бити повезан са упалом мокраћне цијеви или са присуством уобичајене флоре спољашњег дијела. Значај налаза и осјетљивост на антибиотике процјењује љекар', 'Рост бактерий может быть связан с воспалением мочеиспускательного канала или с присутствием обычной флоры наружных отделов. Значимость результата и чувствительность к антибиотикам оценивает врач', 'Ein Nachweis von Bakterien kann mit einer Entzündung der Harnröhre oder mit der üblichen Flora des äußeren Abschnitts zusammenhängen. Die Bedeutung des Ergebnisses und die Antibiotikaempfindlichkeit beurteilt der Arzt', 'Bakteri üremesi üretra iltihabıyla ya da dış bölümün olağan florasının varlığıyla ilişkili olabilir. Sonucun önemini ve antibiyotik duyarlılığını hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urethral-swab-fungi'), 'Examination of discharge from the urethra for yeast-like fungi', 'Ispitivanje sekreta mokraćne cijevi na kvasnice', 'Испитивање секрета мокраћне цијеви на кваснице', 'Исследование отделяемого мочеиспускательного канала на дрожжеподобные грибы', 'Untersuchung des Harnröhrensekrets auf Hefepilze', 'İdrar kanalı salgısında maya mantarlarının araştırılması', 'A thin sterile probe collects material from the opening of the urethra and it is cultured on a medium for fungi', 'Tankom sterilnom sondom uzima se materijal iz spoljašnjeg otvora uretre i zasijava na podlogu za gljivice', 'Танком стерилном сондом узима се материјал из спољашњег отвора уретре и засијава на подлогу за гљивице', 'Тонким стерильным зондом берут материал из наружного отверстия уретры и засевают его на среду для грибов', 'Mit einer dünnen sterilen Sonde wird Material aus der Harnröhrenöffnung entnommen und auf einem Pilznährboden angezüchtet', 'İnce steril bir çubukla üretranın dış ağzından örnek alınır ve mantar besiyerine ekilir', 'Burning and itching when urinating, whitish discharge, recurring complaints, follow-up after a course of treatment', 'Peckanje i svrab pri mokrenju, bjelkast sekret, ponavljane tegobe, kontrola poslije završenog liječenja', 'Пецкање и свраб при мокрењу, бјелкаст секрет, понављане тегобе, контрола послије завршеног лијечења', 'Жжение и зуд при мочеиспускании, белёсые выделения, повторяющиеся жалобы, контроль после курса лечения', 'Brennen und Juckreiz beim Wasserlassen, weißlicher Ausfluss, wiederkehrende Beschwerden, Kontrolle nach einer Behandlung', 'İdrar yaparken yanma ve kaşıntı, beyazımsı akıntı, tekrarlayan şikayetler, tedavi sonrası kontrol', 'Do not urinate for 2–3 hours before the test and avoid sexual intercourse and local antifungal products the day before', 'Ne mokriti 2–3 sata prije uzimanja, dan ranije izbjegavati seksualne odnose i lokalne antimikotske preparate', 'Не мокрити 2–3 сата прије узимања, дан раније избјегавати сексуалне односе и локалне антимикотске препарате', 'Не мочиться 2–3 часа до забора, накануне исключить половые контакты и местные противогрибковые средства', '2–3 Stunden vor der Entnahme nicht Wasser lassen und am Vortag auf Geschlechtsverkehr sowie örtliche Antipilzmittel verzichten', 'Örnekten önce 2–3 saat idrara çıkılmamalı, bir gün öncesinden cinsel ilişki ve bölgesel antifungal ürünlerden kaçınılmalıdır', 'Detection of fungi may be related to a change of the local microflora, recent use of antibiotics, or accompanying conditions. The result is interpreted by a doctor', 'Nalaz gljivica može biti povezan sa promjenom lokalne mikroflore, nedavnim uzimanjem antibiotika ili pratećim stanjima. Nalaz tumači ljekar', 'Налаз гљивица може бити повезан са промјеном локалне микрофлоре, недавним узимањем антибиотика или пратећим стањима. Налаз тумачи љекар', 'Обнаружение грибов может быть связано с изменением местной микрофлоры, недавним приёмом антибиотиков или сопутствующими состояниями. Результат трактует врач', 'Ein Pilznachweis kann mit einer Veränderung der lokalen Mikroflora, einer kürzlichen Antibiotikaeinnahme oder Begleiterkrankungen zusammenhängen. Den Befund beurteilt der Arzt', 'Mantar saptanması yerel mikrofloranın değişmesiyle, yakın zamanda antibiyotik kullanımıyla veya eşlik eden durumlarla ilişkili olabilir. Sonucu hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'vaginal-swab-bacteria'), 'Microbiological culture of vaginal discharge for bacterial flora', 'Mikrobiološka kultura vaginalnog sekreta na bakterijsku floru', 'Микробиолошка култура вагиналног секрета на бактеријску флору', 'Микробиологический посев отделяемого влагалища на бактериальную флору', 'Mikrobiologische Kultur des Vaginalsekrets auf Bakterienflora', 'Vajinal akıntının bakteri florası için mikrobiyolojik kültürü', 'The doctor collects material from the vaginal wall with a sterile swab, the procedure takes a couple of minutes', 'Ljekar uzima uzorak sterilnim štapićem sa zida vagine, postupak traje nekoliko minuta', 'Љекар узима узорак стерилним штапићем са зида вагине, поступак траје неколико минута', 'Врач берёт материал стерильным тампоном со стенки влагалища, процедура занимает пару минут', 'Der Arzt entnimmt das Material mit einem sterilen Tupfer von der Scheidenwand, der Abstrich dauert wenige Minuten', 'Hekim steril bir çubukla vajen duvarından örnek alır, işlem birkaç dakika sürer', 'Discharge, itching or burning, pregnancy planning and follow-up during pregnancy, check after treatment, preparation for gynaecological procedures', 'Pojačan sekret, svrab ili peckanje, planiranje trudnoće i praćenje u trudnoći, kontrola poslije liječenja, priprema za ginekološke zahvate', 'Појачан секрет, свраб или пецкање, планирање трудноће и праћење у трудноћи, контрола послије лијечења, припрема за гинеколошке захвате', 'Выделения, зуд или жжение, планирование беременности и наблюдение при беременности, контроль после лечения, подготовка к гинекологическим вмешательствам', 'Ausfluss, Juckreiz oder Brennen, Kinderwunsch und Kontrolle in der Schwangerschaft, Kontrolle nach einer Behandlung, Vorbereitung auf gynäkologische Eingriffe', 'Akıntı, kaşıntı veya yanma, gebelik planlaması ve gebelikte izlem, tedavi sonrası kontrol, jinekolojik girişimlere hazırlık', 'For a few days before, avoid vaginal suppositories, creams and douching, do not take the sample during menstruation, avoid intercourse the day before; exact intervals are confirmed by the doctor', 'Nekoliko dana prije ne koristiti vaginalete, kreme i ispiranja, uzorak se ne uzima tokom menstruacije, izbjegavati odnose dan ranije; tačne razmake određuje ljekar', 'Неколико дана прије не користити вагиналете, креме и испирања, узорак се не узима током менструације, избјегавати односе дан раније; тачне размаке одређује љекар', 'За несколько дней не использовать вагинальные свечи, кремы и спринцевания, не сдавать во время менструации, воздержаться от половых контактов накануне; точные сроки уточняет врач', 'Einige Tage vorher keine Vaginalzäpfchen, Cremes oder Spülungen verwenden, nicht während der Menstruation abnehmen, am Vortag auf Geschlechtsverkehr verzichten; genaue Abstände legt der Arzt fest', 'Birkaç gün önce vajinal fitil, krem ve vajinal duş uygulanmamalı, örnek adet döneminde alınmamalı, bir gün önce cinsel ilişkiden kaçınılmalı; kesin süreleri hekim belirler', 'Growth of bacteria and a change in the composition of the flora may be related to inflammation or to an imbalance of the vaginal microflora. The meaning of the result and the need for treatment are determined by the doctor', 'Porast bakterija i promjena sastava flore mogu biti povezani sa upalom ili sa poremećajem ravnoteže vaginalne mikroflore. Značenje nalaza i potrebu za liječenjem procjenjuje ljekar', 'Пораст бактерија и промјена састава флоре могу бити повезани са упалом или са поремећајем равнотеже вагиналне микрофлоре. Значење налаза и потребу за лијечењем процјењује љекар', 'Рост бактерий и изменение состава флоры могут быть связаны с воспалением или нарушением баланса микрофлоры. Значение результата и необходимость лечения определяет врач', 'Ein Wachstum von Bakterien und eine veränderte Zusammensetzung der Flora können mit einer Entzündung oder einem gestörten Gleichgewicht der Scheidenflora zusammenhängen. Die Bedeutung des Befundes und die Notwendigkeit einer Behandlung beurteilt der Arzt', 'Bakteri üremesi ve flora bileşimindeki değişiklik, iltihapla veya vajinal mikroflora dengesinin bozulmasıyla ilişkili olabilir. Sonucun anlamını ve tedavi gerekip gerekmediğini hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'vaginal-swab-fungi'), 'Culture of vaginal discharge for yeast fungi, primarily of the Candida genus', 'Kultura vaginalnog sekreta na kvasnice, prije svega roda Candida', 'Култура вагиналног секрета на кваснице, прије свега рода Candida', 'Посев отделяемого влагалища на дрожжевые грибы, прежде всего рода Candida', 'Kultur des Vaginalsekrets auf Hefepilze, vor allem der Gattung Candida', 'Vajinal akıntının maya mantarları, öncelikle Candida için kültürü', 'Material is taken from the vaginal wall with a sterile swab and plated on a medium for fungi', 'Uzorak se uzima sterilnim štapićem sa zida vagine i zasijava na podlogu za gljivice', 'Узорак се узима стерилним штапићем са зида вагине и засијава на подлогу за гљивице', 'Материал берут стерильным тампоном со стенки влагалища и засевают на питательную среду для грибов', 'Das Material wird mit einem sterilen Tupfer von der Scheidenwand entnommen und auf einen Pilznährboden aufgebracht', 'Örnek steril çubukla vajen duvarından alınır ve mantar besiyerine ekilir', 'Thick curd-like discharge, itching and burning, recurring complaints, check after antifungal treatment, complaints while taking antibiotics', 'Gust sirast sekret, svrab i peckanje, tegobe koje se ponavljaju, kontrola poslije antimikotične terapije, tegobe tokom uzimanja antibiotika', 'Густ сираст секрет, свраб и пецкање, тегобе које се понављају, контрола послије антимикотичне терапије, тегобе током узимања антибиотика', 'Густые творожистые выделения, зуд и жжение, повторяющиеся жалобы, контроль после противогрибкового лечения, жалобы на фоне приёма антибиотиков', 'Dicker, quarkartiger Ausfluss, Juckreiz und Brennen, wiederkehrende Beschwerden, Kontrolle nach antimykotischer Behandlung, Beschwerden unter Antibiotikatherapie', 'Koyu peynirimsi akıntı, kaşıntı ve yanma, tekrarlayan şikayetler, antifungal tedavi sonrası kontrol, antibiyotik kullanırken ortaya çıkan şikayetler', 'For a few days before, avoid vaginal suppositories, creams and douching, do not take the sample during menstruation, avoid intercourse the day before', 'Nekoliko dana prije ne koristiti vaginalete i kreme, ne ispirati vaginu, uzorak se ne uzima tokom menstruacije, izbjegavati odnose dan ranije', 'Неколико дана прије не користити вагиналете и креме, не испирати вагину, узорак се не узима током менструације, избјегавати односе дан раније', 'За несколько дней не использовать вагинальные свечи и кремы, не спринцеваться, не сдавать во время менструации, воздержаться от половых контактов накануне', 'Einige Tage vorher keine Vaginalzäpfchen und Cremes verwenden, keine Spülungen, nicht während der Menstruation abnehmen, am Vortag auf Geschlechtsverkehr verzichten', 'Birkaç gün önce vajinal fitil ve krem kullanılmamalı, vajinal duş yapılmamalı, örnek adet döneminde alınmamalı, bir gün önce cinsel ilişkiden kaçınılmalı', 'Growth of fungi may be related to an overgrowth of yeast flora, including during antibiotic therapy, in pregnancy or with reduced immunity. Whether treatment is needed is decided by the doctor', 'Porast gljivica može biti povezan sa prekomjernim razmnožavanjem kvasnica, između ostalog uz antibiotike, u trudnoći ili kod snižene imunosti. Da li je liječenje potrebno, odlučuje ljekar', 'Пораст гљивица може бити повезан са прекомјерним размножавањем квасница, између осталог уз антибиотике, у трудноћи или код снижене имуности. Да ли је лијечење потребно, одлучује љекар', 'Рост грибов может быть связан с избыточным размножением дрожжевой флоры, в том числе на фоне антибиотиков, беременности или снижения иммунитета. Нужно ли лечение, определяет врач', 'Ein Pilzwachstum kann mit einer Vermehrung der Hefeflora zusammenhängen, unter anderem unter Antibiotika, in der Schwangerschaft oder bei geschwächter Abwehr. Ob eine Behandlung nötig ist, entscheidet der Arzt', 'Mantar üremesi, antibiyotik kullanımı, gebelik veya bağışıklığın azalması gibi durumlarda maya florasının çoğalmasıyla ilişkili olabilir. Tedavi gerekip gerekmediğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'vulvar-swab-bacteria'), 'Culture of material from the external genital area for bacterial flora', 'Kultura uzorka sa spoljašnjih genitalija na bakterijsku floru', 'Култура узорка са спољашњих гениталија на бактеријску флору', 'Посев материала с наружных половых органов на бактериальную флору', 'Kultur eines Abstrichs vom äußeren Genitalbereich auf Bakterienflora', 'Dış genital bölgeden alınan örneğin bakteri florası için kültürü', 'Material is taken with a sterile swab from the skin and mucosa of the vulva, without entering the vagina, and takes a couple of minutes', 'Uzorak se uzima sterilnim štapićem sa kože i sluznice vulve, bez ulaska u vaginu, i traje nekoliko minuta', 'Узорак се узима стерилним штапићем са коже и слузнице вулве, без уласка у вагину, и траје неколико минута', 'Материал берут стерильным тампоном с кожи и слизистой вульвы, без введения во влагалище, занимает пару минут', 'Das Material wird mit einem sterilen Tupfer von Haut und Schleimhaut der Vulva entnommen, ohne in die Scheide vorzugehen, und dauert wenige Minuten', 'Örnek steril çubukla vulva derisi ve mukozasından, vajene girilmeden alınır ve birkaç dakika sürer', 'Redness, swelling and itching of the external genitals, rashes, fissures and weeping, complaints in girls before the onset of sexual activity, check after treatment', 'Crvenilo, oticanje i svrab spoljašnjih genitalija, osip, ragade i vlaženje, tegobe kod djevojčica prije početka seksualnog života, kontrola poslije liječenja', 'Црвенило, отицање и свраб спољашњих гениталија, осип, рагаде и влажење, тегобе код дјевојчица прије почетка сексуалног живота, контрола послије лијечења', 'Покраснение, отёк и зуд наружных половых органов, высыпания, трещины и мокнутие, жалобы у девочек до начала половой жизни, контроль после лечения', 'Rötung, Schwellung und Juckreiz im äußeren Genitalbereich, Hautausschlag, Einrisse und Nässen, Beschwerden bei Mädchen vor Beginn der Sexualität, Kontrolle nach einer Behandlung', 'Dış genital bölgede kızarıklık, şişlik ve kaşıntı, döküntü, çatlak ve sulanma, cinsel yaşamı başlamamış kız çocuklarındaki şikayetler, tedavi sonrası kontrol', 'Do not apply ointments, antiseptics or powders before the visit and do not wash with soap right before the sample is taken; tell the doctor about any antibiotics taken', 'Prije uzimanja ne nanositi masti, antiseptike i puder, ne prati se sapunom neposredno prije pregleda; obavijestiti ljekara o antibioticima koji se uzimaju', 'Прије узимања не наносити масти, антисептике и пудер, не прати се сапуном непосредно прије прегледа; обавијестити љекара о антибиотицима који се узимају', 'Перед забором не наносить мази, антисептики и присыпки, не подмываться с мылом непосредственно перед приёмом; о принимаемых антибиотиках сообщить врачу', 'Vor der Entnahme keine Salben, Antiseptika oder Puder auftragen und sich unmittelbar davor nicht mit Seife waschen; eingenommene Antibiotika dem Arzt mitteilen', 'Örnek alınmadan önce merhem, antiseptik veya pudra uygulanmamalı ve hemen öncesinde sabunla yıkanmamalı; kullanılan antibiyotikler hekime bildirilmeli', 'Growth of bacteria may be related to inflammation of the vulvar skin and mucosa or to the normal flora of this area. The doctor evaluates the result together with the examination', 'Porast bakterija može biti povezan sa upalom kože i sluznice vulve ili sa uobičajenom florom tog područja. Značenje nalaza ljekar procjenjuje zajedno sa pregledom', 'Пораст бактерија може бити повезан са упалом коже и слузнице вулве или са уобичајеном флором тог подручја. Значење налаза љекар процјењује заједно са прегледом', 'Рост бактерий может быть связан с воспалением кожи и слизистой вульвы или с обычной флорой этой области. Значение результата вместе с осмотром оценивает врач', 'Ein Bakterienwachstum kann mit einer Entzündung von Haut und Schleimhaut der Vulva oder mit der üblichen Flora dieses Bereichs zusammenhängen. Der Arzt beurteilt den Befund zusammen mit der Untersuchung', 'Bakteri üremesi vulva deri ve mukozasındaki iltihapla ya da bu bölgenin olağan florasıyla ilişkili olabilir. Sonucu hekim muayeneyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'vulvar-swab-fungi'), 'Culture of material from the skin and mucosa of the vulva for yeast fungi', 'Kultura uzorka sa kože i sluznice vulve na kvasnice', 'Култура узорка са коже и слузнице вулве на кваснице', 'Посев материала с кожи и слизистой вульвы на дрожжевые грибы', 'Kultur eines Abstrichs von Haut und Schleimhaut der Vulva auf Hefepilze', 'Vulva derisi ve mukozasından alınan örneğin maya mantarları için kültürü', 'A sterile swab collects material from the vulvar surface and the skin folds, then it is plated on a medium for fungi', 'Sterilnim štapićem uzima se uzorak sa površine vulve i iz nabora, a zatim se zasijava na podlogu za gljivice', 'Стерилним штапићем узима се узорак са површине вулве и из набора, а затим се засијава на подлогу за гљивице', 'Стерильным тампоном берут материал с поверхности вульвы и из складок, затем засевают на среду для грибов', 'Mit einem sterilen Tupfer wird Material von der Vulvaoberfläche und aus den Hautfalten entnommen und auf einen Pilznährboden aufgebracht', 'Steril çubukla vulva yüzeyinden ve kıvrımlardan örnek alınır, ardından mantar besiyerine ekilir', 'Itching and burning of the external genitals, redness and whitish coating in the folds, intertrigo, recurring complaints, complaints during antibiotic therapy or with diabetes mellitus', 'Svrab i peckanje spoljašnjih genitalija, crvenilo i bjelkaste naslage u naborima, intertrigo, tegobe koje se ponavljaju, tegobe uz antibiotike ili šećernu bolest', 'Свраб и пецкање спољашњих гениталија, црвенило и бјелкасте наслаге у наборима, интертриго, тегобе које се понављају, тегобе уз антибиотике или шећерну болест', 'Зуд и жжение наружных половых органов, покраснение и белесый налёт в складках, опрелости, повторяющиеся жалобы, жалобы на фоне антибиотиков или сахарного диабета', 'Juckreiz und Brennen im äußeren Genitalbereich, Rötung und weißliche Beläge in den Falten, Wundsein der Hautfalten, wiederkehrende Beschwerden, Beschwerden unter Antibiotika oder bei Diabetes mellitus', 'Dış genital bölgede kaşıntı ve yanma, kıvrımlarda kızarıklık ve beyazımsı örtü, pişik, tekrarlayan şikayetler, antibiyotik kullanımı veya diyabet sırasındaki şikayetler', 'Do not use antifungal creams or antiseptics before the sample is taken and do not wash with soap right before the visit', 'Prije uzimanja ne koristiti antimikotične kreme i antiseptike, ne prati se sapunom neposredno prije pregleda', 'Прије узимања не користити антимикотичне креме и антисептике, не прати се сапуном непосредно прије прегледа', 'Не использовать противогрибковые кремы и антисептики перед забором, не подмываться с мылом непосредственно перед приёмом', 'Vor der Entnahme keine Antipilzcremes und Antiseptika verwenden und sich unmittelbar davor nicht mit Seife waschen', 'Örnek alınmadan önce antifungal krem ve antiseptik kullanılmamalı, hemen öncesinde sabunla yıkanmamalı', 'Growth of fungi may be related to fungal involvement of the vulvar skin and mucosa or to carriage of yeast flora. Whether treatment is needed is decided by the doctor based on the examination and the complaints', 'Porast gljivica može biti povezan sa gljivičnom promjenom kože i sluznice vulve ili sa nošenjem kvasnica. Da li je liječenje potrebno, ljekar procjenjuje na osnovu pregleda i tegoba', 'Пораст гљивица може бити повезан са гљивичном промјеном коже и слузнице вулве или са ношењем квасница. Да ли је лијечење потребно, љекар процјењује на основу прегледа и тегоба', 'Рост грибов может быть связан с грибковым поражением кожи и слизистой вульвы или с носительством дрожжевой флоры. Нужно ли лечение, определяет врач по осмотру и жалобам', 'Ein Pilzwachstum kann mit einer Pilzbesiedlung von Haut und Schleimhaut der Vulva oder mit einer Besiedlung ohne Beschwerden zusammenhängen. Ob behandelt wird, entscheidet der Arzt nach Untersuchung und Beschwerden', 'Mantar üremesi vulva deri ve mukozasındaki mantar tutulumu ya da maya florası taşıyıcılığı ile ilişkili olabilir. Tedavi kararını hekim muayene ve şikayetlere göre verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'cervical-swab-fungi'), 'Culture of material from the cervical canal for yeast fungi', 'Kultura uzorka iz kanala grlića materice na kvasnice', 'Култура узорка из канала грлића материце на кваснице', 'Посев материала из канала шейки матки на дрожжевые грибы', 'Kultur von Material aus dem Gebärmutterhalskanal auf Hefepilze', 'Rahim ağzı kanalından alınan örneğin maya mantarları için kültürü', 'The gynaecologist inserts a speculum and collects material from the cervical canal with a brush or a swab, the visit takes a few minutes', 'Ginekolog postavlja spekulum i četkicom ili štapićem uzima uzorak iz cervikalnog kanala, pregled traje nekoliko minuta', 'Гинеколог поставља спекулум и четкицом или штапићем узима узорак из цервикалног канала, преглед траје неколико минута', 'Гинеколог вводит зеркало и берёт материал щёточкой или тампоном из цервикального канала, осмотр занимает несколько минут', 'Der Gynäkologe führt ein Spekulum ein und entnimmt mit Bürstchen oder Tupfer Material aus dem Zervikalkanal, die Untersuchung dauert wenige Minuten', 'Jinekolog spekulum yerleştirir ve fırça ya da çubukla servikal kanaldan örnek alır, muayene birkaç dakika sürer', 'Persistent or recurring discharge, itching, follow-up during pregnancy, check after antifungal therapy, work-up before procedures on the cervix', 'Uporan ili povratan sekret, svrab, praćenje u trudnoći, kontrola poslije antimikotične terapije, obrada prije zahvata na grliću materice', 'Упоран или повратан секрет, свраб, праћење у трудноћи, контрола послије антимикотичне терапије, обрада прије захвата на грлићу материце', 'Стойкие или повторяющиеся выделения, зуд, наблюдение при беременности, контроль после противогрибковой терапии, обследование перед вмешательствами на шейке матки', 'Anhaltender oder wiederkehrender Ausfluss, Juckreiz, Kontrolle in der Schwangerschaft, Kontrolle nach antimykotischer Therapie, Abklärung vor Eingriffen am Gebärmutterhals', 'Sürekli veya tekrarlayan akıntı, kaşıntı, gebelikte izlem, antifungal tedavi sonrası kontrol, rahim ağzına yönelik girişimler öncesi değerlendirme', 'Not taken during menstruation; avoid vaginal medications, douching and intercourse for one to two days before', 'Ne uzima se tokom menstruacije; jedan do dva dana ranije izbjegavati vaginalne preparate, ispiranja i seksualne odnose', 'Не узима се током менструације; један до два дана раније избјегавати вагиналне препарате, испирања и сексуалне односе', 'Не сдают во время менструации; за один-два дня исключить вагинальные препараты, спринцевания и половые контакты', 'Nicht während der Menstruation; ein bis zwei Tage vorher keine Vaginalpräparate, keine Spülungen und keinen Geschlechtsverkehr', 'Adet döneminde alınmaz; bir iki gün önce vajinal ilaçlar, vajinal duş ve cinsel ilişkiden kaçınılmalı', 'Detection of fungi may be related to their overgrowth in the genital tract or to symptom-free carriage. The meaning of the result and the next steps are determined by the gynaecologist', 'Nalaz gljivica može biti povezan sa njihovim prekomjernim rastom u genitalnom traktu ili sa nošenjem bez tegoba. Značenje nalaza i dalje korake određuje ginekolog', 'Налаз гљивица може бити повезан са њиховим прекомјерним растом у гениталном тракту или са ношењем без тегоба. Значење налаза и даље кораке одређује гинеколог', 'Обнаружение грибов может быть связано с их избыточным ростом в половых путях или с бессимптомным носительством. Значение результата и дальнейшие шаги определяет гинеколог', 'Der Nachweis von Pilzen kann mit deren vermehrtem Wachstum im Genitaltrakt oder mit einer beschwerdefreien Besiedlung zusammenhängen. Bedeutung des Befundes und weiteres Vorgehen legt der Gynäkologe fest', 'Mantar saptanması, genital yolda aşırı çoğalma ya da belirtisiz taşıyıcılıkla ilişkili olabilir. Sonucun anlamını ve sonraki adımları jinekolog belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'oral-cavity-fungi'), 'Culture of material from the oral mucosa for yeast fungi', 'Kultura brisa sluznice usne duplje na kvasnice', 'Култура бриса слузнице усне дупље на кваснице', 'Посев материала со слизистой рта на дрожжевые грибы', 'Kultur eines Abstrichs der Mundschleimhaut auf Hefepilze', 'Ağız mukozasından alınan örneğin maya mantarları için kültürü', 'A sterile swab is taken from the mucosa of the cheeks, the palate and the gums, it takes less than a minute', 'Bris se uzima sterilnim štapićem sa sluznice obraza, nepca i desni, traje manje od minuta', 'Брис се узима стерилним штапићем са слузнице образа, непца и десни, траје мање од минута', 'Мазок берут стерильным тампоном со слизистой щёк, нёба и дёсен, занимает меньше минуты', 'Der Abstrich wird mit einem sterilen Tupfer von Wangenschleimhaut, Gaumen und Zahnfleisch genommen und dauert weniger als eine Minute', 'Steril çubukla yanak, damak ve diş eti mukozasından sürüntü alınır, bir dakikadan kısa sürer', 'White coating in the mouth, burning and dryness, discomfort under a removable denture, complaints during antibiotics or inhaled corticosteroids, work-up in infants', 'Bijele naslage u ustima, peckanje i suvoća, nelagoda ispod pokretne proteze, tegobe uz antibiotike ili inhalacione kortikosteroide, obrada kod odojčadi', 'Бијеле наслаге у устима, пецкање и сувоћа, нелагода испод покретне протезе, тегобе уз антибиотике или инхалационе кортикостероиде, обрада код одојчади', 'Белый налёт во рту, жжение и сухость, неприятные ощущения под съёмным протезом, жалобы на фоне антибиотиков или ингаляционных гормонов, обследование грудных детей', 'Weißliche Beläge im Mund, Brennen und Trockenheit, Beschwerden unter einer herausnehmbaren Prothese, Beschwerden unter Antibiotika oder inhalativen Kortikosteroiden, Abklärung bei Säuglingen', 'Ağızda beyaz örtü, yanma ve kuruluk, hareketli protez altında rahatsızlık, antibiyotik veya inhaler kortikosteroid kullanımı sırasındaki şikayetler, süt çocuklarında değerlendirme', 'In the morning before eating, drinking and brushing teeth, without antiseptic mouth rinses and without smoking before the sample', 'Ujutru prije jela, pića i pranja zuba, bez ispiranja usta antisepticima i bez pušenja prije uzimanja uzorka', 'Ујутру прије јела, пића и прања зуба, без испирања уста антисептицима и без пушења прије узимања узорка', 'Утром до еды, питья и чистки зубов, не полоскать рот антисептиками и не курить перед забором', 'Morgens vor dem Essen, Trinken und Zähneputzen, ohne antiseptische Mundspülungen und ohne Rauchen vor der Entnahme', 'Sabah yemek, içecek ve diş fırçalamadan önce, antiseptik gargara yapılmadan ve sigara içilmeden örnek verilmeli', 'Growth of fungi may be related to their overgrowth on the oral mucosa or to carriage without symptoms. The doctor evaluates the result together with the examination of the mouth', 'Porast gljivica može biti povezan sa njihovim prekomjernim razmnožavanjem na sluznici usta ili sa nošenjem bez tegoba. Značenje nalaza ljekar procjenjuje zajedno sa pregledom usne duplje', 'Пораст гљивица може бити повезан са њиховим прекомјерним размножавањем на слузници уста или са ношењем без тегоба. Значење налаза љекар процјењује заједно са прегледом усне дупље', 'Рост грибов может быть связан с их избыточным размножением на слизистой рта или с носительством. Значение результата оценивает врач вместе с осмотром полости рта', 'Ein Pilzwachstum kann mit einer Vermehrung auf der Mundschleimhaut oder mit einer Besiedlung ohne Beschwerden zusammenhängen. Der Arzt beurteilt den Befund zusammen mit der Untersuchung der Mundhöhle', 'Mantar üremesi ağız mukozasında aşırı çoğalma ya da belirtisiz taşıyıcılıkla ilişkili olabilir. Sonucu hekim ağız içi muayenesiyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'throat-swab-bacteria'), 'Culture of material from the tonsils and the back of the throat for bacterial flora', 'Kultura brisa krajnika i zadnjeg zida ždrijela na bakterijsku floru', 'Култура бриса крајника и задњег зида ждријела на бактеријску флору', 'Посев материала с миндалин и задней стенки глотки на бактериальную флору', 'Kultur eines Abstrichs von Mandeln und Rachenhinterwand auf Bakterienflora', 'Bademcikler ve arka boğaz duvarından alınan örneğin bakteri florası için kültürü', 'A swab is passed over the tonsils and the posterior pharyngeal wall, it takes a few seconds', 'Štapićem se prelazi preko krajnika i zadnjeg zida ždrijela, uzimanje traje nekoliko sekundi', 'Штапићем се прелази преко крајника и задњег зида ждријела, узимање траје неколико секунди', 'Тампоном проводят по миндалинам и задней стенке глотки, забор занимает несколько секунд', 'Mit dem Tupfer wird über Mandeln und Rachenhinterwand gestrichen, die Entnahme dauert wenige Sekunden', 'Çubuk bademcikler ve arka boğaz duvarı üzerinden geçirilir, alım birkaç saniye sürer', 'Sore throat, coating on the tonsils, prolonged or recurring tonsillitis, checking for carriage, work-up before planned surgery, health certificates for food industry and childcare staff', 'Bol u grlu, naslage na krajnicima, produžen ili povratan tonzilitis, provjera kliconoštva, obrada prije planirane operacije, sanitarni pregledi za rad sa hranom i u vrtićima', 'Бол у грлу, наслаге на крајницима, продужен или повратан тонзилитис, провјера клицоноштва, обрада прије планиране операције, санитарни прегледи за рад са храном и у вртићима', 'Боль в горле, налёты на миндалинах, затяжной или повторяющийся тонзиллит, проверка носительства, обследование перед плановой операцией, санитарные осмотры для работы с пищей и в детских учреждениях', 'Halsschmerzen, Beläge auf den Mandeln, langwierige oder wiederkehrende Mandelentzündung, Abklärung einer Keimträgerschaft, Vorbereitung auf geplante Operationen, Untersuchungen für Lebensmittelberufe und Kinderbetreuung', 'Boğaz ağrısı, bademciklerde örtü, uzamış veya tekrarlayan bademcik iltihabı, taşıyıcılık kontrolü, planlı ameliyat öncesi değerlendirme, gıda ve çocuk bakımı alanında çalışanların sağlık kontrolleri', 'In the morning on an empty stomach, before brushing teeth, without gargling, throat sprays or lozenges; antibiotics only as agreed with the doctor', 'Ujutru natašte, prije pranja zuba, bez ispiranja grla, sprejeva i pastila; antibiotike uzimati samo u dogovoru sa ljekarom', 'Ујутру наташте, прије прања зуба, без испирања грла, спрејева и пастила; антибиотике узимати само у договору са љекаром', 'Утром натощак, до чистки зубов, без полоскания горла, спреев и пастилок; антибиотики принимать только по согласованию с врачом', 'Morgens nüchtern, vor dem Zähneputzen, ohne Gurgeln, Rachensprays und Lutschtabletten; Antibiotika nur nach Rücksprache mit dem Arzt', 'Sabah aç karnına, diş fırçalamadan önce, gargara, boğaz spreyi ve pastil kullanmadan; antibiyotikler yalnızca hekimle görüşerek', 'Detection of bacteria may indicate an infection as well as symptom-free carriage. Whether and how to treat is decided by the doctor based on the clinical picture and the antibiogram', 'Nalaz bakterija može ukazivati na infekciju, ali i na kliconoštvo bez tegoba. Da li i kako liječiti, odlučuje ljekar na osnovu kliničke slike i antibiograma', 'Налаз бактерија може указивати на инфекцију, али и на клицоноштво без тегоба. Да ли и како лијечити, одлучује љекар на основу клиничке слике и антибиограма', 'Обнаружение бактерий может говорить как об инфекции, так и о бессимптомном носительстве. Нужно ли лечение и какое, решает врач по клинической картине и антибиотикограмме', 'Der Nachweis von Bakterien kann für eine Infektion, aber auch für eine beschwerdefreie Keimträgerschaft sprechen. Ob und wie behandelt wird, entscheidet der Arzt anhand des klinischen Bildes und des Antibiogramms', 'Bakteri saptanması enfeksiyonu da belirtisiz taşıyıcılığı da gösterebilir. Tedavi gerekip gerekmediğine ve nasıl olacağına hekim klinik tablo ve antibiyograma göre karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'tongue-swab-fungi'), 'Culture of material from the surface of the tongue for yeast fungi', 'Kultura brisa sa površine jezika na kvasnice', 'Култура бриса са површине језика на кваснице', 'Посев материала с поверхности языка на дрожжевые грибы', 'Kultur eines Abstrichs von der Zungenoberfläche auf Hefepilze', 'Dil yüzeyinden alınan örneğin maya mantarları için kültürü', 'A swab is passed over the back of the tongue and any coating on it, the procedure takes a few seconds', 'Štapićem se prelazi preko površine jezika i naslaga na njemu, postupak traje nekoliko sekundi', 'Штапићем се прелази преко површине језика и наслага на њему, поступак траје неколико секунди', 'Тампоном проводят по спинке языка и налёту на ней, процедура занимает несколько секунд', 'Mit dem Tupfer wird über den Zungenrücken und vorhandene Beläge gestrichen, das dauert wenige Sekunden', 'Çubuk dil sırtı ve üzerindeki örtü boyunca geçirilir, işlem birkaç saniye sürer', 'White or curd-like coating on the tongue, burning and altered taste, dry mouth, complaints during antibiotics, with dentures or with inhalers', 'Bijele ili siraste naslage na jeziku, peckanje i promjena ukusa, suva usta, tegobe uz antibiotike, zubne proteze ili inhalatore', 'Бијеле или сирасте наслаге на језику, пецкање и промјена укуса, сува уста, тегобе уз антибиотике, зубне протезе или инхалаторе', 'Белый или творожистый налёт на языке, жжение и изменение вкуса, сухость во рту, жалобы на фоне антибиотиков, зубных протезов или ингаляторов', 'Weißer oder quarkartiger Belag auf der Zunge, Brennen und Geschmacksveränderung, Mundtrockenheit, Beschwerden unter Antibiotika, mit Zahnersatz oder Inhalatoren', 'Dilde beyaz veya peynirimsi örtü, yanma ve tat değişikliği, ağız kuruluğu, antibiyotik kullanımı, protez veya inhaler kullananlardaki şikayetler', 'Before eating, drinking and brushing teeth, without antiseptic rinses and without cleaning the tongue with a scraper', 'Prije jela, pića i pranja zuba, bez ispiranja antisepticima i bez čišćenja jezika strugačem', 'Прије јела, пића и прања зуба, без испирања антисептицима и без чишћења језика стругачем', 'До еды, питья и чистки зубов, без полосканий антисептиками и без чистки языка скребком', 'Vor dem Essen, Trinken und Zähneputzen, ohne antiseptische Spülungen und ohne Reinigung der Zunge mit einem Schaber', 'Yemek, içecek ve diş fırçalamadan önce, antiseptik gargara yapılmadan ve dil kazıyıcı kullanılmadan', 'Growth of fungi may be related to their overgrowth on the tongue or to carriage, including in smokers and denture wearers. The interpretation is given by the doctor taking the examination into account', 'Porast gljivica može biti povezan sa njihovim prekomjernim razmnožavanjem na jeziku ili sa nošenjem, i kod pušača i kod nosilaca proteza. Tumačenje daje ljekar uz pregled', 'Пораст гљивица може бити повезан са њиховим прекомјерним размножавањем на језику или са ношењем, и код пушача и код носилаца протеза. Тумачење даје љекар уз преглед', 'Рост грибов может быть связан с их избыточным размножением на языке или с носительством, в том числе у курильщиков и носителей протезов. Трактовку даёт врач с учётом осмотра', 'Ein Pilzwachstum kann mit einer Vermehrung auf der Zunge oder mit einer Besiedlung zusammenhängen, auch bei Rauchern und Prothesenträgern. Die Deutung erfolgt durch den Arzt unter Berücksichtigung der Untersuchung', 'Mantar üremesi dilde aşırı çoğalma ya da taşıyıcılıkla ilişkili olabilir, bu sigara içenlerde ve protez kullananlarda da görülür. Yorumu hekim muayeneyle birlikte yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urine-culture'), 'Bacteriological testing of urine with determination of antibiotic sensitivity', 'Zasijavanje urina radi otkrivanja bakterija i određivanja njihove osjetljivosti na antibiotike', 'Засијавање урина ради откривања бактерија и одређивања њихове осјетљивости на антибиотике', 'Бактериологическое исследование мочи с определением чувствительности бактерий к антибиотикам', 'Bakteriologische Untersuchung des Urins mit Bestimmung der Antibiotikaempfindlichkeit', 'İdrarda bakteri saptamak ve antibiyotik duyarlılığını belirlemek için yapılan bakteriyolojik inceleme', 'The patient collects a midstream portion of morning urine into a sterile container, the laboratory plates the sample on a nutrient medium', 'Pacijent sam sakuplja srednji mlaz jutarnjeg urina u sterilnu posudu, a laboratorija uzorak zasijava na hranljivu podlogu', 'Пацијент сам сакупља средњи млаз јутарњег урина у стерилну посуду, а лабораторија узорак засијава на хранљиву подлогу', 'Пациент сам собирает среднюю порцию утренней мочи в стерильный контейнер, лаборатория засевает материал на питательную среду', 'Der Patient fängt selbst den Mittelstrahl des Morgenurins in einem sterilen Gefäß auf, das Labor bringt die Probe auf einen Nährboden', 'Hasta sabah idrarının orta kısmını steril kaba kendisi toplar, laboratuvar örneği besiyerine eker', 'Burning and frequent urination, pain in the lower abdomen or in the lower back, recurring urinary tract infections, follow-up during pregnancy, check after treatment', 'Peckanje i često mokrenje, bol u donjem dijelu trbuha ili u krstima, ponavljane infekcije mokraćnih puteva, praćenje u trudnoći, kontrola poslije liječenja', 'Пецкање и често мокрење, бол у доњем дијелу трбуха или у крстима, понављане инфекције мокраћних путева, праћење у трудноћи, контрола послије лијечења', 'Жжение и частое мочеиспускание, боль внизу живота или в пояснице, повторяющиеся инфекции мочевых путей, наблюдение при беременности, контроль после лечения', 'Brennen und häufiges Wasserlassen, Schmerzen im Unterbauch oder in der Flanke, wiederkehrende Harnwegsinfekte, Kontrolle in der Schwangerschaft, Kontrolle nach einer Behandlung', 'İdrarda yanma ve sık idrara çıkma, alt karın veya bel ağrısı, tekrarlayan idrar yolu enfeksiyonları, gebelikte izlem, tedavi sonrası kontrol', 'Collect the midstream morning portion into a sterile container after washing the external genitals, before starting antibiotics or as instructed by the doctor, and deliver it to the laboratory as soon as possible', 'Sakupiti srednji mlaz jutarnjeg urina u sterilnu posudu poslije pranja spoljašnjih genitalija, prije početka antibiotika ili po uputstvu ljekara, i dostaviti u laboratoriju što prije', 'Сакупити средњи млаз јутарњег урина у стерилну посуду послије прања спољашњих гениталија, прије почетка антибиотика или по упутству љекара, и доставити у лабораторију што прије', 'Собрать среднюю порцию утренней мочи после туалета наружных половых органов в стерильный контейнер, до начала приёма антибиотиков или по указанию врача, и доставить в лабораторию как можно быстрее', 'Den Mittelstrahl des Morgenurins nach Reinigung des Genitalbereichs in einem sterilen Gefäß auffangen, vor Beginn einer Antibiotikatherapie oder nach ärztlicher Anweisung, und möglichst rasch ins Labor bringen', 'Dış genital bölge temizlendikten sonra sabah idrarının orta kısmı steril kaba toplanmalı, antibiyotiğe başlamadan önce veya hekimin önerdiği şekilde verilmeli ve laboratuvara en kısa sürede ulaştırılmalı', 'Growth of bacteria may be related to a urinary tract infection and also to errors in collecting the sample. The result together with the antibiogram is assessed by the doctor', 'Porast bakterija može biti povezan sa infekcijom mokraćnih puteva, ali i sa greškama pri sakupljanju uzorka. Nalaz zajedno sa antibiogramom procjenjuje ljekar', 'Пораст бактерија може бити повезан са инфекцијом мокраћних путева, али и са грешкама при сакупљању узорка. Налаз заједно са антибиограмом процјењује љекар', 'Рост бактерий может быть связан с инфекцией мочевых путей, а также с погрешностями сбора материала. Результат вместе с антибиотикограммой оценивает врач', 'Ein Bakterienwachstum kann mit einem Harnwegsinfekt, aber auch mit Fehlern bei der Probengewinnung zusammenhängen. Befund und Antibiogramm beurteilt der Arzt', 'Bakteri üremesi idrar yolu enfeksiyonuyla olduğu kadar örnek toplama hatalarıyla da ilişkili olabilir. Sonucu antibiyogramla birlikte hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'amine-test'), 'Quick bedside test on vaginal discharge: the odour is assessed after adding an alkaline solution', 'Brzi test vaginalnog sekreta: miris se procjenjuje poslije dodavanja alkalnog rastvora', 'Брзи тест вагиналног секрета: мирис се процјењује послије додавања алкалног раствора', 'Быстрая проба отделяемого влагалища: запах оценивают после добавления щелочного раствора', 'Schnelltest des Vaginalsekrets: der Geruch wird nach Zugabe einer alkalischen Lösung beurteilt', 'Vajinal akıntıya uygulanan hızlı test: alkali çözelti eklendikten sonra koku değerlendirilir', 'A drop of discharge is mixed with KOH solution and the odour is assessed immediately, it takes less than a minute', 'Kap sekreta se pomiješa sa rastvorom KOH i miris se odmah procjenjuje, traje manje od minuta', 'Кап секрета се помијеша са раствором KOH и мирис се одмах процјењује, траје мање од минута', 'Каплю отделяемого смешивают с раствором KOH и сразу оценивают запах, занимает меньше минуты', 'Ein Tropfen Sekret wird mit KOH-Lösung vermischt und der Geruch sofort beurteilt, das dauert weniger als eine Minute', 'Bir damla akıntı KOH çözeltisiyle karıştırılır ve koku hemen değerlendirilir, bir dakikadan kısa sürer', 'Discharge with an odour, work-up of a suspected change in the vaginal flora, usually together with a smear and a pH test', 'Sekret sa mirisom, obrada kod sumnje na promjenu vaginalne flore, obično uz nativni bris i pH test', 'Секрет са мирисом, обрада код сумње на промјену вагиналне флоре, обично уз нативни брис и пХ тест', 'Выделения с запахом, обследование при подозрении на изменение микрофлоры влагалища, обычно вместе с мазком и pH-тестом', 'Ausfluss mit Geruch, Abklärung bei Verdacht auf eine veränderte Scheidenflora, meist zusammen mit Nativpräparat und pH-Test', 'Kokulu akıntı, vajinal florada değişiklik düşünüldüğünde yapılan değerlendirme, genellikle sürüntü ve pH testiyle birlikte', 'Not done during menstruation; avoid douching, vaginal medications and intercourse the day before', 'Ne radi se tokom menstruacije; dan ranije izbjegavati ispiranja, vaginalne preparate i seksualne odnose', 'Не ради се током менструације; дан раније избјегавати испирања, вагиналне препарате и сексуалне односе', 'Не проводят во время менструации; накануне исключить спринцевания, вагинальные препараты и половые контакты', 'Nicht während der Menstruation; am Vortag keine Spülungen, keine Vaginalpräparate und keinen Geschlechtsverkehr', 'Adet döneminde yapılmaz; bir gün önce vajinal duş, vajinal ilaç ve cinsel ilişkiden kaçınılmalı', 'A positive test may be related to a change in the composition of the vaginal flora. It is only one of several signs, and the conclusion is drawn by the doctor together with the smear and other tests', 'Pozitivan test može biti povezan sa promjenom sastava vaginalne flore. To je samo jedan od znakova, a zaključak donosi ljekar zajedno sa brisom i drugim testovima', 'Позитиван тест може бити повезан са промјеном састава вагиналне флоре. То је само један од знакова, а закључак доноси љекар заједно са брисом и другим тестовима', 'Положительная проба может быть связана с изменением состава микрофлоры влагалища. Это лишь один из признаков, итог оценивает врач вместе с мазком и другими тестами', 'Ein positiver Test kann mit einer veränderten Zusammensetzung der Scheidenflora zusammenhängen. Er ist nur eines von mehreren Zeichen, die Gesamtbeurteilung nimmt der Arzt zusammen mit dem Abstrich und weiteren Tests vor', 'Testin pozitif olması vajinal flora bileşimindeki değişiklikle ilişkili olabilir. Bu yalnızca bulgulardan biridir, sonucu hekim sürüntü ve diğer testlerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'blood-culture'), 'Test that detects bacteria which have entered the bloodstream by growing them in culture bottles', 'Zasijavanje krvi radi otkrivanja bakterija dospjelih u krvotok', 'Засијавање крви ради откривања бактерија доспјелих у крвоток', 'Посев крови для выявления бактерий, попавших в кровоток', 'Nachweis von Bakterien, die in die Blutbahn gelangt sind, durch Anzucht in Kulturflaschen', 'Kan dolaşımına geçmiş bakterileri besiyerli şişelerde üreterek saptayan inceleme', 'Blood is drawn from a vein after careful skin disinfection and put straight into bottles with culture medium, usually from two separate punctures', 'Krv se vadi iz vene poslije pažljive dezinfekcije kože i odmah unosi u bočice sa hranljivom podlogom, obično iz dva odvojena uboda', 'Крв се вади из вене послије пажљиве дезинфекције коже и одмах уноси у бочице са хранљивом подлогом, обично из два одвојена убода', 'Кровь берут из вены после тщательной обработки кожи и сразу вносят во флаконы с питательной средой, обычно из двух отдельных проколов', 'Blut wird nach sorgfältiger Hautdesinfektion aus einer Vene entnommen und sofort in Flaschen mit Nährmedium gegeben, meist aus zwei getrennten Punktionen', 'Kan, deri dikkatle dezenfekte edildikten sonra damardan alınır ve doğrudan besiyerli şişelere konur, genellikle iki ayrı girişimle', 'High fever and chills of unclear origin, suspected severe infection, fever in a patient with a catheter or an implant, monitoring in hospital', 'Visoka temperatura i drhtavica nejasnog porijekla, sumnja na tešku infekciju, temperatura kod pacijenta sa kateterom ili ugrađenim materijalom, praćenje u bolnici', 'Висока температура и дрхтавица нејасног поријекла, сумња на тешку инфекцију, температура код пацијента са катетером или уграђеним материјалом, праћење у болници', 'Высокая температура и озноб неясного происхождения, подозрение на тяжёлую инфекцию, лихорадка у пациента с катетером или имплантом, наблюдение в стационаре', 'Hohes Fieber und Schüttelfrost unklarer Ursache, Verdacht auf eine schwere Infektion, Fieber bei Patienten mit Katheter oder Implantat, Überwachung im Krankenhaus', 'Nedeni belirsiz yüksek ateş ve titreme, ağır enfeksiyon düşünülmesi, kateteri veya implantı olan hastada ateş, hastanede izlem', 'No special preparation; the sample is usually taken before antibiotics are started or just before the next dose, most often as the temperature rises', 'Nema posebne pripreme; uzorak se nastoji uzeti prije uvođenja antibiotika ili neposredno prije sljedeće doze, najčešće pri porastu temperature', 'Нема посебне припреме; узорак се настоји узети прије увођења антибиотика или непосредно прије сљедеће дозе, најчешће при порасту температуре', 'Специальной подготовки нет; кровь стараются взять до начала антибиотиков или перед очередной дозой, чаще на подъёме температуры', 'Keine besondere Vorbereitung; die Probe wird möglichst vor Beginn einer Antibiotikatherapie oder kurz vor der nächsten Gabe entnommen, meist beim Fieberanstieg', 'Özel bir hazırlık gerekmez; örnek genellikle antibiyotiğe başlamadan önce veya bir sonraki dozdan hemen önce, çoğunlukla ateş yükselirken alınır', 'Growth of bacteria may indicate that a pathogen has entered the blood, but it may also result from contamination of the sample with skin flora. The result and the antibiogram are assessed by the doctor', 'Porast bakterija može značiti da je uzročnik dospio u krv, ali može biti i posljedica kontaminacije uzorka kožnom florom. Nalaz i antibiogram procjenjuje ljekar', 'Пораст бактерија може значити да је узрочник доспио у крв, али може бити и посљедица контаминације узорка кожном флором. Налаз и антибиограм процјењује љекар', 'Рост бактерий может говорить о попадании возбудителя в кровь, а может быть следствием загрязнения пробы кожной флорой. Результат и антибиотикограмму оценивает врач', 'Ein Bakterienwachstum kann bedeuten, dass ein Erreger ins Blut gelangt ist, kann aber auch durch eine Verunreinigung der Probe mit Hautflora entstehen. Befund und Antibiogramm beurteilt der Arzt', 'Bakteri üremesi etkenin kana geçtiğini gösterebileceği gibi örneğin deri florasıyla kirlenmesinden de kaynaklanabilir. Sonucu ve antibiyogramı hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ear-swab-fungi'), 'Culture of material from the external ear canal for yeast and mould fungi', 'Kultura uzorka iz spoljašnjeg slušnog kanala na kvasnice i plijesni', 'Култура узорка из спољашњег слушног канала на кваснице и плијесни', 'Посев материала из наружного слухового прохода на дрожжевые и плесневые грибы', 'Kultur eines Abstrichs aus dem äußeren Gehörgang auf Hefe- und Schimmelpilze', 'Dış kulak yolundan alınan örneğin maya ve küf mantarları için kültürü', 'The doctor takes material from the ear canal with a thin sterile swab, it takes a couple of minutes', 'Ljekar tankim sterilnim štapićem uzima uzorak iz spoljašnjeg slušnog kanala, traje nekoliko minuta', 'Љекар танким стерилним штапићем узима узорак из спољашњег слушног канала, траје неколико минута', 'Врач берёт материал тонким стерильным тампоном из наружного слухового прохода, занимает пару минут', 'Der Arzt entnimmt mit einem dünnen sterilen Tupfer Material aus dem äußeren Gehörgang, das dauert wenige Minuten', 'Hekim ince steril bir çubukla dış kulak yolundan örnek alır, işlem birkaç dakika sürer', 'Itching and a blocked feeling in the ear, discharge, long-lasting inflammation of the outer ear that does not respond to treatment, complaints after swimming or in users of hearing aids and earphones', 'Svrab i osjećaj zapušenosti uha, sekrecija, dugotrajna upala spoljašnjeg uha bez odgovora na terapiju, tegobe poslije kupanja ili kod korisnika slušnih aparata i slušalica', 'Свраб и осјећај запушености уха, секреција, дуготрајна упала спољашњег уха без одговора на терапију, тегобе послије купања или код корисника слушних апарата и слушалица', 'Зуд и заложенность уха, выделения, длительное воспаление наружного уха без эффекта от лечения, жалобы после купания или у пользователей слуховых аппаратов и наушников', 'Juckreiz und Verstopfungsgefühl im Ohr, Sekretion, langwierige Entzündung des äußeren Ohrs ohne Besserung unter Therapie, Beschwerden nach dem Schwimmen oder bei Trägern von Hörgeräten und Kopfhörern', 'Kulakta kaşıntı ve tıkanıklık hissi, akıntı, tedaviye yanıt vermeyen uzun süreli dış kulak iltihabı, yüzme sonrası veya işitme cihazı ve kulaklık kullananlardaki şikayetler', 'Do not use ear drops and do not clean the ear before the sample; if drops have already been used, tell the doctor', 'Prije uzimanja uzorka ne ukapavati kapi i ne čistiti uho; ako su kapi već korišćene, obavijestiti ljekara', 'Прије узимања узорка не укапавати капи и не чистити ухо; ако су капи већ коришћене, обавијестити љекара', 'Перед забором не закапывать капли и не чистить ухо; если капли уже применялись, сообщить врачу', 'Vor der Entnahme keine Ohrentropfen anwenden und das Ohr nicht reinigen; wurden bereits Tropfen verwendet, den Arzt informieren', 'Örnek alınmadan önce kulak damlası damlatılmamalı ve kulak temizlenmemeli; damla kullanıldıysa hekime bildirilmeli', 'Growth of fungi may be related to a fungal inflammation of the external ear or to carriage. How to interpret the result is decided by the ENT doctor', 'Porast gljivica može biti povezan sa gljivičnom upalom spoljašnjeg uha ili sa nošenjem bez tegoba. Kako tumačiti nalaz, odlučuje ORL ljekar', 'Пораст гљивица може бити повезан са гљивичном упалом спољашњег уха или са ношењем без тегоба. Како тумачити налаз, одлучује ОРЛ љекар', 'Рост грибов может быть связан с грибковым воспалением наружного уха или с носительством. Как трактовать результат, решает ЛОР-врач', 'Ein Pilzwachstum kann mit einer Pilzentzündung des äußeren Ohrs oder mit einer Besiedlung ohne Beschwerden zusammenhängen. Wie der Befund zu deuten ist, entscheidet der HNO-Arzt', 'Mantar üremesi dış kulak mantar iltihabı ya da belirtisiz taşıyıcılıkla ilişkili olabilir. Sonucun nasıl yorumlanacağına KBB hekimi karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'eye-swab-chlamydia'), 'Testing of material from the conjunctiva for Chlamydia trachomatis', 'Ispitivanje uzorka sa konjunktive na Chlamydia trachomatis', 'Испитивање узорка са коњунктиве на Chlamydia trachomatis', 'Исследование материала с конъюнктивы на Chlamydia trachomatis', 'Untersuchung eines Abstrichs von der Bindehaut auf Chlamydia trachomatis', 'Konjonktivadan alınan örnekte Chlamydia trachomatis araştırılması', 'Material is collected with a swab or a brush from the inner surface of the eyelid, the procedure takes a couple of minutes', 'Uzorak se uzima štapićem ili četkicom sa unutrašnje strane kapka, postupak traje nekoliko minuta', 'Узорак се узима штапићем или четкицом са унутрашње стране капка, поступак траје неколико минута', 'Материал берут тампоном или щёточкой с внутренней поверхности века, процедура занимает пару минут', 'Das Material wird mit Tupfer oder Bürstchen von der Innenseite des Lids entnommen, die Entnahme dauert wenige Minuten', 'Örnek göz kapağının iç yüzünden çubuk veya fırçayla alınır, işlem birkaç dakika sürer', 'Prolonged conjunctivitis that does not respond to usual treatment, conjunctivitis in newborns, testing on referral from an ophthalmologist', 'Dugotrajan konjunktivitis koji ne reaguje na uobičajenu terapiju, konjunktivitis kod novorođenčadi, ispitivanje po uputu oftalmologa', 'Дуготрајан коњунктивитис који не реагује на уобичајену терапију, коњунктивитис код новорођенчади, испитивање по упуту офталмолога', 'Затяжной конъюнктивит, не отвечающий на обычное лечение, конъюнктивит у новорождённых, обследование по направлению офтальмолога', 'Langwierige Bindehautentzündung ohne Besserung unter üblicher Therapie, Bindehautentzündung bei Neugeborenen, Untersuchung auf Überweisung des Augenarztes', 'Olağan tedaviye yanıt vermeyen uzamış konjonktivit, yenidoğanda konjonktivit, göz hekiminin yönlendirmesiyle yapılan inceleme', 'Do not use eye drops or ointments before the sample and avoid eye make-up; the interval after antibiotics is specified by the doctor', 'Prije uzimanja uzorka ne ukapavati kapi i ne nanositi masti, izbjegavati šminku za oči; razmak poslije antibiotika određuje ljekar', 'Прије узимања узорка не укапавати капи и не наносити масти, избјегавати шминку за очи; размак послије антибиотика одређује љекар', 'Перед забором не закапывать глазные капли и не наносить мази, не пользоваться косметикой для глаз; паузу после антибиотиков уточняет врач', 'Vor der Entnahme keine Augentropfen und Salben anwenden, kein Augen-Make-up; den Abstand zu einer Antibiotikatherapie legt der Arzt fest', 'Örnek alınmadan önce göz damlası ve merhem kullanılmamalı, göz makyajından kaçınılmalı; antibiyotik sonrası beklenecek süreyi hekim belirler', 'Detection of the pathogen means that chlamydia was found in the sample and calls for a discussion of the next steps with the doctor. A negative result does not always rule out infection, the assessment is made together with the clinical picture', 'Nalaz uzročnika znači da su u uzorku nađene hlamidije i zahtijeva dogovor o daljim koracima sa ljekarom. Negativan nalaz ne isključuje uvijek infekciju, procjena se donosi zajedno sa kliničkom slikom', 'Налаз узрочника значи да су у узорку нађене хламидије и захтијева договор о даљим корацима са љекаром. Негативан налаз не искључује увијек инфекцију, процјена се доноси заједно са клиничком сликом', 'Обнаружение возбудителя означает, что в материале найдены хламидии, и требует обсуждения дальнейших шагов с врачом. Отрицательный результат не всегда исключает инфекцию, оценка проводится вместе с клинической картиной', 'Der Nachweis des Erregers bedeutet, dass im Material Chlamydien gefunden wurden, und erfordert die Besprechung der weiteren Schritte mit dem Arzt. Ein negativer Befund schließt eine Infektion nicht immer aus, die Beurteilung erfolgt zusammen mit dem klinischen Bild', 'Etkenin saptanması örnekte klamidya bulunduğu anlamına gelir ve sonraki adımların hekimle görüşülmesini gerektirir. Negatif sonuç enfeksiyonu her zaman dışlamaz, değerlendirme klinik tabloyla birlikte yapılır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'pap-papanicolaou-test'), 'Cytological examination of cells from the cervix as part of screening', 'Citološki pregled ćelija grlića materice u sklopu skrininga', 'Цитолошки преглед ћелија грлића материце у склопу скрининга', 'Цитологическое исследование клеток шейки матки в рамках скрининга', 'Zytologische Untersuchung von Zellen des Gebärmutterhalses im Rahmen der Vorsorge', 'Tarama kapsamında rahim ağzı hücrelerinin sitolojik incelemesi', 'The gynaecologist inserts a speculum and collects cells from the surface of the cervix and from the cervical canal with a brush, the visit takes a few minutes', 'Ginekolog postavlja spekulum i četkicom uzima ćelije sa površine grlića i iz cervikalnog kanala, pregled traje nekoliko minuta', 'Гинеколог поставља спекулум и четкицом узима ћелије са површине грлића и из цервикалног канала, преглед траје неколико минута', 'Гинеколог вводит зеркало и берёт клетки с поверхности шейки матки и из цервикального канала щёточкой, осмотр занимает несколько минут', 'Der Gynäkologe führt ein Spekulum ein und entnimmt mit einem Bürstchen Zellen von der Oberfläche des Muttermunds und aus dem Zervikalkanal, die Untersuchung dauert wenige Minuten', 'Jinekolog spekulum yerleştirir ve fırçayla rahim ağzı yüzeyinden ve servikal kanaldan hücre alır, muayene birkaç dakika sürer', 'Routine screening according to age and schedule, follow-up after changes found in previous smears, work-up before certain gynaecological procedures', 'Redovan skrining prema uzrastu i rasporedu, praćenje poslije ranije uočenih promjena u brisu, obrada prije pojedinih ginekoloških zahvata', 'Редован скрининг према узрасту и распореду, праћење послије раније уочених промјена у брису, обрада прије појединих гинеколошких захвата', 'Плановый скрининг по возрасту и графику, наблюдение после ранее выявленных изменений в мазке, обследование перед отдельными гинекологическими вмешательствами', 'Reguläre Vorsorge entsprechend Alter und Intervall, Kontrolle nach auffälligen Vorbefunden, Abklärung vor bestimmten gynäkologischen Eingriffen', 'Yaşa ve programa göre düzenli tarama, önceki sonuçlarda değişiklik saptananlarda izlem, bazı jinekolojik girişimler öncesi değerlendirme', 'Not taken during menstruation; avoid vaginal medications, douching and intercourse for one to two days before', 'Ne uzima se tokom menstruacije; jedan do dva dana ranije izbjegavati vaginalne preparate, ispiranja i seksualne odnose', 'Не узима се током менструације; један до два дана раније избјегавати вагиналне препарате, испирања и сексуалне односе', 'Не сдают во время менструации; за один-два дня исключить вагинальные препараты, спринцевания и половые контакты', 'Nicht während der Menstruation; ein bis zwei Tage vorher keine Vaginalpräparate, keine Spülungen und keinen Geschlechtsverkehr', 'Adet döneminde alınmaz; bir iki gün önce vajinal ilaç, vajinal duş ve cinsel ilişkiden kaçınılmalı', 'Changes in the cells may be related to inflammation, hormonal influences or to changes in the epithelium that require follow-up. The result is reported using a standard classification, and the gynaecologist decides on further steps and on the timing of a repeat test', 'Promjene ćelija mogu biti povezane sa upalom, hormonskim uticajima ili sa promjenama epitela koje traže praćenje. Nalaz se opisuje standardnom klasifikacijom, a dalji postupak i rok ponovnog pregleda određuje ginekolog', 'Промјене ћелија могу бити повезане са упалом, хормонским утицајима или са промјенама епитела које траже праћење. Налаз се описује стандардном класификацијом, а даљи поступак и рок поновног прегледа одређује гинеколог', 'Изменения клеток могут быть связаны с воспалением, гормональными влияниями или с изменениями эпителия, требующими наблюдения. Результат описывают по стандартной классификации, дальнейшую тактику и срок повторного обследования определяет гинеколог', 'Zellveränderungen können mit einer Entzündung, hormonellen Einflüssen oder mit Veränderungen des Epithels zusammenhängen, die eine Kontrolle erfordern. Der Befund wird nach einer Standardklassifikation beschrieben, das weitere Vorgehen und den Zeitpunkt der Kontrolle legt der Gynäkologe fest', 'Hücrelerdeki değişiklikler iltihap, hormonal etkenler veya izlem gerektiren epitel değişiklikleriyle ilişkili olabilir. Sonuç standart bir sınıflandırmayla bildirilir, sonraki adımlara ve kontrol zamanına jinekolog karar verir')
