INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urea-clearance'), 'Measure of urea removal by the kidneys, calculated from blood and a 24-hour urine sample', 'Pokazatelj izlučivanja ureje preko bubrega, izračunat iz krvi i 24-časovnog urina', 'Показатељ излучивања уреје преко бубрега, израчунат из крви и 24-часовног урина', 'Показатель выведения мочевины почками, рассчитываемый по крови и суточной моче', 'Kennwert der Harnstoffausscheidung durch die Nieren, berechnet aus Blut und 24-Stunden-Urin', 'Kan ve 24 saatlik idrardan hesaplanan, böbreklerin üreyi atma yeteneğini gösteren ölçüm', 'Urine collection over 24 hours together with a venous blood draw', 'Sakupljanje urina tokom 24 sata uz uzimanje venske krvi', 'Сакупљање урина током 24 сата уз узимање венске крви', 'Сбор мочи за 24 часа вместе с забором венозной крови', 'Urinsammlung über 24 Stunden zusammen mit einer venösen Blutentnahme', '24 saat boyunca idrar biriktirilmesi ve venöz kan alınması', 'Additional assessment of kidney excretory function, follow-up in chronic kidney disease, clarifying the results of other kidney tests', 'Dodatna procjena izlučne funkcije bubrega, praćenje kod hronične bubrežne bolesti, pojašnjenje nalaza drugih bubrežnih proba', 'Додатна процјена излучне функције бубрега, праћење код хроничне бубрежне болести, појашњење налаза других бубрежних проба', 'Дополнительная оценка выделительной функции почек, наблюдение при хронической болезни почек, уточнение результатов других почечных проб', 'Ergänzende Beurteilung der Ausscheidungsfunktion der Nieren, Verlaufskontrolle bei chronischer Nierenerkrankung, Präzisierung anderer Nierenwerte', 'Böbreklerin atım işlevinin ek değerlendirmesi, kronik böbrek hastalığında izlem, diğer böbrek testlerinin sonuçlarının netleştirilmesi', 'Collect all urine for 24 hours into the laboratory container and keep it cool; discuss fluid intake and diet during the collection days with your doctor', 'Sav urin se 24 sata sakuplja u posudu iz laboratorije i čuva na hladnom; unos tečnosti i ishranu tokom dana sakupljanja dogovoriti sa ljekarom', 'Сав урин се 24 сата сакупља у посуду из лабораторије и чува на хладном; унос течности и исхрану током дана сакупљања договорити са љекаром', 'Сутки собирать всю мочу в ёмкость из лаборатории и хранить её в прохладном месте; питьевой режим и питание в дни сбора обсудить с врачом', 'Den gesamten Urin 24 Stunden im Laborgefäß sammeln und kühl aufbewahren; Trinkmenge und Ernährung an den Sammeltagen mit dem Arzt besprechen', 'Tüm idrar 24 saat boyunca laboratuvar kabında biriktirilir ve serin yerde saklanır; toplama günlerindeki sıvı alımı ve beslenme hekimle görüşülmelidir', 'Deviations may be related to kidney function, the amount of fluid consumed, the protein content of the diet or errors in urine collection. A doctor assesses the value together with creatinine', 'Odstupanja mogu biti povezana sa radom bubrega, količinom unijete tečnosti, količinom bjelančevina u ishrani ili greškama pri sakupljanju urina. Ljekar nalaz procjenjuje zajedno sa kreatininom', 'Одступања могу бити повезана са радом бубрега, количином унијете течности, количином бјеланчевина у исхрани или грешкама при сакупљању урина. Љекар налаз процјењује заједно са креатинином', 'Отклонения могут быть связаны с работой почек, объёмом выпитой жидкости, количеством белка в питании или ошибками сбора мочи. Врач оценивает показатель вместе с креатинином', 'Abweichungen können mit der Nierenfunktion, der Trinkmenge, dem Eiweißanteil der Ernährung oder Fehlern bei der Urinsammlung zusammenhängen. Der Arzt beurteilt den Wert zusammen mit dem Kreatinin', 'Sapmalar böbrek fonksiyonu, alınan sıvı miktarı, beslenmedeki protein miktarı veya idrar toplamadaki hatalarla ilişkili olabilir. Hekim sonucu kreatininle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'direct-bilirubin'), 'Blood test for the bilirubin fraction already processed (conjugated) by the liver', 'Analiza krvi na frakciju bilirubina koju je jetra već vezala (konjugovala)', 'Анализа крви на фракцију билирубина коју је јетра већ везала (коњуговала)', 'Анализ крови на связанную печенью фракцию билирубина', 'Bluttest auf den Bilirubinanteil, den die Leber bereits umgewandelt (konjugiert) hat', 'Karaciğer tarafından bağlanmış (konjuge) bilirubin fraksiyonunu ölçen kan testi', 'Venous blood draw, usually on an empty stomach', 'Uzimanje venske krvi, obično natašte', 'Узимање венске крви, обично наташте', 'Забор венозной крови, обычно натощак', 'Entnahme von venösem Blut, in der Regel nüchtern', 'Genellikle aç karnına venöz kan alımı', 'Clarifying the cause of jaundice, assessment of liver function and bile flow, follow-up in liver and biliary tract disease', 'Utvrđivanje uzroka žutice, procjena rada jetre i otjecanja žuči, praćenje oboljenja jetre i žučnih puteva', 'Утврђивање узрока жутице, процјена рада јетре и отјецања жучи, праћење обољења јетре и жучних путева', 'Уточнение причины желтухи, оценка работы печени и оттока жёлчи, наблюдение при заболеваниях печени и жёлчных путей', 'Abklärung der Ursache einer Gelbsucht, Beurteilung der Leberfunktion und des Galleabflusses, Verlaufskontrolle bei Leber- und Gallenwegserkrankungen', 'Sarılığın nedeninin araştırılması, karaciğer işlevi ve safra akışının değerlendirilmesi, karaciğer ve safra yolu hastalıklarında izlem', 'Fasting for 4–8 hours, only water allowed; avoid fatty food and alcohol the day before', 'Natašte 4–8 sati, dozvoljena samo voda; dan ranije izbjegavati masnu hranu i alkohol', 'Наташте 4–8 сати, дозвољена само вода; дан раније избјегавати масну храну и алкохол', 'Натощак 4–8 часов, разрешена только вода; накануне избегать жирной пищи и алкоголя', '4–8 Stunden nüchtern, nur Wasser erlaubt; am Vortag fettreiche Speisen und Alkohol meiden', '4–8 saat aç karnına, sadece su içilebilir; bir önceki gün yağlı yiyecek ve alkolden kaçınılmalıdır', 'An increase is more often related to impaired bile flow or to liver cell function, whereas total bilirubin changes for other reasons as well. A doctor interprets the ratio of the fractions', 'Povišene vrijednosti češće su povezane sa otežanim otjecanjem žuči ili radom ćelija jetre, dok se ukupni bilirubin mijenja i iz drugih razloga. Odnos frakcija tumači ljekar', 'Повишене вриједности чешће су повезане са отежаним отјецањем жучи или радом ћелија јетре, док се укупни билирубин мијења и из других разлога. Однос фракција тумачи љекар', 'Повышение чаще связано с затруднённым оттоком жёлчи или работой клеток печени, тогда как общий билирубин меняется и по другим причинам. Соотношение фракций трактует врач', 'Erhöhte Werte hängen häufiger mit einem gestörten Galleabfluss oder der Funktion der Leberzellen zusammen, während sich das Gesamtbilirubin auch aus anderen Gründen ändert. Das Verhältnis der Fraktionen beurteilt der Arzt', 'Yüksek değerler daha çok safra akışının bozulması veya karaciğer hücrelerinin işleviyle ilişkilidir, total bilirubin ise başka nedenlerle de değişir. Fraksiyonların oranını hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'tibc'), 'Blood test showing how much iron the serum proteins are able to bind in total', 'Analiza krvi koja pokazuje koliko gvožđa bjelančevine seruma ukupno mogu da vežu', 'Анализа крви која показује колико гвожђа бјеланчевине серума укупно могу да вежу', 'Анализ крови, показывающий, сколько железа способны связать белки сыворотки в целом', 'Bluttest, der zeigt, wie viel Eisen die Serumproteine insgesamt binden können', 'Serum proteinlerinin toplamda ne kadar demir bağlayabildiğini gösteren kan testi', 'Venous blood draw, usually together with iron and other markers of iron metabolism', 'Uzimanje venske krvi, obično zajedno sa gvožđem i drugim pokazateljima metabolizma gvožđa', 'Узимање венске крви, обично заједно са гвожђем и другим показатељима метаболизма гвожђа', 'Забор венозной крови, обычно вместе с железом и другими показателями обмена железа', 'Entnahme von venösem Blut, meist zusammen mit Eisen und weiteren Eisenwerten', 'Genellikle demir ve diğer demir metabolizması göstergeleriyle birlikte venöz kan alımı', 'Work-up of anemia, assessment of iron stores and iron metabolism, monitoring during iron supplementation', 'Ispitivanje anemije, procjena zaliha i prometa gvožđa, kontrola tokom terapije preparatima gvožđa', 'Испитивање анемије, процјена залиха и промета гвожђа, контрола током терапије препаратима гвожђа', 'Обследование при анемии, оценка запасов и обмена железа, контроль на фоне терапии препаратами железа', 'Abklärung einer Anämie, Beurteilung von Eisenspeichern und Eisenstoffwechsel, Kontrolle unter Eisentherapie', 'Anemi araştırması, demir depolarının ve metabolizmasının değerlendirilmesi, demir tedavisi sırasında izlem', 'Strictly fasting in the morning; iron supplements the day before only after agreement with the doctor', 'Strogo natašte, ujutru; preparate gvožđa dan ranije uzimati samo uz dogovor sa ljekarom', 'Строго наташте, ујутру; препарате гвожђа дан раније узимати само уз договор са љекаром', 'Строго натощак утром; препараты железа накануне принимать только по согласованию с врачом', 'Streng nüchtern am Morgen; Eisenpräparate am Vortag nur nach Rücksprache mit dem Arzt', 'Sabah, kesinlikle aç karnına; demir preparatları bir gün önce yalnızca hekimle görüşerek alınmalıdır', 'Changes may be related to iron deficiency or excess, inflammation, diet or pregnancy. The value is interpreted only together with iron and ferritin, and the conclusion is drawn by a doctor', 'Promjene mogu biti povezane sa nedostatkom ili viškom gvožđa, upalom, ishranom ili trudnoćom. Vrijednost se tumači samo zajedno sa gvožđem i feritinom, a zaključak donosi ljekar', 'Промјене могу бити повезане са недостатком или вишком гвожђа, упалом, исхраном или трудноћом. Вриједност се тумачи само заједно са гвожђем и феритином, а закључак доноси љекар', 'Изменения могут быть связаны с дефицитом или избытком железа, воспалением, питанием или беременностью. Показатель трактуется только вместе с железом и ферритином, вывод делает врач', 'Veränderungen können mit Eisenmangel oder Eisenüberschuss, Entzündungen, Ernährung oder einer Schwangerschaft zusammenhängen. Der Wert wird nur zusammen mit Eisen und Ferritin beurteilt, die Schlussfolgerung zieht der Arzt', 'Değişiklikler demir eksikliği veya fazlalığı, iltihap, beslenme ya da gebelikle ilişkili olabilir. Değer yalnızca demir ve ferritinle birlikte yorumlanır, sonucu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'uibc'), 'Blood test for the part of the iron-binding capacity that is not yet occupied by iron', 'Analiza krvi na onaj dio kapaciteta vezivanja gvožđa koji još nije popunjen gvožđem', 'Анализа крви на онај дио капацитета везивања гвожђа који још није попуњен гвожђем', 'Анализ крови на ту часть железосвязывающей способности, которая ещё не занята железом', 'Bluttest auf den Teil der Eisenbindungskapazität, der noch nicht mit Eisen besetzt ist', 'Demir bağlama kapasitesinin henüz demirle dolmamış bölümünü ölçen kan testi', 'Venous blood draw, usually together with serum iron; adding the two gives the total capacity', 'Uzimanje venske krvi, obično uz gvožđe u serumu; sabiranjem se dobija ukupni kapacitet', 'Узимање венске крви, обично уз гвожђе у серуму; сабирањем се добија укупни капацитет', 'Забор венозной крови, обычно вместе с сывороточным железом; сумма двух показателей даёт общую способность', 'Entnahme von venösem Blut, meist zusammen mit dem Serumeisen; die Summe ergibt die totale Kapazität', 'Genellikle serum demiriyle birlikte venöz kan alımı; ikisinin toplamı total kapasiteyi verir', 'Clarifying iron metabolism in anemia, calculating transferrin saturation, monitoring during iron treatment', 'Pojašnjenje prometa gvožđa kod anemije, izračunavanje zasićenja transferina, praćenje tokom terapije gvožđem', 'Појашњење промета гвожђа код анемије, израчунавање засићења трансферина, праћење током терапије гвожђем', 'Уточнение обмена железа при анемии, расчёт насыщения трансферрина, наблюдение при лечении препаратами железа', 'Genauere Abklärung des Eisenstoffwechsels bei Anämie, Berechnung der Transferrinsättigung, Kontrolle unter Eisentherapie', 'Anemide demir metabolizmasının netleştirilmesi, transferrin satürasyonunun hesaplanması, demir tedavisi sırasında izlem', 'Taken in the morning on an empty stomach; tell the doctor in advance about iron supplements and vitamins', 'Uzima se ujutru natašte; o uzimanju preparata gvožđa i vitamina unaprijed obavijestiti ljekara', 'Узима се ујутру наташте; о узимању препарата гвожђа и витамина унапријед обавијестити љекара', 'Сдают утром натощак; о приёме препаратов железа и витаминов сообщить врачу заранее', 'Morgens nüchtern; die Einnahme von Eisenpräparaten und Vitaminen dem Arzt vorab mitteilen', 'Sabah aç karnına alınır; demir preparatı ve vitamin kullanımı hekime önceden bildirilmelidir', 'Deviations may be related to iron deficiency or excess in the body and to inflammatory processes. The value is not interpreted apart from iron and total iron-binding capacity, and this is done by a doctor', 'Odstupanja mogu biti povezana sa nedostatkom ili viškom gvožđa u organizmu i sa upalnim procesima. Vrijednost se ne tumači odvojeno od gvožđa i ukupnog kapaciteta vezivanja, to radi ljekar', 'Одступања могу бити повезана са недостатком или вишком гвожђа у организму и са упалним процесима. Вриједност се не тумачи одвојено од гвожђа и укупног капацитета везивања, то ради љекар', 'Отклонения могут быть связаны с недостатком или избытком железа в организме и с воспалительными процессами. Отдельно от железа и общей железосвязывающей способности показатель не трактуется, этим занимается врач', 'Abweichungen können mit Eisenmangel oder Eisenüberschuss sowie mit Entzündungsprozessen zusammenhängen. Der Wert wird nicht getrennt von Eisen und totaler Eisenbindungskapazität beurteilt, das übernimmt der Arzt', 'Sapmalar vücutta demir eksikliği veya fazlalığıyla ve iltihabi süreçlerle ilişkili olabilir. Değer, demir ve total demir bağlama kapasitesinden ayrı yorumlanmaz, bunu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'albumin'), 'Blood test for the main plasma protein produced by the liver', 'Analiza krvi na glavnu bjelančevinu plazme koju stvara jetra', 'Анализа крви на главну бјеланчевину плазме коју ствара јетра', 'Анализ крови на основной белок плазмы, который вырабатывает печень', 'Bluttest auf das wichtigste Plasmaprotein, das die Leber bildet', 'Karaciğerin ürettiği başlıca plazma proteinini ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Assessment of liver and kidney function, work-up of edema, monitoring nutrition and general status in chronic disease, preparation for surgery', 'Procjena rada jetre i bubrega, ispitivanje otoka, praćenje uhranjenosti i opšteg stanja kod hroničnih bolesti, priprema za operaciju', 'Процјена рада јетре и бубрега, испитивање отока, праћење ухрањености и општег стања код хроничних болести, припрема за операцију', 'Оценка работы печени и почек, обследование при отёках, наблюдение за питанием и общим состоянием при хронических болезнях, подготовка к операции', 'Beurteilung der Leber- und Nierenfunktion, Abklärung von Ödemen, Kontrolle von Ernährungszustand und Allgemeinbefinden bei chronischen Erkrankungen, Vorbereitung auf Operationen', 'Karaciğer ve böbrek işlevinin değerlendirilmesi, ödem araştırması, kronik hastalıklarda beslenme ve genel durumun izlenmesi, ameliyat öncesi hazırlık', 'Taken in the morning on an empty stomach; dehydration and a long tourniquet time distort the result, so keep your usual fluid intake the day before', 'Uzima se ujutru natašte; dehidratacija i dugo stajanje poveske mijenjaju nalaz, pa dan ranije zadržati uobičajen unos tečnosti', 'Узима се ујутру наташте; дехидратација и дуго стајање повеске мијењају налаз, па дан раније задржати уобичајен унос течности', 'Сдают утром натощак; обезвоживание и долгое наложение жгута искажают результат, поэтому накануне важен обычный питьевой режим', 'Morgens nüchtern; Flüssigkeitsmangel und langes Stauen verfälschen den Wert, daher am Vortag die gewohnte Trinkmenge beibehalten', 'Sabah aç karnına alınır; sıvı kaybı ve turnikenin uzun süre bağlı kalması sonucu bozar, bu nedenle bir önceki gün olağan sıvı alımı sürdürülmelidir', 'Changes may be related to liver function, protein loss through the kidneys or bowel, nutrition, inflammation or the amount of fluid in the body. The cause is determined by a doctor', 'Promjene mogu biti povezane sa radom jetre, gubitkom bjelančevina preko bubrega ili crijeva, ishranom, upalom ili količinom tečnosti u organizmu. Uzrok utvrđuje ljekar', 'Промјене могу бити повезане са радом јетре, губитком бјеланчевина преко бубрега или цријева, исхраном, упалом или количином течности у организму. Узрок утврђује љекар', 'Изменения могут быть связаны с работой печени, потерями белка через почки или кишечник, питанием, воспалением или количеством жидкости в организме. Причину определяет врач', 'Veränderungen können mit der Leberfunktion, Eiweißverlusten über Nieren oder Darm, der Ernährung, Entzündungen oder dem Flüssigkeitshaushalt zusammenhängen. Die Ursache bestimmt der Arzt', 'Değişiklikler karaciğer işlevi, böbrek veya bağırsak yoluyla protein kaybı, beslenme, iltihap ya da vücuttaki sıvı miktarıyla ilişkili olabilir. Nedeni hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'amylase'), 'Blood test for the enzyme that breaks down carbohydrates, produced by the pancreas and the salivary glands', 'Analiza krvi na enzim koji razgrađuje ugljene hidrate, a stvaraju ga pankreas i pljuvačne žlijezde', 'Анализа крви на ензим који разграђује угљене хидрате, а стварају га панкреас и пљувачне жлијезде', 'Анализ крови на фермент, расщепляющий углеводы; его вырабатывают поджелудочная и слюнные железы', 'Bluttest auf das kohlenhydratspaltende Enzym, das von Bauchspeicheldrüse und Speicheldrüsen gebildet wird', 'Pankreas ve tükürük bezlerinin ürettiği, karbonhidratları parçalayan enzimi ölçen kan testi', 'Venous blood draw; when needed the enzyme is also measured in urine', 'Uzimanje venske krvi; po potrebi se enzim određuje i u urinu', 'Узимање венске крви; по потреби се ензим одређује и у урину', 'Забор венозной крови; при необходимости фермент определяют и в моче', 'Entnahme von venösem Blut; bei Bedarf wird das Enzym auch im Urin bestimmt', 'Venöz kan alımı; gerektiğinde enzim idrarda da ölçülür', 'Pain in the upper abdomen, suspected inflammation of the pancreas, follow-up in salivary gland disorders', 'Bol u gornjem dijelu trbuha, sumnja na upalu pankreasa, praćenje oboljenja pljuvačnih žlijezda', 'Бол у горњем дијелу трбуха, сумња на упалу панкреаса, праћење обољења пљувачних жлијезда', 'Боль в верхней части живота, подозрение на воспаление поджелудочной железы, наблюдение при заболеваниях слюнных желёз', 'Schmerzen im Oberbauch, Verdacht auf eine Entzündung der Bauchspeicheldrüse, Verlaufskontrolle bei Speicheldrüsenerkrankungen', 'Üst karın ağrısı, pankreas iltihabı şüphesi, tükürük bezi hastalıklarında izlem', 'Fasting for 8–12 hours, only water allowed; avoid alcohol and fatty food the day before', 'Natašte 8–12 sati, dozvoljena samo voda; dan ranije izbjegavati alkohol i masnu hranu', 'Наташте 8–12 сати, дозвољена само вода; дан раније избјегавати алкохол и масну храну', 'Натощак 8–12 часов, разрешена только вода; накануне исключить алкоголь и жирную пищу', '8–12 Stunden nüchtern, nur Wasser erlaubt; am Vortag Alkohol und fettreiche Speisen meiden', '8–12 saat aç karnına, sadece su içilebilir; bir önceki gün alkol ve yağlı yiyeceklerden kaçınılmalıdır', 'An increase may be related to the pancreas, the salivary glands or other processes in the abdomen. What lies behind the change is determined by a doctor from the symptoms and additional tests', 'Povišene vrijednosti mogu biti povezane sa pankreasom, pljuvačnim žlijezdama ili drugim zbivanjima u trbuhu. Šta stoji iza promjene, utvrđuje ljekar na osnovu tegoba i dodatnih pretraga', 'Повишене вриједности могу бити повезане са панкреасом, пљувачним жлијездама или другим збивањима у трбуху. Шта стоји иза промјене, утврђује љекар на основу тегоба и додатних претрага', 'Повышение может быть связано с поджелудочной железой, слюнными железами или другими процессами в брюшной полости. Что стоит за изменением, определяет врач по жалобам и дополнительным исследованиям', 'Erhöhte Werte können mit der Bauchspeicheldrüse, den Speicheldrüsen oder anderen Vorgängen im Bauchraum zusammenhängen. Was dahintersteckt, klärt der Arzt anhand der Beschwerden und weiterer Untersuchungen', 'Yüksek değerler pankreas, tükürük bezleri veya karın içindeki başka süreçlerle ilişkili olabilir. Değişikliğin nedenini hekim şikayetlere ve ek tetkiklere göre belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'homocysteine'), 'Blood test for an amino acid whose metabolism depends on B vitamins', 'Analiza krvi na aminokiselinu čiji metabolizam zavisi od vitamina B grupe', 'Анализа крви на аминокиселину чији метаболизам зависи од витамина Б групе', 'Анализ крови на аминокислоту, обмен которой зависит от витаминов группы B', 'Bluttest auf eine Aminosäure, deren Stoffwechsel von B-Vitaminen abhängt', 'Metabolizması B grubu vitaminlere bağlı olan bir amino asidi ölçen kan testi', 'Venous blood draw; the sample must reach the laboratory quickly, so the appointment is arranged around laboratory hours', 'Uzimanje venske krvi; uzorak brzo mora stići u laboratoriju, pa se termin usklađuje sa njenim radnim vremenom', 'Узимање венске крви; узорак брзо мора стићи у лабораторију, па се термин усклађује са њеним радним временом', 'Забор венозной крови; пробирку быстро доставляют в лабораторию, поэтому время сдачи согласуют с её графиком', 'Entnahme von venösem Blut; die Probe muss rasch ins Labor, daher richtet sich der Termin nach den Laborzeiten', 'Venöz kan alımı; örnek laboratuvara hızla ulaşmalıdır, bu nedenle randevu laboratuvarın çalışma saatlerine göre ayarlanır', 'Assessment of cardiovascular risk factors, work-up of vitamin B12 and folate deficiency, follow-up in certain inherited metabolic disorders, pregnancy planning', 'Procjena kardiovaskularnih faktora rizika, ispitivanje nedostatka vitamina B12 i folne kiseline, praćenje pojedinih nasljednih poremećaja metabolizma, planiranje trudnoće', 'Процјена кардиоваскуларних фактора ризика, испитивање недостатка витамина Б12 и фолне киселине, праћење појединих насљедних поремећаја метаболизма, планирање трудноће', 'Оценка сердечно-сосудистых факторов риска, обследование при дефиците витамина B12 и фолиевой кислоты, наблюдение при некоторых наследственных нарушениях обмена, планирование беременности', 'Beurteilung kardiovaskulärer Risikofaktoren, Abklärung eines Vitamin-B12- oder Folsäuremangels, Verlaufskontrolle bei bestimmten angeborenen Stoffwechselstörungen, Planung einer Schwangerschaft', 'Kalp ve damar risk etkenlerinin değerlendirilmesi, B12 vitamini ve folik asit eksikliğinin araştırılması, bazı kalıtsal metabolizma bozukluklarında izlem, gebelik planlaması', 'Strictly fasting for 10–12 hours, only water allowed; tell the doctor about any B-vitamin supplements', 'Strogo natašte 10–12 sati, dozvoljena samo voda; o uzimanju vitamina B grupe obavijestiti ljekara', 'Строго наташте 10–12 сати, дозвољена само вода; о узимању витамина Б групе обавијестити љекара', 'Строго натощак 10–12 часов, разрешена только вода; о приёме витаминов группы B сообщить врачу', 'Streng nüchtern 10–12 Stunden, nur Wasser erlaubt; die Einnahme von B-Vitaminen dem Arzt mitteilen', '10–12 saat kesinlikle aç karnına, sadece su içilebilir; B grubu vitamin kullanımı hekime bildirilmelidir', 'An increase may be related to a lack of vitamin B12, B6 or folate, kidney function, certain medications or inherited features of metabolism. The result is interpreted by a doctor', 'Povišene vrijednosti mogu biti povezane sa nedostatkom vitamina B12, B6 ili folne kiseline, radom bubrega, uzimanjem nekih lijekova ili nasljednim osobinama metabolizma. Nalaz tumači ljekar', 'Повишене вриједности могу бити повезане са недостатком витамина Б12, Б6 или фолне киселине, радом бубрега, узимањем неких лијекова или насљедним особинама метаболизма. Налаз тумачи љекар', 'Повышение может быть связано с недостатком витаминов B12, B6 или фолиевой кислоты, работой почек, приёмом некоторых препаратов или наследственными особенностями обмена. Трактует результат врач', 'Erhöhte Werte können mit einem Mangel an Vitamin B12, B6 oder Folsäure, der Nierenfunktion, bestimmten Medikamenten oder angeborenen Stoffwechselbesonderheiten zusammenhängen. Die Interpretation erfolgt durch den Arzt', 'Yüksek değerler B12, B6 vitamini veya folik asit eksikliği, böbrek işlevi, bazı ilaçlar ya da kalıtsal metabolizma özellikleriyle ilişkili olabilir. Sonucu hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'lipase'), 'Blood test for the pancreatic enzyme that breaks down fats', 'Analiza krvi na enzim pankreasa koji razgrađuje masti', 'Анализа крви на ензим панкреаса који разграђује масти', 'Анализ крови на фермент поджелудочной железы, расщепляющий жиры', 'Bluttest auf das fettspaltende Enzym der Bauchspeicheldrüse', 'Pankreasın yağları parçalayan enzimini ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Abdominal pain, suspected inflammation of the pancreas, follow-up in chronic pancreatic disease', 'Bol u trbuhu, sumnja na upalu pankreasa, praćenje hroničnih oboljenja pankreasa', 'Бол у трбуху, сумња на упалу панкреаса, праћење хроничних обољења панкреаса', 'Боль в животе, подозрение на воспаление поджелудочной железы, наблюдение при хронических заболеваниях поджелудочной железы', 'Bauchschmerzen, Verdacht auf eine Entzündung der Bauchspeicheldrüse, Verlaufskontrolle bei chronischen Erkrankungen der Bauchspeicheldrüse', 'Karın ağrısı, pankreas iltihabı şüphesi, kronik pankreas hastalıklarında izlem', 'Fasting for 8–12 hours, only water allowed; avoid alcohol and fatty food the day before', 'Natašte 8–12 sati, dozvoljena samo voda; dan ranije izbjegavati alkohol i masnu hranu', 'Наташте 8–12 сати, дозвољена само вода; дан раније избјегавати алкохол и масну храну', 'Натощак 8–12 часов, разрешена только вода; накануне исключить алкоголь и жирную пищу', '8–12 Stunden nüchtern, nur Wasser erlaubt; am Vortag Alkohol und fettreiche Speisen meiden', '8–12 saat aç karnına, sadece su içilebilir; bir önceki gün alkol ve yağlı yiyeceklerden kaçınılmalıdır', 'An increase is more often related to the pancreas and lasts longer than a change in amylase; kidney and bowel disease also have an effect. The result is assessed by a doctor', 'Povišene vrijednosti češće su povezane sa pankreasom i zadržavaju se duže nego promjena amilaze; uticaj imaju i bolesti bubrega i crijeva. Nalaz procjenjuje ljekar', 'Повишене вриједности чешће су повезане са панкреасом и задржавају се дуже него промјена амилазе; утицај имају и болести бубрега и цријева. Налаз процјењује љекар', 'Повышение чаще связано с поджелудочной железой и держится дольше, чем изменение амилазы; влияют также болезни почек и кишечника. Результат оценивает врач', 'Erhöhte Werte hängen häufiger mit der Bauchspeicheldrüse zusammen und halten länger an als eine Veränderung der Amylase; auch Nieren- und Darmerkrankungen wirken sich aus. Die Beurteilung erfolgt durch den Arzt', 'Yüksek değerler daha çok pankreasla ilişkilidir ve amilazdaki değişiklikten daha uzun sürer; böbrek ve bağırsak hastalıkları da etkili olur. Sonucu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'transferrin'), 'Blood test for the protein that carries iron through the bloodstream', 'Analiza krvi na bjelančevinu koja prenosi gvožđe kroz krvotok', 'Анализа крви на бјеланчевину која преноси гвожђе кроз крвоток', 'Анализ крови на белок, который переносит железо по кровотоку', 'Bluttest auf das Protein, das Eisen im Blutkreislauf transportiert', 'Demiri kan dolaşımında taşıyan proteini ölçen kan testi', 'Venous blood draw, usually together with iron and ferritin', 'Uzimanje venske krvi, obično zajedno sa gvožđem i feritinom', 'Узимање венске крви, обично заједно са гвожђем и феритином', 'Забор венозной крови, обычно вместе с железом и ферритином', 'Entnahme von venösem Blut, meist zusammen mit Eisen und Ferritin', 'Genellikle demir ve ferritinle birlikte venöz kan alımı', 'Work-up of anemia, assessment of iron metabolism and stores, calculation of transferrin saturation, follow-up in liver disease', 'Ispitivanje anemije, procjena prometa i zaliha gvožđa, izračunavanje zasićenja transferina gvožđem, praćenje oboljenja jetre', 'Испитивање анемије, процјена промета и залиха гвожђа, израчунавање засићења трансферина гвожђем, праћење обољења јетре', 'Обследование при анемии, оценка обмена и запасов железа, расчёт насыщения трансферрина железом, наблюдение при заболеваниях печени', 'Abklärung einer Anämie, Beurteilung von Eisenstoffwechsel und Eisenspeichern, Berechnung der Transferrinsättigung, Verlaufskontrolle bei Lebererkrankungen', 'Anemi araştırması, demir metabolizmasının ve depolarının değerlendirilmesi, transferrin satürasyonunun hesaplanması, karaciğer hastalıklarında izlem', 'Taken in the morning on an empty stomach; iron supplements before the test only after agreement with the doctor', 'Uzima se ujutru natašte; preparate gvožđa prije analize uzimati samo uz dogovor sa ljekarom', 'Узима се ујутру наташте; препарате гвожђа прије анализе узимати само уз договор са љекаром', 'Сдают утром натощак; препараты железа перед анализом принимать только по согласованию с врачом', 'Morgens nüchtern; Eisenpräparate vor der Untersuchung nur nach Rücksprache mit dem Arzt', 'Sabah aç karnına alınır; demir preparatları test öncesinde yalnızca hekimle görüşerek alınmalıdır', 'Changes may be related to iron deficiency or excess, liver function, inflammation, pregnancy or hormonal medication. The doctor draws the conclusion from the whole group of values', 'Promjene mogu biti povezane sa nedostatkom ili viškom gvožđa, radom jetre, upalom, trudnoćom ili uzimanjem hormonskih lijekova. Zaključak ljekar donosi na osnovu cijele grupe pokazatelja', 'Промјене могу бити повезане са недостатком или вишком гвожђа, радом јетре, упалом, трудноћом или узимањем хормонских лијекова. Закључак љекар доноси на основу цијеле групе показатеља', 'Изменения могут быть связаны с дефицитом или избытком железа, работой печени, воспалением, беременностью или приёмом гормональных препаратов. Вывод врач делает по всей группе показателей', 'Veränderungen können mit Eisenmangel oder Eisenüberschuss, der Leberfunktion, Entzündungen, einer Schwangerschaft oder Hormonpräparaten zusammenhängen. Die Schlussfolgerung zieht der Arzt aus der gesamten Wertegruppe', 'Değişiklikler demir eksikliği veya fazlalığı, karaciğer işlevi, iltihap, gebelik ya da hormon ilaçlarıyla ilişkili olabilir. Hekim sonucu göstergelerin tümüne bakarak değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'osteocalcin'), 'Blood test for a protein produced by bone cells when new bone tissue is formed', 'Analiza krvi na bjelančevinu koju stvaraju koštane ćelije pri izgradnji novog koštanog tkiva', 'Анализа крви на бјеланчевину коју стварају коштане ћелије при изградњи новог коштаног ткива', 'Анализ крови на белок, который вырабатывают костные клетки при образовании новой костной ткани', 'Bluttest auf ein Protein, das Knochenzellen beim Aufbau neuen Knochengewebes bilden', 'Yeni kemik dokusu oluşurken kemik hücrelerinin ürettiği bir proteini ölçen kan testi', 'Venous blood draw in the morning, takes a few minutes', 'Uzimanje venske krvi ujutru, traje nekoliko minuta', 'Узимање венске крви ујутру, траје неколико минута', 'Забор венозной крови утром, занимает несколько минут', 'Entnahme von venösem Blut am Morgen, dauert einige Minuten', 'Sabah venöz kan alımı, birkaç dakika sürer', 'Assessment of bone turnover, follow-up in osteoporosis and monitoring of its treatment, work-up of calcium and vitamin D metabolism disorders', 'Procjena koštanog metabolizma, praćenje osteoporoze i kontrola njenog liječenja, ispitivanje poremećaja metabolizma kalcijuma i vitamina D', 'Процјена коштаног метаболизма, праћење остеопорозе и контрола њеног лијечења, испитивање поремећаја метаболизма калцијума и витамина Д', 'Оценка костного обмена, наблюдение при остеопорозе и контроль его лечения, обследование при нарушениях обмена кальция и витамина D', 'Beurteilung des Knochenstoffwechsels, Verlaufskontrolle bei Osteoporose und deren Therapiekontrolle, Abklärung von Störungen des Kalzium- und Vitamin-D-Stoffwechsels', 'Kemik metabolizmasının değerlendirilmesi, osteoporozda izlem ve tedavinin takibi, kalsiyum ve D vitamini metabolizması bozukluklarının araştırılması', 'Strictly in the morning on an empty stomach, as the value changes noticeably during the day; tell the doctor about bone medication and vitamin D supplements', 'Strogo ujutru natašte, jer se vrijednost primjetno mijenja tokom dana; o uzimanju lijekova za kosti i vitamina D obavijestiti ljekara', 'Строго ујутру наташте, јер се вриједност примјетно мијења током дана; о узимању лијекова за кости и витамина Д обавијестити љекара', 'Строго утром натощак, так как показатель заметно меняется в течение суток; о приёме препаратов для костей и витамина D сообщить врачу', 'Streng morgens nüchtern, da sich der Wert im Tagesverlauf deutlich ändert; Knochenmedikamente und Vitamin-D-Präparate dem Arzt mitteilen', 'Değer gün içinde belirgin şekilde değiştiğinden kesinlikle sabah aç karnına alınır; kemik ilaçları ve D vitamini kullanımı hekime bildirilmelidir', 'Changes may be related to the rate of bone renewal, parathyroid function, vitamin D metabolism or ongoing treatment. The doctor assesses the result together with densitometry and other tests', 'Promjene mogu biti povezane sa brzinom obnavljanja koštanog tkiva, radom paratireoidnih žlijezda, metabolizmom vitamina D ili terapijom koja se sprovodi. Nalaz ljekar procjenjuje zajedno sa denzitometrijom i drugim analizama', 'Промјене могу бити повезане са брзином обнављања коштаног ткива, радом паратиреоидних жлијезда, метаболизмом витамина Д или терапијом која се спроводи. Налаз љекар процјењује заједно са дензитометријом и другим анализама', 'Изменения могут быть связаны со скоростью обновления костной ткани, работой паращитовидных желёз, обменом витамина D или проводимой терапией. Результат врач оценивает вместе с денситометрией и другими анализами', 'Veränderungen können mit der Geschwindigkeit des Knochenumbaus, der Funktion der Nebenschilddrüsen, dem Vitamin-D-Stoffwechsel oder der laufenden Therapie zusammenhängen. Der Arzt beurteilt den Wert zusammen mit der Knochendichtemessung und weiteren Untersuchungen', 'Değişiklikler kemik yenilenme hızı, paratiroid bezlerinin çalışması, D vitamini metabolizması ya da uygulanan tedaviyle ilişkili olabilir. Hekim sonucu kemik yoğunluğu ölçümü ve diğer tetkiklerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ace'), 'Blood test for an enzyme involved in the regulation of blood pressure and water-salt balance', 'Analiza krvi na enzim koji učestvuje u regulaciji krvnog pritiska i ravnoteže vode i soli', 'Анализа крви на ензим који учествује у регулацији крвног притиска и равнотеже воде и соли', 'Анализ крови на фермент, участвующий в регуляции артериального давления и водно-солевого обмена', 'Bluttest auf ein Enzym, das an der Regulation von Blutdruck und Wasser-Salz-Haushalt beteiligt ist', 'Kan basıncının ve su-tuz dengesinin düzenlenmesinde rol alan bir enzimi ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Work-up and follow-up of granulomatous diseases, primarily sarcoidosis, assessment of disease activity over time', 'Ispitivanje i praćenje granulomatoznih bolesti, prije svega sarkoidoze, procjena aktivnosti procesa tokom vremena', 'Испитивање и праћење грануломатозних болести, прије свега саркоидозе, процјена активности процеса током времена', 'Обследование и наблюдение при гранулематозных заболеваниях, прежде всего саркоидозе, оценка активности процесса в динамике', 'Abklärung und Verlaufskontrolle granulomatöser Erkrankungen, vor allem der Sarkoidose, Beurteilung der Aktivität im Verlauf', 'Granülomatöz hastalıkların, başta sarkoidoz olmak üzere, araştırılması ve izlenmesi, hastalık aktivitesinin zaman içinde değerlendirilmesi', 'Taken in the morning on an empty stomach; always tell the doctor and the laboratory about ACE inhibitor medication — it changes the result', 'Uzima se ujutru natašte; o uzimanju lijekova iz grupe ACE inhibitora obavezno obavijestiti ljekara i laboratoriju, jer mijenjaju nalaz', 'Узима се ујутру наташте; о узимању лијекова из групе ACE инхибитора обавезно обавијестити љекара и лабораторију, јер мијењају налаз', 'Сдают утром натощак; о приёме препаратов из группы ингибиторов АПФ обязательно сообщить врачу и лаборатории — они меняют результат', 'Morgens nüchtern; die Einnahme von ACE-Hemmern unbedingt dem Arzt und dem Labor mitteilen, da sie den Wert verändern', 'Sabah aç karnına alınır; ACE inhibitörü grubu ilaç kullanımı sonucu değiştirdiğinden hekime ve laboratuvara mutlaka bildirilmelidir', 'Changes may be related to the activity of granulomatous inflammation, liver or thyroid disease, or medication. The value is not used apart from the clinical picture and is interpreted by a doctor', 'Promjene mogu biti povezane sa aktivnošću granulomatozne upale, oboljenjima jetre i štitne žlijezde ili uzimanjem lijekova. Vrijednost se ne koristi odvojeno od kliničke slike, tumači je ljekar', 'Промјене могу бити повезане са активношћу грануломатозне упале, обољењима јетре и штитне жлијезде или узимањем лијекова. Вриједност се не користи одвојено од клиничке слике, тумачи је љекар', 'Изменения могут быть связаны с активностью гранулематозного воспаления, заболеваниями печени и щитовидной железы или приёмом лекарств. Отдельно от клинической картины показатель не используется, трактует его врач', 'Veränderungen können mit der Aktivität einer granulomatösen Entzündung, Leber- oder Schilddrüsenerkrankungen oder Medikamenten zusammenhängen. Der Wert wird nicht losgelöst vom klinischen Bild verwendet und vom Arzt beurteilt', 'Değişiklikler granülomatöz iltihabın aktivitesi, karaciğer ve tiroid hastalıkları ya da ilaç kullanımıyla ilişkili olabilir. Değer klinik tablodan ayrı kullanılmaz, yorumu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'beta-crosslaps'), 'Blood test for a breakdown product of bone collagen — a marker of how fast bone is being resorbed', 'Analiza krvi na proizvod razgradnje koštanog kolagena — pokazatelj brzine razgradnje kosti', 'Анализа крви на производ разградње коштаног колагена — показатељ брзине разградње кости', 'Анализ крови на продукт распада костного коллагена — маркер скорости рассасывания кости', 'Bluttest auf ein Abbauprodukt des Knochenkollagens — ein Marker für die Geschwindigkeit des Knochenabbaus', 'Kemik kollajeninin yıkım ürününü, yani kemik yıkım hızının bir göstergesini ölçen kan testi', 'Venous blood draw strictly in the morning hours, as the value fluctuates markedly during the day', 'Uzimanje venske krvi isključivo u jutarnjim satima, jer vrijednost izrazito varira tokom dana', 'Узимање венске крви искључиво у јутарњим сатима, јер вриједност изразито варира током дана', 'Забор венозной крови строго в утренние часы, так как показатель сильно колеблется в течение суток', 'Entnahme von venösem Blut ausschließlich in den Morgenstunden, da der Wert im Tagesverlauf stark schwankt', 'Değer gün içinde belirgin şekilde dalgalandığından yalnızca sabah saatlerinde venöz kan alımı', 'Assessment of bone turnover in osteoporosis, monitoring the effect of prescribed therapy, work-up of calcium metabolism disorders', 'Procjena koštanog metabolizma kod osteoporoze, praćenje djelovanja propisane terapije, ispitivanje poremećaja metabolizma kalcijuma', 'Процјена коштаног метаболизма код остеопорозе, праћење дјеловања прописане терапије, испитивање поремећаја метаболизма калцијума', 'Оценка костного обмена при остеопорозе, контроль эффективности назначенной терапии, обследование при нарушениях обмена кальция', 'Beurteilung des Knochenstoffwechsels bei Osteoporose, Kontrolle der Wirkung einer verordneten Therapie, Abklärung von Störungen des Kalziumstoffwechsels', 'Osteoporozda kemik metabolizmasının değerlendirilmesi, uygulanan tedavinin etkisinin izlenmesi, kalsiyum metabolizması bozukluklarının araştırılması', 'In the morning on an empty stomach, as food lowers the value; for repeat tests the same time of day is kept', 'Ujutru natašte, jer obrok snižava vrijednost; kod ponovljenih analiza zadržava se isto doba dana', 'Ујутру наташте, јер оброк снижава вриједност; код поновљених анализа задржава се исто доба дана', 'Утром натощак, приём пищи снижает значение; при повторных анализах стараются сохранять одно и то же время сдачи', 'Morgens nüchtern, da Nahrungsaufnahme den Wert senkt; bei Verlaufskontrollen wird dieselbe Tageszeit beibehalten', 'Sabah aç karnına, çünkü yemek değeri düşürür; tekrarlanan testlerde aynı saat tercih edilir', 'Changes may be related to faster or slower bone renewal, hormonal changes or the response to treatment. The doctor assesses the result together with densitometry', 'Promjene mogu biti povezane sa ubrzanim ili usporenim obnavljanjem koštanog tkiva, hormonskim promjenama ili odgovorom na liječenje. Nalaz ljekar procjenjuje zajedno sa denzitometrijom', 'Промјене могу бити повезане са убрзаним или успореним обнављањем коштаног ткива, хормонским промјенама или одговором на лијечење. Налаз љекар процјењује заједно са дензитометријом', 'Изменения могут быть связаны с ускоренным или замедленным обновлением костной ткани, гормональными перестройками или ответом на лечение. Результат врач оценивает вместе с денситометрией', 'Veränderungen können mit einem beschleunigten oder verlangsamten Knochenumbau, hormonellen Umstellungen oder dem Ansprechen auf die Behandlung zusammenhängen. Der Arzt beurteilt den Wert zusammen mit der Knochendichtemessung', 'Değişiklikler kemik yenilenmesinin hızlanması veya yavaşlaması, hormonal değişimler ya da tedaviye yanıtla ilişkili olabilir. Hekim sonucu kemik yoğunluğu ölçümüyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'fructosamine'), 'Blood test for glycated serum proteins, reflecting the average blood sugar level over the past 2–3 weeks', 'Analiza krvi na glikovane bjelančevine seruma, koje odražavaju prosječan nivo šećera tokom posljednje 2–3 sedmice', 'Анализа крви на гликоване бјеланчевине серума, које одражавају просјечан ниво шећера током посљедње 2–3 седмице', 'Анализ крови на гликированные белки сыворотки, отражающие средний уровень сахара за последние 2–3 недели', 'Bluttest auf glykierte Serumproteine, die den durchschnittlichen Blutzuckerspiegel der letzten 2–3 Wochen widerspiegeln', 'Son 2–3 haftadaki ortalama kan şekeri düzeyini yansıtan glike serum proteinlerini ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Short-term monitoring of diabetes, situations where HbA1c is of limited use — pregnancy, a recent change of therapy, blood disorders', 'Kratkoročna kontrola šećerne bolesti, situacije u kojima je HbA1c manje upotrebljiv — trudnoća, nedavna promjena terapije, bolesti krvi', 'Краткорочна контрола шећерне болести, ситуације у којима је HbA1c мање употребљив — трудноћа, недавна промјена терапије, болести крви', 'Контроль сахарного диабета за короткий период, ситуации, когда HbA1c малоинформативен — беременность, недавняя смена терапии, заболевания крови', 'Kurzfristige Kontrolle eines Diabetes, Situationen mit eingeschränkter Aussagekraft des HbA1c — Schwangerschaft, kürzlich geänderte Therapie, Bluterkrankungen', 'Diyabetin kısa dönemli takibi, HbA1c''nin yeterli bilgi vermediği durumlar: gebelik, tedavinin yakın zamanda değişmesi, kan hastalıkları', 'Special preparation is usually not required, but the sample is most often taken in the morning on an empty stomach; check the conditions with the referring doctor', 'Posebna priprema obično nije potrebna, ali se najčešće uzima ujutru natašte; uslove provjeriti kod ljekara koji je uputio na analizu', 'Посебна припрема обично није потребна, али се најчешће узима ујутру наташте; услове провјерити код љекара који је упутио на анализу', 'Специальная подготовка обычно не требуется, но чаще сдают утром натощак; условия уточните у направившего врача', 'Eine besondere Vorbereitung ist meist nicht nötig, die Abnahme erfolgt aber überwiegend morgens nüchtern; die Bedingungen beim überweisenden Arzt erfragen', 'Genellikle özel hazırlık gerekmez, ancak çoğunlukla sabah aç karnına alınır; koşulları yönlendiren hekime danışın', 'Changes may be related to glucose levels in the preceding weeks and also to the protein content of the blood and to liver or kidney disease. The result is assessed by a doctor', 'Promjene mogu biti povezane sa nivoom glukoze u prethodnim sedmicama, ali i sa količinom bjelančevina u krvi te oboljenjima jetre ili bubrega. Nalaz procjenjuje ljekar', 'Промјене могу бити повезане са нивоом глукозе у претходним седмицама, али и са количином бјеланчевина у крви те обољењима јетре или бубрега. Налаз процјењује љекар', 'Изменения могут быть связаны с уровнем глюкозы в предшествующие недели, а также с содержанием белка в крови и заболеваниями печени или почек. Результат оценивает врач', 'Veränderungen können mit den Glukosewerten der vergangenen Wochen sowie mit dem Eiweißgehalt des Blutes und Leber- oder Nierenerkrankungen zusammenhängen. Die Beurteilung erfolgt durch den Arzt', 'Değişiklikler önceki haftalardaki glukoz düzeyiyle, ayrıca kandaki protein miktarı ve karaciğer veya böbrek hastalıklarıyla ilişkili olabilir. Sonucu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'pancreatic-amylase'), 'Blood test for the pancreatic fraction of amylase — the part of the enzyme produced specifically by the pancreas', 'Analiza krvi na pankreasnu frakciju amilaze — onaj dio enzima koji stvara upravo pankreas', 'Анализа крви на панкреасну фракцију амилазе — онај дио ензима који ствара управо панкреас', 'Анализ крови на панкреатическую фракцию амилазы — ту часть фермента, которую вырабатывает именно поджелудочная железа', 'Bluttest auf die Pankreasfraktion der Amylase — jenen Anteil des Enzyms, der gezielt von der Bauchspeicheldrüse gebildet wird', 'Amilazın doğrudan pankreas tarafından üretilen fraksiyonunu ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Pain in the upper abdomen, clarifying a total amylase result, work-up and follow-up of pancreatic disease', 'Bol u gornjem dijelu trbuha, pojašnjenje nalaza ukupne amilaze, ispitivanje i praćenje oboljenja pankreasa', 'Бол у горњем дијелу трбуха, појашњење налаза укупне амилазе, испитивање и праћење обољења панкреаса', 'Боль в верхней части живота, уточнение результата общей амилазы, обследование и наблюдение при заболеваниях поджелудочной железы', 'Schmerzen im Oberbauch, Präzisierung eines Gesamtamylase-Ergebnisses, Abklärung und Verlaufskontrolle von Erkrankungen der Bauchspeicheldrüse', 'Üst karın ağrısı, total amilaz sonucunun netleştirilmesi, pankreas hastalıklarının araştırılması ve izlenmesi', 'Fasting for 8–12 hours, only water allowed; avoid alcohol and fatty food the day before', 'Natašte 8–12 sati, dozvoljena samo voda; dan ranije izbjegavati alkohol i masnu hranu', 'Наташте 8–12 сати, дозвољена само вода; дан раније избјегавати алкохол и масну храну', 'Натощак 8–12 часов, разрешена только вода; накануне исключить алкоголь и жирную пищу', '8–12 Stunden nüchtern, nur Wasser erlaubt; am Vortag Alkohol und fettreiche Speisen meiden', '8–12 saat aç karnına, sadece su içilebilir; bir önceki gün alkol ve yağlı yiyeceklerden kaçınılmalıdır', 'An increase is more often related to the pancreas, unlike total amylase, which is also affected by the salivary glands; kidney function plays a role as well. The conclusion is drawn by a doctor', 'Povišene vrijednosti češće su povezane sa pankreasom, za razliku od ukupne amilaze na koju utiču i pljuvačne žlijezde; značaj ima i rad bubrega. Zaključak donosi ljekar', 'Повишене вриједности чешће су повезане са панкреасом, за разлику од укупне амилазе на коју утичу и пљувачне жлијезде; значај има и рад бубрега. Закључак доноси љекар', 'Повышение чаще связано с поджелудочной железой, в отличие от общей амилазы, на которую влияют и слюнные железы; сказывается также работа почек. Вывод делает врач', 'Erhöhte Werte hängen häufiger mit der Bauchspeicheldrüse zusammen als die Gesamtamylase, die auch von den Speicheldrüsen beeinflusst wird; auch die Nierenfunktion spielt eine Rolle. Die Schlussfolgerung zieht der Arzt', 'Yüksek değerler, tükürük bezlerinden de etkilenen total amilazın aksine daha çok pankreasla ilişkilidir; böbrek işlevi de rol oynar. Sonucu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'anti-thyroglobulin-antibodies'), 'Blood test for antibodies to thyroglobulin (Anti-Tg), one of the markers used when the thyroid gland is examined', 'Analiza krvi na antitijela na tireoglobulin (Anti-Tg), jedan od markera pri pregledu štitne žlijezde', 'Анализа крви на антитијела на тиреоглобулин (Anti-Tg), један од маркера при прегледу штитне жлијезде', 'Анализ крови на антитела к тиреоглобулину (Anti-Tg) — один из маркеров при обследовании щитовидной железы', 'Bluttest auf Antikörper gegen Thyreoglobulin (Anti-Tg), einer der Marker bei der Untersuchung der Schilddrüse', 'Tiroid bezi değerlendirilirken kullanılan belirteçlerden biri olan tiroglobulin antikorları (Anti-Tg) için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Thyroid evaluation when hormone levels or gland structure change, follow-up after treatment of thyroid disease, pregnancy planning', 'Pregled štitne žlijezde pri promjeni hormona ili strukture tkiva, praćenje nakon liječenja oboljenja štitne žlijezde, planiranje trudnoće', 'Преглед штитне жлијезде при промјени хормона или структуре ткива, праћење након лијечења обољења штитне жлијезде, планирање трудноће', 'Обследование щитовидной железы при изменении гормонов или структуры ткани, наблюдение после лечения заболеваний щитовидной железы, планирование беременности', 'Abklärung der Schilddrüse bei veränderten Hormonwerten oder verändertem Gewebe, Verlaufskontrolle nach Behandlung von Schilddrüsenerkrankungen, Schwangerschaftsplanung', 'Hormon düzeyleri veya bez dokusu değiştiğinde tiroid değerlendirmesi, tiroid hastalıklarının tedavisi sonrası izlem, gebelik planlaması', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'A positive result by itself does not mean a disease: such antibodies also occur in healthy people and in other conditions. The doctor decides what the result means together with hormone levels, ultrasound and the clinical picture', 'Pozitivan nalaz sam po sebi ne znači bolest: takva antitijela se sreću i kod zdravih osoba i kod drugih stanja. Značaj rezultata utvrđuje ljekar zajedno sa nivoom hormona, ultrazvukom i kliničkom slikom', 'Позитиван налаз сам по себи не значи болест: таква антитијела се срећу и код здравих особа и код других стања. Значај резултата утврђује љекар заједно са нивоом хормона, ултразвуком и клиничком сликом', 'Положительный результат сам по себе не означает болезнь: такие антитела встречаются и у здоровых людей, и при других состояниях. Значение результата определяет врач вместе с уровнем гормонов, УЗИ и клинической картиной', 'Ein positiver Befund allein bedeutet keine Erkrankung: solche Antikörper kommen auch bei Gesunden und bei anderen Zuständen vor. Was das Ergebnis bedeutet, entscheidet der Arzt zusammen mit Hormonwerten, Ultraschall und klinischem Bild', 'Pozitif sonuç tek başına hastalık anlamına gelmez: bu antikorlar sağlıklı kişilerde ve başka durumlarda da görülebilir. Sonucun anlamını hekim hormon düzeyleri, ultrason ve klinik tabloyla birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'waaler-rose-test'), 'Agglutination blood test used to detect rheumatoid factor when joints are being evaluated', 'Aglutinacioni test krvi kojim se otkriva reumatoidni faktor pri pregledu zglobova', 'Аглутинациони тест крви којим се открива реуматоидни фактор при прегледу зглобова', 'Агглютинационный тест крови, которым выявляют ревматоидный фактор при обследовании суставов', 'Agglutinationstest im Blut, mit dem der Rheumafaktor bei der Abklärung von Gelenkbeschwerden nachgewiesen wird', 'Eklem değerlendirmesinde romatoid faktörü saptamak için kullanılan aglütinasyon esaslı kan testi', 'Venous blood draw; in the laboratory the serum is mixed with antibody-coated red cells and the reaction is read, the draw itself takes a few minutes', 'Uzimanje venske krvi, u laboratoriji se serum miješa sa eritrocitima obloženim antitijelima i prati se reakcija, samo uzimanje traje nekoliko minuta', 'Узимање венске крви, у лабораторији се серум мијеша са еритроцитима обложеним антитијелима и прати се реакција, само узимање траје неколико минута', 'Забор венозной крови, в лаборатории сыворотку смешивают с покрытыми антителами эритроцитами и оценивают реакцию; сам забор занимает несколько минут', 'Blutentnahme aus einer Vene, im Labor wird das Serum mit antikörperbeladenen Erythrozyten vermischt und die Reaktion abgelesen, die Entnahme selbst dauert wenige Minuten', 'Damardan kan alınır, laboratuvarda serum antikorla kaplı alyuvarlarla karıştırılıp reaksiyon değerlendirilir, kan alma işlemi birkaç dakika sürer', 'Joint pain, stiffness and swelling, evaluation when a rheumatic condition is suspected, clarification of other rheumatology test results', 'Bolovi, ukočenost i otok zglobova, pregled pri sumnji na reumatske bolesti, razjašnjenje nalaza drugih reumatoloških testova', 'Болови, укоченост и оток зглобова, преглед при сумњи на реуматске болести, разјашњење налаза других реуматолошких тестова', 'Боли, скованность и припухлость суставов, обследование при подозрении на ревматические заболевания, уточнение результатов других ревмопроб', 'Gelenkschmerzen, Steifigkeit und Schwellungen, Abklärung bei Verdacht auf rheumatische Erkrankungen, Ergänzung zu anderen Rheumawerten', 'Eklem ağrısı, tutukluk ve şişlik, romatizmal hastalık şüphesinde değerlendirme, diğer romatoloji testlerinin sonuçlarının netleştirilmesi', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'A positive reaction by itself is not a diagnosis: it also occurs in healthy people, more often at an older age, and in other inflammatory or infectious conditions. The doctor assesses the result together with symptoms, examination and other tests', 'Pozitivna reakcija sama po sebi nije dijagnoza: sreće se i kod zdravih osoba, češće starijih, i kod drugih upalnih i infektivnih stanja. Nalaz procjenjuje ljekar zajedno sa tegobama, pregledom i drugim analizama', 'Позитивна реакција сама по себи није дијагноза: среће се и код здравих особа, чешће старијих, и код других упалних и инфективних стања. Налаз процјењује љекар заједно са тегобама, прегледом и другим анализама', 'Положительная реакция сама по себе не диагноз: она бывает и у здоровых людей, чаще старшего возраста, и при других воспалительных и инфекционных состояниях. Результат оценивает врач вместе с жалобами, осмотром и другими анализами', 'Eine positive Reaktion ist für sich genommen keine Diagnose: sie kommt auch bei Gesunden vor, häufiger im höheren Alter, sowie bei anderen entzündlichen und infektiösen Zuständen. Der Arzt beurteilt das Ergebnis zusammen mit Beschwerden, Untersuchung und weiteren Werten', 'Pozitif reaksiyon tek başına tanı değildir: sağlıklı kişilerde, özellikle ileri yaşta, ve başka iltihabi veya enfeksiyöz durumlarda da görülebilir. Sonucu hekim şikayetler, muayene ve diğer testlerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'transglutaminase-iga-antibodies'), 'Blood test for IgA antibodies to tissue transglutaminase, the main screening marker when gluten intolerance (coeliac disease) is investigated', 'Analiza krvi na antitijela klase IgA na tkivnu transglutaminazu, osnovni skrining marker pri ispitivanju netolerancije na gluten (celijakije)', 'Анализа крви на антитијела класе IgA на ткивну трансглутаминазу, основни скрининг маркер при испитивању нетолеранције на глутен (целијакије)', 'Анализ крови на антитела класса IgA к тканевой трансглутаминазе — основной скрининговый маркер при обследовании на непереносимость глютена (целиакию)', 'Bluttest auf IgA-Antikörper gegen Gewebetransglutaminase, der wichtigste Suchtest bei der Abklärung einer Glutenunverträglichkeit (Zöliakie)', 'Gluten intoleransının (çölyak hastalığının) araştırılmasında temel tarama belirteci olan doku transglutaminazına karşı IgA antikorları için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Long-lasting diarrhoea, bloating, weight loss, anaemia of unclear origin, growth delay in children, screening of relatives of people with coeliac disease', 'Dugotrajan proliv, nadutost, gubitak tjelesne težine, anemija nejasnog uzroka, zaostajanje u rastu kod djece, ispitivanje srodnika osoba sa celijakijom', 'Дуготрајан пролив, надутост, губитак тјелесне тежине, анемија нејасног узрока, заостајање у расту код дјеце, испитивање сродника особа са целијакијом', 'Длительная диарея, вздутие, потеря веса, анемия неясного происхождения, задержка роста у детей, обследование родственников людей с целиакией', 'Anhaltender Durchfall, Blähungen, Gewichtsverlust, Anämie unklarer Ursache, Wachstumsverzögerung bei Kindern, Abklärung bei Angehörigen von Menschen mit Zöliakie', 'Uzun süren ishal, şişkinlik, kilo kaybı, nedeni belirsiz kansızlık, çocuklarda büyüme geriliği, çölyaklı kişilerin yakınlarının taranması', 'No special preparation required; it is important not to remove gluten-containing foods from the diet before the test, the timing is agreed with the doctor', 'Nije potrebna posebna priprema; važno je da se hrana sa glutenom ne izbacuje iz ishrane prije analize, dogovor se pravi sa ljekarom', 'Није потребна посебна припрема; важно је да се храна са глутеном не избацује из исхране прије анализе, договор се прави са љекаром', 'Специальной подготовки не требуется; важно не убирать продукты с глютеном из питания перед сдачей, порядок обсуждают с врачом', 'Keine besondere Vorbereitung erforderlich; wichtig ist, glutenhaltige Lebensmittel vor dem Test nicht wegzulassen, den Zeitpunkt bespricht man mit dem Arzt', 'Özel bir hazırlık gerekmez; test öncesinde gluten içeren besinlerin diyetten çıkarılmaması önemlidir, zamanlama hekimle kararlaştırılır', 'A positive result by itself does not mean a disease: the antibodies also occur in other conditions and the result is affected by the total IgA level. The doctor decides what the test means together with symptoms and further work-up', 'Pozitivan nalaz sam po sebi ne znači bolest: antitijela se javljaju i kod drugih stanja, a na rezultat utiče nivo ukupnog IgA. Šta analiza znači, utvrđuje ljekar zajedno sa tegobama i daljim ispitivanjem', 'Позитиван налаз сам по себи не значи болест: антитијела се јављају и код других стања, а на резултат утиче ниво укупног IgA. Шта анализа значи, утврђује љекар заједно са тегобама и даљим испитивањем', 'Положительный результат сам по себе не означает болезнь: антитела встречаются и при других состояниях, а на результат влияет уровень общего IgA. Что означает анализ, определяет врач вместе с симптомами и дальнейшим обследованием', 'Ein positiver Befund allein bedeutet keine Erkrankung: die Antikörper kommen auch bei anderen Zuständen vor, und das Gesamt-IgA beeinflusst das Ergebnis. Was der Test bedeutet, entscheidet der Arzt zusammen mit den Beschwerden und der weiteren Abklärung', 'Pozitif sonuç tek başına hastalık anlamına gelmez: bu antikorlar başka durumlarda da görülebilir ve sonucu toplam IgA düzeyi etkiler. Testin anlamını hekim şikayetler ve ileri incelemelerle birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'transglutaminase-igg-antibodies'), 'Blood test for IgG antibodies to tissue transglutaminase, the variant of the gluten test used when total IgA is low', 'Analiza krvi na antitijela klase IgG na tkivnu transglutaminazu, varijanta glutenskog testa koja se koristi kada je ukupni IgA snižen', 'Анализа крви на антитијела класе IgG на ткивну трансглутаминазу, варијанта глутенског теста која се користи када је укупни IgA снижен', 'Анализ крови на антитела класса IgG к тканевой трансглутаминазе — вариант глютенового теста, который используют при сниженном уровне общего IgA', 'Bluttest auf IgG-Antikörper gegen Gewebetransglutaminase, die Variante des Glutentests bei erniedrigtem Gesamt-IgA', 'Toplam IgA düşük olduğunda kullanılan, doku transglutaminazına karşı IgG antikorlarını ölçen gluten testi çeşidi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Investigation of gluten intolerance in people with IgA deficiency, clarification of IgA test results, evaluation of children and relatives of people with coeliac disease', 'Ispitivanje netolerancije na gluten kod nedostatka IgA, razjašnjenje nalaza IgA testova, ispitivanje djece i srodnika osoba sa celijakijom', 'Испитивање нетолеранције на глутен код недостатка IgA, разјашњење налаза IgA тестова, испитивање дјеце и сродника особа са целијакијом', 'Обследование на непереносимость глютена при дефиците IgA, уточнение результатов IgA-тестов, обследование детей и родственников людей с целиакией', 'Abklärung einer Glutenunverträglichkeit bei IgA-Mangel, Klärung von IgA-Testergebnissen, Untersuchung von Kindern und Angehörigen von Menschen mit Zöliakie', 'IgA eksikliği olanlarda gluten intoleransının araştırılması, IgA testi sonuçlarının netleştirilmesi, çocukların ve çölyaklı kişilerin yakınlarının değerlendirilmesi', 'No special preparation required; gluten is not removed from the diet before the test, the arrangement is discussed with the doctor', 'Nije potrebna posebna priprema; gluten se prije analize ne izbacuje iz ishrane, dogovor se pravi sa ljekarom', 'Није потребна посебна припрема; глутен се прије анализе не избацује из исхране, договор се прави са љекаром', 'Специальной подготовки не требуется; глютен из питания перед сдачей не исключают, порядок обсуждают с врачом', 'Keine besondere Vorbereitung erforderlich; Gluten wird vor dem Test nicht vom Speiseplan gestrichen, das Vorgehen bespricht man mit dem Arzt', 'Özel bir hazırlık gerekmez; test öncesi gluten diyetten çıkarılmaz, ayrıntılar hekimle konuşulur', 'A positive result on its own is not a diagnosis: such antibodies are also found in people without symptoms and in other bowel and liver conditions. The doctor decides what it means based on the whole set of tests and symptoms', 'Pozitivan nalaz sam po sebi nije dijagnoza: takva antitijela se nalaze i kod osoba bez tegoba i kod drugih bolesti crijeva i jetre. Šta nalaz znači, odlučuje ljekar na osnovu svih analiza i tegoba', 'Позитиван налаз сам по себи није дијагноза: таква антитијела се налазе и код особа без тегоба и код других болести цријева и јетре. Шта налаз значи, одлучује љекар на основу свих анализа и тегоба', 'Положительный результат сам по себе не диагноз: такие антитела находят и у людей без жалоб, и при других заболеваниях кишечника и печени. Что он означает, решает врач по совокупности анализов и симптомов', 'Ein positiver Befund ist für sich genommen keine Diagnose: solche Antikörper finden sich auch bei Menschen ohne Beschwerden und bei anderen Darm- und Lebererkrankungen. Was er bedeutet, entscheidet der Arzt anhand aller Werte und Beschwerden', 'Pozitif sonuç tek başına tanı değildir: bu antikorlar şikayeti olmayan kişilerde ve başka bağırsak ve karaciğer hastalıklarında da bulunabilir. Anlamını hekim tüm testler ve şikayetlerle birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'anti-ccp-antibodies'), 'Blood test for antibodies to cyclic citrullinated peptide (Anti-CCP), a marker used when joints are evaluated', 'Analiza krvi na antitijela na ciklični citrulinisani peptid (Anti-CCP), marker koji se koristi pri pregledu zglobova', 'Анализа крви на антитијела на циклични цитрулинисани пептид (Anti-CCP), маркер који се користи при прегледу зглобова', 'Анализ крови на антитела к циклическому цитруллинированному пептиду (Anti-CCP) — маркер, используемый при обследовании суставов', 'Bluttest auf Antikörper gegen cyclisches citrulliniertes Peptid (Anti-CCP), ein Marker bei der Abklärung von Gelenkbeschwerden', 'Eklemlerin değerlendirilmesinde kullanılan siklik sitrülline peptit antikorları (Anti-CCP) için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Long-lasting joint pain and swelling, morning stiffness, assessment alongside rheumatoid factor and inflammation markers', 'Dugotrajni bolovi i otok zglobova, jutarnja ukočenost, ispitivanje uz reumatoidni faktor i pokazatelje upale', 'Дуготрајни болови и оток зглобова, јутарња укоченост, испитивање уз реуматоидни фактор и показатеље упале', 'Длительные боли и припухлость суставов, утренняя скованность, обследование вместе с ревматоидным фактором и показателями воспаления', 'Länger bestehende Gelenkschmerzen und Schwellungen, Morgensteifigkeit, Abklärung zusammen mit Rheumafaktor und Entzündungswerten', 'Uzun süren eklem ağrısı ve şişliği, sabah tutukluğu, romatoid faktör ve iltihap göstergeleriyle birlikte değerlendirme', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'A positive result by itself does not mean a disease: the antibodies are sometimes found in people without symptoms and in other conditions. The rheumatologist determines what the result means together with the examination, imaging and other tests', 'Pozitivan nalaz sam po sebi ne znači bolest: antitijela se ponekad nalaze i kod osoba bez tegoba i kod drugih stanja. Značaj rezultata utvrđuje reumatolog zajedno sa pregledom, snimcima i drugim analizama', 'Позитиван налаз сам по себи не значи болест: антитијела се понекад налазе и код особа без тегоба и код других стања. Значај резултата утврђује реуматолог заједно са прегледом, снимцима и другим анализама', 'Положительный результат сам по себе не означает болезнь: антитела иногда обнаруживают у людей без жалоб и при других состояниях. Значение результата определяет ревматолог вместе с осмотром, снимками и другими анализами', 'Ein positiver Befund allein bedeutet keine Erkrankung: die Antikörper finden sich mitunter auch bei Menschen ohne Beschwerden und bei anderen Zuständen. Was das Ergebnis bedeutet, entscheidet der Rheumatologe zusammen mit Untersuchung, Bildgebung und weiteren Werten', 'Pozitif sonuç tek başına hastalık anlamına gelmez: bu antikorlar bazen şikayeti olmayan kişilerde ve başka durumlarda da bulunur. Sonucun anlamını romatolog muayene, görüntüleme ve diğer testlerle birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'gliadin-iga-antibodies'), 'Blood test for IgA antibodies to gliadin, a gluten protein, used when gluten intolerance is investigated', 'Analiza krvi na antitijela klase IgA na glijadin, bjelančevinu glutena, koja se radi pri ispitivanju netolerancije na gluten', 'Анализа крви на антитијела класе IgA на глијадин, бјеланчевину глутена, која се ради при испитивању нетолеранције на глутен', 'Анализ крови на антитела класса IgA к глиадину — белку глютена, определяется при обследовании на непереносимость глютена', 'Bluttest auf IgA-Antikörper gegen Gliadin, ein Eiweiß des Glutens, bei der Abklärung einer Glutenunverträglichkeit', 'Gluten intoleransının araştırılmasında bakılan, bir gluten proteini olan gliadine karşı IgA antikorları için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Bloating, changes in stool and weight loss on a gluten-containing diet, evaluation of young children, addition to transglutaminase tests', 'Nadutost, promjene stolice i gubitak tjelesne težine uz ishranu sa glutenom, ispitivanje male djece, dopuna testovima na transglutaminazu', 'Надутост, промјене столице и губитак тјелесне тежине уз исхрану са глутеном, испитивање мале дјеце, допуна тестовима на трансглутаминазу', 'Вздутие, нарушения стула и потеря веса на питании с глютеном, обследование детей раннего возраста, дополнение к тестам на трансглутаминазу', 'Blähungen, veränderter Stuhlgang und Gewichtsverlust bei glutenhaltiger Ernährung, Untersuchung von Kleinkindern, Ergänzung zu den Transglutaminase-Tests', 'Gluten içeren beslenmede şişkinlik, dışkılama değişiklikleri ve kilo kaybı, küçük çocukların değerlendirilmesi, transglutaminaz testlerine ek olarak', 'No special preparation required; gluten-containing foods are not removed from the diet before the test', 'Nije potrebna posebna priprema; hrana sa glutenom se prije analize ne izbacuje iz ishrane', 'Није потребна посебна припрема; храна са глутеном се прије анализе не избацује из исхране', 'Специальной подготовки не требуется; продукты с глютеном перед сдачей из питания не убирают', 'Keine besondere Vorbereitung erforderlich; glutenhaltige Lebensmittel werden vor dem Test nicht weggelassen', 'Özel bir hazırlık gerekmez; test öncesinde gluten içeren besinler diyetten çıkarılmaz', 'A positive result by itself does not mean coeliac disease: these antibodies are less specific and also occur in healthy people and in other bowel conditions. The doctor assesses the result together with other tests and symptoms', 'Pozitivan nalaz sam po sebi ne znači celijakiju: ova antitijela su manje specifična i sreću se kod zdravih osoba i kod drugih bolesti crijeva. Nalaz procjenjuje ljekar zajedno sa drugim testovima i tegobama', 'Позитиван налаз сам по себи не значи целијакију: ова антитијела су мање специфична и срећу се код здравих особа и код других болести цријева. Налаз процјењује љекар заједно са другим тестовима и тегобама', 'Положительный результат сам по себе не означает целиакию: эти антитела менее специфичны и встречаются у здоровых людей и при других болезнях кишечника. Результат оценивает врач вместе с другими тестами и симптомами', 'Ein positiver Befund allein bedeutet keine Zöliakie: diese Antikörper sind weniger spezifisch und kommen auch bei Gesunden und bei anderen Darmerkrankungen vor. Der Arzt beurteilt das Ergebnis zusammen mit weiteren Tests und Beschwerden', 'Pozitif sonuç tek başına çölyak anlamına gelmez: bu antikorlar daha az özgüldür ve sağlıklı kişilerde ile başka bağırsak hastalıklarında da görülür. Sonucu hekim diğer testler ve şikayetlerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'gliadin-igg-antibodies'), 'Blood test for IgG antibodies to gliadin, a variant of the gluten test that is useful when total IgA is low', 'Analiza krvi na antitijela klase IgG na glijadin, varijanta glutenskog testa korisna kada je ukupni IgA snižen', 'Анализа крви на антитијела класе IgG на глијадин, варијанта глутенског теста корисна када је укупни IgA снижен', 'Анализ крови на антитела класса IgG к глиадину — вариант глютенового теста, полезный при сниженном уровне общего IgA', 'Bluttest auf IgG-Antikörper gegen Gliadin, eine Variante des Glutentests, die bei erniedrigtem Gesamt-IgA hilfreich ist', 'Toplam IgA düşük olduğunda yararlı olan, gliadine karşı IgG antikorlarını ölçen gluten testi çeşidi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Investigation of gluten intolerance in IgA deficiency, long-lasting bowel complaints, follow-up in children alongside other markers', 'Ispitivanje netolerancije na gluten kod nedostatka IgA, dugotrajne crijevne tegobe, praćenje djece uz druge markere', 'Испитивање нетолеранције на глутен код недостатка IgA, дуготрајне цријевне тегобе, праћење дјеце уз друге маркере', 'Обследование на непереносимость глютена при дефиците IgA, длительные кишечные жалобы, наблюдение детей вместе с другими маркерами', 'Abklärung einer Glutenunverträglichkeit bei IgA-Mangel, anhaltende Darmbeschwerden, Verlaufskontrolle bei Kindern zusammen mit anderen Markern', 'IgA eksikliğinde gluten intoleransının araştırılması, uzun süren bağırsak şikayetleri, çocuklarda diğer belirteçlerle birlikte izlem', 'No special preparation required; the usual gluten-containing diet is kept before the test', 'Nije potrebna posebna priprema; uobičajena ishrana sa glutenom se prije analize zadržava', 'Није потребна посебна припрема; уобичајена исхрана са глутеном се прије анализе задржава', 'Специальной подготовки не требуется; питание с глютеном перед сдачей сохраняют в обычном виде', 'Keine besondere Vorbereitung erforderlich; die gewohnte glutenhaltige Ernährung wird vor dem Test beibehalten', 'Özel bir hazırlık gerekmez; test öncesinde her zamanki gluten içeren beslenme sürdürülür', 'A positive result by itself is not a diagnosis: IgG antibodies to gliadin are often found in people without coeliac disease, including healthy ones. The doctor determines the meaning based on the whole set of tests, symptoms and further work-up', 'Pozitivan nalaz sam po sebi nije dijagnoza: IgG antitijela na glijadin se često nalaze i kod osoba bez celijakije, uključujući zdrave. Značaj rezultata utvrđuje ljekar na osnovu svih analiza, tegoba i daljeg ispitivanja', 'Позитиван налаз сам по себи није дијагноза: IgG антитијела на глијадин се често налазе и код особа без целијакије, укључујући здраве. Значај резултата утврђује љекар на основу свих анализа, тегоба и даљег испитивања', 'Положительный результат сам по себе не диагноз: антитела IgG к глиадину нередко находят у людей без целиакии, в том числе здоровых. Значение результата определяет врач по совокупности анализов, жалоб и дальнейшего обследования', 'Ein positiver Befund allein ist keine Diagnose: IgG-Antikörper gegen Gliadin finden sich häufig auch bei Menschen ohne Zöliakie, darunter Gesunde. Die Bedeutung bestimmt der Arzt anhand aller Werte, Beschwerden und der weiteren Abklärung', 'Pozitif sonuç tek başına tanı değildir: gliadine karşı IgG antikorları çölyak hastalığı olmayan kişilerde, sağlıklı olanlar dahil, sıkça bulunur. Sonucun anlamını hekim tüm testler, şikayetler ve ileri incelemelerle belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'lupus-cells'), 'Microscopic blood examination that looks for specific cells (LE cells) appearing in some autoimmune processes', 'Mikroskopski pregled krvi u kojem se traže posebne ćelije (LE ćelije) koje se javljaju kod nekih autoimunih procesa', 'Микроскопски преглед крви у којем се траже посебне ћелије (LE ћелије) које се јављају код неких аутоимуних процеса', 'Микроскопическое исследование крови, при котором ищут особые клетки (LE-клетки), появляющиеся при некоторых аутоиммунных процессах', 'Mikroskopische Blutuntersuchung, bei der nach besonderen Zellen (LE-Zellen) gesucht wird, die bei manchen Autoimmunprozessen auftreten', 'Bazı otoimmün süreçlerde ortaya çıkan özel hücrelerin (LE hücreleri) arandığı mikroskobik kan incelemesi', 'Venous blood draw, after which the sample is processed in the laboratory and examined under a microscope, the draw itself takes a few minutes', 'Uzimanje venske krvi, zatim se uzorak obrađuje u laboratoriji i pregleda pod mikroskopom, samo uzimanje traje nekoliko minuta', 'Узимање венске крви, затим се узорак обрађује у лабораторији и прегледа под микроскопом, само узимање траје неколико минута', 'Забор венозной крови, затем образец обрабатывают в лаборатории и просматривают под микроскопом; сам забор занимает несколько минут', 'Blutentnahme aus einer Vene, anschließend wird die Probe im Labor aufbereitet und unter dem Mikroskop betrachtet, die Entnahme selbst dauert wenige Minuten', 'Damardan kan alınır, ardından örnek laboratuvarda hazırlanıp mikroskopta incelenir, kan alma işlemi birkaç dakika sürer', 'Evaluation when a systemic autoimmune condition is suspected, joint and skin complaints combined with fever, addition to antibody tests', 'Ispitivanje pri sumnji na sistemske autoimune bolesti, spoj zglobnih i kožnih tegoba sa povišenom temperaturom, dopuna testovima na antitijela', 'Испитивање при сумњи на системске аутоимуне болести, спој зглобних и кожних тегоба са повишеном температуром, допуна тестовима на антитијела', 'Обследование при подозрении на системные аутоиммунные заболевания, сочетание суставных и кожных жалоб с лихорадкой, дополнение к тестам на антитела', 'Abklärung bei Verdacht auf systemische Autoimmunerkrankungen, Gelenk- und Hautbeschwerden zusammen mit Fieber, Ergänzung zu Antikörpertests', 'Sistemik otoimmün hastalık şüphesinde değerlendirme, ateşle birlikte eklem ve cilt şikayetleri, antikor testlerine ek olarak', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'Finding such cells by itself does not mean a particular disease, and their absence does not rule one out: the method is old and less sensitive than modern antibody tests. The doctor assesses the result together with the clinical picture and other tests', 'Nalaz takvih ćelija sam po sebi ne znači određenu bolest, a njihovo odsustvo je ne isključuje: metoda je starija i manje osjetljiva od savremenih testova na antitijela. Nalaz procjenjuje ljekar zajedno sa kliničkom slikom i drugim analizama', 'Налаз таквих ћелија сам по себи не значи одређену болест, а њихово одсуство је не искључује: метода је старија и мање осјетљива од савремених тестова на антитијела. Налаз процјењује љекар заједно са клиничком сликом и другим анализама', 'Находка таких клеток сама по себе не означает конкретную болезнь, а их отсутствие её не исключает: метод старый и менее чувствительный, чем современные тесты на антитела. Результат оценивает врач вместе с клинической картиной и другими анализами', 'Der Nachweis solcher Zellen bedeutet für sich genommen keine bestimmte Erkrankung, und ihr Fehlen schließt eine solche nicht aus: die Methode ist älter und weniger empfindlich als moderne Antikörpertests. Der Arzt beurteilt das Ergebnis zusammen mit dem klinischen Bild und weiteren Werten', 'Bu hücrelerin görülmesi tek başına belirli bir hastalık anlamına gelmez, görülmemesi de hastalığı dışlamaz: yöntem eskidir ve güncel antikor testlerine göre daha az duyarlıdır. Sonucu hekim klinik tablo ve diğer testlerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ana-antinuclear-antibodies'), 'Blood test for antibodies to cell nucleus components (ANA), a screening test when systemic autoimmune conditions are investigated', 'Analiza krvi na antitijela na sastojke ćelijskog jedra (ANA), skrining test pri ispitivanju sistemskih autoimunih bolesti', 'Анализа крви на антитијела на састојке ћелијског једра (ANA), скрининг тест при испитивању системских аутоимуних болести', 'Анализ крови на антитела к компонентам клеточного ядра (ANA) — скрининговый тест при обследовании на системные аутоиммунные заболевания', 'Bluttest auf Antikörper gegen Zellkernbestandteile (ANA), ein Suchtest bei der Abklärung systemischer Autoimmunerkrankungen', 'Sistemik otoimmün hastalıkların araştırılmasında tarama testi olarak kullanılan, hücre çekirdeği bileşenlerine karşı antikorlar (ANA) için kan testi', 'Venous blood draw; the laboratory reports the titre and the fluorescence pattern, the draw itself takes a few minutes', 'Uzimanje venske krvi, u laboratoriji se određuju titar i tip fluorescencije, samo uzimanje traje nekoliko minuta', 'Узимање венске крви, у лабораторији се одређују титар и тип флуоресценције, само узимање траје неколико минута', 'Забор венозной крови; в лаборатории определяют титр и тип свечения, сам забор занимает несколько минут', 'Blutentnahme aus einer Vene, im Labor werden Titer und Fluoreszenzmuster bestimmt, die Entnahme selbst dauert wenige Minuten', 'Damardan kan alınır, laboratuvarda titre ve boyanma paterni belirlenir, kan alma işlemi birkaç dakika sürer', 'Prolonged fever of unclear origin, joint pain, skin rashes, increased sensitivity to sunlight, evaluation when a connective tissue disease is suspected', 'Dugotrajna povišena temperatura nejasnog uzroka, bolovi u zglobovima, promjene na koži, pojačana osjetljivost na sunce, ispitivanje pri sumnji na sistemske bolesti vezivnog tkiva', 'Дуготрајна повишена температура нејасног узрока, болови у зглобовима, промјене на кожи, појачана осјетљивост на сунце, испитивање при сумњи на системске болести везивног ткива', 'Длительная лихорадка неясного происхождения, боли в суставах, кожные высыпания, повышенная чувствительность к солнцу, обследование при подозрении на системные болезни соединительной ткани', 'Länger bestehendes Fieber unklarer Ursache, Gelenkschmerzen, Hautausschläge, erhöhte Lichtempfindlichkeit, Abklärung bei Verdacht auf Kollagenosen', 'Nedeni belirsiz uzun süreli ateş, eklem ağrıları, ciltte döküntüler, güneşe karşı artmış duyarlılık, bağ dokusu hastalığı şüphesinde değerlendirme', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'A positive result by itself does not mean a disease: ANA in low titre occur in healthy people, more often with age, and also with infections, thyroid conditions and some medications. The doctor assesses the titre and the pattern together with the clinical picture and confirmatory tests', 'Pozitivan nalaz sam po sebi ne znači bolest: ANA u niskom titru se nalaze i kod zdravih osoba, češće sa godinama, kao i kod infekcija, bolesti štitne žlijezde i uz neke lijekove. Titar i tip fluorescencije procjenjuje ljekar zajedno sa kliničkom slikom i dodatnim testovima', 'Позитиван налаз сам по себи не значи болест: ANA у ниском титру се налазе и код здравих особа, чешће са годинама, као и код инфекција, болести штитне жлијезде и уз неке лијекове. Титар и тип флуоресценције процјењује љекар заједно са клиничком сликом и додатним тестовима', 'Положительный результат сам по себе не означает болезнь: ANA в низком титре встречаются у здоровых людей, чаще с возрастом, а также при инфекциях, болезнях щитовидной железы и на фоне некоторых лекарств. Титр и тип свечения оценивает врач вместе с клинической картиной и уточняющими тестами', 'Ein positiver Befund allein bedeutet keine Erkrankung: ANA in niedrigem Titer kommen bei Gesunden vor, häufiger mit zunehmendem Alter, ebenso bei Infektionen, Schilddrüsenerkrankungen und unter bestimmten Medikamenten. Titer und Muster beurteilt der Arzt zusammen mit dem klinischen Bild und ergänzenden Tests', 'Pozitif sonuç tek başına hastalık anlamına gelmez: düşük titrede ANA sağlıklı kişilerde, özellikle yaşla birlikte, ayrıca enfeksiyonlarda, tiroid hastalıklarında ve bazı ilaçların kullanımında görülebilir. Titreyi ve paterni hekim klinik tablo ve doğrulayıcı testlerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ovarian-antibodies'), 'Blood test for antibodies to ovarian tissue, a supporting test when cycle disorders and difficulties conceiving are investigated', 'Analiza krvi na antitijela na tkivo jajnika, pomoćni test pri ispitivanju poremećaja ciklusa i teškoća sa začećem', 'Анализа крви на антитијела на ткиво јајника, помоћни тест при испитивању поремећаја циклуса и тешкоћа са зачећем', 'Анализ крови на антитела к тканям яичника — вспомогательный тест при обследовании по поводу нарушений цикла и трудностей с зачатием', 'Bluttest auf Antikörper gegen Eierstockgewebe, ein ergänzender Test bei der Abklärung von Zyklusstörungen und unerfülltem Kinderwunsch', 'Adet düzensizlikleri ve gebe kalmada zorlukların araştırılmasında yardımcı olarak kullanılan, yumurtalık dokusuna karşı antikorlar için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Irregular cycle, early decline of ovarian function, long unsuccessful attempts to conceive, assessment before assisted reproduction programmes', 'Neredovan ciklus, rano slabljenje funkcije jajnika, dugotrajni neuspješni pokušaji začeća, ispitivanje prije programa potpomognute oplodnje', 'Нередован циклус, рано слабљење функције јајника, дуготрајни неуспјешни покушаји зачећа, испитивање прије програма потпомогнуте оплодње', 'Нерегулярный цикл, раннее снижение функции яичников, длительные неудачные попытки зачатия, обследование перед программами вспомогательной репродукции', 'Unregelmäßiger Zyklus, frühes Nachlassen der Eierstockfunktion, länger bestehender unerfüllter Kinderwunsch, Abklärung vor Kinderwunschbehandlungen', 'Düzensiz adet döngüsü, yumurtalık işlevinin erken azalması, uzun süredir gebelik elde edilememesi, yardımcı üreme programları öncesi değerlendirme', 'No special preparation required; the referring doctor specifies the cycle day for the sample', 'Nije potrebna posebna priprema; dan ciklusa za uzimanje uzorka određuje ljekar koji je uputio na analizu', 'Није потребна посебна припрема; дан циклуса за узимање узорка одређује љекар који је упутио на анализу', 'Специальной подготовки не требуется; день цикла для забора уточняет направивший врач', 'Keine besondere Vorbereitung erforderlich; den Zyklustag für die Entnahme gibt der überweisende Arzt vor', 'Özel bir hazırlık gerekmez; örneğin alınacağı döngü gününü yönlendiren hekim belirtir', 'A positive result by itself does not mean a disease and does not predict the outcome of treatment: such antibodies also occur in healthy women and laboratory methods differ. The gynaecologist or fertility specialist considers the result together with hormone levels, ultrasound and medical history', 'Pozitivan nalaz sam po sebi ne znači bolest i ne predviđa ishod liječenja: takva antitijela se sreću i kod zdravih žena, a metode se razlikuju među laboratorijama. Nalaz u obzir uzima ginekolog ili specijalista za plodnost zajedno sa hormonima, ultrazvukom i istorijom bolesti', 'Позитиван налаз сам по себи не значи болест и не предвиђа исход лијечења: таква антитијела се срећу и код здравих жена, а методе се разликују међу лабораторијама. Налаз у обзир узима гинеколог или специјалиста за плодност заједно са хормонима, ултразвуком и историјом болести', 'Положительный результат сам по себе не означает болезнь и не предсказывает исход лечения: такие антитела встречаются и у здоровых женщин, а методики в лабораториях различаются. Результат учитывает гинеколог или репродуктолог вместе с гормонами, УЗИ и историей', 'Ein positiver Befund allein bedeutet keine Erkrankung und sagt den Behandlungserfolg nicht voraus: solche Antikörper kommen auch bei gesunden Frauen vor, und die Labormethoden unterscheiden sich. Der Gynäkologe oder Kinderwunschspezialist berücksichtigt das Ergebnis zusammen mit Hormonwerten, Ultraschall und Vorgeschichte', 'Pozitif sonuç tek başına hastalık anlamına gelmez ve tedavinin sonucunu öngörmez: bu antikorlar sağlıklı kadınlarda da görülebilir ve laboratuvar yöntemleri farklılık gösterir. Sonucu kadın hastalıkları veya üreme sağlığı uzmanı hormonlar, ultrason ve öyküyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'anti-tshr'), 'Blood test for antibodies to the thyroid-stimulating hormone (TSH) receptor on thyroid cells', 'Analiza krvi na antitijela na receptor tireostimulišućeg hormona (TSH) na ćelijama štitne žlijezde', 'Анализа крви на антитијела на рецептор тиреостимулишућег хормона (TSH) на ћелијама штитне жлијезде', 'Анализ крови на антитела к рецептору тиреотропного гормона (TSH) на клетках щитовидной железы', 'Bluttest auf Antikörper gegen den Rezeptor des schilddrüsenstimulierenden Hormons (TSH) auf den Schilddrüsenzellen', 'Tiroid hücrelerindeki tiroid uyarıcı hormon (TSH) reseptörüne karşı antikorlar için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Evaluation of increased thyroid activity, eye complaints related to the thyroid, assessment during pregnancy in women with thyroid conditions', 'Ispitivanje pojačane funkcije štitne žlijezde, očne tegobe povezane sa štitnom žlijezdom, ispitivanje u trudnoći kod žena sa oboljenjima štitne žlijezde', 'Испитивање појачане функције штитне жлијезде, очне тегобе повезане са штитном жлијездом, испитивање у трудноћи код жена са обољењима штитне жлијезде', 'Обследование при повышенной функции щитовидной железы, глазные жалобы, связанные со щитовидной железой, обследование при беременности у женщин с заболеваниями щитовидной железы', 'Abklärung einer gesteigerten Schilddrüsenfunktion, Augenbeschwerden im Zusammenhang mit der Schilddrüse, Untersuchung in der Schwangerschaft bei Frauen mit Schilddrüsenerkrankungen', 'Tiroid işlevinin artmış olduğu durumların değerlendirilmesi, tiroidle ilişkili göz şikayetleri, tiroid hastalığı olan kadınlarda gebelikte değerlendirme', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'Detecting the antibodies by itself is not a diagnosis: the result is meaningful only alongside hormone levels, ultrasound and symptoms, and the antibodies also occur outside active disease. The endocrinologist determines what the result means', 'Nalaz antitijela sam po sebi nije dijagnoza: rezultat ima smisla samo uz nivo hormona, ultrazvuk i tegobe, a antitijela se sreću i van aktivne bolesti. Značaj rezultata utvrđuje endokrinolog', 'Налаз антитијела сам по себи није дијагноза: резултат има смисла само уз ниво хормона, ултразвук и тегобе, а антитијела се срећу и ван активне болести. Значај резултата утврђује ендокринолог', 'Обнаружение антител само по себе не равно диагнозу: результат имеет смысл только рядом с уровнем гормонов, УЗИ и жалобами, а антитела встречаются и вне активной болезни. Значение результата определяет эндокринолог', 'Der Nachweis der Antikörper ist für sich genommen keine Diagnose: das Ergebnis ist nur zusammen mit Hormonwerten, Ultraschall und Beschwerden aussagekräftig, und die Antikörper kommen auch außerhalb einer aktiven Erkrankung vor. Was es bedeutet, entscheidet der Endokrinologe', 'Antikorun saptanması tek başına tanı değildir: sonuç ancak hormon düzeyleri, ultrason ve şikayetlerle birlikte anlam taşır, ayrıca antikorlar aktif hastalık dışında da bulunabilir. Sonucun anlamını endokrinolog belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'anti-tshr-antibodies'), 'Blood test for TSHR antibodies that helps clarify the cause of altered thyroid function and follow it over time', 'Analiza krvi na antitijela na TSHR koja pomaže da se razjasni uzrok promijenjenog rada štitne žlijezde i da se prati tok', 'Анализа крви на антитијела на TSHR која помаже да се разјасни узрок промијењеног рада штитне жлијезде и да се прати ток', 'Анализ крови на антитела к TSHR, который помогает уточнить причину изменённой работы щитовидной железы и следить за ней в динамике', 'Bluttest auf TSHR-Antikörper, der hilft, die Ursache einer veränderten Schilddrüsenfunktion zu klären und den Verlauf zu verfolgen', 'Tiroid işlevindeki değişikliğin nedenini netleştirmeye ve gidişi izlemeye yardımcı olan TSHR antikorları için kan testi', 'Venous blood draw, the result is reported as a quantitative value, the draw itself takes a few minutes', 'Uzimanje venske krvi, nalaz se izdaje kao brojčana vrijednost, samo uzimanje traje nekoliko minuta', 'Узимање венске крви, налаз се издаје као бројчана вриједност, само узимање траје неколико минута', 'Забор венозной крови, результат выдают количественно; сам забор занимает несколько минут', 'Blutentnahme aus einer Vene, das Ergebnis wird als Zahlenwert berichtet, die Entnahme selbst dauert wenige Minuten', 'Damardan kan alınır, sonuç sayısal değer olarak verilir, kan alma işlemi birkaç dakika sürer', 'Clarifying the cause of an overactive thyroid, follow-up during prescribed treatment, assessment when planning a pregnancy', 'Razjašnjenje uzroka pojačanog rada štitne žlijezde, praćenje toka tokom propisane terapije, ispitivanje pri planiranju trudnoće', 'Разјашњење узрока појачаног рада штитне жлијезде, праћење тока током прописане терапије, испитивање при планирању трудноће', 'Уточнение причины избыточной функции щитовидной железы, наблюдение в динамике на фоне назначенного лечения, обследование при планировании беременности', 'Klärung der Ursache einer Schilddrüsenüberfunktion, Verlaufskontrolle unter der verordneten Behandlung, Abklärung bei Kinderwunsch', 'Tiroidin aşırı çalışma nedeninin netleştirilmesi, verilen tedavi sırasında izlem, gebelik planlaması öncesi değerlendirme', 'No special preparation required; mention any thyroid medication to the doctor and the laboratory', 'Nije potrebna posebna priprema; o lijekovima za štitnu žlijezdu treba obavijestiti ljekara i laboratoriju', 'Није потребна посебна припрема; о лијековима за штитну жлијезду треба обавијестити љекара и лабораторију', 'Специальной подготовки не требуется; о препаратах для щитовидной железы стоит сказать врачу и в лаборатории', 'Keine besondere Vorbereitung erforderlich; Schilddrüsenmedikamente sollten dem Arzt und dem Labor mitgeteilt werden', 'Özel bir hazırlık gerekmez; kullanılan tiroid ilaçları hekime ve laboratuvara bildirilmelidir', 'Detecting the antibodies by itself does not mean a disease: in some people they persist after the symptoms have settled, and they also occur in other thyroid conditions. The endocrinologist interprets the result over time and together with hormone levels', 'Nalaz antitijela sam po sebi ne znači bolest: kod dijela ljudi ostaju prisutna i nakon što tegobe prođu, a javljaju se i kod drugih stanja štitne žlijezde. Rezultat tokom vremena i zajedno sa hormonima tumači endokrinolog', 'Налаз антитијела сам по себи не значи болест: код дијела људи остају присутна и након што тегобе прођу, а јављају се и код других стања штитне жлијезде. Резултат током времена и заједно са хормонима тумачи ендокринолог', 'Обнаружение антител само по себе не означает болезнь: у части людей они сохраняются и после того, как самочувствие нормализовалось, встречаются и при других состояниях щитовидной железы. Результат в динамике и вместе с гормонами трактует эндокринолог', 'Der Nachweis der Antikörper bedeutet für sich genommen keine Erkrankung: bei manchen Menschen bleiben sie auch nach dem Abklingen der Beschwerden nachweisbar und kommen ebenso bei anderen Schilddrüsenzuständen vor. Den Verlauf und das Ergebnis zusammen mit den Hormonwerten deutet der Endokrinologe', 'Antikorun saptanması tek başına hastalık anlamına gelmez: bazı kişilerde şikayetler geçtikten sonra da bulunur ve başka tiroid durumlarında da görülebilir. Sonucu zaman içindeki seyri ve hormon değerleriyle birlikte endokrinolog yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'calcium-in-urine'), 'Measurement of the amount of calcium the kidneys remove with urine', 'Mjerenje količine kalcijuma koju bubrezi izlučuju mokraćom', 'Мјерење количине калцијума коју бубрези излучују мокраћом', 'Измерение количества кальция, которое почки выводят с мочой', 'Messung der Kalziummenge, die die Nieren mit dem Urin ausscheiden', 'Böbreklerin idrarla attığı kalsiyum miktarının ölçümü', 'Most often a 24-hour collection is examined, with all urine passed during the day gathered in one container, sometimes a single portion is enough', 'Najčešće se ispituje 24-časovni uzorak, gdje se sva mokraća tokom dana sakuplja u jednu posudu, a ponekad je dovoljan i jednokratni uzorak', 'Најчешће се испитује 24-часовни узорак, гдје се сва мокраћа током дана сакупља у једну посуду, а понекад је довољан и једнократни узорак', 'Чаще исследуется суточный сбор: вся моча за день собирается в одну ёмкость, иногда достаточно разовой порции', 'Meist wird Sammelurin über 24 Stunden untersucht, bei dem der gesamte Urin eines Tages in einem Behälter gesammelt wird, manchmal genügt eine Einzelprobe', 'Genellikle gün boyunca çıkarılan tüm idrarın tek kapta toplandığı 24 saatlik örnek incelenir, bazen tek seferlik örnek de yeterlidir', 'Kidney stones and recurrent stone formation, disorders of calcium metabolism, parathyroid gland conditions, monitoring while taking vitamin D or calcium supplements, reduced bone density', 'Kamen u bubregu i ponavljano stvaranje kamenaca, poremećaji metabolizma kalcijuma, bolesti paratireoidnih žlijezda, kontrola tokom uzimanja vitamina D i preparata kalcijuma, smanjena gustina kostiju', 'Камен у бубрегу и понављано стварање каменаца, поремећаји метаболизма калцијума, болести паратиреоидних жлијезда, контрола током узимања витамина Д и препарата калцијума, смањена густина костију', 'Мочекаменная болезнь и повторное образование камней, нарушения обмена кальция, заболевания паращитовидных желёз, контроль при приёме витамина D и препаратов кальция, снижение плотности костей', 'Nierensteine und wiederkehrende Steinbildung, Störungen des Kalziumstoffwechsels, Erkrankungen der Nebenschilddrüsen, Kontrolle bei Einnahme von Vitamin D und Kalziumpräparaten, verminderte Knochendichte', 'Böbrek taşı ve tekrarlayan taş oluşumu, kalsiyum metabolizması bozuklukları, paratiroid bezi hastalıkları, D vitamini ve kalsiyum takviyesi kullanımında izlem, kemik yoğunluğunda azalma', 'For a 24-hour collection the first morning portion is discarded, then all urine is collected until the next morning and the container is kept cool; vitamin D, calcium supplements and diuretics are discussed with the doctor in advance, drinking habits stay as usual', 'Kod 24-časovnog sakupljanja prva jutarnja porcija se baca, zatim se sakuplja sva mokraća do sljedećeg jutra, a posuda se drži na hladnom; uzimanje vitamina D, kalcijuma i diuretika unaprijed dogovoriti sa ljekarom, unos tečnosti ostaje uobičajen', 'Код 24-часовног сакупљања прва јутарња порција се баца, затим се сакупља сва мокраћа до сљедећег јутра, а посуда се држи на хладном; узимање витамина Д, калцијума и диуретика унапријед договорити са љекаром, унос течности остаје уобичајен', 'При суточном сборе первая утренняя порция сливается, дальше собирается вся моча до утра следующего дня, ёмкость хранится в холоде; приём витамина D, кальция и мочегонных заранее обсуждают с врачом, питьевой режим обычный', 'Beim Sammeln über 24 Stunden wird die erste Morgenportion verworfen, danach wird der gesamte Urin bis zum nächsten Morgen gesammelt und der Behälter kühl aufbewahrt; Vitamin D, Kalziumpräparate und Entwässerungsmittel vorher mit dem Arzt besprechen, die Trinkmenge bleibt wie gewohnt', '24 saatlik toplamada ilk sabah idrarı atılır, ardından ertesi sabaha kadar tüm idrar toplanır ve kap serin yerde tutulur; D vitamini, kalsiyum ve idrar söktürücü ilaçlar önceden hekimle görüşülür, sıvı alımı her zamanki gibi sürer', 'Deviations may be related to diet, calcium and vitamin D metabolism, parathyroid or kidney function, or certain medications. The result is assessed by a doctor together with blood calcium', 'Odstupanja mogu biti povezana sa ishranom, metabolizmom kalcijuma i vitamina D, radom paratireoidnih žlijezda ili bubrega, kao i sa nekim lijekovima. Nalaz ljekar procjenjuje zajedno sa kalcijumom u krvi', 'Одступања могу бити повезана са исхраном, метаболизмом калцијума и витамина Д, радом паратиреоидних жлијезда или бубрега, као и са неким лијековима. Налаз љекар процјењује заједно са калцијумом у крви', 'Отклонения могут быть связаны с питанием, обменом кальция и витамина D, работой паращитовидных желёз или почек, а также с приёмом некоторых препаратов. Результат врач оценивает вместе с кальцием крови', 'Abweichungen können mit der Ernährung, dem Kalzium- und Vitamin-D-Stoffwechsel, der Funktion der Nebenschilddrüsen oder der Nieren sowie mit bestimmten Medikamenten zusammenhängen. Der Befund wird vom Arzt zusammen mit dem Kalzium im Blut beurteilt', 'Sapmalar beslenme, kalsiyum ve D vitamini metabolizması, paratiroid bezleri veya böbrek işleviyle ya da bazı ilaçlarla ilişkili olabilir. Sonucu hekim kandaki kalsiyumla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'creatinine-in-urine'), 'Measurement of creatinine, a breakdown product of muscle tissue that is removed by the kidneys', 'Mjerenje kreatinina, produkta razgradnje mišićnog tkiva koji se izlučuje preko bubrega', 'Мјерење креатинина, продукта разградње мишићног ткива који се излучује преко бубрега', 'Измерение креатинина — продукта распада мышечной ткани, который выводится почками', 'Bestimmung von Kreatinin, einem Abbauprodukt der Muskulatur, das über die Nieren ausgeschieden wird', 'Kas dokusunun yıkım ürünü olan ve böbreklerle atılan kreatininin ölçümü', 'Either a single portion or a 24-hour collection is analysed: the single portion serves to express other values per creatinine, the 24-hour one to calculate clearance', 'Ispituje se jednokratni uzorak ili 24-časovno sakupljanje: jednokratni služi za preračunavanje drugih parametara na kreatinin, a dnevni za izračunavanje klirensa', 'Испитује се једнократни узорак или 24-часовно сакупљање: једнократни служи за прерачунавање других параметара на креатинин, а дневни за израчунавање клиренса', 'Исследуется разовая порция или суточный сбор: разовая нужна для пересчёта других показателей на креатинин, суточная — для расчёта клиренса', 'Untersucht wird entweder eine Einzelprobe oder Sammelurin über 24 Stunden: die Einzelprobe dient dem Bezug anderer Werte auf Kreatinin, der Sammelurin der Berechnung der Clearance', 'Tek seferlik örnek ya da 24 saatlik toplama incelenir: tek örnek diğer değerlerin kreatinine oranlanmasında, günlük toplama ise klirens hesabında kullanılır', 'Assessment of kidney filtration, creatinine clearance calculation, expressing protein, albumin and electrolytes in a spot sample, follow-up in chronic kidney disease', 'Procjena filtracione funkcije bubrega, izračunavanje klirensa kreatinina, preračunavanje proteina, albumina i elektrolita u jednokratnom uzorku, praćenje hronične bubrežne bolesti', 'Процјена филтрационе функције бубрега, израчунавање клиренса креатинина, прерачунавање протеина, албумина и електролита у једнократном узорку, праћење хроничне бубрежне болести', 'Оценка фильтрационной функции почек, расчёт клиренса креатинина, пересчёт белка, альбумина и электролитов в разовой порции, наблюдение при хронической болезни почек', 'Beurteilung der Nierenfiltration, Berechnung der Kreatinin-Clearance, Bezug von Eiweiß, Albumin und Elektrolyten in der Einzelprobe, Verlaufskontrolle bei chronischer Nierenerkrankung', 'Böbrek süzme işlevinin değerlendirilmesi, kreatinin klirensi hesabı, tek örnekte protein, albümin ve elektrolitlerin oranlanması, kronik böbrek hastalığında izlem', 'For a single portion usual hygiene and a clean container are enough; for a 24-hour collection all urine of the day goes into one container kept cool, and intense exercise and large amounts of meat are avoided the day before', 'Za jednokratni uzorak dovoljni su uobičajena higijena i čista posuda; kod 24-časovnog sakupljanja sva mokraća ide u jednu posudu koja se drži na hladnom, a dan prije izbjegavaju se veći fizički napori i velika količina mesa', 'За једнократни узорак довољни су уобичајена хигијена и чиста посуда; код 24-часовног сакупљања сва мокраћа иде у једну посуду која се држи на хладном, а дан прије избјегавају се већи физички напори и велика количина меса', 'Для разовой порции достаточно обычной гигиены и чистого контейнера; при суточном сборе вся моча за день идёт в одну ёмкость, которая хранится в холоде, а накануне избегают интенсивных нагрузок и большого количества мяса', 'Für die Einzelprobe genügen übliche Hygiene und ein sauberer Behälter; beim Sammelurin wird der gesamte Urin des Tages in einem kühl gelagerten Behälter gesammelt, am Vortag starke körperliche Belastung und große Fleischmengen meiden', 'Tek örnek için olağan hijyen ve temiz bir kap yeterlidir; 24 saatlik toplamada günün tüm idrarı serin yerde saklanan tek kaba toplanır, bir gün önce yoğun egzersizden ve fazla etten kaçınılır', 'Deviations may be related to muscle mass, diet, fluid intake or kidney function. The doctor assesses the result together with blood creatinine and the urine volume', 'Odstupanja mogu biti povezana sa mišićnom masom, ishranom, unosom tečnosti ili radom bubrega. Ljekar nalaz procjenjuje zajedno sa kreatininom u krvi i zapreminom mokraće', 'Одступања могу бити повезана са мишићном масом, исхраном, уносом течности или радом бубрега. Љекар налаз процјењује заједно са креатинином у крви и запремином мокраће', 'Отклонения могут быть связаны с мышечной массой, питанием, питьевым режимом или работой почек. Врач оценивает результат вместе с креатинином крови и объёмом мочи', 'Abweichungen können mit der Muskelmasse, der Ernährung, der Trinkmenge oder der Nierenfunktion zusammenhängen. Der Arzt beurteilt den Wert zusammen mit dem Kreatinin im Blut und der Urinmenge', 'Sapmalar kas kütlesi, beslenme, sıvı alımı veya böbrek işleviyle ilişkili olabilir. Hekim sonucu kandaki kreatinin ve idrar hacmiyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'phosphorus-in-urine'), 'Measurement of the amount of phosphate the kidneys excrete with urine', 'Mjerenje količine fosfata koju bubrezi izlučuju mokraćom', 'Мјерење количине фосфата коју бубрези излучују мокраћом', 'Измерение количества фосфатов, которые почки выводят с мочой', 'Messung der Phosphatmenge, die die Nieren mit dem Urin ausscheiden', 'Böbreklerin idrarla attığı fosfat miktarının ölçümü', 'Usually a 24-hour collection is examined, less often a single morning portion, and the collection is done at home', 'Obično se ispituje 24-časovno sakupljanje, rjeđe jednokratni jutarnji uzorak, a sakupljanje se obavlja kod kuće', 'Обично се испитује 24-часовно сакупљање, рјеђе једнократни јутарњи узорак, а сакупљање се обавља код куће', 'Обычно исследуется суточный сбор мочи, реже — разовая утренняя порция; сбор пациент проводит дома', 'Meist wird Sammelurin über 24 Stunden untersucht, seltener eine einzelne Morgenprobe, gesammelt wird zu Hause', 'Genellikle 24 saatlik toplama, daha seyrek olarak tek seferlik sabah örneği incelenir, toplama evde yapılır', 'Kidney stones, disorders of calcium and phosphate balance, parathyroid conditions, kidney diseases with electrolyte loss, follow-up in vitamin D deficiency', 'Kamen u bubregu, poremećaji ravnoteže kalcijuma i fosfora, bolesti paratireoidnih žlijezda, bubrežne bolesti sa gubitkom elektrolita, praćenje kod nedostatka vitamina D', 'Камен у бубрегу, поремећаји равнотеже калцијума и фосфора, болести паратиреоидних жлијезда, бубрежне болести са губитком електролита, праћење код недостатка витамина Д', 'Мочекаменная болезнь, нарушения фосфорно-кальциевого обмена, заболевания паращитовидных желёз, болезни почек с потерей электролитов, наблюдение при дефиците витамина D', 'Nierensteine, Störungen des Kalzium-Phosphat-Haushalts, Erkrankungen der Nebenschilddrüsen, Nierenerkrankungen mit Elektrolytverlust, Kontrolle bei Vitamin-D-Mangel', 'Böbrek taşı, kalsiyum-fosfor dengesi bozuklukları, paratiroid hastalıkları, elektrolit kaybına yol açan böbrek hastalıkları, D vitamini eksikliğinde izlem', 'For the 24-hour collection the first morning portion is not collected, all further urine is gathered until the same hour the next morning and kept cool; vitamin D, phosphate binders and antacids are discussed with the doctor in advance', 'Kod 24-časovnog sakupljanja prva jutarnja porcija se ne sakuplja, sva naredna mokraća skuplja se do istog sata narednog jutra i drži na hladnom; uzimanje vitamina D, preparata za vezivanje fosfata i antacida unaprijed dogovoriti sa ljekarom', 'Код 24-часовног сакупљања прва јутарња порција се не сакупља, сва наредна мокраћа скупља се до истог сата наредног јутра и држи на хладном; узимање витамина Д, препарата за везивање фосфата и антацида унапријед договорити са љекаром', 'При суточном сборе первую утреннюю порцию не собирают, всю последующую мочу собирают до того же часа следующего утра и держат в прохладе; приём витамина D, фосфатсвязывающих средств и антацидов заранее обсуждают с врачом', 'Beim Sammeln über 24 Stunden wird die erste Morgenportion nicht gesammelt, der weitere Urin bis zur gleichen Stunde am nächsten Morgen aufgefangen und kühl gelagert; Vitamin D, Phosphatbinder und Säureblocker vorher mit dem Arzt besprechen', '24 saatlik toplamada ilk sabah idrarı toplanmaz, sonraki tüm idrar ertesi sabah aynı saate kadar biriktirilir ve serin yerde saklanır; D vitamini, fosfat bağlayıcılar ve mide ilaçları önceden hekimle görüşülür', 'Changes may be related to diet, calcium and phosphate metabolism, parathyroid function or the kidney tubules. The result has to be read together with blood phosphate and calcium, which is done by a doctor', 'Promjene mogu biti povezane sa ishranom, metabolizmom kalcijuma i fosfora, radom paratireoidnih žlijezda ili bubrežnih tubula. Nalaz se tumači zajedno sa fosforom i kalcijumom u krvi, a to radi ljekar', 'Промјене могу бити повезане са исхраном, метаболизмом калцијума и фосфора, радом паратиреоидних жлијезда или бубрежних тубула. Налаз се тумачи заједно са фосфором и калцијумом у крви, а то ради љекар', 'Изменения могут быть связаны с питанием, обменом кальция и фосфора, работой паращитовидных желёз или канальцев почек. Результат читают вместе с фосфором и кальцием крови, это делает врач', 'Veränderungen können mit der Ernährung, dem Kalzium-Phosphat-Stoffwechsel, den Nebenschilddrüsen oder den Nierentubuli zusammenhängen. Der Wert muss zusammen mit Phosphat und Kalzium im Blut gelesen werden, das übernimmt der Arzt', 'Değişiklikler beslenme, kalsiyum-fosfor metabolizması, paratiroid bezleri veya böbrek tübülleriyle ilişkili olabilir. Sonuç kandaki fosfor ve kalsiyumla birlikte yorumlanmalıdır, bunu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'uric-acid-in-urine'), 'Measurement of how much uric acid leaves the body with urine over a defined period', 'Mjerenje količine mokraćne kiseline koja se mokraćom izluči u određenom periodu', 'Мјерење количине мокраћне киселине која се мокраћом излучи у одређеном периоду', 'Измерение количества мочевой кислоты, которое выводится с мочой за определённое время', 'Messung, wie viel Harnsäure in einem festgelegten Zeitraum mit dem Urin ausgeschieden wird', 'Belirli bir sürede idrarla atılan ürik asit miktarının ölçümü', 'The standard approach is a 24-hour collection into one container, and if the doctor decides so a single portion is analysed and expressed per creatinine', 'Standardno se radi 24-časovno sakupljanje u jednu posudu, a po odluci ljekara ispituje se jednokratni uzorak sa preračunavanjem na kreatinin', 'Стандардно се ради 24-часовно сакупљање у једну посуду, а по одлуци љекара испитује се једнократни узорак са прерачунавањем на креатинин', 'Стандартно проводится суточный сбор мочи в одну ёмкость, по решению врача исследуется разовая порция с пересчётом на креатинин', 'Üblich ist das Sammeln über 24 Stunden in einem Behälter, nach ärztlicher Entscheidung wird eine Einzelprobe untersucht und auf Kreatinin bezogen', 'Standart yöntem tek kapta 24 saatlik toplamadır, hekim uygun görürse tek seferlik örnek alınıp kreatinine oranlanır', 'Gout, urate stones, recurrent kidney stone disease, assessment of purine metabolism, work-up of elevated uric acid in blood', 'Giht, uratni kamenci, ponavljana bolest kamena u bubregu, procjena metabolizma purina, obrada povišene mokraćne kiseline u krvi', 'Гихт, уратни каменци, понављана болест камена у бубрегу, процјена метаболизма пурина, обрада повишене мокраћне киселине у крви', 'Подагра, уратные камни, повторная мочекаменная болезнь, оценка обмена пуринов, обследование при повышенной мочевой кислоте в крови', 'Gicht, Harnsäuresteine, wiederkehrendes Nierensteinleiden, Beurteilung des Purinstoffwechsels, Abklärung erhöhter Harnsäure im Blut', 'Gut hastalığı, ürat taşları, tekrarlayan böbrek taşı hastalığı, pürin metabolizmasının değerlendirilmesi, kanda yüksek ürik asidin araştırılması', 'For two or three days before the collection keep the usual diet agreed with the doctor, without an excess of meat, offal and alcohol; the collection starts after the first morning portion has been discarded and ends with the first portion of the next morning', 'Dva do tri dana prije sakupljanja zadržati uobičajenu ishranu dogovorenu sa ljekarom, bez viška mesa, iznutrica i alkohola; sakupljanje počinje nakon što se prva jutarnja porcija baci, a završava se prvom porcijom narednog jutra', 'Два до три дана прије сакупљања задржати уобичајену исхрану договорену са љекаром, без вишка меса, изнутрица и алкохола; сакупљање почиње након што се прва јутарња порција баци, а завршава се првом порцијом наредног јутра', 'За два-три дня до сбора сохраняют обычный, согласованный с врачом рацион без избытка мяса, субпродуктов и алкоголя; сбор начинается после того, как первая утренняя порция слита, и заканчивается первой порцией следующего утра', 'Zwei bis drei Tage vor dem Sammeln die gewohnte, mit dem Arzt abgesprochene Ernährung beibehalten, ohne Übermaß an Fleisch, Innereien und Alkohol; das Sammeln beginnt nach dem Verwerfen der ersten Morgenportion und endet mit der ersten Portion am nächsten Morgen', 'Toplamadan iki üç gün önce hekimle kararlaştırılan olağan beslenme sürdürülür, aşırı et, sakatat ve alkolden kaçınılır; toplama ilk sabah idrarı atıldıktan sonra başlar ve ertesi sabahın ilk idrarıyla biter', 'Deviations may be related to diet, purine metabolism, some medications or kidney function. What the value means is decided by a doctor together with blood uric acid', 'Odstupanja mogu biti povezana sa ishranom, metabolizmom purina, nekim lijekovima ili radom bubrega. Značenje nalaza ljekar utvrđuje zajedno sa mokraćnom kiselinom u krvi', 'Одступања могу бити повезана са исхраном, метаболизмом пурина, неким лијековима или радом бубрега. Значење налаза љекар утврђује заједно са мокраћном киселином у крви', 'Отклонения могут быть связаны с питанием, обменом пуринов, приёмом некоторых препаратов или работой почек. Значение результата врач определяет вместе с мочевой кислотой крови', 'Abweichungen können mit der Ernährung, dem Purinstoffwechsel, bestimmten Medikamenten oder der Nierenfunktion zusammenhängen. Die Bedeutung des Werts bestimmt der Arzt zusammen mit der Harnsäure im Blut', 'Sapmalar beslenme, pürin metabolizması, bazı ilaçlar veya böbrek işleviyle ilişkili olabilir. Sonucun anlamını hekim kandaki ürik asitle birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protein-in-urine'), 'Detection and measurement of protein in a single urine sample', 'Otkrivanje i mjerenje proteina u jednokratnom uzorku mokraće', 'Откривање и мјерење протеина у једнократном узорку мокраће', 'Определение наличия и концентрации белка в разовой порции мочи', 'Nachweis und Bestimmung von Eiweiß in einer einzelnen Urinprobe', 'Tek seferlik idrar örneğinde proteinin saptanması ve ölçülmesi', 'One portion of urine is passed into a container and the laboratory checks whether protein is present and in what concentration, which takes a couple of minutes', 'Pacijent daje jednu porciju mokraće u posudu, a laboratorija utvrđuje da li ima proteina i u kojoj koncentraciji, što traje nekoliko minuta', 'Пацијент даје једну порцију мокраће у посуду, а лабораторија утврђује да ли има протеина и у којој концентрацији, што траје неколико минута', 'Пациент сдаёт одну порцию мочи в контейнер, лаборатория проверяет, есть ли белок и в какой концентрации; занимает пару минут', 'Eine Urinportion wird in einen Behälter gegeben, das Labor prüft, ob und wie viel Eiweiß enthalten ist, das dauert wenige Minuten', 'Hastanın kaba verdiği tek idrar örneğinde laboratuvar protein olup olmadığını ve derişimini belirler, işlem birkaç dakika sürer', 'Preventive examination, swelling, foamy or discoloured urine, high blood pressure, monitoring during pregnancy, follow-up of kidney conditions', 'Preventivni pregled, otoci, pjenušava ili promijenjena boja mokraće, povišen krvni pritisak, kontrola u trudnoći, praćenje bubrežnih bolesti', 'Превентивни преглед, отоци, пјенушава или промијењена боја мокраће, повишен крвни притисак, контрола у трудноћи, праћење бубрежних болести', 'Профилактический осмотр, отёки, пенистая или изменившая цвет моча, повышенное давление, контроль при беременности, наблюдение при болезнях почек', 'Vorsorgeuntersuchung, Ödeme, schäumender oder verfärbter Urin, hoher Blutdruck, Kontrolle in der Schwangerschaft, Verlaufskontrolle bei Nierenerkrankungen', 'Koruyucu muayene, ödem, köpüklü veya rengi değişmiş idrar, yüksek tansiyon, gebelikte izlem, böbrek hastalıklarının takibi', 'Morning portion after hygiene of the external genitals, midstream into a sterile container; avoid heavy physical exertion the day before and postpone the test during menstruation', 'Jutarnja porcija poslije higijene spoljašnjih genitalija, srednji mlaz u sterilnu posudu; dan prije izbjegavati veće fizičke napore, a tokom menstruacije analizu odložiti', 'Јутарња порција послије хигијене спољашњих гениталија, средњи млаз у стерилну посуду; дан прије избјегавати веће физичке напоре, а током менструације анализу одложити', 'Утренняя порция после гигиены наружных половых органов, средняя струя в стерильный контейнер; накануне избегать тяжёлых физических нагрузок, во время менструации сдачу лучше отложить', 'Morgenportion nach Reinigung des Intimbereichs, Mittelstrahl in einen sterilen Behälter; am Vortag starke körperliche Belastung meiden, während der Menstruation den Test verschieben', 'Genital bölge temizliğinden sonra sabah idrarı, orta akım steril kaba alınır; bir gün önce ağır fiziksel efordan kaçınılır, adet döneminde test ertelenir', 'Protein in urine may be related to exertion, fever, dehydration or to processes in the kidneys and urinary tract. A single finding calls for a repeat test, and the decision is made by a doctor', 'Prisustvo proteina može biti povezano sa naporom, povišenom tjelesnom temperaturom, dehidratacijom ili sa procesima u bubrezima i mokraćnim putevima. Jedan nalaz traži ponavljanje analize, a odluku donosi ljekar', 'Присуство протеина може бити повезано са напором, повишеном тјелесном температуром, дехидратацијом или са процесима у бубрезима и мокраћним путевима. Један налаз тражи понављање анализе, а одлуку доноси љекар', 'Появление белка может быть связано с нагрузкой, повышенной температурой, обезвоживанием или с процессами в почках и мочевых путях. Однократная находка требует повторного анализа, решение принимает врач', 'Eiweiß im Urin kann mit Belastung, Fieber, Flüssigkeitsmangel oder mit Vorgängen in Nieren und Harnwegen zusammenhängen. Ein einzelner Befund erfordert eine Kontrolle, darüber entscheidet der Arzt', 'İdrarda protein bulunması efor, ateş, sıvı kaybı ya da böbrek ve idrar yollarındaki süreçlerle ilişkili olabilir. Tek bir sonuç tekrar test gerektirir, kararı hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'microalbumin-in-urine'), 'Detection of small amounts of albumin that a routine protein test does not pick up', 'Otkrivanje malih količina albumina koje obična analiza proteina ne registruje', 'Откривање малих количина албумина које обична анализа протеина не региструје', 'Выявление небольших количеств альбумина, которые обычный тест на белок не улавливает', 'Nachweis kleiner Albuminmengen, die ein üblicher Eiweißtest nicht erfasst', 'Standart protein testinin yakalayamadığı küçük miktarlardaki albüminin saptanması', 'Most often the first morning portion is analysed together with creatinine so that the ratio can be calculated, less often a 24-hour collection is used', 'Najčešće se ispituje prva jutarnja porcija uz istovremeno određivanje kreatinina radi izračunavanja odnosa, rjeđe se koristi 24-časovno sakupljanje', 'Најчешће се испитује прва јутарња порција уз истовремено одређивање креатинина ради израчунавања односа, рјеђе се користи 24-часовно сакупљање', 'Чаще исследуется первая утренняя порция с одновременным определением креатинина для расчёта соотношения, реже используется суточный сбор', 'Meist wird die erste Morgenportion zusammen mit Kreatinin untersucht, um das Verhältnis zu berechnen, seltener kommt Sammelurin über 24 Stunden zum Einsatz', 'Çoğunlukla ilk sabah idrarı, oran hesaplanabilsin diye kreatininle birlikte incelenir, daha seyrek olarak 24 saatlik toplama kullanılır', 'Regular monitoring in diabetes mellitus and arterial hypertension, follow-up in chronic kidney disease, cardiovascular risk assessment', 'Redovna kontrola kod šećerne bolesti i povišenog krvnog pritiska, praćenje hronične bubrežne bolesti, procjena kardiovaskularnog rizika', 'Редовна контрола код шећерне болести и повишеног крвног притиска, праћење хроничне бубрежне болести, процјена кардиоваскуларног ризика', 'Регулярный контроль при сахарном диабете и артериальной гипертензии, наблюдение при хронической болезни почек, оценка сердечно-сосудистого риска', 'Regelmäßige Kontrolle bei Diabetes mellitus und Bluthochdruck, Verlaufskontrolle bei chronischer Nierenerkrankung, Einschätzung des Herz-Kreislauf-Risikos', 'Diyabet ve yüksek tansiyonda düzenli kontrol, kronik böbrek hastalığında izlem, kalp-damar riskinin değerlendirilmesi', 'First morning portion after hygiene; avoid intense exercise for a day before, and do not take the test during fever, a urinary tract infection or menstruation', 'Prva jutarnja porcija poslije higijene; dan prije izbjegavati intenzivne napore, a analizu ne raditi kod povišene tjelesne temperature, infekcije mokraćnih puteva i tokom menstruacije', 'Прва јутарња порција послије хигијене; дан прије избјегавати интензивне напоре, а анализу не радити код повишене тјелесне температуре, инфекције мокраћних путева и током менструације', 'Первая утренняя порция после гигиены; за сутки избегать интенсивных нагрузок, анализ не сдают при повышенной температуре, инфекции мочевых путей и во время менструации', 'Erste Morgenportion nach der Hygiene; am Tag davor starke Anstrengung meiden, bei Fieber, Harnwegsinfekt und während der Menstruation nicht durchführen', 'Hijyen sonrası ilk sabah idrarı; bir gün önce yoğun egzersizden kaçınılır, ateş, idrar yolu enfeksiyonu ve adet döneminde test yapılmaz', 'Increased albumin excretion may be related to the state of the kidney filters, high blood pressure, high blood sugar or temporary causes. Conclusions require a repeat test and assessment by a doctor', 'Povećano izlučivanje albumina može biti povezano sa stanjem bubrežnih filtera, visokim pritiskom, povišenim šećerom u krvi ili privremenim uzrocima. Za zaključak su potrebni ponovljena analiza i procjena ljekara', 'Повећано излучивање албумина може бити повезано са стањем бубрежних филтера, високим притиском, повишеним шећером у крви или привременим узроцима. За закључак су потребни поновљена анализа и процјена љекара', 'Повышенное выделение альбумина может быть связано с состоянием почечных фильтров, высоким давлением, повышенным сахаром крови или временными причинами. Для выводов нужен повторный анализ и оценка врача', 'Eine erhöhte Albuminausscheidung kann mit dem Zustand der Nierenfilter, hohem Blutdruck, hohem Blutzucker oder vorübergehenden Ursachen zusammenhängen. Für Schlussfolgerungen sind eine Kontrolle und die Beurteilung durch den Arzt nötig', 'Albümin atılımının artması böbrek süzgeçlerinin durumu, yüksek tansiyon, yüksek kan şekeri ya da geçici nedenlerle ilişkili olabilir. Sonuç çıkarmak için testin tekrarı ve hekim değerlendirmesi gerekir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'spermogram'), 'Laboratory analysis of semen: volume, number, motility and shape of sperm cells', 'Laboratorijska analiza ejakulata: zapremina, broj, pokretljivost i oblik spermatozoida', 'Лабораторијска анализа ејакулата: запремина, број, покретљивост и облик сперматозоида', 'Лабораторное исследование эякулята: объём, количество, подвижность и строение сперматозоидов', 'Laboruntersuchung des Ejakulats: Menge, Anzahl, Beweglichkeit und Form der Samenzellen', 'Meninin laboratuvar incelemesi: hacim, sperm sayısı, hareketlilik ve şekil', 'The sample is produced by masturbation into a sterile container in a separate room at the clinic and is examined within about an hour', 'Uzorak se dobija masturbacijom u sterilnu posudu u posebnoj prostoriji klinike i obrađuje se u roku od otprilike jednog sata', 'Узорак се добија мастурбацијом у стерилну посуду у посебној просторији клинике и обрађује се у року од отприлике једног сата', 'Образец получают путём мастурбации в отдельной комнате клиники в стерильный контейнер, исследование начинают примерно в течение часа', 'Die Probe wird durch Masturbation in einem separaten Raum der Klinik in einen sterilen Becher gewonnen und innerhalb etwa einer Stunde untersucht', 'Örnek klinikte ayrı bir odada mastürbasyonla steril kaba alınır ve yaklaşık bir saat içinde incelenir', 'Work-up of a couple with difficulty conceiving, assessment of male fertility, follow-up after surgery or treatment such as varicocele or inflammation, check after vasectomy, preparation for assisted reproduction', 'Obrada para sa teškoćama u začeću, procjena muške plodnosti, kontrola poslije operacija i liječenja (varikokela, upale), provjera poslije vazektomije, priprema za postupke vantjelesne oplodnje', 'Обрада пара са тешкоћама у зачећу, процјена мушке плодности, контрола послије операција и лијечења (варикокела, упале), провјера послије вазектомије, припрема за поступке вантјелесне оплодње', 'Обследование пары при трудностях с зачатием, оценка мужской фертильности, контроль после операций и лечения (варикоцеле, воспаления), проверка после вазэктомии, подготовка к программам вспомогательной репродукции', 'Abklärung eines Paares mit unerfülltem Kinderwunsch, Beurteilung der männlichen Fruchtbarkeit, Kontrolle nach Operationen und Behandlungen wie Varikozele oder Entzündungen, Kontrolle nach Vasektomie, Vorbereitung auf eine künstliche Befruchtung', 'Gebe kalmakta güçlük çeken çiftlerin araştırılması, erkek doğurganlığının değerlendirilmesi, varikosel veya iltihap tedavisi ve ameliyat sonrası kontrol, vazektomi sonrası kontrol, yardımcı üreme tedavilerine hazırlık', 'Sexual abstinence of two to five days (the clinic states the exact period), avoid alcohol and overheating such as sauna or hot baths for several days, do not attend during an acute illness with fever or shortly after a course of antibiotics', 'Polna apstinencija od dva do pet dana (tačan period određuje klinika), nekoliko dana izbjegavati alkohol i pregrijavanje (sauna, vruća kupka), ne dolaziti tokom akutne bolesti sa povišenom temperaturom ni ubrzo poslije terapije antibioticima', 'Полна апстиненција од два до пет дана (тачан период одређује клиника), неколико дана избјегавати алкохол и прегријавање (сауна, врућа купка), не долазити током акутне болести са повишеном температуром ни убрзо послије терапије антибиотицима', 'Половое воздержание от двух до пяти дней (точный срок называет клиника), несколько дней избегать алкоголя и перегрева (сауна, горячая ванна), не сдавать во время острого заболевания с температурой и вскоре после курса антибиотиков', 'Sexuelle Karenz von zwei bis fünf Tagen (den genauen Zeitraum nennt die Klinik), einige Tage vorher Alkohol und Überhitzung wie Sauna oder heiße Bäder meiden, nicht während einer akuten fieberhaften Erkrankung oder kurz nach einer Antibiotikatherapie', 'İki ila beş gün cinsel perhiz (kesin süreyi klinik belirtir), birkaç gün alkolden ve sauna, sıcak banyo gibi aşırı ısınmadan kaçınma, ateşli akut hastalık sırasında ve antibiyotik kürünün hemen ardından test yapılmaz', 'Deviations may be related to temporary factors such as illness, stress, overheating or recent fever, or to the state of the reproductive system. Conclusions are not drawn from one sample, a repeat test and a consultation with a urologist or andrologist are arranged', 'Odstupanja mogu biti povezana sa privremenim faktorima (bolest, stres, pregrijavanje, nedavno povišena temperatura) ili sa stanjem reproduktivnog sistema. Zaključak se ne donosi na osnovu jednog nalaza, već se radi ponovna analiza i pregled urologa ili androloga', 'Одступања могу бити повезана са привременим факторима (болест, стрес, прегријавање, недавно повишена температура) или са стањем репродуктивног система. Закључак се не доноси на основу једног налаза, већ се ради поновна анализа и преглед уролога или андролога', 'Отклонения могут быть связаны с временными факторами (болезнь, стресс, перегрев, недавняя лихорадка) или с состоянием репродуктивной системы. По одному анализу выводы не делают, назначают повтор и консультацию уролога или андролога', 'Abweichungen können mit vorübergehenden Faktoren wie Krankheit, Stress, Überhitzung oder kürzlichem Fieber oder mit dem Zustand des Fortpflanzungssystems zusammenhängen. Aus einer einzelnen Untersuchung werden keine Schlüsse gezogen, es folgen eine Wiederholung und ein Gespräch beim Urologen oder Andrologen', 'Sapmalar hastalık, stres, aşırı ısınma, yakın zamanda geçirilmiş ateş gibi geçici etkenlerle ya da üreme sisteminin durumuyla ilişkili olabilir. Tek bir sonuçla yorum yapılmaz, test tekrarlanır ve üroloji veya androloji görüşü alınır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'amylase-in-urine'), 'Measurement of the activity of an enzyme of the pancreas and salivary glands that is excreted with urine', 'Mjerenje aktivnosti enzima gušterače i pljuvačnih žlijezda koji se izlučuje mokraćom', 'Мјерење активности ензима гуштераче и пљувачних жлијезда који се излучује мокраћом', 'Измерение активности фермента поджелудочной железы и слюнных желёз, который выводится с мочой', 'Bestimmung der Aktivität eines Enzyms der Bauchspeicheldrüse und der Speicheldrüsen, das mit dem Urin ausgeschieden wird', 'Pankreas ve tükürük bezlerine ait olup idrarla atılan bir enzimin etkinliğinin ölçümü', 'A single urine portion is analysed, and sometimes a timed collection over several hours or a full day is used to assess how much enzyme is excreted', 'Ispituje se jednokratni uzorak mokraće, a ponekad se radi sakupljanje kroz nekoliko sati ili tokom dana radi procjene izlučivanja enzima', 'Испитује се једнократни узорак мокраће, а понекад се ради сакупљање кроз неколико сати или током дана ради процјене излучивања ензима', 'Исследуется разовая порция мочи, иногда делают сбор за несколько часов или за сутки, чтобы оценить выведение фермента', 'Untersucht wird eine einzelne Urinportion, manchmal wird über mehrere Stunden oder einen Tag gesammelt, um die ausgeschiedene Enzymmenge zu beurteilen', 'Tek seferlik idrar örneği incelenir, bazen enzim atılımını değerlendirmek için birkaç saatlik ya da günlük toplama yapılır', 'Pain in the upper abdomen, suspected inflammation of the pancreas, follow-up over time, work-up of salivary gland conditions', 'Bol u gornjem dijelu trbuha, sumnja na upalu gušterače, praćenje toka, obrada oboljenja pljuvačnih žlijezda', 'Бол у горњем дијелу трбуха, сумња на упалу гуштераче, праћење тока, обрада обољења пљувачних жлијезда', 'Боль в верхней части живота, подозрение на воспаление поджелудочной железы, наблюдение в динамике, обследование при болезнях слюнных желёз', 'Schmerzen im Oberbauch, Verdacht auf eine Entzündung der Bauchspeicheldrüse, Verlaufskontrolle, Abklärung von Speicheldrüsenerkrankungen', 'Üst karın ağrısı, pankreas iltihabı şüphesi, seyrin izlenmesi, tükürük bezi hastalıklarının araştırılması', 'No special preparation is needed; the urine is collected in a clean container, and medications or alcohol taken the day before should be mentioned to the doctor', 'Posebna priprema nije potrebna; mokraća se skuplja u čistu posudu, a o lijekovima i alkoholu uzetim dan prije treba obavijestiti ljekara', 'Посебна припрема није потребна; мокраћа се скупља у чисту посуду, а о лијековима и алкохолу узетим дан прије треба обавијестити љекара', 'Специальная подготовка не нужна; моча собирается в чистый контейнер, о принимаемых препаратах и алкоголе накануне стоит сообщить врачу', 'Eine besondere Vorbereitung ist nicht nötig; der Urin wird in einem sauberen Behälter aufgefangen, Medikamente und Alkohol vom Vortag sollten dem Arzt mitgeteilt werden', 'Özel bir hazırlık gerekmez; idrar temiz bir kaba alınır, bir gün önce kullanılan ilaçlar ve alkol hekime bildirilmelidir', 'A change in activity may be related to the pancreas, the salivary glands, kidney function or certain medications. The result is read together with blood amylase and the clinical picture, which is done by a doctor', 'Promjena aktivnosti može biti povezana sa stanjem gušterače, pljuvačnih žlijezda, radom bubrega ili sa uzimanjem nekih lijekova. Nalaz se tumači zajedno sa amilazom u krvi i kliničkom slikom, a to radi ljekar', 'Промјена активности може бити повезана са стањем гуштераче, пљувачних жлијезда, радом бубрега или са узимањем неких лијекова. Налаз се тумачи заједно са амилазом у крви и клиничком сликом, а то ради љекар', 'Изменение активности может быть связано с состоянием поджелудочной железы, слюнных желёз, работой почек или с приёмом некоторых препаратов. Результат читают вместе с амилазой крови и клинической картиной, это делает врач', 'Eine veränderte Aktivität kann mit der Bauchspeicheldrüse, den Speicheldrüsen, der Nierenfunktion oder bestimmten Medikamenten zusammenhängen. Der Wert wird zusammen mit der Amylase im Blut und dem Beschwerdebild vom Arzt beurteilt', 'Etkinlikteki değişiklik pankreas, tükürük bezleri, böbrek işlevi veya bazı ilaçlarla ilişkili olabilir. Sonuç kandaki amilaz ve klinik tabloyla birlikte hekim tarafından yorumlanır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protein-in-24h-urine'), 'Measurement of the total amount of protein lost with urine over a full day', 'Mjerenje ukupne količine proteina koja se mokraćom izgubi tokom cijelog dana', 'Мјерење укупне количине протеина која се мокраћом изгуби током цијелог дана', 'Измерение общего количества белка, которое теряется с мочой за целые сутки', 'Bestimmung der gesamten Eiweißmenge, die im Verlauf eines Tages mit dem Urin verloren geht', 'Bir gün boyunca idrarla kaybedilen toplam protein miktarının ölçümü', 'Urine is collected into one graduated container for 24 hours, and the measured total volume plus a sample from the mixed collection go to the laboratory', 'Mokraća se 24 sata skuplja u jednu graduisanu posudu, a u laboratoriju se nose izmjerena ukupna zapremina i uzorak iz promiješanog sakupljenog materijala', 'Мокраћа се 24 сата скупља у једну градуисану посуду, а у лабораторију се носе измјерена укупна запремина и узорак из промијешаног сакупљеног материјала', 'Мочу собирают в одну градуированную ёмкость в течение 24 часов, в лабораторию сдают измеренный общий объём и порцию из перемешанного сбора', 'Der Urin wird 24 Stunden in einem Messbehälter gesammelt, ins Labor kommen das gemessene Gesamtvolumen und eine Probe aus dem durchmischten Sammelurin', 'İdrar 24 saat boyunca dereceli tek bir kapta toplanır, laboratuvara ölçülen toplam hacim ve karıştırılmış toplamadan alınan örnek götürülür', 'Clarifying protein found in a single portion, follow-up of kidney disease, monitoring of high blood pressure in pregnancy, tracking change during treatment', 'Provjera proteina nađenih u jednokratnom uzorku, praćenje bubrežnih bolesti, kontrola povišenog pritiska u trudnoći, praćenje promjene tokom liječenja', 'Провјера протеина нађених у једнократном узорку, праћење бубрежних болести, контрола повишеног притиска у трудноћи, праћење промјене током лијечења', 'Уточнение белка, найденного в разовой порции, наблюдение при болезнях почек, контроль повышенного давления при беременности, отслеживание динамики на фоне лечения', 'Abklärung von Eiweiß aus einer Einzelprobe, Verlaufskontrolle bei Nierenerkrankungen, Überwachung bei Bluthochdruck in der Schwangerschaft, Beurteilung des Verlaufs unter Therapie', 'Tek örnekte bulunan proteinin doğrulanması, böbrek hastalıklarının takibi, gebelikte yüksek tansiyonun izlenmesi, tedavi sırasında değişimin izlenmesi', 'The collection starts after the first morning portion has been discarded and ends with the first portion of the following morning, which is included; the container is kept in a cool place, drinking stays as usual and hard exercise on the collection day is better avoided', 'Sakupljanje počinje nakon što se prva jutarnja porcija baci, a završava prvom porcijom narednog jutra koja se uključuje; posuda se drži na hladnom, unos tečnosti je uobičajen, a veće fizičke napore na dan sakupljanja bolje je izbjegavati', 'Сакупљање почиње након што се прва јутарња порција баци, а завршава првом порцијом наредног јутра која се укључује; посуда се држи на хладном, унос течности је уобичајен, а веће физичке напоре на дан сакупљања боље је избјегавати', 'Сбор начинают после того, как первая утренняя порция слита, и заканчивают первой порцией следующего утра, которую включают в сбор; ёмкость держат в прохладном месте, питьевой режим обычный, тяжёлых нагрузок в день сбора лучше избегать', 'Das Sammeln beginnt nach dem Verwerfen der ersten Morgenportion und endet mit der ersten Portion am nächsten Morgen, die mitgesammelt wird; der Behälter wird kühl gelagert, die Trinkmenge bleibt gewohnt, starke Belastung am Sammeltag besser vermeiden', 'Toplama ilk sabah idrarı atıldıktan sonra başlar ve ertesi sabahın ilk idrarı da eklenerek biter; kap serin yerde tutulur, sıvı alımı olağan sürer, toplama gününde ağır egzersizden kaçınmak daha iyidir', 'An increased daily protein loss may be related to the state of the kidney filters, high blood pressure or systemic conditions. The amount and its cause are assessed by a doctor together with blood tests', 'Povećan dnevni gubitak proteina može biti povezan sa stanjem bubrežnih filtera, visokim pritiskom ili sistemskim bolestima. Količinu i uzrok ljekar procjenjuje zajedno sa analizama krvi', 'Повећан дневни губитак протеина може бити повезан са стањем бубрежних филтера, високим притиском или системским болестима. Количину и узрок љекар процјењује заједно са анализама крви', 'Повышенная суточная потеря белка может быть связана с состоянием почечных фильтров, высоким давлением или системными заболеваниями. Величину и причину врач оценивает вместе с анализами крови', 'Ein erhöhter täglicher Eiweißverlust kann mit dem Zustand der Nierenfilter, hohem Blutdruck oder systemischen Erkrankungen zusammenhängen. Menge und Ursache beurteilt der Arzt zusammen mit Blutwerten', 'Günlük protein kaybının artması böbrek süzgeçlerinin durumu, yüksek tansiyon veya sistemik hastalıklarla ilişkili olabilir. Miktarı ve nedenini hekim kan testleriyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'bilirubin-in-urine'), 'Detection of a bile pigment that is practically absent from the urine of a healthy person', 'Otkrivanje žučnog pigmenta kojeg u mokraći zdrave osobe praktično nema', 'Откривање жучног пигмента којег у мокраћи здраве особе практично нема', 'Обнаружение жёлчного пигмента, которого в моче здорового человека практически нет', 'Nachweis eines Gallenfarbstoffs, der im Urin eines gesunden Menschen praktisch nicht vorkommt', 'Sağlıklı kişinin idrarında neredeyse bulunmayan bir safra pigmentinin saptanması', 'A fresh single portion is tested with a reagent strip as part of the routine urinalysis and confirmed by a separate method if needed', 'Svjež jednokratni uzorak ispituje se test-trakom u okviru opšte analize mokraće, a po potrebi se potvrđuje posebnom metodom', 'Свјеж једнократни узорак испитује се тест-траком у оквиру опште анализе мокраће, а по потреби се потврђује посебном методом', 'Свежую разовую порцию проверяют тест-полоской в составе общего анализа мочи, при необходимости подтверждают отдельным методом', 'Eine frische Einzelprobe wird im Rahmen der Urinuntersuchung mit einem Teststreifen geprüft und bei Bedarf mit einem gesonderten Verfahren bestätigt', 'Taze tek örnek, tam idrar tetkiki kapsamında test çubuğuyla incelenir, gerekirse ayrı bir yöntemle doğrulanır', 'Yellowing of the skin and eyes, dark urine, work-up of liver and bile duct conditions, monitoring during treatment that puts a load on the liver', 'Žuta prebojenost kože i očiju, tamna mokraća, obrada bolesti jetre i žučnih puteva, kontrola tokom terapije koja opterećuje jetru', 'Жута пребојеност коже и очију, тамна мокраћа, обрада болести јетре и жучних путева, контрола током терапије која оптерећује јетру', 'Желтушность кожи и глаз, тёмная моча, обследование при болезнях печени и жёлчных путей, контроль при лечении, дающем нагрузку на печень', 'Gelbfärbung von Haut und Augen, dunkler Urin, Abklärung von Leber- und Gallenwegserkrankungen, Kontrolle bei leberbelastender Therapie', 'Ciltte ve gözlerde sararma, koyu renkli idrar, karaciğer ve safra yolu hastalıklarının araştırılması, karaciğeri zorlayan tedavilerde izlem', 'A fresh portion after hygiene, the container is closed and delivered quickly, and the sample is kept away from light because bilirubin breaks down during storage in the light', 'Svjež uzorak poslije higijene, posuda se zatvara i brzo nosi u laboratoriju, a uzorak se čuva od svjetlosti jer se bilirubin razgrađuje stajanjem na svjetlu', 'Свјеж узорак послије хигијене, посуда се затвара и брзо носи у лабораторију, а узорак се чува од свјетлости јер се билирубин разграђује стајањем на свјетлу', 'Свежая порция после гигиены, контейнер закрывают и быстро доставляют в лабораторию, образец берегут от света — билирубин разрушается при хранении на свету', 'Frische Probe nach der Hygiene, der Behälter wird verschlossen und zügig abgegeben, die Probe vor Licht schützen, da Bilirubin bei Lichteinwirkung zerfällt', 'Hijyen sonrası taze örnek, kap kapatılır ve hızla laboratuvara ulaştırılır, örnek ışıktan korunur çünkü bilirubin ışıkta bekleyince bozulur', 'The appearance of bilirubin may be related to liver function or to the flow of bile. It is a reason for further examination, and the doctor decides what that should be', 'Pojava bilirubina može biti povezana sa radom jetre ili sa otjecanjem žuči. To je razlog za dalju obradu, a njen smjer određuje ljekar', 'Појава билирубина може бити повезана са радом јетре или са отјецањем жучи. То је разлог за даљу обраду, а њен смјер одређује љекар', 'Появление билирубина может быть связано с работой печени или с оттоком жёлчи. Это повод для дальнейшего обследования, его направление определяет врач', 'Auftretendes Bilirubin kann mit der Leberfunktion oder dem Gallenabfluss zusammenhängen. Das ist ein Anlass für weitere Abklärung, deren Richtung der Arzt festlegt', 'İdrarda bilirubin görülmesi karaciğerin işleyişi veya safra akışıyla ilişkili olabilir. Bu, ileri incelemeyi gerektirir, yönünü hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urea-in-urine'), 'Measurement of urea, the end product of protein metabolism that the kidneys remove', 'Mjerenje uree, krajnjeg produkta metabolizma bjelančevina koji izlučuju bubrezi', 'Мјерење урее, крајњег продукта метаболизма бјеланчевина који излучују бубрези', 'Измерение мочевины — конечного продукта белкового обмена, который выводят почки', 'Bestimmung von Harnstoff, dem Endprodukt des Eiweißstoffwechsels, das über die Nieren ausgeschieden wird', 'Protein metabolizmasının son ürünü olan ve böbreklerle atılan ürenin ölçümü', 'Usually a 24-hour collection is analysed, which shows the total nitrogen output, less often a single portion is used', 'Obično se analizira 24-časovno sakupljanje, koje pokazuje ukupno izlučivanje azota, rjeđe se koristi jednokratni uzorak', 'Обично се анализира 24-часовно сакупљање, које показује укупно излучивање азота, рјеђе се користи једнократни узорак', 'Обычно анализируют суточный сбор, показывающий общее выведение азота, реже используют разовую порцию', 'Meist wird Sammelurin über 24 Stunden untersucht, der die gesamte Stickstoffausscheidung zeigt, seltener genügt eine Einzelprobe', 'Genellikle toplam azot atılımını gösteren 24 saatlik toplama incelenir, daha seyrek olarak tek seferlik örnek kullanılır', 'Assessment of the excretory function of the kidneys, monitoring of protein metabolism, follow-up in kidney and liver disease, nitrogen balance calculation during therapeutic nutrition', 'Procjena izlučne funkcije bubrega, praćenje metabolizma bjelančevina, kontrola kod bolesti bubrega i jetre, izračunavanje azotnog bilansa kod posebne ishrane', 'Процјена излучне функције бубрега, праћење метаболизма бјеланчевина, контрола код болести бубрега и јетре, израчунавање азотног биланса код посебне исхране', 'Оценка выделительной функции почек, контроль белкового обмена, наблюдение при болезнях почек и печени, расчёт азотистого баланса при лечебном питании', 'Beurteilung der Ausscheidungsfunktion der Nieren, Kontrolle des Eiweißstoffwechsels, Verlauf bei Nieren- und Lebererkrankungen, Berechnung der Stickstoffbilanz bei besonderer Ernährungstherapie', 'Böbreklerin atım işlevinin değerlendirilmesi, protein metabolizmasının izlenmesi, böbrek ve karaciğer hastalıklarında takip, özel beslenme tedavisinde azot dengesi hesabı', 'For the 24-hour collection the first morning portion is not included, all further urine is gathered until the next morning; eating stays as usual during the collection days, there is no need to change the amount of protein, and the container is kept cool', 'Kod 24-časovnog sakupljanja prva jutarnja porcija se ne uključuje, sva naredna mokraća skuplja se do narednog jutra; ishrana tokom dana sakupljanja ostaje uobičajena, količinu bjelančevina nije potrebno mijenjati, a posuda se drži na hladnom', 'Код 24-часовног сакупљања прва јутарња порција се не укључује, сва наредна мокраћа скупља се до наредног јутра; исхрана током дана сакупљања остаје уобичајена, количину бјеланчевина није потребно мијењати, а посуда се држи на хладном', 'При суточном сборе первую утреннюю порцию не включают, всю последующую мочу собирают до следующего утра; питание в дни сбора остаётся обычным, количество белка менять не нужно, ёмкость держат в прохладе', 'Beim Sammeln über 24 Stunden wird die erste Morgenportion nicht mitgesammelt, der weitere Urin bis zum nächsten Morgen aufgefangen; die Ernährung bleibt an den Sammeltagen gewohnt, die Eiweißmenge muss nicht geändert werden, der Behälter wird kühl gelagert', '24 saatlik toplamada ilk sabah idrarı dahil edilmez, sonraki tüm idrar ertesi sabaha kadar biriktirilir; toplama günlerinde beslenme olağan sürer, protein miktarını değiştirmek gerekmez, kap serin yerde saklanır', 'Deviations may be related to the amount of protein in the diet, fluid intake, kidney or liver function. The value is interpreted together with blood urea, which is done by a doctor', 'Odstupanja mogu biti povezana sa količinom bjelančevina u ishrani, unosom tečnosti, radom bubrega ili jetre. Nalaz se tumači zajedno sa ureom u krvi, a to radi ljekar', 'Одступања могу бити повезана са количином бјеланчевина у исхрани, уносом течности, радом бубрега или јетре. Налаз се тумачи заједно са уреом у крви, а то ради љекар', 'Отклонения могут быть связаны с количеством белка в питании, объёмом выпитой жидкости, работой почек или печени. Результат интерпретируют вместе с мочевиной крови, это делает врач', 'Abweichungen können mit der Eiweißmenge in der Nahrung, der Trinkmenge, der Nieren- oder Leberfunktion zusammenhängen. Der Wert wird zusammen mit dem Harnstoff im Blut vom Arzt beurteilt', 'Sapmalar beslenmedeki protein miktarı, sıvı alımı, böbrek veya karaciğer işleviyle ilişkili olabilir. Sonuç kandaki üreyle birlikte hekim tarafından yorumlanır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urobilinogen-in-urine'), 'Measurement of a substance formed from bilirubin in the intestine, part of which returns to the blood and is excreted by the kidneys', 'Određivanje materije koja nastaje od bilirubina u crijevima, a dijelom se vraća u krv i izlučuje preko bubrega', 'Одређивање материје која настаје од билирубина у цријевима, а дијелом се враћа у крв и излучује преко бубрега', 'Определение вещества, которое образуется из билирубина в кишечнике, частично возвращается в кровь и выводится почками', 'Bestimmung eines Stoffes, der im Darm aus Bilirubin entsteht, teilweise ins Blut zurückkehrt und über die Nieren ausgeschieden wird', 'Bağırsakta bilirubinden oluşan, bir kısmı kana geri dönüp böbreklerle atılan maddenin ölçümü', 'A fresh single portion is checked with a reagent strip, usually together with the other parameters of a routine urinalysis', 'Svjež jednokratni uzorak provjerava se test-trakom, obično uz ostale parametre opšte analize mokraće', 'Свјеж једнократни узорак провјерава се тест-траком, обично уз остале параметре опште анализе мокраће', 'Свежую разовую порцию проверяют тест-полоской, обычно вместе с остальными показателями общего анализа мочи', 'Eine frische Einzelprobe wird mit einem Teststreifen geprüft, meist gemeinsam mit den übrigen Werten der Urinuntersuchung', 'Taze tek örnek, genellikle tam idrar tetkikinin diğer değerleriyle birlikte test çubuğuyla incelenir', 'Work-up of liver disease, conditions with increased breakdown of red blood cells, complaints of yellow skin, changes in the colour of urine or stool', 'Obrada bolesti jetre, stanja sa pojačanom razgradnjom crvenih krvnih zrnaca, tegobe sa žutom prebojenošću kože, promjena boje mokraće ili stolice', 'Обрада болести јетре, стања са појачаном разградњом црвених крвних зрнаца, тегобе са жутом пребојеношћу коже, промјена боје мокраће или столице', 'Обследование при болезнях печени, состояния с усиленным распадом эритроцитов, жалобы на желтушность кожи, изменение цвета мочи или кала', 'Abklärung von Lebererkrankungen, Zustände mit vermehrtem Abbau roter Blutkörperchen, Beschwerden mit gelblicher Haut, Veränderungen der Farbe von Urin oder Stuhl', 'Karaciğer hastalıklarının araştırılması, alyuvarların hızlı yıkıldığı durumlar, ciltte sararma şikayeti, idrar veya dışkı renginde değişiklik', 'A fresh portion, preferably the morning one, after hygiene; it should be examined quickly and kept in the dark, since urobilinogen breaks down in the light', 'Svjež uzorak, najbolje jutarnji, poslije higijene; treba ga brzo obraditi i čuvati u mraku jer se urobilinogen razgrađuje na svjetlu', 'Свјеж узорак, најбоље јутарњи, послије хигијене; треба га брзо обрадити и чувати у мраку јер се уробилиноген разграђује на свјетлу', 'Свежая порция, лучше утренняя, после гигиены; исследовать нужно быстро и хранить образец в темноте, так как уробилиноген разрушается на свету', 'Frische Probe, am besten der Morgenurin, nach der Hygiene; sie sollte rasch untersucht und dunkel aufbewahrt werden, da Urobilinogen im Licht zerfällt', 'Hijyen sonrası taze, tercihen sabah örneği; ürobilinojen ışıkta bozulduğu için örnek hızla incelenmeli ve karanlıkta saklanmalıdır', 'Deviations may be related to liver function, the bile ducts, faster breakdown of red blood cells or certain medications. The result is assessed together with bilirubin in blood and urine, which is done by a doctor', 'Odstupanja mogu biti povezana sa radom jetre, žučnim putevima, bržom razgradnjom crvenih krvnih zrnaca ili sa nekim lijekovima. Nalaz se procjenjuje zajedno sa bilirubinom u krvi i mokraći, a to radi ljekar', 'Одступања могу бити повезана са радом јетре, жучним путевима, бржом разградњом црвених крвних зрнаца или са неким лијековима. Налаз се процјењује заједно са билирубином у крви и мокраћи, а то ради љекар', 'Отклонения могут быть связаны с работой печени, состоянием жёлчных путей, ускоренным распадом эритроцитов или с приёмом некоторых препаратов. Результат оценивают вместе с билирубином крови и мочи, это делает врач', 'Abweichungen können mit der Leberfunktion, den Gallenwegen, einem schnelleren Abbau roter Blutkörperchen oder bestimmten Medikamenten zusammenhängen. Der Wert wird zusammen mit Bilirubin in Blut und Urin vom Arzt beurteilt', 'Sapmalar karaciğer işlevi, safra yolları, alyuvarların daha hızlı yıkımı veya bazı ilaçlarla ilişkili olabilir. Sonuç kandaki ve idrardaki bilirubinle birlikte hekim tarafından değerlendirilir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ca-125'), 'Blood test for the glycoprotein CA 125, used as a tumour marker when monitoring the condition of the ovaries and pelvic organs', 'Analiza krvi na glikoprotein CA 125, koji se koristi kao tumorski marker pri praćenju stanja jajnika i organa male karlice', 'Анализа крви на гликопротеин CA 125, који се користи као туморски маркер при праћењу стања јајника и органа мале карлице', 'Анализ крови на гликопротеин CA 125, который используют как онкомаркер при наблюдении за состоянием яичников и органов малого таза', 'Bluttest auf das Glykoprotein CA 125, das als Tumormarker bei der Verlaufsbeobachtung der Eierstöcke und der Beckenorgane verwendet wird', 'Yumurtalıkların ve pelvis organlarının durumunun izlenmesinde tümör belirteci olarak kullanılan CA 125 glikoproteini için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Toplardamardan kan alınması, birkaç dakika sürer', 'Ordered by a doctor when a pelvic mass is being examined, follow-up monitoring of patients already receiving treatment, control after completed treatment', 'Po uputu ljekara pri pregledu promjena u maloj karlici, praćenje pacijenata koji već primaju terapiju, kontrola poslije završenog liječenja', 'По упуту љекара при прегледу промјена у малој карлици, праћење пацијената који већ примају терапију, контрола послије завршеног лијечења', 'По назначению врача при обследовании образований в малом тазу, динамическое наблюдение пациентов, уже получающих лечение, контроль после завершённого лечения', 'Auf ärztliche Anordnung bei der Abklärung von Raumforderungen im Becken, Verlaufskontrolle bei Patientinnen, die bereits behandelt werden, Kontrolle nach abgeschlossener Behandlung', 'Pelviste saptanan oluşumların değerlendirilmesinde hekim isteğiyle, tedavi almakta olan hastaların izleminde, tamamlanan tedaviden sonraki kontrollerde', 'No special preparation is usually required; the doctor may ask for the sample to be taken outside the days of menstruation', 'Posebna priprema obično nije potrebna; ljekar može tražiti da se krv uzme van dana menstruacije', 'Посебна припрема обично није потребна; љекар може тражити да се крв узме ван дана менструације', 'Специальной подготовки обычно не требуется; врач может попросить сдать кровь вне дней менструации', 'In der Regel ist keine besondere Vorbereitung nötig; der Arzt kann darum bitten, die Blutentnahme außerhalb der Menstruationstage durchzuführen', 'Genellikle özel bir hazırlık gerekmez; hekim, kanın adet günleri dışında alınmasını isteyebilir', 'An increase also occurs with benign conditions — endometriosis, fibroids, inflammation of the pelvic organs, liver disease, during menstruation and pregnancy — and on its own it does not mean an oncological disease. Only a doctor determines what the result means, comparing it with the examination and ultrasound', 'Povećanje se javlja i kod benignih stanja — endometrioze, mioma, upale organa male karlice, bolesti jetre, tokom menstruacije i trudnoće — i samo po sebi ne znači onkološko oboljenje. Značenje nalaza određuje isključivo ljekar, upoređujući ga sa pregledom i ultrazvukom', 'Повећање се јавља и код бенигних стања — ендометриозе, миома, упале органа мале карлице, болести јетре, током менструације и трудноће — и само по себи не значи онколошко обољење. Значење налаза одређује искључиво љекар, упоређујући га са прегледом и ултразвуком', 'Повышение бывает при доброкачественных состояниях — эндометриозе, миоме, воспалении органов малого таза, заболеваниях печени, во время менструации и беременности — и само по себе не означает онкологического заболевания. Значение результата определяет только врач, сопоставляя его с осмотром и УЗИ', 'Ein Anstieg kommt auch bei gutartigen Zuständen vor — Endometriose, Myomen, Entzündungen der Beckenorgane, Lebererkrankungen, während der Menstruation und in der Schwangerschaft — und bedeutet für sich genommen keine onkologische Erkrankung. Was der Wert bedeutet, entscheidet allein der Arzt im Zusammenhang mit Untersuchung und Ultraschall', 'Yükselme endometriozis, miyom, pelvik iltihaplanma, karaciğer hastalıkları gibi iyi huylu durumlarda, adet döneminde ve gebelikte de görülür ve tek başına onkolojik bir hastalık anlamına gelmez. Sonucun anlamını yalnızca hekim, muayene ve ultrason bulgularıyla birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ca-15-3'), 'Blood test for the tumour marker CA 15-3, used mainly when monitoring the condition of the breast', 'Analiza krvi na tumorski marker CA 15-3, koji se prvenstveno koristi pri praćenju stanja dojke', 'Анализа крви на туморски маркер CA 15-3, који се првенствено користи при праћењу стања дојке', 'Анализ крови на онкомаркер CA 15-3, который применяют преимущественно при наблюдении за состоянием молочных желёз', 'Bluttest auf den Tumormarker CA 15-3, der vor allem bei der Verlaufsbeobachtung der Brustdrüse eingesetzt wird', 'Başlıca meme dokusunun durumunun izlenmesinde kullanılan CA 15-3 tümör belirteci için kan testi', 'Venous blood draw, the procedure takes a few minutes', 'Uzimanje venske krvi, postupak traje nekoliko minuta', 'Узимање венске крви, поступак траје неколико минута', 'Забор венозной крови, процедура занимает несколько минут', 'Venöse Blutentnahme, der Vorgang dauert wenige Minuten', 'Venöz kan alımı, işlem birkaç dakika sürer', 'Ordered by a doctor for follow-up monitoring of patients already receiving treatment and for subsequent control; it is not used as a screening test in healthy people', 'Po uputu ljekara radi praćenja pacijenata koji već primaju terapiju i kasnijih kontrola; ne koristi se kao skrining kod zdravih osoba', 'По упуту љекара ради праћења пацијената који већ примају терапију и каснијих контрола; не користи се као скрининг код здравих особа', 'По назначению врача для динамического наблюдения пациентов, уже получающих лечение, и последующего контроля; как скрининговый тест у здоровых людей не используется', 'Auf ärztliche Anordnung zur Verlaufskontrolle bei Patientinnen, die bereits behandelt werden, und zur weiteren Nachsorge; als Screening bei Gesunden wird er nicht eingesetzt', 'Tedavi almakta olan hastaların izlemi ve sonraki kontroller için hekim isteğiyle; sağlıklı kişilerde tarama testi olarak kullanılmaz', 'No special preparation is required; for repeat tests it is better to use the same laboratory each time', 'Posebna priprema nije potrebna; kod ponovljenih analiza poželjno je birati istu laboratoriju', 'Посебна припрема није потребна; код поновљених анализа пожељно је бирати исту лабораторију', 'Специальной подготовки не требуется; при повторных анализах желательно сдавать кровь в одной и той же лаборатории', 'Eine besondere Vorbereitung ist nicht nötig; bei Verlaufskontrollen sollte möglichst immer dasselbe Labor genutzt werden', 'Özel bir hazırlık gerekmez; tekrarlanan ölçümlerde aynı laboratuvarın tercih edilmesi uygundur', 'A moderate increase occurs with benign breast changes, liver disease, autoimmune and inflammatory processes, during pregnancy and breastfeeding, and on its own it does not mean an oncological disease. Only the treating doctor assesses the result, usually from the trend of several measurements', 'Umjereno povećanje javlja se kod benignih promjena dojke, bolesti jetre, autoimunih i upalnih procesa, u trudnoći i tokom dojenja i samo po sebi ne znači onkološko oboljenje. Nalaz tumači isključivo ljekar, najčešće prema kretanju više mjerenja', 'Умјерено повећање јавља се код бенигних промјена дојке, болести јетре, аутоимуних и упалних процеса, у трудноћи и током дојења и само по себи не значи онколошко обољење. Налаз тумачи искључиво љекар, најчешће према кретању више мјерења', 'Умеренное повышение встречается при доброкачественных изменениях молочных желёз, заболеваниях печени, аутоиммунных и воспалительных процессах, при беременности и кормлении грудью и само по себе не означает онкологического заболевания. Оценивает результат только лечащий врач, обычно по динамике нескольких измерений', 'Ein mäßiger Anstieg kommt bei gutartigen Veränderungen der Brust, Lebererkrankungen, autoimmunen und entzündlichen Prozessen sowie in Schwangerschaft und Stillzeit vor und bedeutet für sich genommen keine onkologische Erkrankung. Den Wert beurteilt ausschließlich der behandelnde Arzt, meist anhand des Verlaufs mehrerer Messungen', 'Ölçülü yükselmeler memenin iyi huylu değişikliklerinde, karaciğer hastalıklarında, otoimmün ve iltihabi süreçlerde, gebelikte ve emzirme döneminde de görülür ve tek başına onkolojik bir hastalık anlamına gelmez. Sonucu yalnızca tedaviyi yürüten hekim, genellikle birkaç ölçümün seyrine bakarak değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ca-19-9'), 'Blood test for the carbohydrate antigen CA 19-9, used as a tumour marker when monitoring the pancreas and the bile ducts', 'Analiza krvi na ugljenohidratni antigen CA 19-9, koji se koristi kao tumorski marker pri praćenju pankreasa i žučnih puteva', 'Анализа крви на угљенохидратни антиген CA 19-9, који се користи као туморски маркер при праћењу панкреаса и жучних путева', 'Анализ крови на углеводный антиген CA 19-9, который используют как онкомаркер при наблюдении за поджелудочной железой и желчевыводящими путями', 'Bluttest auf das Kohlenhydrat-Antigen CA 19-9, das als Tumormarker bei der Verlaufsbeobachtung von Bauchspeicheldrüse und Gallenwegen verwendet wird', 'Pankreas ve safra yollarının izlenmesinde tümör belirteci olarak kullanılan CA 19-9 karbonhidrat antijeni için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert wenige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Ordered by a doctor when the digestive organs are being examined, follow-up monitoring during treatment and afterwards', 'Po uputu ljekara pri pregledu organa za varenje, praćenje tokom liječenja i poslije njega', 'По упуту љекара при прегледу органа за варење, праћење током лијечења и послије њега', 'По назначению врача при обследовании органов пищеварения, динамическое наблюдение в процессе лечения и после него', 'Auf ärztliche Anordnung bei der Abklärung der Verdauungsorgane, Verlaufskontrolle während und nach einer Behandlung', 'Sindirim organlarının değerlendirilmesinde hekim isteğiyle, tedavi sırasında ve sonrasında izlem amacıyla', 'No special preparation is usually required; the laboratory may ask for a morning sample on an empty stomach', 'Posebna priprema obično nije potrebna; laboratorija može tražiti da se krv uzme ujutru natašte', 'Посебна припрема обично није потребна; лабораторија може тражити да се крв узме ујутру наташте', 'Специальной подготовки обычно не требуется; лаборатория может попросить сдать кровь утром натощак', 'In der Regel ist keine besondere Vorbereitung nötig; das Labor kann eine morgendliche Blutentnahme nüchtern verlangen', 'Genellikle özel hazırlık gerekmez; laboratuvar sabah aç karnına kan alınmasını isteyebilir', 'An increase is more often due to benign causes — inflammation of the pancreas, impaired bile flow, gallstones, liver disease, diabetes mellitus — and on its own it does not mean an oncological disease. Some people do not produce this antigen because of an inherited trait, so their result stays low regardless of their condition; only a doctor interprets it', 'Povećanje je češće posljedica benignih uzroka — upale pankreasa, otežanog oticanja žuči, kamenaca u žučnoj kesi, bolesti jetre, šećerne bolesti — i samo po sebi ne znači onkološko oboljenje. Kod dijela ljudi ovaj antigen se nasljedno ne stvara, pa nalaz ostaje nizak bez obzira na stanje; tumači ga isključivo ljekar', 'Повећање је чешће посљедица бенигних узрока — упале панкреаса, отежаног отицања жучи, каменаца у жучној кеси, болести јетре, шећерне болести — и само по себи не значи онколошко обољење. Код дијела људи овај антиген се насљедно не ствара, па налаз остаје низак без обзира на стање; тумачи га искључиво љекар', 'Повышение чаще связано с доброкачественными причинами — воспалением поджелудочной железы, нарушением оттока желчи, камнями в желчном пузыре, заболеваниями печени, сахарным диабетом — и само по себе не означает онкологического заболевания. У части людей этот антиген не вырабатывается из-за наследственной особенности, поэтому результат бывает низким независимо от состояния; трактует его только врач', 'Ein Anstieg hat häufiger gutartige Ursachen — Entzündung der Bauchspeicheldrüse, gestörten Gallenabfluss, Gallensteine, Lebererkrankungen, Diabetes mellitus — und bedeutet für sich genommen keine onkologische Erkrankung. Ein Teil der Menschen bildet dieses Antigen erblich bedingt nicht, sodass der Wert unabhängig vom Zustand niedrig bleibt; die Beurteilung übernimmt ausschließlich der Arzt', 'Yükselme çoğunlukla pankreas iltihabı, safra akışının bozulması, safra kesesi taşları, karaciğer hastalıkları, diyabet gibi iyi huylu nedenlere bağlıdır ve tek başına onkolojik bir hastalık anlamına gelmez. Bazı kişilerde bu antijen kalıtsal olarak üretilmez, bu nedenle sonuç durumdan bağımsız olarak düşük çıkabilir; değerlendirmeyi yalnızca hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'cea'), 'Blood test for a protein produced in fetal tissue that is present in small amounts in adults; it is used as a tumour marker when monitoring the digestive organs', 'Analiza krvi na bjelančevinu koja se stvara u tkivima ploda, a kod odraslih se nalazi u malim količinama; koristi se kao tumorski marker pri praćenju organa za varenje', 'Анализа крви на бјеланчевину која се ствара у ткивима плода, а код одраслих се налази у малим количинама; користи се као туморски маркер при праћењу органа за варење', 'Анализ крови на белок, который вырабатывается в тканях плода и у взрослых определяется в небольшом количестве; применяется как онкомаркер при наблюдении за органами пищеварения', 'Bluttest auf ein Eiweiß, das im fetalen Gewebe gebildet wird und bei Erwachsenen nur in geringer Menge vorkommt; es dient als Tumormarker bei der Verlaufsbeobachtung der Verdauungsorgane', 'Fetal dokularda üretilen ve erişkinlerde az miktarda bulunan bir protein için kan testi; sindirim organlarının izleminde tümör belirteci olarak kullanılır', 'Venous blood draw, the whole procedure takes a few minutes', 'Uzimanje venske krvi, cijeli postupak traje nekoliko minuta', 'Узимање венске крви, цијели поступак траје неколико минута', 'Забор венозной крови, вся процедура занимает несколько минут', 'Venöse Blutentnahme, der gesamte Vorgang dauert wenige Minuten', 'Venöz kan alımı, işlemin tamamı birkaç dakika sürer', 'Ordered by a doctor when the gastrointestinal tract is being examined, follow-up monitoring of patients already receiving treatment, regular control afterwards', 'Po uputu ljekara pri pregledu probavnog trakta, praćenje pacijenata koji već primaju terapiju, redovne kontrole kasnije', 'По упуту љекара при прегледу пробавног тракта, праћење пацијената који већ примају терапију, редовне контроле касније', 'По назначению врача при обследовании желудочно-кишечного тракта, динамическое наблюдение пациентов, уже получающих лечение, регулярный контроль в дальнейшем', 'Auf ärztliche Anordnung bei der Abklärung des Magen-Darm-Trakts, Verlaufskontrolle bei Patienten, die bereits behandelt werden, regelmäßige Kontrollen danach', 'Sindirim sisteminin değerlendirilmesinde hekim isteğiyle, tedavi almakta olan hastaların izleminde, sonrasındaki düzenli kontrollerde', 'No special preparation is required; the doctor should know whether the patient smokes, as smoking affects the result', 'Posebna priprema nije potrebna; ljekaru je važno da zna da li pacijent puši, jer pušenje utiče na nalaz', 'Посебна припрема није потребна; љекару је важно да зна да ли пацијент пуши, јер пушење утиче на налаз', 'Специальной подготовки не требуется; врачу важно знать, курит ли пациент, — курение влияет на результат', 'Eine besondere Vorbereitung ist nicht nötig; der Arzt sollte wissen, ob der Patient raucht, denn Rauchen beeinflusst den Wert', 'Özel bir hazırlık gerekmez; sigara kullanımı sonucu etkilediği için hekimin bunu bilmesi önemlidir', 'An increase occurs in smokers and with benign conditions — inflammatory bowel disease, peptic ulcer, polyps, diseases of the liver, lungs and thyroid — and on its own it does not mean an oncological disease. The doctor assesses the result, usually by its trend rather than by a single measurement', 'Povećanje se javlja kod pušača i kod benignih stanja — upalnih bolesti crijeva, čira, polipa, bolesti jetre, pluća i štitne žlijezde — i samo po sebi ne znači onkološko oboljenje. Nalaz procjenjuje ljekar, češće prema kretanju vrijednosti nego prema jednom mjerenju', 'Повећање се јавља код пушача и код бенигних стања — упалних болести цријева, чира, полипа, болести јетре, плућа и штитне жлијезде — и само по себи не значи онколошко обољење. Налаз процјењује љекар, чешће према кретању вриједности него према једном мјерењу', 'Повышение встречается у курящих и при доброкачественных состояниях — воспалительных заболеваниях кишечника, язвенной болезни, полипах, заболеваниях печени, лёгких и щитовидной железы — и само по себе не означает онкологического заболевания. Результат оценивает врач, чаще по изменению в динамике, а не по одному измерению', 'Ein Anstieg kommt bei Rauchern und bei gutartigen Zuständen vor — chronisch-entzündlichen Darmerkrankungen, Magengeschwüren, Polypen, Erkrankungen von Leber, Lunge und Schilddrüse — und bedeutet für sich genommen keine onkologische Erkrankung. Der Arzt beurteilt den Wert meist anhand des Verlaufs und nicht anhand einer einzelnen Messung', 'Yükselme sigara içenlerde ve iltihabi bağırsak hastalıkları, ülser, polipler, karaciğer, akciğer ve tiroid hastalıkları gibi iyi huylu durumlarda da görülür; tek başına onkolojik bir hastalık anlamına gelmez. Hekim sonucu genellikle tek bir ölçüme değil, değerlerin seyrine bakarak değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'free-psa'), 'Blood test for the fraction of prostate-specific antigen that is not bound to plasma proteins; it is assessed together with total PSA as a ratio', 'Analiza krvi na onaj dio prostata-specifičnog antigena koji nije vezan za bjelančevine plazme; procjenjuje se zajedno sa ukupnim PSA, kao njihov odnos', 'Анализа крви на онај дио простата-специфичног антигена који није везан за бјеланчевине плазме; процјењује се заједно са укупним PSA, као њихов однос', 'Анализ крови на ту часть простат-специфического антигена, которая не связана с белками плазмы; оценивается вместе с общим PSA в виде их соотношения', 'Bluttest auf den Anteil des prostataspezifischen Antigens, der nicht an Plasmaeiweiße gebunden ist; er wird zusammen mit dem Gesamt-PSA als Verhältnis beurteilt', 'Prostata özgü antijenin plazma proteinlerine bağlı olmayan bölümünü ölçen kan testi; toplam PSA ile birlikte oran olarak değerlendirilir', 'Venous blood draw, usually from the same sample as total PSA', 'Uzimanje venske krvi, obično iz istog uzorka kao i ukupni PSA', 'Узимање венске крви, обично из истог узорка као и укупни PSA', 'Забор венозной крови, обычно из той же пробы, что и общий PSA', 'Venöse Blutentnahme, meist aus derselben Probe wie das Gesamt-PSA', 'Venöz kan alımı, genellikle toplam PSA ile aynı örnekten yapılır', 'Ordered by a urologist when a total PSA result needs clarification, follow-up monitoring of the prostate over time', 'Po uputu urologa kada nalaz ukupnog PSA treba dodatno razjasniti, praćenje stanja prostate tokom vremena', 'По упуту уролога када налаз укупног PSA треба додатно разјаснити, праћење стања простате током времена', 'По назначению уролога, когда нужно уточнить результат общего PSA, наблюдение за состоянием простаты в динамике', 'Auf Anordnung des Urologen, wenn ein Gesamt-PSA-Wert genauer eingeordnet werden soll, Verlaufsbeobachtung der Prostata', 'Toplam PSA sonucunun netleştirilmesi gerektiğinde ürolog isteğiyle, prostat durumunun zaman içinde izlenmesinde', 'Avoid ejaculation, cycling and intense physical activity for a few days beforehand; the sample is taken before a digital rectal examination or several days after it', 'Nekoliko dana ranije uzdržati se od ejakulacije, vožnje bicikla i jakog fizičkog napora; krv se uzima prije digitorektalnog pregleda ili nekoliko dana poslije njega', 'Неколико дана раније уздржати се од ејакулације, вожње бицикла и јаког физичког напора; крв се узима прије дигиторекталног прегледа или неколико дана послије њега', 'За несколько дней воздержаться от эякуляции, езды на велосипеде и интенсивных нагрузок; кровь сдают до пальцевого ректального исследования или спустя несколько дней после него', 'Einige Tage vorher auf Ejakulation, Radfahren und starke körperliche Belastung verzichten; die Blutentnahme erfolgt vor einer digital-rektalen Untersuchung oder einige Tage danach', 'Birkaç gün önceden ejakülasyondan, bisiklet kullanımından ve yoğun fiziksel aktiviteden kaçınılmalı; kan, parmakla rektal muayeneden önce veya birkaç gün sonra alınmalıdır', 'The ratio of free to total PSA changes with benign prostatic hyperplasia, inflammation of the prostate and after medical procedures, and on its own it does not mean an oncological disease. The urologist interprets the result together with total PSA and the findings of the examination', 'Odnos slobodnog i ukupnog PSA mijenja se kod benigno uvećane prostate, upale prostate i poslije medicinskih zahvata i sam po sebi ne znači onkološko oboljenje. Nalaz tumači urolog zajedno sa ukupnim PSA i nalazom pregleda', 'Однос слободног и укупног PSA мијења се код бенигно увећане простате, упале простате и послије медицинских захвата и сам по себи не значи онколошко обољење. Налаз тумачи уролог заједно са укупним PSA и налазом прегледа', 'Соотношение свободного и общего PSA меняется при доброкачественной гиперплазии простаты, воспалении простаты, после медицинских манипуляций и само по себе не означает онкологического заболевания. Результат интерпретирует уролог вместе с общим PSA и данными осмотра', 'Das Verhältnis von freiem zu Gesamt-PSA verändert sich bei gutartiger Prostatavergrößerung, bei Entzündung der Prostata und nach medizinischen Eingriffen und bedeutet für sich genommen keine onkologische Erkrankung. Der Urologe deutet den Wert zusammen mit dem Gesamt-PSA und dem Untersuchungsbefund', 'Serbest PSA''nın toplam PSA''ya oranı iyi huylu prostat büyümesinde, prostat iltihabında ve tıbbi işlemlerden sonra değişir; tek başına onkolojik bir hastalık anlamına gelmez. Sonucu ürolog, toplam PSA ve muayene bulgularıyla birlikte yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ca-72-4'), 'Blood test for the glycoprotein tumour marker CA 72-4, used mainly when monitoring the condition of the stomach and the ovaries', 'Analiza krvi na glikoproteinski tumorski marker CA 72-4, koji se prvenstveno koristi pri praćenju stanja želuca i jajnika', 'Анализа крви на гликопротеински туморски маркер CA 72-4, који се првенствено користи при праћењу стања желуца и јајника', 'Анализ крови на гликопротеиновый онкомаркер CA 72-4, который применяют преимущественно при наблюдении за состоянием желудка и яичников', 'Bluttest auf den Glykoprotein-Tumormarker CA 72-4, der vor allem bei der Verlaufsbeobachtung von Magen und Eierstöcken eingesetzt wird', 'Başlıca mide ve yumurtalıkların durumunun izlenmesinde kullanılan CA 72-4 glikoprotein tümör belirteci için kan testi', 'Venous blood draw, the procedure is short', 'Uzimanje venske krvi, postupak je kratak', 'Узимање венске крви, поступак је кратак', 'Забор венозной крови, процедура короткая', 'Venöse Blutentnahme, der Vorgang ist kurz', 'Venöz kan alımı, işlem kısa sürer', 'Ordered by a doctor when the gastrointestinal tract is being examined, follow-up monitoring during treatment, usually alongside other markers', 'Po uputu ljekara pri pregledu probavnog trakta, praćenje tokom liječenja, obično uz druge markere', 'По упуту љекара при прегледу пробавног тракта, праћење током лијечења, обично уз друге маркере', 'По назначению врача при обследовании желудочно-кишечного тракта, динамическое наблюдение в процессе лечения, обычно вместе с другими маркерами', 'Auf ärztliche Anordnung bei der Abklärung des Magen-Darm-Trakts, Verlaufskontrolle während einer Behandlung, meist zusammen mit anderen Markern', 'Sindirim sisteminin değerlendirilmesinde hekim isteğiyle, tedavi sırasında izlemde, genellikle diğer belirteçlerle birlikte', 'No special preparation is required; tell the doctor about all medicines being taken, as some of them affect the result', 'Posebna priprema nije potrebna; ljekaru treba reći koje lijekove pacijent uzima, jer neki od njih utiču na nalaz', 'Посебна припрема није потребна; љекару треба рећи које лијекове пацијент узима, јер неки од њих утичу на налаз', 'Специальной подготовки не требуется; стоит сообщить врачу обо всех принимаемых препаратах, некоторые из них влияют на результат', 'Eine besondere Vorbereitung ist nicht nötig; dem Arzt sollten alle eingenommenen Medikamente genannt werden, da einige den Wert beeinflussen', 'Özel bir hazırlık gerekmez; bazı ilaçlar sonucu etkilediği için kullanılan tüm ilaçlar hekime bildirilmelidir', 'An increase occurs with benign diseases of the stomach, pancreas, liver and ovaries, with inflammatory processes and while taking certain medicines, so on its own it does not mean an oncological disease. The conclusion is drawn by the doctor, comparing the marker with other investigations', 'Povećanje se javlja kod benignih bolesti želuca, pankreasa, jetre i jajnika, kod upalnih procesa i uz uzimanje pojedinih lijekova, pa samo po sebi ne znači onkološko oboljenje. Zaključak donosi ljekar, upoređujući marker sa ostalim pregledima', 'Повећање се јавља код бенигних болести желуца, панкреаса, јетре и јајника, код упалних процеса и уз узимање појединих лијекова, па само по себи не значи онколошко обољење. Закључак доноси љекар, упоређујући маркер са осталим прегледима', 'Повышение встречается при доброкачественных заболеваниях желудка, поджелудочной железы, печени и яичников, при воспалительных процессах и на фоне приёма некоторых лекарств, поэтому само по себе не означает онкологического заболевания. Вывод делает врач, сопоставляя маркер с другими обследованиями', 'Ein Anstieg kommt bei gutartigen Erkrankungen von Magen, Bauchspeicheldrüse, Leber und Eierstöcken, bei entzündlichen Prozessen und unter bestimmten Medikamenten vor und bedeutet daher für sich genommen keine onkologische Erkrankung. Die Einordnung nimmt der Arzt im Vergleich mit weiteren Untersuchungen vor', 'Yükselme mide, pankreas, karaciğer ve yumurtalıkların iyi huylu hastalıklarında, iltihabi süreçlerde ve bazı ilaçların kullanımı sırasında da görülür; bu nedenle tek başına onkolojik bir hastalık anlamına gelmez. Değerlendirmeyi, belirteci diğer tetkiklerle karşılaştırarak hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'cyfra-21-1'), 'Blood test for a fragment of cytokeratin 19, a protein of epithelial cells; it is used as a tumour marker when monitoring the condition of the lungs', 'Analiza krvi na fragment citokeratina 19, bjelančevine epitelnih ćelija; koristi se kao tumorski marker pri praćenju stanja pluća', 'Анализа крви на фрагмент цитокератина 19, бјеланчевине епителних ћелија; користи се као туморски маркер при праћењу стања плућа', 'Анализ крови на фрагмент цитокератина 19 — белка эпителиальных клеток; используется как онкомаркер при наблюдении за состоянием лёгких', 'Bluttest auf ein Fragment von Cytokeratin 19, einem Eiweiß der Epithelzellen; es dient als Tumormarker bei der Verlaufsbeobachtung der Lunge', 'Epitel hücrelerinin proteini olan sitokeratin 19''un bir parçasını ölçen kan testi; akciğerlerin durumunun izlenmesinde tümör belirteci olarak kullanılır', 'Blood draw from a vein in the arm, takes a few minutes', 'Uzimanje venske krvi iz vene na ruci, traje nekoliko minuta', 'Узимање венске крви из вене на руци, траје неколико минута', 'Забор венозной крови из вены руки, занимает несколько минут', 'Blutentnahme aus einer Armvene, dauert wenige Minuten', 'Koldaki toplardamardan kan alınması, birkaç dakika sürer', 'Ordered by a doctor when the chest organs are being examined, follow-up monitoring of patients already receiving treatment', 'Po uputu ljekara pri pregledu organa grudnog koša, praćenje pacijenata koji već primaju terapiju', 'По упуту љекара при прегледу органа грудног коша, праћење пацијената који већ примају терапију', 'По назначению врача при обследовании органов грудной клетки, динамическое наблюдение пациентов, уже получающих лечение', 'Auf ärztliche Anordnung bei der Abklärung der Brustorgane, Verlaufskontrolle bei Patienten, die bereits behandelt werden', 'Göğüs bölgesi organlarının değerlendirilmesinde hekim isteğiyle, tedavi almakta olan hastaların izleminde', 'No special preparation is required, there are usually no restrictions on food', 'Posebna priprema nije potrebna, obično nema ograničenja u ishrani', 'Посебна припрема није потребна, обично нема ограничења у исхрани', 'Специальной подготовки не требуется, ограничений по еде обычно нет', 'Eine besondere Vorbereitung ist nicht nötig, Einschränkungen beim Essen bestehen in der Regel nicht', 'Özel bir hazırlık gerekmez, genellikle beslenmeyle ilgili bir kısıtlama yoktur', 'An increase occurs with benign diseases of the lungs and pleura, chronic inflammation and impaired kidney and liver function, and on its own it does not mean an oncological disease. The doctor assesses the result together with an X-ray or computed tomography', 'Povećanje se javlja kod benignih bolesti pluća i plućne maramice, hroničnih upala, oslabljene funkcije bubrega i jetre i samo po sebi ne znači onkološko oboljenje. Nalaz procjenjuje ljekar zajedno sa rendgenskim snimkom ili kompjuterizovanom tomografijom', 'Повећање се јавља код бенигних болести плућа и плућне марамице, хроничних упала, ослабљене функције бубрега и јетре и само по себи не значи онколошко обољење. Налаз процјењује љекар заједно са рендгенским снимком или компјутеризованом томографијом', 'Повышение бывает при доброкачественных заболеваниях лёгких и плевры, хронических воспалениях, нарушении функции почек и печени и само по себе не означает онкологического заболевания. Результат оценивает врач вместе с рентгеном или компьютерной томографией', 'Ein Anstieg kommt bei gutartigen Erkrankungen von Lunge und Rippenfell, bei chronischen Entzündungen sowie bei eingeschränkter Nieren- und Leberfunktion vor und bedeutet für sich genommen keine onkologische Erkrankung. Der Arzt beurteilt den Wert zusammen mit Röntgenbild oder Computertomografie', 'Yükselme akciğer ve akciğer zarının iyi huylu hastalıklarında, kronik iltihaplarda, böbrek ve karaciğer işlevlerinin bozulmasında da görülür ve tek başına onkolojik bir hastalık anlamına gelmez. Hekim sonucu röntgen veya bilgisayarlı tomografi bulgularıyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'he4'), 'Blood test for the HE4 protein, used when ovarian masses are being examined, most often together with CA 125', 'Analiza krvi na bjelančevinu HE4, koja se koristi pri pregledu promjena na jajnicima, najčešće zajedno sa CA 125', 'Анализа крви на бјеланчевину HE4, која се користи при прегледу промјена на јајницима, најчешће заједно са CA 125', 'Анализ крови на белок HE4, который используют при обследовании образований в яичниках, чаще вместе с CA 125', 'Bluttest auf das Eiweiß HE4, das bei der Abklärung von Veränderungen an den Eierstöcken eingesetzt wird, meist zusammen mit CA 125', 'Yumurtalıklardaki oluşumların değerlendirilmesinde, çoğunlukla CA 125 ile birlikte kullanılan HE4 proteini için kan testi', 'Venous blood draw, usually from the same sample as CA 125', 'Uzimanje venske krvi, obično iz istog uzorka kao i CA 125', 'Узимање венске крви, обично из истог узорка као и CA 125', 'Забор венозной крови, обычно из той же пробы, что и CA 125', 'Venöse Blutentnahme, meist aus derselben Probe wie CA 125', 'Venöz kan alımı, genellikle CA 125 ile aynı örnekten yapılır', 'Ordered by a gynaecologist when a pelvic mass is being examined, follow-up monitoring, calculation of the ROMA index', 'Po uputu ginekologa pri pregledu promjena u maloj karlici, praćenje tokom vremena, izračunavanje ROMA indeksa', 'По упуту гинеколога при прегледу промјена у малој карлици, праћење током времена, израчунавање ROMA индекса', 'По назначению гинеколога при обследовании образований в малом тазу, динамическое наблюдение, расчёт индекса ROMA', 'Auf Anordnung des Gynäkologen bei der Abklärung von Raumforderungen im Becken, Verlaufsbeobachtung, Berechnung des ROMA-Index', 'Pelviste saptanan oluşumların değerlendirilmesinde jinekolog isteğiyle, zaman içinde izlemde, ROMA indeksinin hesaplanmasında', 'No special preparation is required; the doctor should be told about kidney disease and smoking, as both affect the result', 'Posebna priprema nije potrebna; ljekaru treba reći za bolesti bubrega i za pušenje, jer utiču na nalaz', 'Посебна припрема није потребна; љекару треба рећи за болести бубрега и за пушење, јер утичу на налаз', 'Специальной подготовки не требуется; врачу стоит сообщить о заболеваниях почек и о курении — они влияют на результат', 'Eine besondere Vorbereitung ist nicht nötig; Nierenerkrankungen und Rauchen sollten dem Arzt mitgeteilt werden, da sie den Wert beeinflussen', 'Özel bir hazırlık gerekmez; böbrek hastalıkları ve sigara kullanımı sonucu etkilediğinden hekime bildirilmelidir', 'The level rises with reduced kidney function, with some lung diseases, in smokers and with age, so on its own the result does not mean an oncological disease. The gynaecologist assesses it together with CA 125, ultrasound and the clinical picture', 'Vrijednost raste kod slabije funkcije bubrega, kod nekih bolesti pluća, kod pušača i sa godinama, pa nalaz sam po sebi ne znači onkološko oboljenje. Procjenjuje ga ginekolog zajedno sa CA 125, ultrazvukom i kliničkom slikom', 'Вриједност расте код слабије функције бубрега, код неких болести плућа, код пушача и са годинама, па налаз сам по себи не значи онколошко обољење. Процјењује га гинеколог заједно са CA 125, ултразвуком и клиничком сликом', 'Уровень повышается при снижении функции почек, некоторых заболеваниях лёгких, у курящих и с возрастом, поэтому сам по себе результат не означает онкологического заболевания. Оценивает его гинеколог вместе с CA 125, УЗИ и клинической картиной', 'Der Wert steigt bei eingeschränkter Nierenfunktion, bei manchen Lungenerkrankungen, bei Rauchern und mit zunehmendem Alter, daher bedeutet er für sich genommen keine onkologische Erkrankung. Beurteilt wird er vom Gynäkologen zusammen mit CA 125, Ultraschall und dem klinischen Bild', 'Değer böbrek işlevinin azalmasında, bazı akciğer hastalıklarında, sigara içenlerde ve yaşla birlikte yükselir; bu nedenle sonuç tek başına onkolojik bir hastalık anlamına gelmez. Jinekolog sonucu CA 125, ultrason ve klinik tabloyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'nse'), 'Blood test for an enzyme of nerve and neuroendocrine cells, used as a tumour marker in selected clinical situations', 'Analiza krvi na enzim nervnih i neuroendokrinih ćelija, koji se u pojedinim kliničkim situacijama koristi kao tumorski marker', 'Анализа крви на ензим нервних и неуроендокриних ћелија, који се у појединим клиничким ситуацијама користи као туморски маркер', 'Анализ крови на фермент нервных и нейроэндокринных клеток, который применяют как онкомаркер в отдельных клинических ситуациях', 'Bluttest auf ein Enzym der Nerven- und neuroendokrinen Zellen, das in bestimmten klinischen Situationen als Tumormarker dient', 'Sinir ve nöroendokrin hücrelerin bir enzimini ölçen kan testi; belirli klinik durumlarda tümör belirteci olarak kullanılır', 'Venous blood draw; the sample is taken carefully, without prolonged use of the tourniquet, and sent to the laboratory quickly', 'Uzimanje venske krvi; uzorak se uzima pažljivo, bez dugog stezanja podvezom, i brzo šalje u laboratoriju', 'Узимање венске крви; узорак се узима пажљиво, без дугог стезања подвезом, и брзо шаље у лабораторију', 'Забор венозной крови; пробу берут аккуратно, без длительного сдавливания жгутом, и быстро передают в лабораторию', 'Venöse Blutentnahme; die Probe wird vorsichtig und ohne langes Stauen entnommen und rasch ins Labor gebracht', 'Venöz kan alımı; kan, turnike uzun süre bağlı tutulmadan dikkatle alınır ve hızla laboratuvara iletilir', 'Ordered by a doctor when neuroendocrine conditions and lung diseases are being monitored, control during treatment', 'Po uputu ljekara pri praćenju neuroendokrinih stanja i bolesti pluća, kontrola tokom liječenja', 'По упуту љекара при праћењу неуроендокриних стања и болести плућа, контрола током лијечења', 'По назначению врача при наблюдении за нейроэндокринными состояниями и заболеваниями лёгких, контроль в процессе лечения', 'Auf ärztliche Anordnung bei der Verlaufsbeobachtung neuroendokriner Zustände und von Lungenerkrankungen, Kontrolle während der Behandlung', 'Nöroendokrin durumların ve akciğer hastalıklarının izleminde hekim isteğiyle, tedavi sırasında kontrol amacıyla', 'No special preparation is required; it matters that the laboratory processes the sample quickly, as the reliability of the result depends on it', 'Posebna priprema nije potrebna; važno je da laboratorija brzo obradi uzorak, jer od toga zavisi pouzdanost nalaza', 'Посебна припрема није потребна; важно је да лабораторија брзо обради узорак, јер од тога зависи поузданост налаза', 'Специальной подготовки не требуется; важно, чтобы лаборатория обработала пробу быстро — от этого зависит достоверность результата', 'Eine besondere Vorbereitung ist nicht nötig; wichtig ist, dass das Labor die Probe zügig verarbeitet, davon hängt die Verlässlichkeit des Werts ab', 'Özel bir hazırlık gerekmez; sonucun güvenilirliği alınan kanın hızla işlenmesine bağlı olduğu için bu önemlidir', 'An elevated result is often technical, caused by breakdown of red blood cells in the tube; an increase also occurs with diseases of the lungs, kidneys and liver, so on its own it does not mean an oncological disease. What the result means is decided by the doctor, and in case of doubt the test is repeated', 'Povišen nalaz je nerijetko tehničke prirode, zbog raspadanja crvenih krvnih zrnaca u epruveti; povećanje se javlja i kod bolesti pluća, bubrega i jetre, pa samo po sebi ne znači onkološko oboljenje. Značenje nalaza određuje ljekar, a u slučaju sumnje analiza se ponavlja', 'Повишен налаз је неријетко техничке природе, због распадања црвених крвних зрнаца у епрувети; повећање се јавља и код болести плућа, бубрега и јетре, па само по себи не значи онколошко обољење. Значење налаза одређује љекар, а у случају сумње анализа се понавља', 'Завышенный результат нередко оказывается техническим, из-за разрушения эритроцитов в пробирке; повышение встречается также при заболеваниях лёгких, почек и печени, поэтому само по себе оно не означает онкологического заболевания. Значение результата определяет врач, при сомнении анализ пересдают', 'Ein erhöhter Wert ist häufig technisch bedingt, durch den Zerfall roter Blutkörperchen im Röhrchen; ein Anstieg kommt außerdem bei Erkrankungen von Lunge, Nieren und Leber vor und bedeutet daher für sich genommen keine onkologische Erkrankung. Was der Wert bedeutet, entscheidet der Arzt, im Zweifelsfall wird die Untersuchung wiederholt', 'Yüksek sonuç çoğu zaman tüpteki alyuvarların parçalanmasına bağlı teknik bir durumdur; yükselme ayrıca akciğer, böbrek ve karaciğer hastalıklarında da görülür, bu nedenle tek başına onkolojik bir hastalık anlamına gelmez. Sonucun anlamını hekim belirler, kuşku varsa test tekrarlanır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'chromogranin-a'), 'Blood test for a protein released by neuroendocrine cells; it is used when neuroendocrine diseases are being monitored', 'Analiza krvi na bjelančevinu koju luče neuroendokrine ćelije; koristi se pri praćenju neuroendokrinih bolesti', 'Анализа крви на бјеланчевину коју луче неуроендокрине ћелије; користи се при праћењу неуроендокриних болести', 'Анализ крови на белок, который выделяют нейроэндокринные клетки; используется при наблюдении за нейроэндокринными заболеваниями', 'Bluttest auf ein Eiweiß, das von neuroendokrinen Zellen freigesetzt wird; es dient der Verlaufsbeobachtung neuroendokriner Erkrankungen', 'Nöroendokrin hücrelerin salgıladığı bir proteini ölçen kan testi; nöroendokrin hastalıkların izleminde kullanılır', 'Venous blood draw, usually in the morning, takes a few minutes', 'Uzimanje venske krvi, najčešće ujutru, traje nekoliko minuta', 'Узимање венске крви, најчешће ујутру, траје неколико минута', 'Забор венозной крови, чаще утром, занимает несколько минут', 'Venöse Blutentnahme, meist morgens, dauert wenige Minuten', 'Venöz kan alımı, çoğunlukla sabah yapılır ve birkaç dakika sürer', 'Ordered by an endocrinologist or gastroenterologist when neuroendocrine diseases are being investigated and for follow-up monitoring during treatment', 'Po uputu endokrinologa ili gastroenterologa pri ispitivanju neuroendokrinih bolesti i praćenju tokom liječenja', 'По упуту ендокринолога или гастроентеролога при испитивању неуроендокриних болести и праћењу током лијечења', 'По назначению эндокринолога или гастроэнтеролога при обследовании нейроэндокринных заболеваний и динамическом наблюдении в процессе лечения', 'Auf Anordnung des Endokrinologen oder Gastroenterologen bei der Abklärung neuroendokriner Erkrankungen und zur Verlaufskontrolle während der Behandlung', 'Nöroendokrin hastalıkların araştırılmasında ve tedavi sırasındaki izlemde endokrinolog ya da gastroenterolog isteğiyle', 'The sample is taken on an empty stomach; medicines that reduce stomach acid noticeably raise the value — only the doctor decides whether to pause them, treatment must not be interrupted on one''s own', 'Krv se uzima natašte; lijekovi koji smanjuju želudačnu kiselinu osjetno povećavaju vrijednost — o njihovom privremenom prekidu odlučuje isključivo ljekar, terapija se ne smije prekidati samoinicijativno', 'Крв се узима наташте; лијекови који смањују желудачну киселину осјетно повећавају вриједност — о њиховом привременом прекиду одлучује искључиво љекар, терапија се не смије прекидати самоиницијативно', 'Кровь сдают натощак; препараты, снижающие кислотность желудка, заметно повышают показатель — вопрос об их временной отмене решает только врач, самостоятельно прерывать лечение нельзя', 'Die Blutentnahme erfolgt nüchtern; Medikamente, die die Magensäure senken, erhöhen den Wert deutlich — über ein vorübergehendes Pausieren entscheidet allein der Arzt, eigenmächtig darf die Therapie nicht unterbrochen werden', 'Kan aç karnına alınır; mide asidini azaltan ilaçlar değeri belirgin şekilde yükseltir — bunların geçici olarak bırakılmasına yalnızca hekim karar verir, tedavi kendi başına kesilmemelidir', 'An increase is most often related to heartburn medicines, atrophic gastritis, reduced kidney function, heart failure and chronic inflammation, and on its own it does not mean an oncological disease. The doctor assesses the result taking into account the medicines taken and other investigations', 'Povećanje je najčešće povezano sa lijekovima protiv gorušice, atrofičnim gastritisom, slabijom funkcijom bubrega, srčanom slabošću i hroničnim upalama i samo po sebi ne znači onkološko oboljenje. Nalaz procjenjuje ljekar uzimajući u obzir lijekove koje pacijent koristi i ostale preglede', 'Повећање је најчешће повезано са лијековима против горушице, атрофичним гастритисом, слабијом функцијом бубрега, срчаном слабошћу и хроничним упалама и само по себи не значи онколошко обољење. Налаз процјењује љекар узимајући у обзир лијекове које пацијент користи и остале прегледе', 'Повышение чаще всего связано с приёмом препаратов от изжоги, атрофическим гастритом, снижением функции почек, сердечной недостаточностью и хроническими воспалениями и само по себе не означает онкологического заболевания. Результат оценивает врач с учётом принимаемых лекарств и других обследований', 'Ein Anstieg hängt am häufigsten mit Medikamenten gegen Sodbrennen, atrophischer Gastritis, eingeschränkter Nierenfunktion, Herzschwäche und chronischen Entzündungen zusammen und bedeutet für sich genommen keine onkologische Erkrankung. Der Arzt beurteilt den Wert unter Berücksichtigung der eingenommenen Medikamente und weiterer Untersuchungen', 'Yükselme çoğunlukla mide yanmasına karşı kullanılan ilaçlar, atrofik gastrit, böbrek işlevinin azalması, kalp yetmezliği ve kronik iltihaplarla ilişkilidir ve tek başına onkolojik bir hastalık anlamına gelmez. Hekim sonucu, kullanılan ilaçları ve diğer tetkikleri göz önünde bulundurarak değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'roma-index'), 'A calculated value that combines the results of CA 125 and HE4 taking the woman''s menopausal status into account', 'Izračunata vrijednost koja objedinjuje nalaze CA 125 i HE4 uz uzimanje u obzir menopauzalnog statusa žene', 'Израчуната вриједност која обједињује налазе CA 125 и HE4 уз узимање у обзир менопаузалног статуса жене', 'Расчётный показатель, который объединяет результаты CA 125 и HE4 с учётом менопаузального статуса женщины', 'Ein berechneter Wert, der die Ergebnisse von CA 125 und HE4 unter Berücksichtigung des Menopausenstatus der Frau zusammenführt', 'CA 125 ve HE4 sonuçlarını kadının menopoz durumunu da hesaba katarak birleştiren hesaplanmış bir değer', 'No separate blood draw is needed: the laboratory calculates the value from two tests run on one sample', 'Zasebno vađenje krvi nije potrebno: laboratorija vrijednost izračunava iz dvije analize iz istog uzorka', 'Засебно вађење крви није потребно: лабораторија вриједност израчунава из двије анализе из истог узорка', 'Отдельный забор крови не нужен: показатель рассчитывает лаборатория по двум анализам из одной пробы', 'Eine gesonderte Blutentnahme ist nicht nötig: das Labor berechnet den Wert aus zwei Untersuchungen derselben Probe', 'Ayrı bir kan alımı gerekmez: laboratuvar değeri aynı örnekten yapılan iki testten hesaplar', 'Ordered by a gynaecologist when ovarian masses are being examined and the further monitoring plan has to be decided', 'Po uputu ginekologa pri pregledu promjena na jajnicima, kada treba odrediti dalji plan praćenja', 'По упуту гинеколога при прегледу промјена на јајницима, када треба одредити даљи план праћења', 'По назначению гинеколога при обследовании образований в яичниках, когда нужно определить дальнейшую тактику наблюдения', 'Auf Anordnung des Gynäkologen bei der Abklärung von Veränderungen an den Eierstöcken, wenn das weitere Vorgehen festgelegt werden soll', 'Yumurtalıklardaki oluşumların değerlendirilmesinde, izlem planının belirlenmesi gerektiğinde jinekolog isteğiyle', 'The preparation is the same as for CA 125 and HE4; the referral must state the menopausal status, without it the calculation cannot be made', 'Priprema je ista kao za CA 125 i HE4; na uputu se obavezno navodi menopauzalni status, bez njega se izračun ne radi', 'Припрема је иста као за CA 125 и HE4; на упуту се обавезно наводи менопаузални статус, без њега се израчун не ради', 'Подготовка та же, что для CA 125 и HE4; в направлении обязательно указывают менопаузальный статус, без него расчёт не выполняется', 'Die Vorbereitung entspricht der für CA 125 und HE4; auf der Überweisung muss der Menopausenstatus angegeben sein, ohne ihn ist die Berechnung nicht möglich', 'Hazırlık CA 125 ve HE4 ile aynıdır; istem belgesinde menopoz durumunun belirtilmesi zorunludur, aksi hâlde hesaplama yapılamaz', 'The value is not a diagnosis and does not replace examination and ultrasound: it is affected by the same benign conditions as CA 125 and HE4. Only the gynaecologist interprets the result together with the rest of the examination findings', 'Vrijednost nije dijagnoza i ne zamjenjuje pregled i ultrazvuk: na nju utiču ista benigna stanja kao na CA 125 i HE4. Nalaz tumači isključivo ginekolog, zajedno sa ostalim nalazima pregleda', 'Вриједност није дијагноза и не замјењује преглед и ултразвук: на њу утичу иста бенигна стања као на CA 125 и HE4. Налаз тумачи искључиво гинеколог, заједно са осталим налазима прегледа', 'Показатель не является диагнозом и не заменяет осмотр и УЗИ: на него влияют те же доброкачественные состояния, что на CA 125 и HE4. Результат интерпретирует только гинеколог в комплексе с остальными данными обследования', 'Der Wert ist keine Diagnose und ersetzt weder Untersuchung noch Ultraschall: Ihn beeinflussen dieselben gutartigen Zustände wie CA 125 und HE4. Die Deutung nimmt ausschließlich der Gynäkologe im Zusammenhang mit den übrigen Befunden vor', 'Bu değer bir tanı değildir ve muayene ile ultrasonun yerini tutmaz: CA 125 ve HE4''ü etkileyen aynı iyi huylu durumlardan etkilenir. Sonucu yalnızca jinekolog, diğer inceleme bulgularıyla birlikte yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'iga'), 'Blood test for class A immunoglobulin, the antibodies that protect the mucous membranes of the airways and the gut', 'Analiza krvi na imunoglobulin klase A, antitijela koja štite sluznice disajnih puteva i crijeva', 'Анализа крви на имуноглобулин класе А, антитијела која штите слузнице дисајних путева и цријева', 'Анализ крови на иммуноглобулин класса A — антитела, которые защищают слизистые дыхательных путей и кишечника', 'Bluttest auf Immunglobulin der Klasse A, die Antikörper, die die Schleimhäute von Atemwegen und Darm schützen', 'Solunum yollarının ve bağırsağın mukozasını koruyan A sınıfı immünoglobulin için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Frequent respiratory and intestinal infections, evaluation for weak mucosal immune defence, check before interpreting coeliac disease serology, immune panel', 'Česte infekcije disajnih puteva i crijeva, ispitivanje pri sumnji na slabu imunu zaštitu sluznica, provjera prije tumačenja serologije na celijakiju, imunogram', 'Честе инфекције дисајних путева и цријева, испитивање при сумњи на слабу имуну заштиту слузница, провјера прије тумачења серологије на целијакију, имунограм', 'Частые инфекции дыхательных путей и кишечника, обследование при подозрении на слабую иммунную защиту слизистых, проверка перед трактовкой серологии на целиакию, иммунограмма', 'Häufige Atemwegs- und Darminfekte, Abklärung bei Verdacht auf eine schwache Schleimhautabwehr, Kontrolle vor der Beurteilung der Zöliakie-Serologie, Immunstatus', 'Sık solunum yolu ve bağırsak enfeksiyonları, mukoza bağışıklığının zayıflığı şüphesi, çölyak serolojisinin yorumlanmasından önce kontrol, bağışıklık paneli', 'No special preparation is required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Eine besondere Vorbereitung ist nicht nötig, das Blut wird meist morgens entnommen', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'A low level may be related to a congenital or acquired IgA deficiency and affects the interpretation of other tests based on this antibody class, a high level to chronic mucosal inflammation or liver disease. The result is assessed by a doctor together with IgG and IgM', 'Snižen nivo može biti povezan sa urođenim ili stečenim nedostatkom IgA i utiče na tumačenje drugih testova zasnovanih na ovoj klasi antitijela, povišen sa hroničnim zapaljenjem sluznica ili oboljenjem jetre. Rezultat procjenjuje ljekar zajedno sa IgG i IgM', 'Снижен ниво може бити повезан са урођеним или стеченим недостатком IgA и утиче на тумачење других тестова заснованих на овој класи антитијела, повишен са хроничним запаљењем слузница или обољењем јетре. Резултат процјењује љекар заједно са IgG и IgM', 'Снижение может быть связано с врождённым или приобретённым дефицитом IgA и влияет на трактовку других анализов, построенных на антителах этого класса, повышение — с хроническим воспалением слизистых или заболеванием печени. Результат оценивает врач вместе с IgG и IgM', 'Ein niedriger Wert kann mit einem angeborenen oder erworbenen IgA-Mangel zusammenhängen und beeinflusst die Beurteilung anderer Tests, die auf dieser Antikörperklasse beruhen, ein hoher Wert mit einer chronischen Schleimhautentzündung oder einer Lebererkrankung. Der Arzt beurteilt das Ergebnis zusammen mit IgG und IgM', 'Düşük değer doğuştan veya sonradan gelişen IgA eksikliğiyle ilişkili olabilir ve bu antikor sınıfına dayanan diğer testlerin yorumunu etkiler, yüksek değer ise kronik mukoza iltihabı veya karaciğer hastalığıyla ilişkili olabilir. Sonucu hekim IgG ve IgM ile birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'igg'), 'Blood test for class G immunoglobulin, the main antibodies of the blood that persist for a long time and provide lasting immunity', 'Analiza krvi na imunoglobulin klase G, glavna antitijela u krvi koja se dugo zadržavaju i obezbjeđuju dugotrajan imunitet', 'Анализа крви на имуноглобулин класе Г, главна антитијела у крви која се дуго задржавају и обезбјеђују дуготрајан имунитет', 'Анализ крови на иммуноглобулин класса G — основные антитела крови, которые сохраняются долго и обеспечивают длительный иммунитет', 'Bluttest auf Immunglobulin der Klasse G, die wichtigsten Antikörper im Blut, die lange bestehen bleiben und für den dauerhaften Immunschutz sorgen', 'Kanda uzun süre kalan ve kalıcı bağışıklığı sağlayan başlıca antikorlar olan G sınıfı immünoglobulin için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Recurrent and prolonged infections, evaluation for insufficient antibody production, monitoring during immunoglobulin replacement therapy, chronic inflammation and liver disease', 'Ponavljane i dugotrajne infekcije, ispitivanje pri sumnji na nedovoljno stvaranje antitijela, kontrola tokom nadoknadne terapije imunoglobulinima, hronično zapaljenje i oboljenja jetre', 'Понављане и дуготрајне инфекције, испитивање при сумњи на недовољно стварање антитијела, контрола током надокнадне терапије имуноглобулинима, хронично запаљење и обољења јетре', 'Повторяющиеся и затяжные инфекции, обследование при подозрении на недостаточную выработку антител, контроль на фоне заместительной терапии иммуноглобулинами, хроническое воспаление и заболевания печени', 'Wiederkehrende und langwierige Infekte, Abklärung bei Verdacht auf eine unzureichende Antikörperbildung, Verlaufskontrolle unter Immunglobulin-Substitution, chronische Entzündungen und Lebererkrankungen', 'Tekrarlayan ve uzayan enfeksiyonlar, yetersiz antikor üretimi şüphesi, immünoglobulin replasman tedavisi sırasında izlem, kronik iltihap ve karaciğer hastalıkları', 'No special preparation is required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Eine besondere Vorbereitung ist nicht nötig, das Blut wird meist morgens entnommen', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'A low level may be related to insufficient antibody production or to losses through the kidneys and gut, a high level to a long-standing inflammatory or infectious process. The level changes slowly, so a repeat test after months shows the doctor a steady trend rather than short-term fluctuation', 'Snižen nivo može biti povezan sa nedovoljnim stvaranjem antitijela ili njihovim gubitkom preko bubrega i crijeva, povišen sa dugotrajnim zapaljenjskim ili infektivnim procesom. Nivo se mijenja sporo, pa ponovljeno mjerenje poslije nekoliko mjeseci ljekaru pokazuje trajniju tendenciju, a ne trenutna kolebanja', 'Снижен ниво може бити повезан са недовољним стварањем антитијела или њиховим губитком преко бубрега и цријева, повишен са дуготрајним запаљењским или инфективним процесом. Ниво се мијења споро, па поновљено мјерење послије неколико мјесеци љекару показује трајнију тенденцију, а не тренутна колебања', 'Снижение может быть связано с недостаточной выработкой антител или их потерей через почки и кишечник, повышение — с длительным воспалительным или инфекционным процессом. Уровень меняется медленно, поэтому повторное измерение через месяцы показывает врачу устойчивую тенденцию, а не сиюминутные колебания', 'Ein niedriger Wert kann mit einer unzureichenden Antikörperbildung oder mit Verlusten über Nieren und Darm zusammenhängen, ein hoher Wert mit einem lang bestehenden Entzündungs- oder Infektionsprozess. Der Wert ändert sich langsam, daher zeigt eine Kontrolle nach Monaten dem Arzt eine dauerhafte Tendenz und keine kurzfristigen Schwankungen', 'Düşük değer antikor üretiminin yetersizliğiyle ya da böbrek ve bağırsak yoluyla kaybıyla, yüksek değer uzun süren iltihabi veya enfeksiyöz bir süreçle ilişkili olabilir. Değer yavaş değiştiğinden aylar sonra yapılan tekrar ölçüm hekime anlık dalgalanmayı değil kalıcı eğilimi gösterir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'igm'), 'Blood test for class M immunoglobulin, the antibodies the body produces first when it meets a pathogen anew', 'Analiza krvi na imunoglobulin klase M, antitijela koja organizam stvara prva pri novom susretu sa uzročnikom', 'Анализа крви на имуноглобулин класе М, антитијела која организам ствара прва при новом сусрету са узрочником', 'Анализ крови на иммуноглобулин класса M — антитела, которые организм вырабатывает первыми при новой встрече с возбудителем', 'Bluttest auf Immunglobulin der Klasse M, die Antikörper, die der Körper bei einem neuen Kontakt mit einem Erreger als Erste bildet', 'Vücudun bir etkenle yeni karşılaşmasında ilk olarak ürettiği antikorlar olan M sınıfı immünoglobulin için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Assessment of the early phase of the immune response, recurrent infections in children and adults, evaluation for impaired antibody maturation, immune panel together with IgA and IgG', 'Procjena rane faze imunog odgovora, ponavljane infekcije kod djece i odraslih, ispitivanje pri sumnji na poremećaj sazrijevanja antitijela, imunogram zajedno sa IgA i IgG', 'Процјена ране фазе имуног одговора, понављане инфекције код дјеце и одраслих, испитивање при сумњи на поремећај сазријевања антитијела, имунограм заједно са IgA и IgG', 'Оценка ранней фазы иммунного ответа, повторяющиеся инфекции у детей и взрослых, обследование при подозрении на нарушение созревания антител, иммунограмма вместе с IgA и IgG', 'Beurteilung der frühen Phase der Immunantwort, wiederkehrende Infekte bei Kindern und Erwachsenen, Abklärung bei Verdacht auf eine gestörte Antikörperreifung, Immunstatus zusammen mit IgA und IgG', 'Bağışıklık yanıtının erken evresinin değerlendirilmesi, çocuklarda ve erişkinlerde tekrarlayan enfeksiyonlar, antikor olgunlaşmasında bozukluk şüphesi, IgA ve IgG ile birlikte bağışıklık paneli', 'No special preparation is required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Eine besondere Vorbereitung ist nicht nötig, das Blut wird meist morgens entnommen', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'A high level may be related to a recent or ongoing infection, a low level to insufficient antibody production. A repeat test paired with IgG helps the doctor tell a fresh immune response from an older one', 'Povišen nivo može biti povezan sa skorašnjom ili aktuelnom infekcijom, snižen sa nedovoljnim stvaranjem antitijela. Ponovljeno mjerenje u paru sa IgG pomaže ljekaru da razlikuje svjež imuni odgovor od ranijeg', 'Повишен ниво може бити повезан са скорашњом или актуелном инфекцијом, снижен са недовољним стварањем антитијела. Поновљено мјерење у пару са IgG помаже љекару да разликује свјеж имуни одговор од ранијег', 'Повышение может быть связано с недавним или текущим инфекционным процессом, снижение — с недостаточной выработкой антител. Повторное измерение в паре с IgG помогает врачу отличить свежий иммунный ответ от давнего', 'Ein hoher Wert kann mit einer kürzlichen oder aktuellen Infektion zusammenhängen, ein niedriger mit einer unzureichenden Antikörperbildung. Eine Wiederholung zusammen mit IgG hilft dem Arzt, eine frische Immunantwort von einer länger zurückliegenden zu unterscheiden', 'Yüksek değer yakın zamandaki veya süregelen bir enfeksiyonla, düşük değer yetersiz antikor üretimiyle ilişkili olabilir. IgG ile birlikte yapılan tekrar ölçüm hekime yeni bir bağışıklık yanıtını eskisinden ayırt etmede yardımcı olur')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ige'), 'Blood test for total class E immunoglobulin, the antibodies involved in allergic reactions and in the response to parasites', 'Analiza krvi na ukupni imunoglobulin klase E, antitijela koja učestvuju u alergijskim reakcijama i u odgovoru na parazite', 'Анализа крви на укупни имуноглобулин класе Е, антитијела која учествују у алергијским реакцијама и у одговору на паразите', 'Анализ крови на общий иммуноглобулин класса E — антитела, участвующие в аллергических реакциях и в ответе на паразитов', 'Bluttest auf Gesamt-Immunglobulin der Klasse E, die Antikörper, die an allergischen Reaktionen und an der Abwehr von Parasiten beteiligt sind', 'Alerjik reaksiyonlarda ve parazitlere karşı yanıtta rol alan antikorlar olan total E sınıfı immünoglobulin için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Suspected allergy, atopic dermatitis, bronchial asthma, urticaria, year-round or seasonal rhinitis, work-up before choosing allergy tests, suspected parasitic infestation', 'Sumnja na alergiju, atopijski dermatitis, astma, koprivnjača, cjelogodišnja ili sezonska kijavica, priprema za izbor alergoloških testova, sumnja na parazitarnu infekciju', 'Сумња на алергију, атопијски дерматитис, астма, копривњача, цјелогодишња или сезонска кијавица, припрема за избор алерголошких тестова, сумња на паразитарну инфекцију', 'Подозрение на аллергию, атопический дерматит, бронхиальная астма, крапивница, круглогодичный или сезонный насморк, обследование перед подбором аллергологических тестов, подозрение на паразитарную инвазию', 'Verdacht auf eine Allergie, Neurodermitis, Asthma bronchiale, Nesselsucht, ganzjähriger oder saisonaler Schnupfen, Abklärung vor der Auswahl von Allergietests, Verdacht auf Parasitenbefall', 'Alerji şüphesi, atopik dermatit, bronş astımı, ürtiker, yıl boyu süren veya mevsimsel nezle, alerji testlerinin seçiminden önce değerlendirme, parazit şüphesi', 'No special preparation is required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Eine besondere Vorbereitung ist nicht nötig', 'Özel bir hazırlık gerekmez', 'A raised total IgE may be related to an allergic predisposition or to a parasitic infestation, but it does not show which allergen the person reacts to, which requires specific IgE tests or skin tests. An allergist assesses the result together with the symptoms', 'Povišen ukupni IgE može biti povezan sa alergijskom sklonošću organizma ili sa parazitarnom infekcijom, ali ne pokazuje na koji tačno alergen osoba reaguje, za to su potrebni specifični IgE ili kožni testovi. Rezultat zajedno sa tegobama procjenjuje alergolog', 'Повишен укупни IgE може бити повезан са алергијском склоношћу организма или са паразитарном инфекцијом, али не показује на који тачно алерген особа реагује, за то су потребни специфични IgE или кожни тестови. Резултат заједно са тегобама процјењује алерголог', 'Повышение общего IgE может быть связано с аллергической настроенностью организма или с паразитарной инвазией, но не показывает, на какой именно аллерген реагирует человек, для этого нужны специфические IgE или кожные пробы. Результат вместе с жалобами оценивает аллерголог', 'Ein erhöhtes Gesamt-IgE kann mit einer allergischen Veranlagung oder mit einem Parasitenbefall zusammenhängen, zeigt aber nicht, auf welches Allergen der Körper reagiert, dafür sind spezifische IgE-Tests oder Hauttests nötig. Der Allergologe beurteilt das Ergebnis zusammen mit den Beschwerden', 'Yüksek total IgE alerjik yatkınlıkla veya parazit enfeksiyonuyla ilişkili olabilir, ancak kişinin hangi alerjene tepki verdiğini göstermez, bunun için spesifik IgE veya deri testleri gerekir. Sonucu şikayetlerle birlikte alerji uzmanı değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'c3-complement'), 'Blood test for the complement protein C3, a part of innate immunity that is consumed during active inflammation', 'Analiza krvi na protein sistema komplementa C3, dio urođenog imuniteta koji se troši tokom aktivnog zapaljenja', 'Анализа крви на протеин система комплемента Ц3, дио урођеног имунитета који се троши током активног запаљења', 'Анализ крови на белок системы комплемента C3 — часть врождённого иммунитета, которая расходуется при активном воспалении', 'Bluttest auf das Komplementprotein C3, einen Teil der angeborenen Immunabwehr, der bei aktiver Entzündung verbraucht wird', 'Aktif iltihap sırasında tüketilen ve doğuştan gelen bağışıklığın bir parçası olan kompleman proteini C3 için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Work-up of autoimmune diseases, kidney disease with abnormal urine findings, recurrent bacterial infections, following the activity of a known autoimmune process', 'Ispitivanje autoimunih bolesti, bubrežna oboljenja sa promjenama u mokraći, ponavljane bakterijske infekcije, praćenje aktivnosti poznatog autoimunog procesa', 'Испитивање аутоимуних болести, бубрежна обољења са промјенама у мокраћи, понављане бактеријске инфекције, праћење активности познатог аутоимуног процеса', 'Обследование при аутоиммунных заболеваниях, болезни почек с изменениями в моче, повторяющиеся бактериальные инфекции, наблюдение за активностью известного аутоиммунного процесса', 'Abklärung von Autoimmunerkrankungen, Nierenerkrankungen mit auffälligem Urinbefund, wiederkehrende bakterielle Infekte, Verlaufskontrolle der Aktivität eines bekannten Autoimmunprozesses', 'Otoimmün hastalıkların değerlendirilmesi, idrar bulguları bozuk olan böbrek hastalıkları, tekrarlayan bakteriyel enfeksiyonlar, bilinen bir otoimmün sürecin etkinliğinin izlenmesi', 'No special preparation is required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Eine besondere Vorbereitung ist nicht nötig', 'Özel bir hazırlık gerekmez', 'A low level may be related to active consumption of complement in an autoimmune or kidney process, a high level to acute inflammation, since C3 is also an acute-phase protein. Doctors use repeat measurements to follow how active the process is over time', 'Snižen nivo može biti povezan sa pojačanim trošenjem komplementa u autoimunom ili bubrežnom procesu, povišen sa akutnim zapaljenjem, jer je C3 i protein akutne faze. Ponovljena mjerenja ljekar koristi da prati koliko je proces aktivan tokom vremena', 'Снижен ниво може бити повезан са појачаним трошењем комплемента у аутоимуном или бубрежном процесу, повишен са акутним запаљењем, јер је Ц3 и протеин акутне фазе. Поновљена мјерења љекар користи да прати колико је процес активан током времена', 'Снижение может быть связано с активным расходом комплемента при аутоиммунном или почечном процессе, повышение — с острым воспалением, так как C3 ещё и белок острой фазы. Повторные измерения врач использует, чтобы следить за активностью процесса в динамике', 'Ein niedriger Wert kann mit einem verstärkten Verbrauch des Komplements bei einem Autoimmun- oder Nierenprozess zusammenhängen, ein hoher Wert mit einer akuten Entzündung, da C3 auch ein Akute-Phase-Protein ist. Wiederholte Messungen nutzt der Arzt, um die Aktivität des Prozesses im Verlauf zu verfolgen', 'Düşük değer otoimmün veya böbrek kaynaklı bir süreçte komplemanın artan tüketimiyle, yüksek değer ise C3 aynı zamanda bir akut faz proteini olduğundan akut iltihapla ilişkili olabilir. Hekim tekrarlanan ölçümleri sürecin ne kadar etkin olduğunu zaman içinde izlemek için kullanır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'c4-complement'), 'Blood test for the complement protein C4, a component of the classical activation pathway', 'Analiza krvi na protein sistema komplementa C4, sastavni dio njegovog klasičnog puta aktivacije', 'Анализа крви на протеин система комплемента Ц4, саставни дио његовог класичног пута активације', 'Анализ крови на белок системы комплемента C4 — компонент её классического пути активации', 'Bluttest auf das Komplementprotein C4, einen Bestandteil des klassischen Aktivierungswegs', 'Kompleman sisteminin klasik aktivasyon yolunun bir bileşeni olan C4 proteini için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Recurrent swellings without hives, work-up of autoimmune diseases and vasculitis, addition to the C3 result', 'Ponavljani otoci bez koprivnjače, ispitivanje autoimunih bolesti i vaskulitisa, dopuna nalazu C3', 'Понављани отоци без копривњаче, испитивање аутоимуних болести и васкулитиса, допуна налазу Ц3', 'Повторяющиеся отёки без крапивницы, обследование при аутоиммунных заболеваниях и васкулитах, дополнение к результату C3', 'Wiederkehrende Schwellungen ohne Quaddeln, Abklärung von Autoimmunerkrankungen und Vaskulitiden, Ergänzung zum C3-Befund', 'Kurdeşen olmadan tekrarlayan şişlikler, otoimmün hastalıkların ve vaskülitlerin değerlendirilmesi, C3 sonucunun tamamlanması', 'No special preparation is required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Eine besondere Vorbereitung ist nicht nötig', 'Özel bir hazırlık gerekmez', 'A persistently low level may be related to an inherited deficiency of this protein or to activation of the classical complement pathway in an autoimmune process. Comparing C4 with C3 helps the doctor see which activation pathway is involved', 'Trajno snižen nivo može biti povezan sa nasljednim nedostatkom ovog proteina ili sa aktivacijom klasičnog puta komplementa u autoimunom procesu. Poređenje C4 sa C3 pomaže ljekaru da sagleda koji je put aktivacije uključen', 'Трајно снижен ниво може бити повезан са насљедним недостатком овог протеина или са активацијом класичног пута комплемента у аутоимуном процесу. Поређење Ц4 са Ц3 помаже љекару да сагледа који је пут активације укључен', 'Стойко низкий уровень может быть связан с наследственным недостатком этого белка или с активацией классического пути комплемента при аутоиммунном процессе. Сопоставление C4 с C3 помогает врачу понять, какой путь активации задействован', 'Ein dauerhaft niedriger Wert kann mit einem erblichen Mangel dieses Proteins oder mit der Aktivierung des klassischen Komplementwegs bei einem Autoimmunprozess zusammenhängen. Der Vergleich von C4 mit C3 hilft dem Arzt zu erkennen, welcher Aktivierungsweg beteiligt ist', 'Sürekli düşük değer bu proteinin kalıtsal eksikliğiyle veya otoimmün süreçte klasik kompleman yolunun etkinleşmesiyle ilişkili olabilir. C4 değerinin C3 ile karşılaştırılması hekime hangi aktivasyon yolunun devrede olduğunu görmede yardımcı olur')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'spermatozoa-antibodies-asa'), 'Test for antisperm antibodies (ASA), an immune factor that can interfere with fertilisation', 'Ispitivanje antitijela na spermatozoide (ASA), imunog faktora koji može ometati oplodnju', 'Испитивање антитијела на сперматозоиде (ASA), имуног фактора који може ометати оплодњу', 'Анализ на антитела к сперматозоидам (ASA) — иммунный фактор, который может мешать оплодотворению', 'Untersuchung auf Spermien-Antikörper (ASA), einen Immunfaktor, der die Befruchtung stören kann', 'Döllenmeyi engelleyebilen bir bağışıklık etkeni olan sperm antikorları (ASA) incelemesi', 'Examination of venous blood or of a semen sample, collection takes a few minutes', 'Analiza venske krvi ili uzorka sjemena, uzimanje traje nekoliko minuta', 'Анализа венске крви или узорка сјемена, узимање траје неколико минута', 'Исследование венозной крови или образца спермы, забор занимает несколько минут', 'Untersuchung von venösem Blut oder einer Samenprobe, die Gewinnung dauert wenige Minuten', 'Damardan alınan kanın veya semen örneğinin incelenmesi, örnek alımı birkaç dakika sürer', 'Work-up of a couple with difficulty conceiving, clumping of sperm on a semen analysis, past testicular injury or inflammation, surgery on the genital tract including vasectomy', 'Ispitivanje para kod otežanog začeća, slijepljivanje spermatozoida u spermogramu, ranija povreda ili zapaljenje testisa, operacije na polnim putevima uključujući vazektomiju', 'Испитивање пара код отежаног зачећа, слијепљивање сперматозоида у спермограму, ранија повреда или запаљење тестиса, операције на полним путевима укључујући вазектомију', 'Обследование пары при трудностях с зачатием, склеивание сперматозоидов в спермограмме, перенесённая травма или воспаление яичка, операции на половых путях, включая вазэктомию', 'Abklärung bei einem Paar mit unerfülltem Kinderwunsch, Verklumpung der Spermien im Spermiogramm, frühere Hodenverletzung oder Hodenentzündung, Operationen am Genitaltrakt einschließlich Vasektomie', 'Gebe kalmakta güçlük çeken çiftlerin değerlendirilmesi, spermiyogramda spermlerin kümeleşmesi, geçirilmiş testis travması veya iltihabı, vazektomi dahil genital yol ameliyatları', 'For a semen sample, sexual abstinence of 2 to 7 days, the blood test needs no preparation', 'Za uzorak sjemena potrebna je polna apstinencija od 2 do 7 dana, za analizu krvi priprema nije potrebna', 'За узорак сјемена потребна је полна апстиненција од 2 до 7 дана, за анализу крви припрема није потребна', 'Для образца спермы половое воздержание от 2 до 7 дней, для анализа крови подготовка не нужна', 'Für die Samenprobe sexuelle Karenz von 2 bis 7 Tagen, für die Blutentnahme ist keine Vorbereitung nötig', 'Semen örneği için 2 ila 7 gün cinsel perhiz gerekir, kan testi için hazırlık gerekmez', 'Finding such antibodies may be related to an immune factor in reduced fertility and is considered only together with the semen analysis and the assessment of both partners. Further steps are decided by a urologist or a fertility specialist', 'Nalaz ovih antitijela može biti povezan sa imunim faktorom smanjene plodnosti i razmatra se samo zajedno sa spermogramom i pregledom oba partnera. Dalji postupak određuje urolog ili specijalista za reprodukciju', 'Налаз ових антитијела може бити повезан са имуним фактором смањене плодности и разматра се само заједно са спермограмом и прегледом оба партнера. Даљи поступак одређује уролог или специјалиста за репродукцију', 'Обнаружение таких антител может быть связано с иммунным фактором снижения фертильности и рассматривается только вместе со спермограммой и обследованием обоих партнёров. Дальнейшую тактику определяет уролог или врач-репродуктолог', 'Der Nachweis solcher Antikörper kann mit einem immunologischen Faktor einer verminderten Fruchtbarkeit zusammenhängen und wird nur zusammen mit dem Spermiogramm und der Untersuchung beider Partner bewertet. Das weitere Vorgehen legt der Urologe oder der Reproduktionsmediziner fest', 'Bu antikorların saptanması doğurganlığın azalmasında bağışıklık etkeniyle ilişkili olabilir ve yalnızca spermiyogram ve her iki eşin değerlendirilmesiyle birlikte ele alınır. Sonraki adımları üroloji uzmanı veya üreme sağlığı uzmanı belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'hcv-total-antibodies'), 'Screening blood test for total antibodies to the hepatitis C virus, classes IgM and IgG together', 'Skrining analiza krvi na ukupna antitijela na virus hepatitisa C, klase IgM i IgG zajedno', 'Скрининг анализа крви на укупна антитијела на вирус хепатитиса Ц, класе IgM и IgG заједно', 'Скрининговый анализ крови на суммарные антитела к вирусу гепатита C — классов IgM и IgG вместе', 'Screening-Bluttest auf Gesamt-Antikörper gegen das Hepatitis-C-Virus, Klassen IgM und IgG zusammen', 'Hepatit C virüsüne karşı IgM ve IgG sınıflarının birlikte ölçüldüğü total antikorlar için tarama kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Preventive screening, preparation for surgery, blood donation, pregnancy, evaluation of altered liver values, at personal request', 'Preventivni skrining, priprema za operaciju, davanje krvi, trudnoća, ispitivanje kod izmijenjenih nalaza jetre, na lični zahtjev', 'Превентивни скрининг, припрема за операцију, давање крви, трудноћа, испитивање код измијењених налаза јетре, на лични захтјев', 'Профилактический скрининг, подготовка к операции, донорство крови, беременность, обследование при изменённых печёночных показателях, по личному желанию', 'Vorsorgescreening, Vorbereitung auf eine Operation, Blutspende, Schwangerschaft, Abklärung bei veränderten Leberwerten, auf eigenen Wunsch', 'Koruyucu tarama, ameliyat öncesi hazırlık, kan bağışı, gebelik, karaciğer değerlerinde değişiklik olduğunda değerlendirme, kişisel istek üzerine', 'No special preparation is required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Eine besondere Vorbereitung ist nicht nötig', 'Özel bir hazırlık gerekmez', 'A positive result indicates contact with the virus now or in the past and by itself does not distinguish between the two, so a confirmatory test for viral RNA is ordered. Further steps are decided by a doctor', 'Pozitivan nalaz govori o kontaktu sa virusom sada ili ranije i sam po sebi ne razlikuje te situacije, zbog čega se radi potvrdni test na RNK virusa. Dalje korake određuje ljekar', 'Позитиван налаз говори о контакту са вирусом сада или раније и сам по себи не разликује те ситуације, због чега се ради потврдни тест на РНК вируса. Даље кораке одређује љекар', 'Положительный результат говорит о контакте с вирусом сейчас или в прошлом и сам по себе эти ситуации не различает, для уточнения назначают подтверждающий тест на РНК вируса. Дальнейшие шаги определяет врач', 'Ein positives Ergebnis spricht für einen Kontakt mit dem Virus jetzt oder in der Vergangenheit und unterscheidet diese beiden Situationen für sich allein nicht, zur Klärung wird ein Bestätigungstest auf die Virus-RNA durchgeführt. Das weitere Vorgehen legt der Arzt fest', 'Pozitif sonuç virüsle şu anda veya geçmişte temas olduğunu gösterir ve tek başına bu iki durumu ayırt etmez, netleştirmek için virüs RNA''sını arayan doğrulayıcı test yapılır. Sonraki adımları hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'bleeding-time'), 'A simple test showing how long it takes for bleeding from a small skin puncture to stop', 'Jednostavna proba koja pokazuje za koliko se zaustavlja krvarenje iz malog uboda kože', 'Једноставна проба која показује за колико се зауставља крварење из малог убода коже', 'Простая проба, показывающая, за какое время останавливается кровотечение из небольшого прокола кожи', 'Ein einfacher Test, der zeigt, wie lange die Blutung aus einem kleinen Hautstich bis zum Stillstand braucht', 'Küçük bir cilt deliğinden gelen kanamanın ne kadar sürede durduğunu gösteren basit bir test', 'A nurse makes a small puncture on the finger or forearm and times the moment the bleeding stops, taking a few minutes', 'Medicinska sestra napravi mali ubod na prstu ili podlaktici i štopericom bilježi trenutak prestanka krvarenja, traje nekoliko minuta', 'Медицинска сестра направи мали убод на прсту или подлактици и штоперицом биљежи тренутак престанка крварења, траје неколико минута', 'Медсестра делает небольшой прокол кожи пальца или предплечья и с секундомером отмечает момент остановки кровотечения, занимает несколько минут', 'Eine Pflegekraft setzt einen kleinen Stich an Finger oder Unterarm und stoppt die Zeit bis zum Ende der Blutung, dauert wenige Minuten', 'Hemşire parmakta veya ön kolda küçük bir delik açar ve kanamanın durduğu anı kronometreyle kaydeder, birkaç dakika sürer', 'Work-up before minor procedures, tendency to bruising and bleeding gums, assessment of primary hemostasis', 'Obrada prije manjih zahvata, sklonost modricama i krvarenju desni, procjena primarne hemostaze', 'Обрада прије мањих захвата, склоност модрицама и крварењу десни, процјена примарне хемостазе', 'Обследование перед небольшими вмешательствами, склонность к синякам и кровоточивости дёсен, оценка первичного гемостаза', 'Abklärung vor kleineren Eingriffen, Neigung zu blauen Flecken und Zahnfleischbluten, Beurteilung der primären Hämostase', 'Küçük girişimler öncesi inceleme, kolay morarma ve diş eti kanaması, birincil hemostazın değerlendirilmesi', 'No special preparation required; inform the doctor and the laboratory in advance about anticoagulants, aspirin and other medications affecting clotting, as only the doctor decides whether to pause them', 'Nije potrebna posebna priprema; o antikoagulansima, aspirinu i drugim lijekovima koji utiču na zgrušavanje unaprijed obavijestite ljekara i laboratoriju, a odluku o pauzi u terapiji donosi isključivo ljekar', 'Није потребна посебна припрема; о антикоагулансима, аспирину и другим лијековима који утичу на згрушавање унапријед обавијестите љекара и лабораторију, а одлуку о паузи у терапији доноси искључиво љекар', 'Специальной подготовки не требуется; о приёме антикоагулянтов, аспирина и других влияющих на свёртывание препаратов заранее сообщите врачу и лаборатории, решение о паузе в приёме принимает только врач', 'Keine besondere Vorbereitung erforderlich; informieren Sie Arzt und Labor vorab über Antikoagulanzien, Aspirin und andere gerinnungswirksame Medikamente, über ein Pausieren entscheidet ausschließlich der Arzt', 'Özel bir hazırlık gerektirmez; antikoagülan, aspirin ve pıhtılaşmayı etkileyen diğer ilaçlar hakkında hekimi ve laboratuvarı önceden bilgilendirin, bunlara ara verilip verilmeyeceğine yalnızca hekim karar verir', 'A prolonged time may be related to platelet function, medication use, or the condition of the vessel wall. The meaning of the result is assessed by a doctor together with other clotting values', 'Produženo vrijeme može biti povezano sa radom trombocita, uzimanjem lijekova ili stanjem zida krvnih sudova. Značaj nalaza procjenjuje ljekar zajedno sa ostalim pokazateljima zgrušavanja', 'Продужено вријеме може бити повезано са радом тромбоцита, узимањем лијекова или стањем зида крвних судова. Значај налаза процјењује љекар заједно са осталим показатељима згрушавања', 'Удлинение времени может быть связано с особенностями работы тромбоцитов, приёмом препаратов или состоянием сосудистой стенки. Значение результата оценивает врач вместе с другими показателями свёртывания', 'Eine verlängerte Zeit kann mit der Funktion der Blutplättchen, der Einnahme von Medikamenten oder dem Zustand der Gefäßwand zusammenhängen. Die Bedeutung des Ergebnisses beurteilt der Arzt zusammen mit weiteren Gerinnungswerten', 'Sürenin uzaması trombositlerin işleyişi, ilaç kullanımı veya damar duvarının durumuyla ilişkili olabilir. Sonucun anlamını hekim diğer pıhtılaşma göstergeleriyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'coagulation-time'), 'A basic test assessing how long a drawn blood sample takes to form a clot in a tube', 'Osnovna proba koja procjenjuje za koliko uzeta krv stvori ugrušak u epruveti', 'Основна проба која процјењује за колико узета крв створи угрушак у епрувети', 'Базовая проба, оценивающая, за какое время взятая кровь образует сгусток в пробирке', 'Ein grundlegender Test, der beurteilt, wie lange eine entnommene Blutprobe im Röhrchen bis zur Gerinnselbildung braucht', 'Alınan kanın tüp içinde ne kadar sürede pıhtı oluşturduğunu değerlendiren temel bir test', 'Blood is drawn and the formation of a clot in the tube is observed at a controlled temperature, taking a few minutes', 'Uzima se krv i prati se stvaranje ugruška u epruveti na kontrolisanoj temperaturi, traje nekoliko minuta', 'Узима се крв и прати се стварање угрушка у епрувети на контролисаној температури, траје неколико минута', 'Забор крови и наблюдение за образованием сгустка в пробирке при контролируемой температуре, занимает несколько минут', 'Es wird Blut entnommen und die Gerinnselbildung im Röhrchen bei kontrollierter Temperatur beobachtet, dauert wenige Minuten', 'Kan alınır ve kontrollü sıcaklıkta tüpte pıhtı oluşumu izlenir, birkaç dakika sürer', 'Rough assessment of clotting before procedures, work-up for bleeding tendency, supplement to other coagulation tests', 'Okvirna procjena zgrušavanja prije zahvata, obrada kod sklonosti krvarenju, dopuna drugim koagulacionim testovima', 'Оквирна процјена згрушавања прије захвата, обрада код склоности крварењу, допуна другим коагулационим тестовима', 'Ориентировочная оценка свёртывания перед вмешательствами, обследование при кровоточивости, дополнение к другим коагуляционным тестам', 'Grobe Einschätzung der Gerinnung vor Eingriffen, Abklärung bei Blutungsneigung, Ergänzung zu anderen Gerinnungstests', 'Girişim öncesi pıhtılaşmanın kaba değerlendirmesi, kanamaya eğilimde inceleme, diğer koagülasyon testlerinin tamamlayıcısı', 'No special preparation required; tell the doctor and the laboratory about anticoagulants and other medications affecting clotting, and do not stop them on your own', 'Nije potrebna posebna priprema; o antikoagulansima i drugim lijekovima koji utiču na zgrušavanje obavijestite ljekara i laboratoriju, njihovo prekidanje na svoju ruku nije dozvoljeno', 'Није потребна посебна припрема; о антикоагулансима и другим лијековима који утичу на згрушавање обавијестите љекара и лабораторију, њихово прекидање на своју руку није дозвољено', 'Специальной подготовки не требуется; о приёме антикоагулянтов и других влияющих на свёртывание препаратов предупредите врача и лабораторию, самостоятельно отменять их нельзя', 'Keine besondere Vorbereitung erforderlich; informieren Sie Arzt und Labor über Antikoagulanzien und andere gerinnungswirksame Medikamente und setzen Sie diese nicht eigenmächtig ab', 'Özel bir hazırlık gerektirmez; antikoagülanlar ve pıhtılaşmayı etkileyen diğer ilaçlar hakkında hekimi ve laboratuvarı bilgilendirin, bu ilaçları kendi başınıza bırakmayın', 'Deviations may be related to medication use, a lack of clotting factors, or the conditions of sample collection. The result is interpreted by a doctor, usually together with more precise tests', 'Odstupanja mogu biti povezana sa uzimanjem lijekova, nedostatkom faktora zgrušavanja ili uslovima uzimanja uzorka. Nalaz tumači ljekar, obično uz preciznije testove', 'Одступања могу бити повезана са узимањем лијекова, недостатком фактора згрушавања или условима узимања узорка. Налаз тумачи љекар, обично уз прецизније тестове', 'Отклонения могут быть связаны с приёмом препаратов, недостатком факторов свёртывания или условиями забора материала. Результат трактует врач, обычно вместе с более точными тестами', 'Abweichungen können mit der Einnahme von Medikamenten, einem Mangel an Gerinnungsfaktoren oder den Bedingungen der Probenentnahme zusammenhängen. Das Ergebnis interpretiert der Arzt, meist zusammen mit genaueren Tests', 'Sapmalar ilaç kullanımı, pıhtılaşma faktörlerinin eksikliği veya örnek alma koşullarıyla ilişkili olabilir. Sonucu hekim, genellikle daha kesin testlerle birlikte yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'antithrombin-iii'), 'A blood test for a natural protein that restrains excessive clotting', 'Analiza krvi na prirodni protein koji sprječava pretjerano zgrušavanje', 'Анализа крви на природни протеин који спрјечава претјерано згрушавање', 'Анализ крови на естественный белок, сдерживающий избыточное свёртывание', 'Bluttest auf ein körpereigenes Eiweiß, das eine übermäßige Gerinnung bremst', 'Aşırı pıhtılaşmayı frenleyen doğal bir proteini ölçen kan testi', 'Venous blood draw into a citrate tube', 'Uzimanje venske krvi u epruvetu sa citratom', 'Узимање венске крви у епрувету са цитратом', 'Забор венозной крови в пробирку с цитратом', 'Entnahme von venösem Blut in ein Citratröhrchen', 'Sitratlı tüpe venöz kan alımı', 'Work-up for recurrent thrombosis, thrombosis at a young age, family tendency to thrombosis, pregnancy planning as directed by a doctor', 'Obrada kod ponovljenih tromboza, tromboze u mlađem životnom dobu, porodične sklonosti trombozama, planiranje trudnoće po uputu ljekara', 'Обрада код поновљених тромбоза, тромбозе у млађем животном добу, породичне склоности тромбозама, планирање трудноће по упуту љекара', 'Обследование при повторных тромбозах, тромбозе в молодом возрасте, семейной склонности к тромбозам, планирование беременности по назначению врача', 'Abklärung bei wiederholten Thrombosen, Thrombose in jungen Jahren, familiärer Thromboseneigung, Schwangerschaftsplanung auf ärztliche Anweisung', 'Tekrarlayan tromboz, genç yaşta tromboz, ailede tromboz eğilimi, hekim yönlendirmesiyle gebelik planlaması', 'The sample is taken outside an acute thrombosis episode; heparin, warfarin and other anticoagulants must be reported to the doctor and the laboratory, and only the doctor decides on any pause in treatment', 'Uzorak se uzima van akutne epizode tromboze; o heparinu, varfarinu i drugim antikoagulansima obavezno se obavještavaju ljekar i laboratorija, a o pauzi u terapiji odlučuje ljekar', 'Узорак се узима ван акутне епизоде тромбозе; о хепарину, варфарину и другим антикоагулансима обавезно се обавјештавају љекар и лабораторија, а о паузи у терапији одлучује љекар', 'Кровь сдают вне острого эпизода тромбоза; о приёме гепарина, варфарина и других антикоагулянтов обязательно сообщают врачу и лаборатории, а решение о паузе в лечении принимает врач', 'Die Probe wird außerhalb eines akuten Thromboseereignisses entnommen; Heparin, Warfarin und andere Antikoagulanzien sind Arzt und Labor mitzuteilen, über eine Pause der Behandlung entscheidet allein der Arzt', 'Örnek akut tromboz dönemi dışında alınır; heparin, varfarin ve diğer antikoagülanlar hekime ve laboratuvara mutlaka bildirilir, tedaviye ara verilip verilmeyeceğine yalnızca hekim karar verir', 'A reduced value may be related to inherited features, liver disease, protein loss, or the influence of medications. The result is assessed by a doctor, usually as part of a thrombophilia panel', 'Sniženje vrijednosti može biti povezano sa nasljednim osobinama, oboljenjima jetre, gubitkom bjelančevina ili uticajem lijekova. Nalaz procjenjuje ljekar, obično u sklopu panela za trombofiliju', 'Снижење вриједности може бити повезано са насљедним особинама, обољењима јетре, губитком бјеланчевина или утицајем лијекова. Налаз процјењује љекар, обично у склопу панела за тромбофилију', 'Снижение показателя может быть связано с наследственными особенностями, болезнями печени, потерей белка или влиянием лекарств. Результат оценивает врач, обычно в составе панели на тромбофилию', 'Ein erniedrigter Wert kann mit erblichen Besonderheiten, Lebererkrankungen, Eiweißverlust oder dem Einfluss von Medikamenten zusammenhängen. Das Ergebnis beurteilt der Arzt, meist im Rahmen einer Thrombophilie-Abklärung', 'Değerin düşük olması kalıtsal özellikler, karaciğer hastalıkları, protein kaybı veya ilaç etkisiyle ilişkili olabilir. Sonucu hekim, genellikle trombofili paneli kapsamında değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'lupus-anticoagulant'), 'A blood test for antibodies that interfere with phospholipid-dependent clotting reactions in the tube', 'Ispitivanje krvi na antitijela koja ometaju fosfolipid-zavisne reakcije zgrušavanja u epruveti', 'Испитивање крви на антитијела која ометају фосфолипид-зависне реакције згрушавања у епрувети', 'Исследование крови на антитела, влияющие на фосфолипид-зависимые реакции свёртывания в пробирке', 'Blutuntersuchung auf Antikörper, die phospholipidabhängige Gerinnungsreaktionen im Reagenzglas stören', 'Tüp içinde fosfolipide bağlı pıhtılaşma tepkimelerini bozan antikorları araştıran kan tetkiki', 'Venous blood draw; the test is performed as a set of coagulation assays, and a positive result is usually repeated after some time', 'Uzimanje venske krvi, ispitivanje se radi setom koagulacionih testova, a pozitivan nalaz se obično ponavlja nakon izvjesnog vremena', 'Узимање венске крви, испитивање се ради сетом коагулационих тестова, а позитиван налаз се обично понавља након извјесног времена', 'Забор венозной крови, исследование выполняется набором коагуляционных тестов, положительный результат обычно повторяют спустя некоторое время', 'Entnahme von venösem Blut; die Untersuchung besteht aus mehreren Gerinnungstests, ein positiver Befund wird in der Regel nach einiger Zeit wiederholt', 'Venöz kan alınır, inceleme bir dizi koagülasyon testiyle yapılır ve pozitif sonuç genellikle bir süre sonra yinelenir', 'Work-up for thrombosis, recurrent pregnancy loss, autoimmune diseases as directed by a doctor, unexplained prolongation of clotting tests', 'Obrada kod tromboza, ponovljenih gubitaka trudnoće, autoimunih oboljenja po uputu ljekara, neobjašnjenog produženja koagulacionih testova', 'Обрада код тромбоза, поновљених губитака трудноће, аутоимуних обољења по упуту љекара, необјашњеног продужења коагулационих тестова', 'Обследование при тромбозах, повторных потерях беременности, аутоиммунных заболеваниях по назначению врача, необъяснимом удлинении коагуляционных тестов', 'Abklärung bei Thrombosen, wiederholten Fehlgeburten, Autoimmunerkrankungen auf ärztliche Anweisung, ungeklärter Verlängerung von Gerinnungstests', 'Tromboz, yinelenen gebelik kayıpları, hekim yönlendirmesiyle otoimmün hastalıklar, koagülasyon testlerinde açıklanamayan uzama', 'No special preparation required; anticoagulants and heparin affect the result, so they are reported to the doctor and the laboratory in advance, and the doctor decides on the timing of the test', 'Nije potrebna posebna priprema; antikoagulansi i heparin utiču na nalaz, pa se o njima unaprijed obavještavaju ljekar i laboratorija, a termin vađenja određuje ljekar', 'Није потребна посебна припрема; антикоагуланси и хепарин утичу на налаз, па се о њима унапријед обавјештавају љекар и лабораторија, а термин вађења одређује љекар', 'Специальной подготовки не требуется; антикоагулянты и гепарин влияют на результат, поэтому о них заранее сообщают врачу и лаборатории, а срок сдачи определяет врач', 'Keine besondere Vorbereitung erforderlich; Antikoagulanzien und Heparin beeinflussen den Befund und werden Arzt und Labor vorab mitgeteilt, den Zeitpunkt der Blutentnahme legt der Arzt fest', 'Özel bir hazırlık gerektirmez; antikoagülanlar ve heparin sonucu etkiler, bu nedenle hekime ve laboratuvara önceden bildirilir, kan alma zamanını hekim belirler', 'A positive result may be related to antiphospholipid antibodies, a recent infection, or the influence of medications, and is not a diagnosis in itself. Confirmation requires repeat testing and assessment by a doctor', 'Pozitivan nalaz može biti povezan sa antifosfolipidnim antitijelima, nedavnom infekcijom ili uticajem lijekova i sam po sebi nije dijagnoza. Potvrda zahtijeva ponovljeno ispitivanje i procjenu ljekara', 'Позитиван налаз може бити повезан са антифосфолипидним антитијелима, недавном инфекцијом или утицајем лијекова и сам по себи није дијагноза. Потврда захтијева поновљено испитивање и процјену љекара', 'Положительный результат может быть связан с антифосфолипидными антителами, недавней инфекцией или влиянием лекарств и сам по себе не является диагнозом. Подтверждение требует повторного исследования и оценки врача', 'Ein positiver Befund kann mit Antiphospholipid-Antikörpern, einer kürzlichen Infektion oder dem Einfluss von Medikamenten zusammenhängen und ist für sich genommen keine Diagnose. Die Bestätigung erfordert eine Wiederholung und die Beurteilung durch den Arzt', 'Pozitif sonuç antifosfolipid antikorlarıyla, yakın zamanda geçirilen bir enfeksiyonla veya ilaç etkisiyle ilişkili olabilir ve tek başına tanı değildir. Doğrulama için testin yinelenmesi ve hekim değerlendirmesi gerekir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protein-c'), 'A blood test for one of the natural regulatory proteins of clotting produced by the liver', 'Analiza krvi na jedan od prirodnih proteina regulatora zgrušavanja koje stvara jetra', 'Анализа крви на један од природних протеина регулатора згрушавања које ствара јетра', 'Анализ крови на один из естественных белков-регуляторов свёртывания, вырабатываемых печенью', 'Bluttest auf eines der natürlichen, in der Leber gebildeten Regulatorproteine der Gerinnung', 'Karaciğerde üretilen ve pıhtılaşmayı düzenleyen doğal proteinlerden birini ölçen kan testi', 'Venous blood draw into a citrate tube', 'Uzimanje venske krvi u citratnu epruvetu', 'Узимање венске крви у цитратну епрувету', 'Забор венозной крови в цитратную пробирку', 'Entnahme von venösem Blut in ein Citratröhrchen', 'Sitratlı tüpe venöz kan alımı', 'Work-up for venous thrombosis, family tendency to thrombosis, treatment planning as directed by a doctor', 'Obrada kod venskih tromboza, porodične sklonosti trombozama, planiranje terapije po uputu ljekara', 'Обрада код венских тромбоза, породичне склоности тромбозама, планирање терапије по упуту љекара', 'Обследование при венозных тромбозах, семейной склонности к тромбозам, планирование терапии по назначению врача', 'Abklärung bei Venenthrombosen, familiärer Thromboseneigung, Therapieplanung auf ärztliche Anweisung', 'Ven trombozu, ailede tromboz eğilimi, hekim yönlendirmesiyle tedavi planlaması', 'Taken outside an acute thrombosis; warfarin and other anticoagulants are reported to the doctor and the laboratory, and the doctor sets the timing of the test relative to therapy', 'Vadi se van akutne tromboze; o varfarinu i drugim antikoagulansima obavještavaju se ljekar i laboratorija, a vrijeme vađenja u odnosu na terapiju određuje ljekar', 'Вади се ван акутне тромбозе; о варфарину и другим антикоагулансима обавјештавају се љекар и лабораторија, а вријеме вађења у односу на терапију одређује љекар', 'Сдают вне острого тромбоза; о приёме варфарина и других антикоагулянтов предупреждают врача и лабораторию, а срок сдачи относительно терапии назначает врач', 'Die Entnahme erfolgt außerhalb einer akuten Thrombose; Warfarin und andere Antikoagulanzien werden Arzt und Labor mitgeteilt, den Zeitpunkt im Verhältnis zur Therapie bestimmt der Arzt', 'Akut tromboz dönemi dışında alınır; varfarin ve diğer antikoagülanlar hekime ve laboratuvara bildirilir, testin tedaviye göre zamanlamasını hekim belirler', 'A reduced value may be related to inherited deficiency, liver disease, lack of vitamin K, or medication use. The result is interpreted by a doctor together with other thrombophilia tests', 'Sniženje može biti povezano sa nasljednim nedostatkom, oboljenjima jetre, manjkom vitamina K ili uzimanjem lijekova. Nalaz tumači ljekar zajedno sa ostalim testovima na trombofiliju', 'Снижење може бити повезано са насљедним недостатком, обољењима јетре, мањком витамина К или узимањем лијекова. Налаз тумачи љекар заједно са осталим тестовима на тромбофилију', 'Снижение может быть связано с наследственным дефицитом, заболеваниями печени, нехваткой витамина K или приёмом препаратов. Результат интерпретирует врач вместе с другими тестами на тромбофилию', 'Ein erniedrigter Wert kann mit einem angeborenen Mangel, Lebererkrankungen, Vitamin-K-Mangel oder der Einnahme von Medikamenten zusammenhängen. Das Ergebnis interpretiert der Arzt zusammen mit weiteren Thrombophilie-Tests', 'Düşük değer kalıtsal eksiklik, karaciğer hastalıkları, K vitamini azlığı veya ilaç kullanımıyla ilişkili olabilir. Sonucu hekim diğer trombofili testleriyle birlikte yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protein-s'), 'A blood test for the cofactor protein of the protein C system, involved in restraining clotting', 'Analiza krvi na pomoćni protein sistema proteina C koji učestvuje u kočenju zgrušavanja', 'Анализа крви на помоћни протеин система протеина Ц који учествује у кочењу згрушавања', 'Анализ крови на белок-помощник системы протеина C, участвующий в торможении свёртывания', 'Bluttest auf das Kofaktor-Eiweiß des Protein-C-Systems, das an der Hemmung der Gerinnung beteiligt ist', 'Pıhtılaşmanın frenlenmesinde görev alan, protein C sisteminin yardımcı proteinini ölçen kan testi', 'Venous blood draw into a citrate tube; the laboratory may measure the free and the total fraction', 'Uzimanje venske krvi u citratnu epruvetu, laboratorija može određivati slobodnu i ukupnu frakciju', 'Узимање венске крви у цитратну епрувету, лабораторија може одређивати слободну и укупну фракцију', 'Забор венозной крови в цитратную пробирку, лаборатория может определять свободную и общую фракции', 'Entnahme von venösem Blut in ein Citratröhrchen, das Labor kann die freie und die Gesamtfraktion bestimmen', 'Sitratlı tüpe venöz kan alımı, laboratuvar serbest ve toplam fraksiyonu ölçebilir', 'Work-up for venous thrombosis, thrombosis at unusual sites, thrombosis in close relatives as directed by a doctor', 'Obrada kod venskih tromboza, tromboza neuobičajene lokalizacije, tromboza kod bliskih srodnika po uputu ljekara', 'Обрада код венских тромбоза, тромбоза неуобичајене локализације, тромбоза код блиских сродника по упуту љекара', 'Обследование при венозных тромбозах, тромбозах необычной локализации, тромбозах у близких родственников по назначению врача', 'Abklärung bei Venenthrombosen, Thrombosen an ungewöhnlicher Stelle, Thrombosen bei nahen Verwandten auf ärztliche Anweisung', 'Ven trombozu, alışılmadık bölgelerde tromboz, hekim yönlendirmesiyle yakın akrabalarda görülen tromboz', 'Taken outside an acute thrombosis and, where possible, outside pregnancy; hormonal contraception and anticoagulants are reported to the doctor and the laboratory, and medications must not be stopped on your own', 'Vadi se van akutne tromboze i po mogućnosti van trudnoće; o hormonskoj kontracepciji i antikoagulansima obavještavaju se ljekar i laboratorija, a lijekovi se ne prekidaju na svoju ruku', 'Вади се ван акутне тромбозе и по могућности ван трудноће; о хормонској контрацепцији и антикоагулансима обавјештавају се љекар и лабораторија, а лијекови се не прекидају на своју руку', 'Сдают вне острого тромбоза и по возможности вне беременности; о гормональной контрацепции и антикоагулянтах сообщают врачу и лаборатории, самостоятельно отменять препараты нельзя', 'Die Entnahme erfolgt außerhalb einer akuten Thrombose und möglichst außerhalb einer Schwangerschaft; hormonelle Verhütung und Antikoagulanzien werden Arzt und Labor mitgeteilt, Medikamente dürfen nicht eigenmächtig abgesetzt werden', 'Akut tromboz dışında ve mümkünse gebelik dışında alınır; hormonal doğum kontrol yöntemleri ve antikoagülanlar hekime ve laboratuvara bildirilir, ilaçlar kendi başınıza bırakılmamalıdır', 'A reduced value may be related to inherited features, pregnancy, hormonal medication, or liver disease. The conclusion is made by a doctor, often after a repeat test', 'Sniženje može biti povezano sa nasljednim osobinama, trudnoćom, uzimanjem hormonskih lijekova ili oboljenjima jetre. Zaključak donosi ljekar, često nakon ponovljenog ispitivanja', 'Снижење може бити повезано са насљедним особинама, трудноћом, узимањем хормонских лијекова или обољењима јетре. Закључак доноси љекар, често након поновљеног испитивања', 'Снижение может быть связано с наследственными особенностями, беременностью, приёмом гормональных препаратов или болезнями печени. Итог оценивает врач, часто после повторного исследования', 'Ein erniedrigter Wert kann mit erblichen Besonderheiten, einer Schwangerschaft, hormonellen Medikamenten oder Lebererkrankungen zusammenhängen. Die Beurteilung trifft der Arzt, häufig nach einer Wiederholung', 'Düşük değer kalıtsal özellikler, gebelik, hormonal ilaç kullanımı veya karaciğer hastalıklarıyla ilişkili olabilir. Sonucu hekim, çoğu zaman tekrar testten sonra değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'phosphorus'), 'Blood test for inorganic phosphate — a mineral involved in bone and energy metabolism', 'Analiza krvi na neorganski fosfat, mineral koji učestvuje u metabolizmu kostiju i energije', 'Анализа крви на неоргански фосфат, минерал који учествује у метаболизму костију и енергије', 'Анализ крови на неорганический фосфат — минерал, участвующий в обмене костной ткани и энергии', 'Bluttest auf anorganisches Phosphat, einen Mineralstoff des Knochen- und Energiestoffwechsels', 'Kemik ve enerji metabolizmasında rol alan bir mineral olan inorganik fosfatı ölçen kan testi', 'Venous blood draw', 'Uzimanje venske krvi', 'Узимање венске крви', 'Забор венозной крови', 'Entnahme von venösem Blut', 'Venöz kan alımı', 'Assessment of bone and mineral metabolism, kidney disease, disturbances of calcium and vitamin D levels, follow-up of chronic conditions as directed by a doctor', 'Procjena koštanog i mineralnog metabolizma, bubrežna oboljenja, poremećaji nivoa kalcijuma i vitamina D, praćenje hroničnih bolesti po uputu ljekara', 'Процјена коштаног и минералног метаболизма, бубрежна обољења, поремећаји нивоа калцијума и витамина Д, праћење хроничних болести по упуту љекара', 'Оценка костного и минерального обмена, заболевания почек, нарушения уровня кальция и витамина D, наблюдение при хронических болезнях по назначению врача', 'Beurteilung des Knochen- und Mineralstoffwechsels, Nierenerkrankungen, Störungen des Kalzium- und Vitamin-D-Spiegels, Verlaufskontrolle chronischer Erkrankungen auf ärztliche Anweisung', 'Kemik ve mineral metabolizmasının değerlendirilmesi, böbrek hastalıkları, kalsiyum ve D vitamini düzeyi bozuklukları, hekim yönlendirmesiyle kronik hastalık takibi', 'In the morning on an empty stomach, water allowed; supplements with phosphates and vitamin D are taken the day before only in agreement with the doctor', 'Ujutru natašte, dozvoljena je voda; dodaci sa fosfatima i vitaminom D uzimaju se dan ranije samo uz dogovor sa ljekarom', 'Ујутру наташте, дозвољена је вода; додаци са фосфатима и витамином Д узимају се дан раније само уз договор са љекаром', 'Утром натощак, разрешена вода; добавки с фосфатами и витамином D накануне принимают только по согласованию с врачом', 'Morgens nüchtern, Wasser ist erlaubt; Präparate mit Phosphat und Vitamin D am Vortag nur in Absprache mit dem Arzt einnehmen', 'Sabah aç karnına, su içilebilir; fosfat ve D vitamini içeren takviyeler bir gün önce yalnızca hekimle görüşerek alınır', 'Changes may be related to kidney function, calcium metabolism, parathyroid function, or diet. The meaning of the result is determined by a doctor together with calcium and other values', 'Promjene mogu biti povezane sa radom bubrega, metabolizmom kalcijuma, funkcijom paratireoidnih žlijezda ili ishranom. Značenje nalaza određuje ljekar uz kalcijum i druge pokazatelje', 'Промјене могу бити повезане са радом бубрега, метаболизмом калцијума, функцијом паратиреоидних жлијезда или исхраном. Значење налаза одређује љекар уз калцијум и друге показатеље', 'Изменения могут быть связаны с работой почек, обменом кальция, функцией паращитовидных желёз или питанием. Значение результата определяет врач в сочетании с кальцием и другими показателями', 'Veränderungen können mit der Nierenfunktion, dem Kalziumstoffwechsel, der Funktion der Nebenschilddrüsen oder der Ernährung zusammenhängen. Die Bedeutung des Ergebnisses bestimmt der Arzt zusammen mit Kalzium und weiteren Werten', 'Değişiklikler böbrek işlevi, kalsiyum metabolizması, paratiroid bezlerinin çalışması veya beslenmeyle ilişkili olabilir. Sonucun anlamını hekim kalsiyum ve diğer değerlerle birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ionized-calcium'), 'Blood test for the free, biologically active portion of calcium that is not bound to proteins', 'Analiza krvi na slobodni, biološki aktivni dio kalcijuma koji nije vezan za bjelančevine', 'Анализа крви на слободни, биолошки активни дио калцијума који није везан за бјеланчевине', 'Анализ крови на свободную, биологически активную часть кальция, не связанную с белками', 'Bluttest auf den freien, biologisch aktiven Anteil des Kalziums, der nicht an Eiweiße gebunden ist', 'Kalsiyumun proteine bağlı olmayan, serbest ve biyolojik olarak etkin bölümünü ölçen kan testi', 'Venous or arterial blood draw with prompt delivery to the laboratory, often performed together with blood gas analysis', 'Uzimanje venske ili arterijske krvi uz brzu dostavu u laboratoriju, često se radi zajedno sa gasnim analizama krvi', 'Узимање венске или артеријске крви уз брзу доставу у лабораторију, често се ради заједно са гасним анализама крви', 'Забор венозной или артериальной крови с быстрой доставкой в лабораторию, часто выполняется вместе с анализом газов крови', 'Entnahme von venösem oder arteriellem Blut mit rascher Zustellung ins Labor, häufig zusammen mit der Blutgasanalyse', 'Venöz veya arteriyel kan alınır ve hızla laboratuvara ulaştırılır, sıklıkla kan gazı analiziyle birlikte yapılır', 'Clarification of calcium metabolism disorders, parathyroid disease, kidney failure, monitoring in intensive care', 'Razjašnjenje poremećaja metabolizma kalcijuma, oboljenja paratireoidnih žlijezda, bubrežna slabost, praćenje stanja u intenzivnoj njezi', 'Разјашњење поремећаја метаболизма калцијума, обољења паратиреоидних жлијезда, бубрежна слабост, праћење стања у интензивној њези', 'Уточнение нарушений кальциевого обмена, заболевания паращитовидных желёз, почечная недостаточность, наблюдение за состоянием при интенсивной терапии', 'Klärung von Störungen des Kalziumstoffwechsels, Erkrankungen der Nebenschilddrüsen, Niereninsuffizienz, Überwachung in der Intensivmedizin', 'Kalsiyum metabolizması bozukluklarının netleştirilmesi, paratiroid hastalıkları, böbrek yetmezliği, yoğun bakımda izlem', 'In the morning on an empty stomach, without prolonged fist clenching or tourniquet use; calcium and vitamin D supplements are reported to the laboratory', 'Ujutru natašte, bez dužeg stiskanja šake i podveze; o preparatima kalcijuma i vitamina D obavještava se laboratorija', 'Ујутру наташте, без дужег стискања шаке и подвезе; о препаратима калцијума и витамина Д обавјештава се лабораторија', 'Утром натощак, без длительного сжимания кулака и жгута; о приёме препаратов кальция и витамина D сообщают лаборатории', 'Morgens nüchtern, ohne längeres Faustschließen und Abbinden; Kalzium- und Vitamin-D-Präparate werden dem Labor mitgeteilt', 'Sabah aç karnına, yumruk uzun süre sıkılmadan ve turnike uzun tutulmadan; kalsiyum ve D vitamini takviyeleri laboratuvara bildirilir', 'Deviations may be related to parathyroid and kidney function, vitamin D level, or the acid-base state of the blood. The assessment is made by a doctor taking total calcium and albumin into account', 'Odstupanja mogu biti povezana sa funkcijom paratireoidnih žlijezda i bubrega, nivoom vitamina D ili acido-baznim stanjem krvi. Procjenu vrši ljekar uz ukupni kalcijum i albumin', 'Одступања могу бити повезана са функцијом паратиреоидних жлијезда и бубрега, нивоом витамина Д или ацидо-базним стањем крви. Процјену врши љекар уз укупни калцијум и албумин', 'Отклонения могут быть связаны с функцией паращитовидных желёз и почек, уровнем витамина D или кислотно-щелочным состоянием крови. Оценку проводит врач с учётом общего кальция и альбумина', 'Abweichungen können mit der Funktion der Nebenschilddrüsen und der Nieren, dem Vitamin-D-Spiegel oder dem Säure-Basen-Status des Blutes zusammenhängen. Die Beurteilung erfolgt durch den Arzt unter Berücksichtigung von Gesamtkalzium und Albumin', 'Sapmalar paratiroid ve böbrek işlevi, D vitamini düzeyi veya kanın asit-baz durumuyla ilişkili olabilir. Değerlendirmeyi hekim, total kalsiyum ve albümini de dikkate alarak yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'magnesium'), 'Blood test for magnesium — a mineral important for muscle and nerve function and heart rhythm', 'Analiza krvi na magnezijum, mineral važan za rad mišića, nerava i srčanog ritma', 'Анализа крви на магнезијум, минерал важан за рад мишића, нерава и срчаног ритма', 'Анализ крови на магний — минерал, важный для работы мышц, нервов и сердечного ритма', 'Bluttest auf Magnesium, einen Mineralstoff für Muskel- und Nervenfunktion sowie den Herzrhythmus', 'Kas ve sinir işlevi ile kalp ritmi için önemli bir mineral olan magnezyumu ölçen kan testi', 'Venous blood draw', 'Uzimanje venske krvi', 'Узимање венске крви', 'Забор венозной крови', 'Entnahme von venösem Blut', 'Venöz kan alımı', 'Cramps and muscle twitching, heart rhythm disturbances, long-term diuretic use, kidney and bowel disease, monitoring during tube feeding', 'Grčevi i trzanje mišića, poremećaji srčanog ritma, dugotrajno uzimanje diuretika, oboljenja bubrega i crijeva, praćenje kod ishrane preko sonde', 'Грчеви и трзање мишића, поремећаји срчаног ритма, дуготрајно узимање диуретика, обољења бубрега и цријева, праћење код исхране преко сонде', 'Судороги и подёргивания мышц, нарушения сердечного ритма, длительный приём мочегонных, заболевания почек и кишечника, контроль при питании через зонд', 'Krämpfe und Muskelzucken, Herzrhythmusstörungen, langfristige Einnahme von Diuretika, Nieren- und Darmerkrankungen, Kontrolle bei Sondenernährung', 'Kramplar ve kas seğirmeleri, kalp ritmi bozuklukları, uzun süreli diüretik kullanımı, böbrek ve bağırsak hastalıkları, sonda ile beslenmede izlem', 'In the morning on an empty stomach; magnesium supplements and laxatives taken the day before should be mentioned to the doctor, as they change the result', 'Ujutru natašte; o preparatima magnezijuma i laksativima uzetim dan ranije treba reći ljekaru jer mijenjaju nalaz', 'Ујутру наташте; о препаратима магнезијума и лаксативима узетим дан раније треба рећи љекару јер мијењају налаз', 'Утром натощак; о препаратах магния и слабительных, принятых накануне, нужно сказать врачу, так как они меняют результат', 'Morgens nüchtern; am Vortag eingenommene Magnesiumpräparate und Abführmittel sollten dem Arzt mitgeteilt werden, da sie das Ergebnis verändern', 'Sabah aç karnına; bir gün önce alınan magnezyum takviyeleri ve müshiller sonucu değiştirdiği için hekime söylenmelidir', 'Deviations may be related to diet, losses through the kidneys or bowel, or medication use. The interpretation is given by a doctor together with potassium and calcium', 'Odstupanja mogu biti povezana sa ishranom, gubicima preko bubrega ili crijeva i uzimanjem lijekova. Tumačenje daje ljekar zajedno sa kalijumom i kalcijumom', 'Одступања могу бити повезана са исхраном, губицима преко бубрега или цријева и узимањем лијекова. Тумачење даје љекар заједно са калијумом и калцијумом', 'Отклонения могут быть связаны с питанием, потерями через почки или кишечник, приёмом лекарств. Трактовку даёт врач вместе с калием и кальцием', 'Abweichungen können mit der Ernährung, Verlusten über Nieren oder Darm sowie der Einnahme von Medikamenten zusammenhängen. Die Interpretation nimmt der Arzt zusammen mit Kalium und Kalzium vor', 'Sapmalar beslenme, böbrek veya bağırsak yoluyla kayıplar ya da ilaç kullanımıyla ilişkili olabilir. Yorumu hekim potasyum ve kalsiyumla birlikte yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'chloride'), 'Blood test for chloride — the main negatively charged electrolyte of the fluid outside the cells', 'Analiza krvi na hloride, glavni negativno naelektrisani elektrolit tečnosti izvan ćelija', 'Анализа крви на хлориде, главни негативно наелектрисани електролит течности изван ћелија', 'Анализ крови на хлориды — основной отрицательно заряженный электролит внеклеточной жидкости', 'Bluttest auf Chlorid, das wichtigste negativ geladene Elektrolyt der Flüssigkeit außerhalb der Zellen', 'Hücre dışı sıvının başlıca negatif yüklü elektroliti olan klorürü ölçen kan testi', 'Venous blood draw, most often together with sodium and potassium', 'Uzimanje venske krvi, najčešće zajedno sa natrijumom i kalijumom', 'Узимање венске крви, најчешће заједно са натријумом и калијумом', 'Забор венозной крови, чаще всего вместе с натрием и калием', 'Entnahme von venösem Blut, meist zusammen mit Natrium und Kalium', 'Venöz kan alımı, çoğunlukla sodyum ve potasyumla birlikte', 'Assessment of water and salt balance, dehydration, vomiting and diarrhea, kidney disease, work-up of acid-base disturbances', 'Procjena vodeno-solne ravnoteže, dehidracija, povraćanje i proljev, bubrežna oboljenja, obrada poremećaja acido-bazne ravnoteže', 'Процјена водено-солне равнотеже, дехидрација, повраћање и прољев, бубрежна обољења, обрада поремећаја ацидо-базне равнотеже', 'Оценка водно-солевого баланса, обезвоживание, рвота и диарея, заболевания почек, разбор нарушений кислотно-щелочного равновесия', 'Beurteilung des Wasser- und Salzhaushalts, Austrocknung, Erbrechen und Durchfall, Nierenerkrankungen, Abklärung von Säure-Basen-Störungen', 'Su-tuz dengesinin değerlendirilmesi, sıvı kaybı, kusma ve ishal, böbrek hastalıkları, asit-baz bozukluklarının incelenmesi', 'No special preparation required, a morning draw is preferable; diuretics and intravenous fluids are reported to the doctor', 'Nije potrebna posebna priprema, poželjno je jutarnje vađenje; o diureticima i infuzijama obavještava se ljekar', 'Није потребна посебна припрема, пожељно је јутарње вађење; о диуретицима и инфузијама обавјештава се љекар', 'Специальной подготовки не требуется, предпочтителен утренний забор; о мочегонных и капельницах сообщают врачу', 'Keine besondere Vorbereitung erforderlich, eine Entnahme am Morgen ist vorzuziehen; Diuretika und Infusionen werden dem Arzt mitgeteilt', 'Özel bir hazırlık gerektirmez, sabah alınması tercih edilir; diüretikler ve damar içi sıvılar hekime bildirilir', 'Changes may be related to fluid loss, renal and respiratory regulation mechanisms, or medication use. The result is assessed together with sodium and bicarbonate, and the conclusion is made by a doctor', 'Promjene mogu biti povezane sa gubitkom tečnosti, bubrežnim i disajnim mehanizmima regulacije ili uzimanjem lijekova. Nalaz se procjenjuje uz natrijum i bikarbonate, a zaključak donosi ljekar', 'Промјене могу бити повезане са губитком течности, бубрежним и дисајним механизмима регулације или узимањем лијекова. Налаз се процјењује уз натријум и бикарбонате, а закључак доноси љекар', 'Изменения могут быть связаны с потерей жидкости, почечными и дыхательными механизмами регуляции, приёмом препаратов. Результат оценивают вместе с натрием и бикарбонатами, вывод делает врач', 'Veränderungen können mit Flüssigkeitsverlusten, Regulationsmechanismen von Nieren und Lunge oder der Einnahme von Medikamenten zusammenhängen. Der Wert wird zusammen mit Natrium und Bikarbonat beurteilt, die Schlussfolgerung zieht der Arzt', 'Değişiklikler sıvı kaybı, böbrek ve solunum yoluyla düzenleme mekanizmaları veya ilaç kullanımıyla ilişkili olabilir. Sonuç sodyum ve bikarbonatla birlikte değerlendirilir, kararı hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'bicarbonates'), 'A blood value reflecting the alkaline reserve and the role of the kidneys in maintaining acid-base balance', 'Pokazatelj u krvi koji odražava alkalnu rezervu i ulogu bubrega u održavanju acido-bazne ravnoteže', 'Показатељ у крви који одражава алкалну резерву и улогу бубрега у одржавању ацидо-базне равнотеже', 'Показатель крови, отражающий щелочной резерв и участие почек в поддержании кислотно-щелочного равновесия', 'Ein Blutwert, der die alkalische Reserve und die Rolle der Nieren im Säure-Basen-Haushalt widerspiegelt', 'Alkali rezervi ve böbreklerin asit-baz dengesindeki rolünü yansıtan bir kan değeri', 'Measured in venous or arterial blood, often as part of a blood gas analysis, with the sample delivered to the laboratory immediately', 'Određuje se u venskoj ili arterijskoj krvi, često u sklopu gasnih analiza, a uzorak se odmah dostavlja u laboratoriju', 'Одређује се у венској или артеријској крви, често у склопу гасних анализа, а узорак се одмах доставља у лабораторију', 'Определяется в венозной или артериальной крови, часто в составе анализа газов крови, образец доставляют в лабораторию сразу', 'Bestimmung in venösem oder arteriellem Blut, häufig im Rahmen der Blutgasanalyse, die Probe wird sofort ins Labor gebracht', 'Venöz veya arteriyel kanda, çoğu zaman kan gazı analizinin bir parçası olarak ölçülür, örnek hemen laboratuvara ulaştırılır', 'Work-up of acid-base disturbances, severe dehydration, kidney and lung disease, monitoring during flare-ups of chronic conditions', 'Obrada poremećaja acido-bazne ravnoteže, teška dehidracija, oboljenja bubrega i pluća, praćenje kod pogoršanja hroničnih bolesti', 'Обрада поремећаја ацидо-базне равнотеже, тешка дехидрација, обољења бубрега и плућа, праћење код погоршања хроничних болести', 'Разбор нарушений кислотно-щелочного равновесия, тяжёлое обезвоживание, заболевания почек и лёгких, наблюдение при обострении хронических болезней', 'Abklärung von Säure-Basen-Störungen, schwere Austrocknung, Nieren- und Lungenerkrankungen, Überwachung bei Verschlechterung chronischer Erkrankungen', 'Asit-baz bozukluklarının incelenmesi, ağır sıvı kaybı, böbrek ve akciğer hastalıkları, kronik hastalıkların alevlenmesinde izlem', 'No special preparation required; before the draw it is important to sit calmly and not to hold your breath', 'Nije potrebna posebna priprema; prije vađenja je važno mirno sjediti i ne zadržavati dah', 'Није потребна посебна припрема; прије вађења је важно мирно сједити и не задржавати дах', 'Специальной подготовки не требуется; перед забором важно спокойно посидеть и не задерживать дыхание', 'Keine besondere Vorbereitung erforderlich; vor der Entnahme ruhig sitzen und die Luft nicht anhalten', 'Özel bir hazırlık gerektirmez; kan alınmadan önce sakin oturmak ve nefes tutmamak önemlidir', 'Deviations may be related to breathing disorders, kidney function, vomiting, or fluid loss. The result is assessed together with pH and blood gases, and interpreted by a doctor', 'Odstupanja mogu biti povezana sa disajnim poremećajima, radom bubrega, povraćanjem ili gubitkom tečnosti. Nalaz se procjenjuje uz pH i gasne analize, a tumači ga ljekar', 'Одступања могу бити повезана са дисајним поремећајима, радом бубрега, повраћањем или губитком течности. Налаз се процјењује уз пХ и гасне анализе, а тумачи га љекар', 'Отклонения могут быть связаны с дыхательными нарушениями, работой почек, рвотой или потерей жидкости. Результат оценивают вместе с pH и газами крови, интерпретацию проводит врач', 'Abweichungen können mit Atemstörungen, der Nierenfunktion, Erbrechen oder Flüssigkeitsverlust zusammenhängen. Der Wert wird zusammen mit pH und Blutgasen beurteilt, die Interpretation erfolgt durch den Arzt', 'Sapmalar solunum bozuklukları, böbrek işlevi, kusma veya sıvı kaybıyla ilişkili olabilir. Sonuç pH ve kan gazlarıyla birlikte değerlendirilir, yorumu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'leukocyte-formula'), 'A count of the proportions of the different types of white blood cells in the sample', 'Brojanje udjela različitih vrsta bijelih krvnih ćelija u uzorku', 'Бројање удјела различитих врста бијелих крвних ћелија у узорку', 'Подсчёт долей разных видов белых клеток крови в образце', 'Auszählung der Anteile der verschiedenen Arten weißer Blutkörperchen in der Probe', 'Örnekteki farklı akyuvar türlerinin oranlarının sayımı', 'Venous or capillary blood draw, counted on an analyzer, with a laboratory technician reviewing the smear under a microscope when needed', 'Uzimanje venske ili kapilarne krvi, brojanje na analizatoru, a po potrebi laborant pregleda razmaz pod mikroskopom', 'Узимање венске или капиларне крви, бројање на анализатору, а по потреби лаборант прегледа размаз под микроскопом', 'Забор венозной или капиллярной крови, подсчёт на анализаторе, при необходимости лаборант просматривает мазок под микроскопом', 'Entnahme von venösem oder kapillarem Blut, Auszählung am Analysegerät, bei Bedarf begutachtet eine Fachkraft den Ausstrich unter dem Mikroskop', 'Venöz veya kapiller kan alınır, sayım cihazda yapılır, gerektiğinde laboratuvar uzmanı yaymayı mikroskopta inceler', 'Clarifying the picture in infections, prolonged fever, inflammatory and allergic conditions, monitoring during treatment', 'Razjašnjenje slike kod infekcija, dugotrajne temperature, upalnih i alergijskih stanja, praćenje tokom liječenja', 'Разјашњење слике код инфекција, дуготрајне температуре, упалних и алергијских стања, праћење током лијечења', 'Уточнение картины при инфекциях, длительной температуре, воспалительных и аллергических состояниях, наблюдение в ходе лечения', 'Genauere Einordnung bei Infektionen, anhaltendem Fieber, entzündlichen und allergischen Zuständen, Verlaufskontrolle während einer Behandlung', 'Enfeksiyonlarda, uzun süren ateşte, iltihabi ve alerjik durumlarda tablonun netleştirilmesi, tedavi sırasında izlem', 'No special preparation required, a morning draw before physical exertion is preferable', 'Nije potrebna posebna priprema, poželjno je vađenje ujutru prije fizičkog napora', 'Није потребна посебна припрема, пожељно је вађење ујутру прије физичког напора', 'Специальной подготовки не требуется, предпочтителен забор утром до физической нагрузки', 'Keine besondere Vorbereitung erforderlich, eine Entnahme am Morgen vor körperlicher Belastung ist vorzuziehen', 'Özel bir hazırlık gerektirmez, sabah ve fiziksel zorlanmadan önce alınması tercih edilir', 'Shifts in the ratio of the cells may be related to bacterial or viral infection, allergy, parasites, medication use, and other causes. The picture is assessed by a doctor together with the symptoms and the rest of the blood values', 'Pomjeranje odnosa ćelija može biti povezano sa bakterijskom ili virusnom infekcijom, alergijom, parazitima, uzimanjem lijekova i drugim uzrocima. Sliku procjenjuje ljekar uz tegobe i ostale pokazatelje krvi', 'Помјерање односа ћелија може бити повезано са бактеријском или вирусном инфекцијом, алергијом, паразитима, узимањем лијекова и другим узроцима. Слику процјењује љекар уз тегобе и остале показатеље крви', 'Сдвиги в соотношении клеток могут быть связаны с бактериальной или вирусной инфекцией, аллергией, паразитами, приёмом препаратов и другими причинами. Картину оценивает врач вместе с жалобами и остальными показателями крови', 'Verschiebungen im Verhältnis der Zellen können mit bakteriellen oder viralen Infektionen, Allergien, Parasiten, Medikamenten und anderen Ursachen zusammenhängen. Das Bild beurteilt der Arzt zusammen mit den Beschwerden und den übrigen Blutwerten', 'Hücre oranlarındaki kaymalar bakteriyel veya viral enfeksiyon, alerji, parazitler, ilaç kullanımı ve başka nedenlerle ilişkili olabilir. Tabloyu hekim şikayetler ve diğer kan değerleriyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'erythrocyte-resistance'), 'A laboratory test showing how resistant red blood cells are to breaking down in salt solutions of different concentrations', 'Laboratorijska proba koja pokazuje otpornost eritrocita na razgradnju u slanim rastvorima različite koncentracije', 'Лабораторијска проба која показује отпорност еритроцита на разградњу у сланим растворима различите концентрације', 'Лабораторная проба, показывающая устойчивость эритроцитов к разрушению в солевых растворах разной концентрации', 'Ein Labortest, der zeigt, wie widerstandsfähig rote Blutkörperchen gegenüber dem Zerfall in Salzlösungen unterschiedlicher Konzentration sind', 'Alyuvarların farklı yoğunluktaki tuz çözeltilerinde parçalanmaya ne kadar dayanıklı olduğunu gösteren laboratuvar testi', 'Blood is placed in a series of solutions with decreasing salt concentration, and the point where red cell breakdown begins and where it is complete is recorded', 'Krv se stavlja u niz rastvora sa opadajućom koncentracijom soli i bilježi se u kojem počinje i u kojem se završava razgradnja eritrocita', 'Крв се ставља у низ раствора са опадајућом концентрацијом соли и биљежи се у којем почиње и у којем се завршава разградња еритроцита', 'Кровь помещают в серию растворов с убывающей концентрацией соли и отмечают, в каком из них разрушение эритроцитов начинается и в каком завершается', 'Das Blut wird in eine Reihe von Lösungen mit abnehmender Salzkonzentration gegeben, und es wird festgehalten, wo der Zerfall der roten Blutkörperchen beginnt und wo er abgeschlossen ist', 'Kan, tuz yoğunluğu giderek azalan bir dizi çözeltiye konur ve alyuvar parçalanmasının nerede başlayıp nerede tamamlandığı kaydedilir', 'Work-up for suspected inherited features of the red cell membrane, clarifying the cause of anemia as directed by a hematologist', 'Obrada kod sumnje na nasljedne osobine opne eritrocita, razjašnjenje uzroka anemije po uputu hematologa', 'Обрада код сумње на насљедне особине опне еритроцита, разјашњење узрока анемије по упуту хематолога', 'Обследование при подозрении на наследственные особенности оболочки эритроцитов, уточнение причины анемии по назначению гематолога', 'Abklärung bei Verdacht auf erbliche Besonderheiten der Erythrozytenmembran, Klärung der Ursache einer Anämie auf Anweisung eines Hämatologen', 'Alyuvar zarının kalıtsal özelliklerinden şüphelenildiğinde inceleme, hematolog yönlendirmesiyle anemi nedeninin netleştirilmesi', 'No special preparation required; a recent blood transfusion and iron supplements should be reported to the doctor', 'Nije potrebna posebna priprema; o nedavnoj transfuziji krvi i uzimanju preparata gvožđa treba obavijestiti ljekara', 'Није потребна посебна припрема; о недавној трансфузији крви и узимању препарата гвожђа треба обавијестити љекара', 'Специальной подготовки не требуется; о недавнем переливании крови и приёме препаратов железа нужно сообщить врачу', 'Keine besondere Vorbereitung erforderlich; eine kürzliche Bluttransfusion und Eisenpräparate sind dem Arzt mitzuteilen', 'Özel bir hazırlık gerektirmez; yakın zamanda yapılan kan nakli ve demir preparatları hekime bildirilmelidir', 'A change in the resistance of red blood cells may be related to inherited features of their membrane or to other forms of anemia. The result is interpreted by a doctor together with the blood count and the blood smear', 'Promjena otpornosti eritrocita može biti povezana sa nasljednim osobinama njihove opne ili sa drugim oblicima anemije. Nalaz tumači ljekar uz kompletnu krvnu sliku i razmaz krvi', 'Промјена отпорности еритроцита може бити повезана са насљедним особинама њихове опне или са другим облицима анемије. Налаз тумачи љекар уз комплетну крвну слику и размаз крви', 'Изменение устойчивости эритроцитов может быть связано с наследственными особенностями их оболочки или с другими формами анемии. Результат интерпретирует врач вместе с общим анализом крови и мазком', 'Eine veränderte Widerstandsfähigkeit der roten Blutkörperchen kann mit erblichen Besonderheiten ihrer Membran oder mit anderen Formen der Anämie zusammenhängen. Das Ergebnis interpretiert der Arzt zusammen mit dem Blutbild und dem Blutausstrich', 'Alyuvarların direncindeki değişim, hücre zarının kalıtsal özellikleriyle veya başka anemi biçimleriyle ilişkili olabilir. Sonucu hekim tam kan sayımı ve kan yaymasıyla birlikte yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'reticulocytes'), 'A count of young red blood cells that have recently left the bone marrow', 'Brojanje mladih eritrocita koji su nedavno napustili koštanu srž', 'Бројање младих еритроцита који су недавно напустили коштану срж', 'Подсчёт молодых эритроцитов, недавно вышедших из костного мозга', 'Auszählung junger roter Blutkörperchen, die das Knochenmark erst kürzlich verlassen haben', 'Kemik iliğinden yakın zamanda ayrılmış genç alyuvarların sayımı', 'Venous or capillary blood draw, counted on an analyzer or in a stained smear', 'Uzimanje venske ili kapilarne krvi, brojanje na analizatoru ili u obojenom razmazu', 'Узимање венске или капиларне крви, бројање на анализатору или у обојеном размазу', 'Забор венозной или капиллярной крови, подсчёт на анализаторе или в окрашенном мазке', 'Entnahme von venösem oder kapillarem Blut, Auszählung am Analysegerät oder im gefärbten Ausstrich', 'Venöz veya kapiller kan alınır, sayım cihazda veya boyalı yaymada yapılır', 'Clarifying the cause of anemia, assessing the response to iron or vitamin B12 treatment, follow-up after blood loss and in bone marrow disorders', 'Razjašnjenje uzroka anemije, procjena odgovora na terapiju gvožđem ili vitaminom B12, praćenje nakon gubitka krvi i kod oboljenja koštane srži', 'Разјашњење узрока анемије, процјена одговора на терапију гвожђем или витамином Б12, праћење након губитка крви и код обољења коштане сржи', 'Уточнение причины анемии, оценка ответа на лечение препаратами железа или витамином B12, наблюдение после кровопотери и при болезнях костного мозга', 'Klärung der Ursache einer Anämie, Beurteilung des Ansprechens auf eine Behandlung mit Eisen oder Vitamin B12, Verlaufskontrolle nach Blutverlust und bei Knochenmarkerkrankungen', 'Anemi nedeninin netleştirilmesi, demir veya B12 vitamini tedavisine yanıtın değerlendirilmesi, kan kaybı sonrası ve kemik iliği hastalıklarında izlem', 'No special preparation required; a started anemia treatment and a recent blood transfusion are reported to the doctor', 'Nije potrebna posebna priprema; o započetoj terapiji anemije i nedavnoj transfuziji obavještava se ljekar', 'Није потребна посебна припрема; о започетој терапији анемије и недавној трансфузији обавјештава се љекар', 'Специальной подготовки не требуется; о начатом лечении анемии и недавнем переливании крови сообщают врачу', 'Keine besondere Vorbereitung erforderlich; eine begonnene Anämiebehandlung und eine kürzliche Bluttransfusion sind dem Arzt mitzuteilen', 'Özel bir hazırlık gerektirmez; başlanan anemi tedavisi ve yakın zamanda yapılan kan nakli hekime bildirilir', 'A higher or lower share of young red blood cells may be related to bone marrow activity, a lack of iron or vitamins, or the loss or breakdown of blood cells. The meaning of the result is determined by a doctor', 'Povećanje ili smanjenje udjela mladih eritrocita može biti povezano sa aktivnošću koštane srži, manjkom gvožđa ili vitamina, gubitkom ili razgradnjom krvnih ćelija. Smisao nalaza određuje ljekar', 'Повећање или смањење удјела младих еритроцита може бити повезано са активношћу коштане сржи, мањком гвожђа или витамина, губитком или разградњом крвних ћелија. Смисао налаза одређује љекар', 'Повышение или снижение доли молодых эритроцитов может быть связано с активностью костного мозга, нехваткой железа или витаминов, потерей или разрушением клеток крови. Смысл результата определяет врач', 'Ein höherer oder niedrigerer Anteil junger roter Blutkörperchen kann mit der Aktivität des Knochenmarks, einem Mangel an Eisen oder Vitaminen oder dem Verlust bzw. Abbau von Blutzellen zusammenhängen. Die Bedeutung des Ergebnisses bestimmt der Arzt', 'Genç alyuvar oranının artması veya azalması kemik iliğinin etkinliği, demir ya da vitamin azlığı, kan hücrelerinin kaybı veya yıkımıyla ilişkili olabilir. Sonucun anlamını hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'complete-blood-count-with-leukocyte-formula'), 'An extended version of the blood count in which the counting of white cell types is added to the main values', 'Prošireni oblik krvne slike u kojem je osnovnim pokazateljima dodato brojanje vrsta leukocita', 'Проширени облик крвне слике у којем је основним показатељима додато бројање врста леукоцита', 'Расширенный вариант общего анализа крови, где к основным показателям добавлен подсчёт видов лейкоцитов', 'Eine erweiterte Form des Blutbildes, bei der zu den Grundwerten die Auszählung der Leukozytenarten hinzukommt', 'Temel değerlere akyuvar türlerinin sayımının eklendiği, genişletilmiş kan sayımı', 'A single venous or capillary blood draw from which the laboratory obtains both the cell values and the distribution of white cells', 'Jedno vađenje venske ili kapilarne krvi iz kojeg laboratorija dobija i ćelijske pokazatelje i raspodjelu leukocita', 'Једно вађење венске или капиларне крви из којег лабораторија добија и ћелијске показатеље и расподјелу леукоцита', 'Один забор венозной или капиллярной крови, из которого лаборатория получает и клеточные показатели, и распределение лейкоцитов', 'Eine einzige Entnahme von venösem oder kapillarem Blut, aus der das Labor sowohl die Zellwerte als auch die Verteilung der weißen Blutkörperchen bestimmt', 'Tek bir venöz veya kapiller kan alımıyla laboratuvar hem hücre değerlerini hem de akyuvar dağılımını elde eder', 'Initial work-up for complaints, suspected infection or inflammation, routine check-ups, preparation for surgery, follow-up during therapy', 'Prva obrada kod tegoba, sumnja na infekciju ili upalu, sistematski pregled, priprema za operaciju, praćenje tokom terapije', 'Прва обрада код тегоба, сумња на инфекцију или упалу, систематски преглед, припрема за операцију, праћење током терапије', 'Первичное обследование при жалобах, подозрение на инфекцию или воспаление, диспансеризация, подготовка к операции, наблюдение во время терапии', 'Erstabklärung bei Beschwerden, Verdacht auf Infektion oder Entzündung, Vorsorgeuntersuchung, Vorbereitung auf eine Operation, Verlaufskontrolle während einer Therapie', 'Şikayetlerde ilk inceleme, enfeksiyon veya iltihap şüphesi, genel kontrol, ameliyata hazırlık, tedavi sırasında izlem', 'No special preparation required, the sample is usually taken in the morning, and intense exertion the day before is better postponed', 'Nije potrebna posebna priprema, uzorak se najčešće uzima ujutru, a jači fizički napor dan ranije bolje je odložiti', 'Није потребна посебна припрема, узорак се најчешће узима ујутру, а јачи физички напор дан раније боље је одложити', 'Специальной подготовки не требуется, чаще сдают утром, а интенсивные нагрузки накануне лучше отложить', 'Keine besondere Vorbereitung erforderlich, die Entnahme erfolgt meist morgens, starke körperliche Belastung am Vortag sollte verschoben werden', 'Özel bir hazırlık gerektirmez, örnek genellikle sabah alınır, bir gün önce ağır fiziksel zorlanmayı ertelemek daha iyidir', 'A combination of changes in the cell values and in the white cell ratio may be related to infection, inflammation, anemia, or a response to treatment. Which values matter is decided by a doctor based on the whole picture', 'Kombinacija promjena ćelijskih pokazatelja i odnosa leukocita može biti povezana sa infekcijom, upalom, anemijom ili odgovorom na liječenje. Koji su pokazatelji značajni, odlučuje ljekar prema cjelokupnoj slici', 'Комбинација промјена ћелијских показатеља и односа леукоцита може бити повезана са инфекцијом, упалом, анемијом или одговором на лијечење. Који су показатељи значајни, одлучује љекар према цјелокупној слици', 'Сочетание изменений клеточных показателей и соотношения лейкоцитов может быть связано с инфекцией, воспалением, анемией или ответом на лечение. Какие именно показатели значимы, решает врач по всей картине', 'Eine Kombination aus veränderten Zellwerten und einem verschobenen Leukozytenverhältnis kann mit einer Infektion, Entzündung, Anämie oder einer Reaktion auf die Behandlung zusammenhängen. Welche Werte bedeutsam sind, entscheidet der Arzt anhand des Gesamtbildes', 'Hücre değerlerindeki değişikliklerin ve akyuvar oranlarındaki kaymaların birlikteliği enfeksiyon, iltihap, anemi veya tedaviye yanıtla ilişkili olabilir. Hangi değerlerin önemli olduğuna hekim bütün tabloya bakarak karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'platelets'), 'A count of the blood platelets responsible for the initial stopping of bleeding', 'Brojanje krvnih pločica koje su odgovorne za početno zaustavljanje krvarenja', 'Бројање крвних плочица које су одговорне за почетно заустављање крварења', 'Подсчёт количества кровяных пластинок, отвечающих за первичную остановку кровотечения', 'Auszählung der Blutplättchen, die für das erste Stillen einer Blutung zuständig sind', 'Kanamanın ilk durdurulmasından sorumlu kan pulcuklarının sayımı', 'Venous or capillary blood draw, counted on an analyzer; if the result is unusual, the laboratory additionally checks the smear', 'Uzimanje venske ili kapilarne krvi, brojanje na analizatoru, a kod neobičnog nalaza laboratorija dodatno provjerava razmaz', 'Узимање венске или капиларне крви, бројање на анализатору, а код необичног налаза лабораторија додатно провјерава размаз', 'Забор венозной или капиллярной крови, подсчёт на анализаторе, при необычном результате лаборатория дополнительно проверяет мазок', 'Entnahme von venösem oder kapillarem Blut, Auszählung am Analysegerät; bei einem ungewöhnlichen Ergebnis prüft das Labor zusätzlich den Ausstrich', 'Venöz veya kapiller kan alınır ve cihazda sayılır; sonuç alışılmadıksa laboratuvar ayrıca yaymayı kontrol eder', 'Bleeding gums and easy bruising, preparation for surgery, monitoring during certain medications, follow-up in blood disorders', 'Krvarenje desni i lako stvaranje modrica, priprema za operaciju, kontrola tokom uzimanja pojedinih lijekova, praćenje kod bolesti krvi', 'Крварење десни и лако стварање модрица, припрема за операцију, контрола током узимања појединих лијекова, праћење код болести крви', 'Кровоточивость дёсен и лёгкое образование синяков, подготовка к операции, контроль при приёме некоторых препаратов, наблюдение при заболеваниях крови', 'Zahnfleischbluten und leichte Blutergüsse, Vorbereitung auf eine Operation, Kontrolle bei bestimmten Medikamenten, Verlaufskontrolle bei Bluterkrankungen', 'Diş eti kanaması ve kolay morarma, ameliyata hazırlık, bazı ilaçların kullanımı sırasında kontrol, kan hastalıklarında izlem', 'No special preparation required; blood is drawn without prolonged tourniquet use, otherwise the result may be distorted', 'Nije potrebna posebna priprema; krv se vadi bez dužeg stezanja vene, jer se nalaz inače može izmijeniti', 'Није потребна посебна припрема; крв се вади без дужег стезања вене, јер се налаз иначе може измијенити', 'Специальной подготовки не требуется; кровь берут без длительного пережатия вены, иначе результат может исказиться', 'Keine besondere Vorbereitung erforderlich; die Entnahme erfolgt ohne längeres Abbinden der Vene, da das Ergebnis sonst verfälscht werden kann', 'Özel bir hazırlık gerektirmez; kan, turnike uzun süre tutulmadan alınır, aksi halde sonuç yanıltıcı olabilir', 'Deviations may be related to infection, inflammation, medication use, bone marrow disorders, or features of the sample, such as cells clumping in the tube. The significance is assessed by a doctor, who may order a repeat test', 'Odstupanja mogu biti povezana sa infekcijom, upalom, uzimanjem lijekova, oboljenjima koštane srži ili osobinama uzorka, na primjer slijepljivanjem ćelija u epruveti. Značaj procjenjuje ljekar, po potrebi uz ponovljenu analizu', 'Одступања могу бити повезана са инфекцијом, упалом, узимањем лијекова, обољењима коштане сржи или особинама узорка, на примјер слијепљивањем ћелија у епрувети. Значај процјењује љекар, по потреби уз поновљену анализу', 'Отклонения могут быть связаны с инфекцией, воспалением, приёмом лекарств, заболеваниями костного мозга или особенностями образца, например слипанием клеток в пробирке. Значимость оценивает врач, при необходимости назначая повторный анализ', 'Abweichungen können mit einer Infektion, Entzündung, Medikamenteneinnahme, Knochenmarkerkrankungen oder Eigenschaften der Probe zusammenhängen, etwa dem Verklumpen der Zellen im Röhrchen. Die Bedeutung beurteilt der Arzt und ordnet bei Bedarf eine Wiederholung an', 'Sapmalar enfeksiyon, iltihap, ilaç kullanımı, kemik iliği hastalıkları veya örneğe özgü durumlarla, örneğin hücrelerin tüpte kümelenmesiyle ilişkili olabilir. Önemini hekim değerlendirir, gerekirse testi yineletir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'oral-glucose-tolerance-test'), 'A challenge test showing how the body handles the absorption of sugar', 'Test opterećenja koji pokazuje kako organizam podnosi unos šećera', 'Тест оптерећења који показује како организам подноси унос шећера', 'Нагрузочная проба, показывающая, как организм справляется с усвоением сахара', 'Ein Belastungstest, der zeigt, wie der Körper mit der Aufnahme von Zucker zurechtkommt', 'Vücudun şekeri ne ölçüde iyi kullandığını gösteren bir yükleme testi', 'Blood is first drawn fasting, then the patient drinks a glucose solution prepared by the laboratory, after which blood is drawn again at set intervals; the whole test takes about two hours, which must be spent at the laboratory', 'Prvo se vadi krv natašte, zatim pacijent popije rastvor glukoze koji priprema laboratorija, a krv se ponovo vadi u zadatim razmacima; cijeli postupak traje oko dva sata koje treba provesti u laboratoriji', 'Прво се вади крв наташте, затим пацијент попије раствор глукозе који припрема лабораторија, а крв се поново вади у задатим размацима; цијели поступак траје око два сата које треба провести у лабораторији', 'Сначала берут кровь натощак, затем пациент выпивает подготовленный лабораторией раствор глюкозы, после чего кровь берут повторно через заданные промежутки; вся проба занимает около двух часов, которые нужно провести в лаборатории', 'Zuerst wird nüchtern Blut abgenommen, dann trinkt die Patientin oder der Patient eine vom Labor vorbereitete Glukoselösung, danach wird in festgelegten Abständen erneut Blut abgenommen; der gesamte Ablauf dauert etwa zwei Stunden, die im Labor verbracht werden', 'Önce aç karnına kan alınır, ardından hasta laboratuvarın hazırladığı glikoz çözeltisini içer ve belirlenen aralıklarla yeniden kan alınır; tüm işlem yaklaşık iki saat sürer ve bu süre laboratuvarda geçirilir', 'Screening for carbohydrate metabolism disorders, testing during pregnancy as directed by a doctor, borderline fasting glucose results', 'Skrining poremećaja metabolizma ugljenih hidrata, ispitivanje trudnica po uputu ljekara, granični nalazi glukoze natašte', 'Скрининг поремећаја метаболизма угљених хидрата, испитивање трудница по упуту љекара, гранични налази глукозе наташте', 'Скрининг нарушений углеводного обмена, обследование беременных по назначению врача, пограничные результаты глюкозы натощак', 'Screening auf Störungen des Kohlenhydratstoffwechsels, Untersuchung in der Schwangerschaft auf ärztliche Anweisung, grenzwertige Nüchternwerte der Glukose', 'Karbonhidrat metabolizması bozukluklarının taranması, hekim yönlendirmesiyle gebelikte inceleme, sınırda açlık glikoz sonuçları', 'Fasting for 8–12 hours, water allowed; usual diet without strict restrictions the day before, and on the day of the test no eating, smoking or physical activity, while during an acute illness the test is postponed', 'Natašte 8–12 sati, dozvoljena je voda; dan ranije uobičajena ishrana bez strogih dijeta, a na dan testa se ne jede, ne puši i ne vježba, dok se tokom akutne bolesti test odlaže', 'Наташте 8–12 сати, дозвољена је вода; дан раније уобичајена исхрана без строгих дијета, а на дан теста се не једе, не пуши и не вјежба, док се током акутне болести тест одлаже', 'Натощак 8–12 часов, разрешена вода; накануне обычное питание без строгих диет, в день пробы нельзя есть, курить и активно двигаться, при остром заболевании пробу переносят', '8–12 Stunden nüchtern, Wasser ist erlaubt; am Vortag normale Ernährung ohne strenge Diät, am Testtag nicht essen, nicht rauchen und sich nicht körperlich anstrengen, bei einer akuten Erkrankung wird der Test verschoben', '8–12 saat açlık, su içilebilir; bir gün önce katı diyet yapmadan olağan beslenme, test günü yememek, sigara içmemek ve fiziksel olarak zorlanmamak, akut hastalık sırasında test ertelenir', 'The result may be related to features of carbohydrate metabolism, a recent illness, certain medications, or pregnancy. The conclusion is made by a doctor, usually taking a repeat test into account', 'Nalaz može biti povezan sa osobinama metabolizma ugljenih hidrata, nedavnom bolešću, uzimanjem pojedinih lijekova ili trudnoćom. Zaključak donosi ljekar, obično uz ponovljeno ispitivanje', 'Налаз може бити повезан са особинама метаболизма угљених хидрата, недавном болешћу, узимањем појединих лијекова или трудноћом. Закључак доноси љекар, обично уз поновљено испитивање', 'Результат может быть связан с особенностями углеводного обмена, недавней болезнью, приёмом некоторых препаратов или беременностью. Вывод делает врач, обычно с учётом повторного исследования', 'Das Ergebnis kann mit Besonderheiten des Kohlenhydratstoffwechsels, einer kürzlichen Erkrankung, bestimmten Medikamenten oder einer Schwangerschaft zusammenhängen. Die Schlussfolgerung zieht der Arzt, meist unter Berücksichtigung einer Wiederholung', 'Sonuç karbonhidrat metabolizmasının özellikleri, yakın zamanda geçirilen bir hastalık, bazı ilaçlar veya gebelikle ilişkili olabilir. Kararı hekim, genellikle testin tekrarını da dikkate alarak verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-cervical-biopsy'), 'Microscopic examination of a piece of cervical tissue obtained by biopsy', 'Mikroskopski pregled djelića tkiva grlića materice uzetog biopsijom', 'Микроскопски преглед дјелића ткива грлића материце узетог биопсијом', 'Микроскопическое исследование кусочка ткани шейки матки, взятого при биопсии', 'Mikroskopische Untersuchung eines bei der Biopsie entnommenen Gewebestücks des Gebärmutterhalses', 'Biyopsiyle alınan rahim ağzı dokusunun mikroskopla incelenmesi', 'The sample is fixed, embedded in paraffin, cut into thin sections, stained and examined under a microscope; the biopsy itself is performed separately by a gynaecologist', 'Uzorak se fiksira, ukalupljuje u parafin, reže na tanke presjeke, boji i pregleda pod mikroskopom; samu biopsiju ginekolog radi zasebno', 'Узорак се фиксира, укалупљује у парафин, реже на танке пресјеке, боји и прегледа под микроскопом; саму биопсију гинеколог ради засебно', 'Материал фиксируют, заливают в парафин, режут на тонкие срезы, окрашивают и изучают под микроскопом; саму биопсию гинеколог выполняет отдельно', 'Das Material wird fixiert, in Paraffin eingebettet, in dünne Schnitte geschnitten, gefärbt und unter dem Mikroskop beurteilt; die Biopsie selbst nimmt die Frauenärztin oder der Frauenarzt gesondert vor', 'Örnek tespit edilir, parafine gömülür, ince kesitler alınır, boyanır ve mikroskopta değerlendirilir; biyopsi işlemini kadın doğum hekimi ayrıca yapar', 'Changes seen at colposcopy, an abnormal cytology smear, persistently detected high-risk HPV, follow-up after treatment of the cervix', 'Promjene uočene na kolposkopiji, odstupanja u citološkom brisu, uporno prisustvo HPV visokog rizika, kontrola poslije liječenja grlića materice', 'Промјене уочене на колпоскопији, одступања у цитолошком брису, упорно присуство HPV високог ризика, контрола послије лијечења грлића материце', 'Изменения, замеченные при кольпоскопии, отклонения в цитологическом мазке, стойкое выявление ВПЧ высокого риска, контроль после лечения шейки матки', 'Auffälligkeiten bei der Kolposkopie, abweichender zytologischer Abstrich, anhaltender Nachweis von Hochrisiko-HPV, Kontrolle nach Behandlung am Gebärmutterhals', 'Kolposkopide görülen değişiklikler, sitolojik yaymada sapma, yüksek riskli HPV''nin sürekli saptanması, rahim ağzı tedavisi sonrası kontrol', 'Preparation applies to the biopsy procedure and is discussed with the gynaecologist; the laboratory stage requires nothing from the patient', 'Priprema se odnosi na sam zahvat biopsije i dogovara se sa ginekologom; za laboratorijski dio pacijentkinja ne radi ništa', 'Припрема се односи на сам захват биопсије и договара се са гинекологом; за лабораторијски дио пацијенткиња не ради ништа', 'Подготовка относится к процедуре биопсии и обсуждается с гинекологом; на лабораторном этапе от пациентки ничего не требуется', 'Die Vorbereitung betrifft den Eingriff selbst und wird mit der Frauenärztin oder dem Frauenarzt besprochen; für den Laborteil ist nichts zu tun', 'Hazırlık biyopsi işlemiyle ilgilidir ve kadın doğum hekimiyle konuşulur; laboratuvar aşamasında hastadan bir şey istenmez', 'The report describes the nature of the tissue changes, from inflammatory to those needing follow-up or treatment. What this means in a particular case and what comes next is decided by the gynaecologist', 'Nalaz opisuje prirodu promjena u tkivu, od upalnih do onih koje traže praćenje ili liječenje. Šta to znači u konkretnom slučaju i koji su sljedeći koraci, određuje ginekolog', 'Налаз описује природу промјена у ткиву, од упалних до оних које траже праћење или лијечење. Шта то значи у конкретном случају и који су сљедећи кораци, одређује гинеколог', 'Заключение описывает характер изменений в ткани — от воспалительных до требующих наблюдения или лечения. Что это значит в конкретном случае и какие шаги нужны дальше, определяет гинеколог', 'Der Befund beschreibt die Art der Gewebeveränderungen, von entzündlich bis hin zu solchen, die Kontrolle oder Behandlung erfordern. Was das im Einzelfall bedeutet und wie es weitergeht, entscheidet die Frauenärztin oder der Frauenarzt', 'Rapor, dokudaki değişikliklerin niteliğini iltihabi olandan izlem ya da tedavi gerektirene kadar tanımlar. Bunun o kişide ne anlama geldiğine ve sonraki adımlara kadın doğum hekimi karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-liver-biopsy'), 'Microscopic examination of a core of liver tissue obtained by needle biopsy', 'Mikroskopski pregled isječka tkiva jetre dobijenog punkcionom biopsijom', 'Микроскопски преглед исјечка ткива јетре добијеног пункционом биопсијом', 'Микроскопическое исследование столбика ткани печени, полученного при пункционной биопсии', 'Mikroskopische Untersuchung eines durch Punktionsbiopsie gewonnenen Lebergewebszylinders', 'İğne biyopsisiyle alınan karaciğer doku örneğinin mikroskopla incelenmesi', 'The material is fixed, embedded in paraffin, cut into thin sections and stained, including special stains that show connective tissue; the puncture itself is performed separately by a doctor, usually under ultrasound guidance', 'Uzorak se fiksira, ukalupljuje u parafin, reže na tanke presjeke i boji, uz posebna bojenja za procjenu vezivnog tkiva; samu punkciju ljekar radi zasebno, najčešće pod kontrolom ultrazvuka', 'Узорак се фиксира, укалупљује у парафин, реже на танке пресјеке и боји, уз посебна бојења за процјену везивног ткива; саму пункцију љекар ради засебно, најчешће под контролом ултразвука', 'Материал фиксируют, заливают в парафин, режут на тонкие срезы и окрашивают, в том числе специальными красителями для оценки соединительной ткани; саму пункцию врач выполняет отдельно, обычно под контролем УЗИ', 'Das Material wird fixiert, in Paraffin eingebettet, in dünne Schnitte geschnitten und gefärbt, auch mit Spezialfärbungen zur Beurteilung des Bindegewebes; die Punktion selbst führt der Arzt gesondert durch, meist unter Ultraschallkontrolle', 'Örnek tespit edilir, parafine gömülür, ince kesitler alınır ve bağ dokusunu gösteren özel boyalar dahil olmak üzere boyanır; biyopsi işlemini hekim genellikle ultrason eşliğinde ayrıca yapar', 'Persistently elevated liver values without a clear cause, chronic viral hepatitis, assessment of fibrosis and fatty change, clarifying the cause of chronic liver damage, follow-up after transplantation', 'Uporno povišeni jetreni pokazatelji bez jasnog uzroka, hronični virusni hepatitisi, procjena stepena fibroze i masne promjene, razjašnjenje uzroka hroničnog oštećenja jetre, praćenje poslije transplantacije', 'Упорно повишени јетрени показатељи без јасног узрока, хронични вирусни хепатитиси, процјена степена фиброзе и масне промјене, разјашњење узрока хроничног оштећења јетре, праћење послије трансплантације', 'Стойкое повышение печёночных показателей без ясной причины, хронические вирусные гепатиты, оценка выраженности фиброза и жирового перерождения, уточнение причины хронического поражения печени, наблюдение после трансплантации', 'Dauerhaft erhöhte Leberwerte ohne klare Ursache, chronische Virushepatitiden, Beurteilung von Fibrose und Verfettung, Abklärung einer chronischen Leberschädigung, Verlaufskontrolle nach Transplantation', 'Nedeni belirsiz sürekli yüksek karaciğer değerleri, kronik viral hepatitler, fibroz ve yağlanma derecesinin değerlendirilmesi, kronik karaciğer hasarının nedeninin araştırılması, nakil sonrası izlem', 'Preparation concerns the puncture: clotting parameters are checked beforehand, and only the doctor decides whether blood-thinning medicines are paused', 'Priprema se odnosi na samu punkciju: unaprijed se rade parametri koagulacije, a o privremenom prekidu lijekova koji razrjeđuju krv odlučuje isključivo ljekar', 'Припрема се односи на саму пункцију: унапријед се раде параметри коагулације, а о привременом прекиду лијекова који разрјеђују крв одлучује искључиво љекар', 'Подготовка относится к самой пункции: заранее сдают показатели свёртывания крови, а вопрос о временной отмене препаратов, разжижающих кровь, решает только врач', 'Die Vorbereitung betrifft die Punktion: Gerinnungswerte werden vorab bestimmt, über ein vorübergehendes Pausieren blutverdünnender Medikamente entscheidet ausschließlich der Arzt', 'Hazırlık biyopsi işlemiyle ilgilidir: önceden pıhtılaşma testleri yapılır, kan sulandırıcı ilaçlara ara verilip verilmeyeceğine yalnızca hekim karar verir', 'The report describes the extent and nature of the changes in liver tissue. The treating doctor matches it with laboratory results and the clinical picture and decides on further management', 'Nalaz opisuje stepen i prirodu promjena u tkivu jetre. Sa analizama i kliničkom slikom poredi ga i dalji postupak određuje ljekar koji vodi liječenje', 'Налаз описује степен и природу промјена у ткиву јетре. Са анализама и клиничком сликом пореди га и даљи поступак одређује љекар који води лијечење', 'Заключение описывает степень и характер изменений ткани печени. Сопоставляет его с анализами и клинической картиной и определяет дальнейшую тактику лечащий врач', 'Der Befund beschreibt Ausmaß und Art der Veränderungen im Lebergewebe. Die behandelnde Ärztin oder der behandelnde Arzt ordnet ihn den Laborwerten und dem klinischen Bild zu und legt das weitere Vorgehen fest', 'Rapor karaciğer dokusundaki değişikliklerin derecesini ve niteliğini tanımlar. Sonucu laboratuvar bulguları ve klinik tabloyla birleştirip izlenecek yolu tedaviyi yürüten hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-vulvar-biopsy'), 'Microscopic examination of a sample of vulvar skin and mucosa taken by biopsy', 'Mikroskopski pregled isječka kože i sluznice vulve uzetog biopsijom', 'Микроскопски преглед исјечка коже и слузнице вулве узетог биопсијом', 'Микроскопическое исследование участка кожи и слизистой вульвы, взятого при биопсии', 'Mikroskopische Untersuchung einer per Biopsie entnommenen Probe von Haut und Schleimhaut der Vulva', 'Biyopsiyle alınan vulva derisi ve mukozası örneğinin mikroskopla incelenmesi', 'A small tissue fragment taken by the gynaecologist under local anaesthesia is fixed, embedded in paraffin, sectioned, stained and examined under a microscope', 'Mali komadić tkiva koji ginekolog uzme u lokalnoj anesteziji fiksira se, ukalupljuje u parafin, reže na presjeke, boji i pregleda pod mikroskopom', 'Мали комадић ткива који гинеколог узме у локалној анестезији фиксира се, укалупљује у парафин, реже на пресјеке, боји и прегледа под микроскопом', 'Небольшой фрагмент ткани, взятый гинекологом под местным обезболиванием, фиксируют, заливают в парафин, режут на срезы, окрашивают и изучают под микроскопом', 'Das unter örtlicher Betäubung entnommene kleine Gewebestück wird fixiert, in Paraffin eingebettet, geschnitten, gefärbt und unter dem Mikroskop beurteilt', 'Kadın doğum hekiminin lokal anesteziyle aldığı küçük doku parçası tespit edilir, parafine gömülür, kesitlenir, boyanır ve mikroskopta incelenir', 'Long-lasting itching and burning of the vulva, changes in skin colour and texture, persistent patches and nodules, non-healing sores, clarifying the nature of chronic skin changes, follow-up after treatment', 'Dugotrajan svrab i peckanje u predjelu vulve, promjene boje i čvrstine kože, uporne mrlje i kvržice, ranice koje ne zarastaju, razjašnjenje prirode hroničnih promjena na koži, kontrola poslije liječenja', 'Дуготрајан свраб и пецкање у предјелу вулве, промјене боје и чврстине коже, упорне мрље и квржице, ранице које не зарастају, разјашњење природе хроничних промјена на кожи, контрола послије лијечења', 'Длительный зуд и жжение в области вульвы, изменения цвета и плотности кожи, стойкие пятна и узелки, незаживающие ранки, уточнение природы хронических кожных изменений, контроль после лечения', 'Anhaltender Juckreiz und Brennen im Vulvabereich, Veränderungen von Hautfarbe und Hautbeschaffenheit, hartnäckige Flecken und Knötchen, nicht heilende Stellen, Abklärung chronischer Hautveränderungen, Kontrolle nach Behandlung', 'Vulva bölgesinde uzun süreli kaşıntı ve yanma, deri renginde ve dokusunda değişiklik, geçmeyen lekeler ve kabartılar, iyileşmeyen yaralar, kronik deri değişikliklerinin nedeninin araştırılması, tedavi sonrası kontrol', 'Preparation concerns the biopsy procedure: on that day avoid creams and antiseptic hygiene products, the gynaecologist explains the rest', 'Priprema se odnosi na sam zahvat: na dan biopsije ne koristiti kreme i antiseptična higijenska sredstva, ostalo dogovara ginekolog', 'Припрема се односи на сам захват: на дан биопсије не користити креме и антисептична хигијенска средства, остало договара гинеколог', 'Подготовка касается процедуры биопсии: в день вмешательства не пользоваться кремами и антисептическими средствами гигиены, остальное уточняет гинеколог', 'Die Vorbereitung betrifft den Eingriff: am Tag der Biopsie keine Cremes und keine antiseptischen Pflegeprodukte verwenden, alles Weitere bespricht die Frauenärztin oder der Frauenarzt', 'Hazırlık işlemle ilgilidir: biyopsi günü krem ve antiseptik hijyen ürünleri kullanılmaz, gerisini kadın doğum hekimi anlatır', 'The report describes the nature of the changes, inflammatory, dystrophic or requiring further follow-up and treatment. The gynaecologist interprets the result and decides on the next steps', 'Nalaz opisuje prirodu promjena, upalne, distrofične ili one koje traže dalje praćenje i liječenje. Rezultat tumači i sljedeće korake određuje ginekolog', 'Налаз описује природу промјена, упалне, дистрофичне или оне које траже даље праћење и лијечење. Резултат тумачи и сљедеће кораке одређује гинеколог', 'Заключение описывает характер изменений — воспалительные, дистрофические или требующие дальнейшего наблюдения и лечения. Трактует результат и назначает следующие шаги гинеколог', 'Der Befund beschreibt die Art der Veränderungen, entzündlich, dystrophisch oder weiter kontrollbedürftig. Die Deutung und das weitere Vorgehen legt die Frauenärztin oder der Frauenarzt fest', 'Rapor değişikliklerin niteliğini iltihabi, distrofik ya da izlem ve tedavi gerektiren olarak tanımlar. Sonucu yorumlayıp sonraki adımları kadın doğum hekimi belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protia-allergy-q64-inhalation-panel-64-allergens'), 'A panel of specific IgE against 64 inhaled allergens: tree, grass and weed pollen, house dust mites, moulds, animal dander and hair', 'Panel specifičnih IgE na 64 inhalaciona alergena: polen drveća, trava i korova, grinje kućne prašine, plijesni, epitel i dlaka životinja', 'Панел специфичних IgE на 64 инхалациона алергена: полен дрвећа, трава и корова, гриње кућне прашине, плијесни, епител и длака животиња', 'Панель специфических IgE к 64 вдыхаемым аллергенам: пыльца деревьев, трав и сорняков, клещи домашней пыли, плесневые грибы, эпителий и шерсть животных', 'Panel spezifischer IgE gegen 64 Inhalationsallergene: Baum-, Gras- und Kräuterpollen, Hausstaubmilben, Schimmelpilze, Tierepithelien und Tierhaare', 'Ağaç, çayır ve yabani ot polenleri, ev tozu akarları, küfler, hayvan epiteli ve tüyü gibi 64 solunum alerjenine karşı özgül IgE paneli', 'A single venous blood draw, the laboratory determines the whole set of parameters from one sample', 'Jedno vađenje venske krvi, laboratorija iz istog uzorka određuje čitav skup pokazatelja', 'Једно вађење венске крви, лабораторија из истог узорка одређује читав скуп показатеља', 'Однократный забор венозной крови, из одной пробы лаборатория определяет сразу весь набор показателей', 'Eine einzige venöse Blutentnahme, aus derselben Probe bestimmt das Labor den gesamten Parametersatz', 'Tek seferde venöz kan alınır, laboratuvar aynı örnekten tüm parametreleri çalışır', 'Seasonal or year-round runny nose, sneezing, blocked nose, itchy eyes, suspected allergic asthma, looking for the trigger of flare-ups, situations where skin testing is not advisable', 'Sezonska ili cjelogodišnja kijavica, kijanje, zapušen nos, svrab očiju, sumnja na alergijsku astmu, traženje uzroka pogoršanja, situacije kada kožni testovi nisu poželjni', 'Сезонска или цјелогодишња кијавица, кијање, запушен нос, свраб очију, сумња на алергијску астму, тражење узрока погоршања, ситуације када кожни тестови нису пожељни', 'Сезонный или круглогодичный насморк, чихание, заложенность носа, зуд глаз, подозрение на аллергическую астму, поиск причины обострений, ситуации, когда кожные пробы нежелательны', 'Saisonaler oder ganzjähriger Schnupfen, Niesen, verstopfte Nase, juckende Augen, Verdacht auf allergisches Asthma, Suche nach dem Auslöser von Beschwerdeschüben, Situationen, in denen Hauttests nicht infrage kommen', 'Mevsimsel ya da yıl boyu süren burun akıntısı, hapşırma, burun tıkanıklığı, göz kaşıntısı, alerjik astım şüphesi, alevlenmelerin nedeninin aranması, deri testinin uygun olmadığı durumlar', 'No special preparation is needed and antihistamines do not have to be stopped, they do not affect a blood test', 'Posebna priprema nije potrebna, antihistaminike nije potrebno prekidati jer ne utiču na nalaz iz krvi', 'Посебна припрема није потребна, антихистаминике није потребно прекидати јер не утичу на налаз из крви', 'Специальной подготовки не требуется, антигистаминные препараты отменять не нужно — на анализ крови они не влияют', 'Keine besondere Vorbereitung nötig, Antihistaminika müssen nicht abgesetzt werden, sie beeinflussen den Bluttest nicht', 'Özel hazırlık gerekmez, antihistaminiklerin kesilmesine gerek yoktur, kan testini etkilemezler', 'Detected specific IgE indicates sensitisation to an allergen and by itself is not the same as an allergy. An allergist compares the set of results with the symptoms and living conditions', 'Nalaz specifičnih IgE govori o senzibilizaciji na alergen i sam po sebi ne znači alergiju. Skup pokazatelja sa tegobama i uslovima života poredi ljekar alergolog', 'Налаз специфичних IgE говори о сензибилизацији на алерген и сам по себи не значи алергију. Скуп показатеља са тегобама и условима живота пореди љекар алерголог', 'Выявление специфических IgE говорит о сенсибилизации к аллергену и само по себе не равно аллергии. Сопоставляет набор показателей с симптомами и условиями жизни врач-аллерголог', 'Nachweisbare spezifische IgE zeigen eine Sensibilisierung gegenüber einem Allergen an und bedeuten für sich genommen noch keine Allergie. Die Zusammenschau mit Beschwerden und Lebensumständen nimmt die Allergologin oder der Allergologe vor', 'Özgül IgE saptanması alerjene duyarlanmayı gösterir, tek başına alerji anlamına gelmez. Sonuç kümesini şikayetler ve yaşam koşullarıyla birlikte alerji uzmanı değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protia-allergy-q64-nutritive-panel-72-allergens'), 'A panel of specific IgE against 72 food allergens: milk and egg, cereals, nuts, fish and seafood, vegetables, fruit, spices', 'Panel specifičnih IgE na 72 nutritivna alergena: mlijeko i jaje, žitarice, orašasti plodovi, riba i morski plodovi, povrće, voće, začini', 'Панел специфичних IgE на 72 нутритивна алергена: млијеко и јаје, житарице, орашасти плодови, риба и морски плодови, поврће, воће, зачини', 'Панель специфических IgE к 72 пищевым аллергенам: молоко и яйцо, злаки, орехи, рыба и морепродукты, овощи, фрукты, специи', 'Panel spezifischer IgE gegen 72 Nahrungsmittelallergene: Milch und Ei, Getreide, Nüsse, Fisch und Meeresfrüchte, Gemüse, Obst, Gewürze', 'Süt ve yumurta, tahıllar, sert kabuklu yemişler, balık ve deniz ürünleri, sebze, meyve ve baharatlar gibi 72 besin alerjenine karşı özgül IgE paneli', 'The whole list of parameters is determined from a single venous blood sample, no repeat visits are needed', 'Iz jednog uzorka venske krvi određuje se cijeli spisak pokazatelja, bez ponovnih dolazaka', 'Из једног узорка венске крви одређује се цијели списак показатеља, без поновних долазака', 'Из одной пробы венозной крови определяют весь список показателей, повторные визиты не нужны', 'Aus einer einzigen venösen Blutprobe wird die gesamte Liste der Parameter bestimmt, weitere Termine entfallen', 'Tek bir venöz kan örneğinden tüm parametreler çalışılır, tekrar gelmek gerekmez', 'Hives, swelling, itching and rashes after meals, flare-ups of atopic dermatitis, stomach and bowel complaints after certain foods, planning a diet together with a doctor', 'Koprivnjača, otoci, svrab i osip poslije jela, pogoršanja atopijskog dermatitisa, tegobe želuca i crijeva poslije određenih namirnica, planiranje ishrane zajedno sa ljekarom', 'Копривњача, отоци, свраб и осип послије јела, погоршања атопијског дерматитиса, тегобе желуца и цријева послије одређених намирница, планирање исхране заједно са љекаром', 'Крапивница, отёки, зуд и высыпания после еды, обострения атопического дерматита, жалобы со стороны желудка и кишечника после определённых продуктов, подбор рациона вместе с врачом', 'Nesselsucht, Schwellungen, Juckreiz und Hautausschlag nach dem Essen, Schübe einer Neurodermitis, Magen-Darm-Beschwerden nach bestimmten Lebensmitteln, Ernährungsplanung gemeinsam mit dem Arzt', 'Yemek sonrası kurdeşen, şişlik, kaşıntı ve döküntü, atopik dermatit alevlenmeleri, belirli besinlerden sonra mide ve bağırsak şikayetleri, hekimle birlikte beslenme planlaması', 'No special preparation is required and there is no need to avoid suspected foods beforehand, the test detects antibodies rather than a reaction to a recent meal', 'Posebna priprema nije potrebna, sumnjive namirnice nije potrebno izbjegavati prije vađenja krvi jer test otkriva antitijela, a ne reakciju na skorašnji obrok', 'Посебна припрема није потребна, сумњиве намирнице није потребно избјегавати прије вађења крви јер тест открива антитијела, а не реакцију на скорашњи оброк', 'Специальной подготовки не требуется, исключать подозрительные продукты перед сдачей не нужно — тест выявляет антитела, а не реакцию на недавнюю еду', 'Keine besondere Vorbereitung nötig, verdächtige Lebensmittel müssen vorher nicht gemieden werden, der Test weist Antikörper nach und nicht die Reaktion auf eine kürzliche Mahlzeit', 'Özel hazırlık gerekmez, şüpheli besinleri önceden kesmeye gerek yoktur, test yakın zamanda yenen yemeğe verilen tepkiyi değil antikorları gösterir', 'Detected IgE point to sensitisation, but tolerance of a food is judged only together with the history of reactions and, if needed, a trial diet supervised by an allergist', 'Nađena IgE ukazuju na senzibilizaciju, ali se podnošljivost namirnice procjenjuje samo uz istoriju reakcija i po potrebi probnu ishranu pod nadzorom alergologa', 'Нађена IgE указују на сензибилизацију, али се подношљивост намирнице процјењује само уз историју реакција и по потреби пробну исхрану под надзором алерголога', 'Найденные IgE указывают на сенсибилизацию, но переносимость продукта оценивают только вместе с историей реакций, при необходимости — пробной диетой под наблюдением врача-аллерголога', 'Nachgewiesene IgE sprechen für eine Sensibilisierung, die Verträglichkeit eines Lebensmittels wird jedoch nur zusammen mit der Vorgeschichte der Reaktionen und gegebenenfalls einer ärztlich begleiteten Probediät beurteilt', 'Saptanan IgE duyarlanmayı gösterir, ancak bir besinin tolere edilip edilmediği yalnızca tepki öyküsüyle ve gerekirse alerji uzmanı gözetiminde deneme diyetiyle değerlendirilir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protia-allergy-q64s-combined-panel-63-allergens'), 'A combined panel of specific IgE against 63 allergens, covering both inhaled and food items in one test', 'Kombinovani panel specifičnih IgE na 63 alergena, u jednom pregledu i inhalacione i nutritivne stavke', 'Комбиновани панел специфичних IgE на 63 алергена, у једном прегледу и инхалационе и нутритивне ставке', 'Комбинированная панель специфических IgE к 63 аллергенам — в одном исследовании и вдыхаемые, и пищевые позиции', 'Kombiniertes Panel spezifischer IgE gegen 63 Allergene, in einer Untersuchung sowohl Inhalations- als auch Nahrungsmittelallergene', 'Tek incelemede hem solunum hem besin alerjenlerini kapsayan, 63 alerjene karşı özgül IgE kombine paneli', 'One venous blood sample, the parameters are measured in parallel on a single test system', 'Jedan uzorak venske krvi, pokazatelji se određuju uporedo na jednom test-sistemu', 'Један узорак венске крви, показатељи се одређују упоредо на једном тест-систему', 'Одна проба венозной крови, показатели определяются параллельно на единой тест-системе', 'Eine venöse Blutprobe, die Parameter werden parallel auf einem Testsystem bestimmt', 'Tek bir venöz kan örneği alınır, parametreler tek test sisteminde eş zamanlı çalışılır', 'Complaints that are hard to trace to a single source: rhinitis together with skin rash, year-round symptoms without clear seasonality, first work-up for suspected allergy', 'Tegobe koje je teško vezati za jedan izvor: kijavica zajedno sa osipom, cjelogodišnji simptomi bez jasne sezonalnosti, prva obrada kod sumnje na alergiju', 'Тегобе које је тешко везати за један извор: кијавица заједно са осипом, цјелогодишњи симптоми без јасне сезоналности, прва обрада код сумње на алергију', 'Жалобы, которые трудно связать с одним источником: сочетание насморка и высыпаний, круглогодичные симптомы без явной сезонности, первичное обследование при подозрении на аллергию', 'Beschwerden, die sich schwer auf eine Quelle zurückführen lassen: Schnupfen zusammen mit Hautausschlag, ganzjährige Symptome ohne klare Saison, Erstabklärung bei Allergieverdacht', 'Tek bir kaynağa bağlanması güç şikayetler: burun akıntısının döküntüyle birlikte olması, mevsim ayrımı olmayan yıl boyu süren belirtiler, alerji şüphesinde ilk değerlendirme', 'No special preparation is needed, meals and antihistamines do not affect the result', 'Posebna priprema nije potrebna, obrok i antihistaminici ne utiču na nalaz', 'Посебна припрема није потребна, оброк и антихистаминици не утичу на налаз', 'Специальной подготовки не требуется, приём пищи и антигистаминных препаратов на результат не влияет', 'Keine besondere Vorbereitung nötig, Mahlzeiten und Antihistaminika beeinflussen das Ergebnis nicht', 'Özel hazırlık gerekmez, yemek ve antihistaminikler sonucu etkilemez', 'The panel shows which allergen groups there is sensitisation to. Which of the findings actually matter for a particular person is decided by an allergist based on symptoms, adding further tests if necessary', 'Panel pokazuje na koje grupe alergena postoji senzibilizacija. Koje su od nađenih stavki zaista značajne za konkretnu osobu, prema tegobama procjenjuje alergolog i po potrebi dopunjava obradu', 'Панел показује на које групе алергена постоји сензибилизација. Које су од нађених ставки заиста значајне за конкретну особу, према тегобама процјењује алерголог и по потреби допуњава обраду', 'Панель показывает, к каким группам аллергенов есть сенсибилизация. Какие из найденных позиций действительно значимы для конкретного человека, решает врач-аллерголог по симптомам, при необходимости дополняя обследование', 'Das Panel zeigt, gegenüber welchen Allergengruppen eine Sensibilisierung besteht. Welche Befunde für die einzelne Person tatsächlich bedeutsam sind, entscheidet die Allergologin oder der Allergologe anhand der Beschwerden und ergänzt bei Bedarf weitere Untersuchungen', 'Panel hangi alerjen gruplarına duyarlanma olduğunu gösterir. Bulunanlardan hangilerinin o kişi için gerçekten önemli olduğuna alerji uzmanı şikayetlere göre karar verir, gerekirse incelemeyi genişletir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protia-allergy-q96m-combined-panel-107-allergens'), 'An extended combined panel of specific IgE against 107 allergens, the widest set in this line, inhaled and food items together', 'Prošireni kombinovani panel specifičnih IgE na 107 alergena, najširi skup u ovoj liniji, inhalacione i nutritivne stavke zajedno', 'Проширени комбиновани панел специфичних IgE на 107 алергена, најшири скуп у овој линији, инхалационе и нутритивне ставке заједно', 'Расширенная комбинированная панель специфических IgE к 107 аллергенам — самый широкий набор в этой линейке, вдыхаемые и пищевые позиции вместе', 'Erweitertes kombiniertes Panel spezifischer IgE gegen 107 Allergene, der umfangreichste Satz dieser Reihe, Inhalations- und Nahrungsmittelallergene zusammen', 'Bu serinin en geniş kapsamlı seçeneği olan, solunum ve besin alerjenlerini birlikte içeren 107 alerjene karşı özgül IgE kombine paneli', 'A single venous blood draw, the whole panel is run from one sample with no extra visits', 'Jedno vađenje venske krvi, cijeli panel se radi iz istog uzorka bez dodatnih dolazaka', 'Једно вађење венске крви, цијели панел се ради из истог узорка без додатних долазака', 'Однократный забор венозной крови, вся панель выполняется из одной пробы без дополнительных визитов', 'Eine einzige venöse Blutentnahme, das gesamte Panel wird aus einer Probe ohne weitere Termine bearbeitet', 'Tek seferde venöz kan alınır, panelin tamamı aynı örnekten çalışılır, ek randevu gerekmez', 'Multiple or changing complaints, an unsuccessful search for the trigger with narrower panels, planning treatment with an allergist, work-up before specific immunotherapy at the doctor''s discretion', 'Brojne ili promjenljive tegobe, neuspješno traženje uzroka užim panelima, planiranje liječenja kod alergologa, obrada prije specifične imunoterapije po odluci ljekara', 'Бројне или промјенљиве тегобе, неуспјешно тражење узрока ужим панелима, планирање лијечења код алерголога, обрада прије специфичне имунотерапије по одлуци љекара', 'Множественные или меняющиеся жалобы, безуспешный поиск причины по узким панелям, планирование лечения у аллерголога, обследование перед специфической иммунотерапией по решению врача', 'Vielfältige oder wechselnde Beschwerden, erfolglose Ursachensuche mit kleineren Panels, Therapieplanung beim Allergologen, Abklärung vor einer spezifischen Immuntherapie nach ärztlicher Entscheidung', 'Çok sayıda ya da değişken şikayet, dar panellerle nedenin bulunamaması, alerji uzmanıyla tedavi planlaması, hekim kararıyla özgül immünoterapi öncesi değerlendirme', 'No special preparation is required, the sample can be taken at any time of day', 'Posebna priprema nije potrebna, krv se može dati u bilo koje doba dana', 'Посебна припрема није потребна, крв се може дати у било које доба дана', 'Специальной подготовки не требуется, сдать кровь можно в любое время дня', 'Keine besondere Vorbereitung nötig, die Blutentnahme ist zu jeder Tageszeit möglich', 'Özel hazırlık gerekmez, kan günün herhangi bir saatinde alınabilir', 'The wider the panel, the more often results appear that have no clinical meaning, since sensitisation is not the same as an allergy. An allergist selects the relevant findings and plans the next steps', 'Što je panel širi, to se češće nađu pokazatelji bez kliničkog značaja jer senzibilizacija nije isto što i alergija. Značajne stavke izdvaja i dalje korake planira alergolog', 'Што је панел шири, то се чешће нађу показатељи без клиничког значаја јер сензибилизација није исто што и алергија. Значајне ставке издваја и даље кораке планира алерголог', 'Чем шире панель, тем чаще находятся показатели без клинического значения: сенсибилизация не равна аллергии. Значимые позиции отбирает и дальнейшие шаги планирует врач-аллерголог', 'Je breiter das Panel, desto häufiger finden sich Werte ohne klinische Bedeutung, denn eine Sensibilisierung ist nicht gleich einer Allergie. Welche Befunde relevant sind und wie es weitergeht, entscheidet die Allergologin oder der Allergologe', 'Panel genişledikçe klinik karşılığı olmayan sonuçlar daha sık çıkar, çünkü duyarlanma alerjiyle aynı şey değildir. Anlamlı bulguları seçip sonraki adımları alerji uzmanı planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'bordetella-pertussis-pcr'), 'A molecular test that detects the DNA of Bordetella pertussis, the bacterium causing whooping cough', 'Molekularni test koji otkriva DNK bakterije Bordetella pertussis, uzročnika velikog kašlja', 'Молекуларни тест који открива ДНК бактерије Bordetella pertussis, узрочника великог кашља', 'Молекулярный тест, выявляющий ДНК бактерии Bordetella pertussis — возбудителя коклюша', 'Molekularer Test zum Nachweis der DNA von Bordetella pertussis, dem Erreger des Keuchhustens', 'Boğmaca etkeni Bordetella pertussis bakterisinin DNA''sını saptayan moleküler test', 'A thin swab is taken from the nasopharynx, sampling itself takes less than a minute, the DNA is detected by PCR in the laboratory', 'Bris tankim štapićem iz nazofarinksa, samo uzimanje traje kraće od minuta, DNK se određuje metodom PCR u laboratoriji', 'Брис танким штапићем из назофаринкса, само узимање траје краће од минута, ДНК се одређује методом ПЦР у лабораторији', 'Мазок тонким тампоном из носоглотки, сам забор занимает меньше минуты, ДНК определяют методом ПЦР в лаборатории', 'Abstrich mit einem dünnen Tupfer aus dem Nasenrachenraum, die Entnahme dauert weniger als eine Minute, die DNA wird im Labor mittels PCR bestimmt', 'Genizden ince çubukla sürüntü alınır, örnek alma bir dakikadan kısa sürer, DNA laboratuvarda PCR yöntemiyle belirlenir', 'Prolonged coughing fits, a cough lasting more than two weeks, especially in children and teenagers, cough after contact with someone with whooping cough, testing of household contacts', 'Dugotrajan kašalj u napadima, kašalj duži od dvije sedmice, naročito kod djece i adolescenata, kašalj poslije kontakta sa oboljelim od velikog kašlja, obrada kontakata u porodici', 'Дуготрајан кашаљ у нападима, кашаљ дужи од двије седмице, нарочито код дјеце и адолесцената, кашаљ послије контакта са обољелим од великог кашља, обрада контаката у породици', 'Затяжной приступообразный кашель, кашель дольше двух недель, особенно у детей и подростков, кашель после контакта с больным коклюшем, обследование контактных в семье', 'Anhaltende Hustenanfälle, Husten über mehr als zwei Wochen, besonders bei Kindern und Jugendlichen, Husten nach Kontakt zu einer erkrankten Person, Abklärung von Kontaktpersonen im Haushalt', 'Nöbetler halinde süren uzun öksürük, iki haftadan uzun süren öksürük, özellikle çocuk ve ergenlerde, boğmacalı biriyle temas sonrası öksürük, ev içi temaslıların incelenmesi', 'For about an hour before the swab do not eat, drink or rinse the throat and do not use nasal sprays or drops; the interval after starting antibiotics is set by the doctor', 'Otprilike sat prije brisa ne jesti, ne piti i ne ispirati grlo, ne koristiti sprejeve i kapi za nos; razmak poslije početka antibiotika određuje ljekar', 'Отприлике сат прије бриса не јести, не пити и не испирати грло, не користити спрејеве и капи за нос; размак послије почетка антибиотика одређује љекар', 'Примерно за час до мазка не есть, не пить и не полоскать горло, не пользоваться спреями и каплями в нос; интервал после начала антибиотиков уточняет врач', 'Etwa eine Stunde vor dem Abstrich nicht essen, trinken oder gurgeln und keine Nasensprays oder Nasentropfen verwenden; den Abstand nach Beginn einer Antibiotikatherapie legt der Arzt fest', 'Sürüntüden yaklaşık bir saat önce yememek, içmemek ve gargara yapmamak, burun spreyi ve damlası kullanmamak gerekir; antibiyotik başlandıysa bekleme süresini hekim belirler', 'Detected DNA means the bacterium is present in the sample. Late in the illness and after antibiotics the test can be negative even with whooping cough, so the result is interpreted by a doctor together with the clinical picture', 'Nalaz DNK znači da je bakterija prisutna u uzorku. U kasnijoj fazi bolesti i poslije antibiotika test može biti negativan i kod velikog kašlja, pa rezultat tumači ljekar uz kliničku sliku', 'Налаз ДНК значи да је бактерија присутна у узорку. У каснијој фази болести и послије антибиотика тест може бити негативан и код великог кашља, па резултат тумачи љекар уз клиничку слику', 'Обнаружение ДНК означает присутствие бактерии в пробе. На поздних сроках болезни и после антибиотиков тест может быть отрицательным даже при коклюше, поэтому результат оценивает врач вместе с картиной заболевания', 'Nachgewiesene DNA bedeutet, dass der Erreger in der Probe vorhanden ist. Im späten Krankheitsverlauf und nach Antibiotika kann der Test trotz Keuchhusten negativ ausfallen, daher beurteilt der Arzt das Ergebnis zusammen mit dem klinischen Bild', 'DNA saptanması bakterinin örnekte bulunduğunu gösterir. Hastalığın geç döneminde ve antibiyotik sonrası test boğmaca varken bile negatif çıkabilir, bu nedenle sonucu hekim klinik tabloyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'chlamydia-trachomatis-pcr-urine'), 'A molecular test for Chlamydia trachomatis DNA in urine, an option that avoids taking a swab', 'Molekularni test na DNK bakterije Chlamydia trachomatis iz mokraće, varijanta bez uzimanja brisa', 'Молекуларни тест на ДНК бактерије Chlamydia trachomatis из мокраће, варијанта без узимања бриса', 'Молекулярный тест на ДНК бактерии Chlamydia trachomatis в моче — вариант без взятия мазка', 'Molekularer Test auf DNA von Chlamydia trachomatis im Urin, eine Variante ohne Abstrich', 'İdrarda Chlamydia trachomatis DNA''sını arayan, sürüntü almayı gerektirmeyen moleküler test', 'The patient collects the first portion of urine into a sterile container, the DNA is then detected by PCR', 'Pacijent sam sakuplja prvi mlaz mokraće u sterilnu posudu, DNK se zatim određuje metodom PCR', 'Пацијент сам сакупља први млаз мокраће у стерилну посуду, ДНК се затим одређује методом ПЦР', 'Пациент самостоятельно собирает первую порцию мочи в стерильный контейнер, дальше ДНК определяют методом ПЦР', 'Die Patientin oder der Patient fängt die erste Urinportion in einem sterilen Becher auf, anschließend wird die DNA mittels PCR bestimmt', 'Hasta ilk idrar akımını steril kaba kendisi toplar, ardından DNA PCR yöntemiyle belirlenir', 'Discomfort or burning on urination, discharge, screening after a change of partner and when planning a pregnancy, testing of a partner, follow-up after treatment as prescribed', 'Nelagoda i peckanje pri mokrenju, sekret, skrining pri promjeni partnera i pri planiranju trudnoće, pregled partnera, kontrola poslije liječenja po nalogu ljekara', 'Нелагода и пецкање при мокрењу, секрет, скрининг при промјени партнера и при планирању трудноће, преглед партнера, контрола послије лијечења по налогу љекара', 'Дискомфорт и жжение при мочеиспускании, выделения, скрининг при смене партнёра и при планировании беременности, обследование партнёра, контроль после лечения по назначению врача', 'Beschwerden oder Brennen beim Wasserlassen, Ausfluss, Screening bei Partnerwechsel und bei Kinderwunsch, Untersuchung des Partners, Kontrolle nach Behandlung auf ärztliche Anordnung', 'İdrar yaparken rahatsızlık ve yanma, akıntı, partner değişiminde ve gebelik planlamasında tarama, partnerin incelenmesi, hekim önerisiyle tedavi sonrası kontrol', 'Do not urinate for 2–3 hours before collection, collect exactly the first portion of the stream, do not use antiseptics for hygiene beforehand; the interval after antibiotics is set by the doctor', 'Ne mokriti 2–3 sata prije sakupljanja, uzeti baš prvi mlaz, ne koristiti antiseptike pri higijeni; razmak poslije antibiotika određuje ljekar', 'Не мокрити 2–3 сата прије сакупљања, узети баш први млаз, не користити антисептике при хигијени; размак послије антибиотика одређује љекар', 'Не мочиться 2–3 часа до сбора, собрать именно первую порцию струи, не использовать антисептики при гигиене; сроки после приёма антибиотиков уточняет врач', '2–3 Stunden vor der Gewinnung nicht Wasser lassen, genau die erste Portion des Strahls auffangen, vorher keine Antiseptika zur Reinigung verwenden; den Abstand nach einer Antibiotikatherapie legt der Arzt fest', 'Toplamadan 2–3 saat önce idrara çıkmamak, akımın tam ilk bölümünü almak, temizlikte antiseptik kullanmamak gerekir; antibiyotik sonrası bekleme süresini hekim belirler', 'Detected DNA means the bacterium is present in the sample. A negative urine result does not always rule out infection at another site, so the need for a swab and the next steps are decided by the doctor', 'Nalaz DNK znači da je bakterija prisutna u uzorku. Negativan nalaz iz mokraće ne isključuje uvijek infekciju na drugom mjestu, pa potrebu za brisom i dalje korake određuje ljekar', 'Налаз ДНК значи да је бактерија присутна у узорку. Негативан налаз из мокраће не искључује увијек инфекцију на другом мјесту, па потребу за брисом и даље кораке одређује љекар', 'Обнаружение ДНК означает присутствие бактерии в пробе. Отрицательный результат из мочи не всегда исключает инфекцию другой локализации, поэтому необходимость мазка и дальнейшую тактику определяет врач', 'Nachgewiesene DNA bedeutet, dass der Erreger in der Probe vorhanden ist. Ein negativer Urinbefund schließt eine Infektion an anderer Stelle nicht immer aus, über einen Abstrich und das weitere Vorgehen entscheidet der Arzt', 'DNA saptanması bakterinin örnekte bulunduğunu gösterir. İdrarda negatif sonuç başka bölgedeki enfeksiyonu her zaman dışlamaz, sürüntü gerekip gerekmediğine ve sonraki adımlara hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'sars-cov-2-pcr'), 'A molecular test detecting SARS-CoV-2 viral RNA by real-time PCR', 'Molekularni test koji otkriva RNK virusa SARS-CoV-2 metodom PCR u realnom vremenu', 'Молекуларни тест који открива РНК вируса SARS-CoV-2 методом ПЦР у реалном времену', 'Молекулярный тест, выявляющий РНК вируса SARS-CoV-2 методом ПЦР в реальном времени', 'Molekularer Test zum Nachweis der RNA des Virus SARS-CoV-2 mittels Real-Time-PCR', 'SARS-CoV-2 virüsünün RNA''sını gerçek zamanlı PCR yöntemiyle saptayan moleküler test', 'A swab from the nasopharynx and throat with a single-use swab, sampling takes about a minute, the sample is then processed in the laboratory', 'Bris iz nazofarinksa i ždrijela jednokratnim štapićem, uzimanje traje oko minut, uzorak se zatim obrađuje u laboratoriji', 'Брис из назофаринкса и ждријела једнократним штапићем, узимање траје око минут, узорак се затим обрађује у лабораторији', 'Мазок из носоглотки и ротоглотки одноразовым тампоном, забор занимает около минуты, дальше пробу исследуют в лаборатории', 'Abstrich aus Nasenrachenraum und Rachen mit einem Einwegtupfer, die Entnahme dauert etwa eine Minute, danach wird die Probe im Labor untersucht', 'Tek kullanımlık çubukla genizden ve boğazdan sürüntü alınır, işlem yaklaşık bir dakika sürer, örnek sonra laboratuvarda çalışılır', 'Symptoms of a respiratory infection, contact with an infected person, checking before a planned hospital admission or procedure, requirements of a particular institution or destination country', 'Simptomi respiratorne infekcije, kontakt sa oboljelim, provjera prije planiranog prijema u bolnicu ili zahvata, zahtjevi konkretne ustanove ili zemlje u koju se putuje', 'Симптоми респираторне инфекције, контакт са обољелим, провјера прије планираног пријема у болницу или захвата, захтјеви конкретне установе или земље у коју се путује', 'Симптомы респираторной инфекции, контакт с заболевшим, обследование перед плановой госпитализацией или вмешательством, требования конкретного учреждения или страны назначения', 'Symptome eines Atemwegsinfekts, Kontakt zu einer erkrankten Person, Untersuchung vor geplanter Aufnahme oder einem Eingriff, Vorgaben einer bestimmten Einrichtung oder des Ziellandes', 'Solunum yolu enfeksiyonu belirtileri, hasta biriyle temas, planlı hastane yatışı veya işlem öncesi kontrol, ilgili kurumun ya da gidilecek ülkenin istediği koşullar', 'One to two hours before the swab do not eat, drink, brush teeth, rinse the mouth or use nasal sprays and drops', 'Sat do dva prije brisa ne jesti, ne piti, ne prati zube, ne ispirati usta i ne koristiti sprejeve i kapi za nos', 'Сат до два прије бриса не јести, не пити, не прати зубе, не испирати уста и не користити спрејеве и капи за нос', 'За час-два до мазка не есть, не пить, не чистить зубы, не полоскать рот и не использовать спреи и капли в нос', 'Ein bis zwei Stunden vor dem Abstrich nicht essen, trinken, Zähne putzen, den Mund spülen oder Nasensprays und Nasentropfen verwenden', 'Sürüntüden bir iki saat önce yememek, içmemek, diş fırçalamamak, ağzı çalkalamamak ve burun spreyi ya da damlası kullanmamak gerekir', 'A positive result means viral RNA was found in the sample, a negative one does not rule out infection very early in the illness or after incorrect sampling. Decisions about treatment and isolation are made by a doctor', 'Pozitivan nalaz znači da je RNK virusa nađena u uzorku, negativan ne isključuje infekciju na samom početku bolesti ili kod loše uzetog uzorka. Odluku o liječenju i izolaciji donosi ljekar', 'Позитиван налаз значи да је РНК вируса нађена у узорку, негативан не искључује инфекцију на самом почетку болести или код лоше узетог узорка. Одлуку о лијечењу и изолацији доноси љекар', 'Положительный результат означает, что РНК вируса найдена в пробе; отрицательный не исключает инфекцию в самом начале болезни или при неправильном заборе. Решение о лечении и изоляции принимает врач', 'Ein positives Ergebnis bedeutet, dass Virus-RNA in der Probe nachgewiesen wurde, ein negatives schließt eine Infektion ganz zu Beginn der Erkrankung oder bei fehlerhafter Entnahme nicht aus. Über Behandlung und Isolation entscheidet der Arzt', 'Pozitif sonuç virüs RNA''sının örnekte bulunduğunu gösterir, negatif sonuç hastalığın ilk gününde ya da örnek hatalı alındığında enfeksiyonu dışlamaz. Tedavi ve izolasyon kararını hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'fecal-occult-blood'), 'A stool test for traces of blood that are not visible to the eye', 'Analiza stolice na tragove krvi koji se ne vide golim okom', 'Анализа столице на трагове крви који се не виде голим оком', 'Анализ кала на следы крови, не видимые глазом', 'Stuhltest auf Blutspuren, die mit bloßem Auge nicht sichtbar sind', 'Gaitada gözle görülmeyen kan izlerini arayan test', 'At home the patient collects a small stool sample into a container with a spatula and brings it to the laboratory; modern immunochemical tests react only to human haemoglobin', 'Pacijent kod kuće sakupi mali uzorak stolice u posudu sa lopaticom i donese ga u laboratoriju; savremeni imunohemijski testovi reaguju samo na ljudski hemoglobin', 'Пацијент код куће сакупи мали узорак столице у посуду са лопатицом и донесе га у лабораторију; савремени имунохемијски тестови реагују само на људски хемоглобин', 'Пациент дома собирает небольшую пробу кала в контейнер с лопаточкой и приносит в лабораторию; современные иммунохимические тесты реагируют только на человеческий гемоглобин', 'Zu Hause entnimmt die Patientin oder der Patient mit einem Spatel eine kleine Stuhlprobe in ein Röhrchen und bringt sie ins Labor; moderne immunchemische Tests reagieren nur auf menschliches Hämoglobin', 'Hasta evde spatulalı kaba küçük bir gaita örneği alır ve laboratuvara getirir; güncel immünkimyasal testler yalnızca insan hemoglobinine tepki verir', 'Preventive bowel screening programmes, anaemia of unclear origin, persistent changes in stool, abdominal pain, monitoring as prescribed by a doctor', 'Preventivni programi pregleda crijeva, anemija nejasnog uzroka, uporne promjene stolice, bolovi u trbuhu, praćenje po nalogu ljekara', 'Превентивни програми прегледа цријева, анемија нејасног узрока, упорне промјене столице, болови у трбуху, праћење по налогу љекара', 'Профилактические программы обследования кишечника, анемия неясного происхождения, стойкие изменения стула, боли в животе, наблюдение по назначению врача', 'Vorsorgeprogramme zur Darmuntersuchung, Blutarmut unklarer Ursache, anhaltende Stuhlveränderungen, Bauchschmerzen, Verlaufskontrolle auf ärztliche Anordnung', 'Koruyucu bağırsak tarama programları, nedeni belirsiz kansızlık, dışkıda süregelen değişiklikler, karın ağrısı, hekim önerisiyle izlem', 'An immunochemical test usually needs no diet; do not collect the sample during menstruation, during a haemorrhoid flare-up or with bleeding gums, and never take it from toilet water', 'Za imunohemijski test dijeta obično nije potrebna; uzorak ne uzimati u dane menstruacije, kod pogoršanja hemoroida i krvarenja desni, niti iz vode u šolji', 'За имунохемијски тест дијета обично није потребна; узорак не узимати у дане менструације, код погоршања хемороида и крварења десни, нити из воде у шољи', 'Для иммунохимического теста диета обычно не нужна; не собирать пробу в дни менструации, при обострении геморроя и кровоточивости дёсен, не брать материал из воды в унитазе', 'Für den immunchemischen Test ist meist keine Diät nötig; die Probe nicht während der Menstruation, bei akuten Hämorrhoiden oder Zahnfleischbluten und nie aus dem Toilettenwasser entnehmen', 'İmmünkimyasal test için genellikle diyet gerekmez; örneği adet günlerinde, hemoroit alevlenmesinde ve diş eti kanaması varken almamak, klozetteki sudan hiç almamak gerekir', 'Blood in the sample may be related to bleeding at any level of the digestive tract, including haemorrhoids and fissures. Further investigation, most often an examination of the bowel, is arranged by the doctor', 'Nalaz krvi može biti povezan sa krvarenjem na bilo kom nivou probavnog trakta, uključujući hemoroide i fisure. Dopunsku obradu, najčešće pregled crijeva, određuje ljekar', 'Налаз крви може бити повезан са крварењем на било ком нивоу пробавног тракта, укључујући хемороиде и фисуре. Допунску обраду, најчешће преглед цријева, одређује љекар', 'Обнаружение крови может быть связано с кровоточивостью на любом уровне пищеварительного тракта, включая геморрой и трещины. Уточняющее обследование, чаще всего осмотр кишечника, назначает врач', 'Nachgewiesenes Blut kann mit einer Blutung auf jeder Ebene des Verdauungstrakts zusammenhängen, auch mit Hämorrhoiden oder Einrissen. Die weiterführende Abklärung, meist eine Darmuntersuchung, veranlasst der Arzt', 'Kan bulunması hemoroit ve çatlaklar dahil sindirim yolunun herhangi bir düzeyindeki kanamayla ilişkili olabilir. Çoğunlukla bağırsak incelemesi olan ileri tetkiki hekim planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'calprotectin'), 'A neutrophil protein measured in stool as an indicator of inflammation in the bowel', 'Bjelančevina iz neutrofila koja se mjeri u stolici kao pokazatelj upale u crijevima', 'Бјеланчевина из неутрофила која се мјери у столици као показатељ упале у цријевима', 'Белок из нейтрофилов, который определяют в кале как показатель воспаления в кишечнике', 'Ein Protein aus neutrophilen Granulozyten, das im Stuhl als Hinweis auf eine Entzündung im Darm bestimmt wird', 'Bağırsaktaki iltihabın göstergesi olarak gaitada ölçülen, nötrofillerden kaynaklanan bir protein', 'A small stool sample is collected into a container and analysed in the laboratory; no blood draw is needed for this test', 'Mali uzorak stolice u posudi, analiza se radi u laboratoriji; vađenje krvi za ovaj nalaz nije potrebno', 'Мали узорак столице у посуди, анализа се ради у лабораторији; вађење крви за овај налаз није потребно', 'Небольшая проба кала в контейнере, анализ выполняется в лаборатории; кровь для этого исследования брать не нужно', 'Eine kleine Stuhlprobe wird in ein Röhrchen gegeben und im Labor untersucht; eine Blutentnahme ist dafür nicht nötig', 'Küçük bir gaita örneği kaba alınır ve laboratuvarda çalışılır; bu tetkik için kan alınması gerekmez', 'Prolonged diarrhoea, abdominal pain, distinguishing inflammatory from functional causes of complaints, monitoring chronic inflammatory bowel disease, assessing the effect of prescribed treatment', 'Dugotrajni proliv, bol u trbuhu, razlikovanje upalnih od funkcionalnih uzroka tegoba, praćenje hroničnih upalnih bolesti crijeva, procjena djelovanja propisane terapije', 'Дуготрајни пролив, бол у трбуху, разликовање упалних од функционалних узрока тегоба, праћење хроничних упалних болести цријева, процјена дјеловања прописане терапије', 'Длительная диарея, боль в животе, различение воспалительных и функциональных причин жалоб, наблюдение за течением хронических воспалительных заболеваний кишечника, оценка эффекта назначенного лечения', 'Anhaltender Durchfall, Bauchschmerzen, Unterscheidung entzündlicher von funktionellen Ursachen der Beschwerden, Verlaufskontrolle chronisch entzündlicher Darmerkrankungen, Beurteilung des Therapieerfolgs', 'Uzun süren ishal, karın ağrısı, şikayetlerin iltihabi mi işlevsel mi olduğunun ayrımı, kronik iltihabi bağırsak hastalıklarının izlemi, verilen tedavinin etkisinin değerlendirilmesi', 'No special diet is required; tell the doctor about non-steroidal anti-inflammatory drugs as they can affect the result, and never take the sample from toilet water', 'Posebna dijeta nije potrebna; obavijestiti ljekara o uzimanju nesteroidnih antiinflamatornih lijekova jer mogu uticati na nalaz, uzorak ne uzimati iz vode u šolji', 'Посебна дијета није потребна; обавијестити љекара о узимању нестероидних антиинфламаторних лијекова јер могу утицати на налаз, узорак не узимати из воде у шољи', 'Специальной диеты не требуется; сообщите врачу о приёме нестероидных противовоспалительных препаратов — они могут влиять на результат, материал не берут из воды в унитазе', 'Keine besondere Diät nötig; die Einnahme nicht steroidaler Entzündungshemmer dem Arzt mitteilen, da sie das Ergebnis beeinflussen kann, und die Probe nie aus dem Toilettenwasser entnehmen', 'Özel diyet gerekmez; steroid olmayan ağrı kesici kullanımı sonucu etkileyebileceğinden hekime bildirilmeli, örnek klozetteki sudan alınmamalıdır', 'An elevated value may be related to inflammation in the bowel, an intestinal infection or certain medicines. Whether an endoscopic examination is needed is decided by the doctor', 'Povišena vrijednost može biti povezana sa upalom u crijevima, crijevnom infekcijom ili uzimanjem pojedinih lijekova. Da li je potrebna endoskopska obrada, odlučuje ljekar', 'Повишена вриједност може бити повезана са упалом у цријевима, цријевном инфекцијом или узимањем појединих лијекова. Да ли је потребна ендоскопска обрада, одлучује љекар', 'Повышение может быть связано с воспалением в кишечнике, кишечной инфекцией или приёмом некоторых препаратов. Нужно ли эндоскопическое обследование, решает врач', 'Ein erhöhter Wert kann mit einer Entzündung im Darm, einer Darminfektion oder bestimmten Medikamenten zusammenhängen. Ob eine endoskopische Abklärung nötig ist, entscheidet der Arzt', 'Yüksek değer bağırsaktaki iltihapla, bağırsak enfeksiyonuyla ya da bazı ilaçların kullanımıyla ilişkili olabilir. Endoskopik incelemenin gerekip gerekmediğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'afp'), 'A protein produced by the fetal liver; in adults it is measured in blood as one of the monitoring parameters, and in pregnancy it belongs to a screening set', 'Bjelančevina koju stvara jetra ploda; kod odraslih se mjeri u krvi kao jedan od pokazatelja praćenja, a u trudnoći ulazi u sklop skrininga', 'Бјеланчевина коју ствара јетра плода; код одраслих се мјери у крви као један од показатеља праћења, а у трудноћи улази у склоп скрининга', 'Белок, который вырабатывает печень плода; у взрослых его определяют в крови как один из показателей наблюдения, а при беременности он входит в комплекс скрининга', 'Ein Eiweiß, das die Leber des Ungeborenen bildet; bei Erwachsenen wird es im Blut als Verlaufsparameter bestimmt, in der Schwangerschaft gehört es zu einem Screening-Satz', 'Bebeğin karaciğerinde üretilen bir protein; yetişkinlerde izlem parametrelerinden biri olarak kanda ölçülür, gebelikte ise tarama setinin parçasıdır', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alınır, birkaç dakika sürer', 'Second-trimester prenatal screening as part of a set of parameters, monitoring in chronic liver disease, follow-up over time as prescribed by a doctor', 'Prenatalni skrining u drugom tromjesečju kao dio skupa pokazatelja, praćenje kod hroničnih bolesti jetre, praćenje kroz vrijeme po nalogu ljekara', 'Пренатални скрининг у другом тромјесечју као дио скупа показатеља, праћење код хроничних болести јетре, праћење кроз вријеме по налогу љекара', 'Пренатальный скрининг второго триместра в составе набора показателей, наблюдение при хронических заболеваниях печени, динамическое наблюдение по назначению врача', 'Pränatales Screening im zweiten Trimester als Teil eines Parametersatzes, Verlaufskontrolle bei chronischen Lebererkrankungen, Kontrolle im Zeitverlauf auf ärztliche Anordnung', 'İkinci üç aylık dönemde parametre setinin parçası olarak prenatal tarama, kronik karaciğer hastalıklarında izlem, hekim önerisiyle zaman içinde takip', 'Usually no special preparation is needed; in pregnancy the exact gestational age must be stated, without it the result is not assessed', 'Posebna priprema obično nije potrebna; u trudnoći je nužno tačno navesti gestacijsku starost, bez toga se nalaz ne procjenjuje', 'Посебна припрема обично није потребна; у трудноћи је нужно тачно навести гестацијску старост, без тога се налаз не процјењује', 'Специальной подготовки обычно не требуется; при беременности нужно точно указать срок — без него результат не оценивают', 'Meist ist keine besondere Vorbereitung nötig; in der Schwangerschaft muss die Schwangerschaftswoche genau angegeben werden, sonst ist der Wert nicht beurteilbar', 'Genellikle özel hazırlık gerekmez; gebelikte gebelik haftasının tam olarak bildirilmesi gerekir, aksi halde sonuç değerlendirilmez', 'The value is not interpreted on its own: in pregnancy it is assessed only together with the other screening parameters and the gestational age, outside pregnancy over time and alongside other investigations. Conclusions are drawn by a doctor', 'Pokazatelj se ne tumači sam za sebe: u trudnoći se procjenjuje isključivo zajedno sa ostalim pokazateljima skrininga i gestacijskom starošću, van trudnoće kroz vrijeme i uz druge nalaze. Zaključak donosi ljekar', 'Показатељ се не тумачи сам за себе: у трудноћи се процјењује искључиво заједно са осталим показатељима скрининга и гестацијском старошћу, ван трудноће кроз вријеме и уз друге налазе. Закључак доноси љекар', 'Показатель не трактуется сам по себе: при беременности его оценивают только вместе с остальными показателями скрининга и сроком, вне беременности — в динамике и вместе с другими исследованиями. Выводы делает врач', 'Der Wert wird nicht für sich allein gedeutet: in der Schwangerschaft nur zusammen mit den übrigen Screening-Parametern und der Schwangerschaftswoche, außerhalb der Schwangerschaft im Verlauf und zusammen mit anderen Untersuchungen. Die Bewertung nimmt der Arzt vor', 'Değer tek başına yorumlanmaz: gebelikte yalnızca diğer tarama parametreleri ve gebelik haftasıyla birlikte, gebelik dışında ise zaman içindeki seyriyle ve diğer tetkiklerle birlikte değerlendirilir. Yorumu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'interleukin-6'), 'A cytokine used to assess how active the body''s inflammatory response is', 'Citokin po kojem se procjenjuje aktivnost upalnog odgovora organizma', 'Цитокин по којем се процјењује активност упалног одговора организма', 'Цитокин, по которому оценивают активность воспалительного ответа организма', 'Ein Zytokin, mit dem die Aktivität der Entzündungsreaktion des Körpers beurteilt wird', 'Vücudun iltihap yanıtının ne kadar etkin olduğunu değerlendirmeye yarayan bir sitokin', 'Venous blood draw into a separate tube, the assay is run in the laboratory', 'Uzimanje venske krvi u zasebnu epruvetu, analiza se radi u laboratoriji', 'Узимање венске крви у засебну епрувету, анализа се ради у лабораторији', 'Забор венозной крови в отдельную пробирку, исследование выполняется в лаборатории', 'Venöse Blutentnahme in ein eigenes Röhrchen, die Bestimmung erfolgt im Labor', 'Ayrı bir tüpe venöz kan alınır, çalışma laboratuvarda yapılır', 'Assessing the intensity of inflammation in severe infections, monitoring in hospital, rheumatic and autoimmune diseases, as an addition to other inflammatory markers, monitoring during prescribed therapy', 'Procjena jačine upale kod teških infekcija, praćenje u bolnici, reumatske i autoimune bolesti, dopuna drugim pokazateljima upale, kontrola tokom propisane terapije', 'Процјена јачине упале код тешких инфекција, праћење у болници, реуматске и аутоимуне болести, допуна другим показатељима упале, контрола током прописане терапије', 'Оценка выраженности воспаления при тяжёлых инфекциях, наблюдение в стационаре, ревматические и аутоиммунные заболевания, дополнение к другим маркерам воспаления, контроль на фоне назначенной терапии', 'Beurteilung der Entzündungsstärke bei schweren Infektionen, Überwachung im Krankenhaus, rheumatische und autoimmune Erkrankungen, Ergänzung zu anderen Entzündungsmarkern, Kontrolle unter laufender Therapie', 'Ağır enfeksiyonlarda iltihabın şiddetinin değerlendirilmesi, hastanede izlem, romatizmal ve otoimmün hastalıklar, diğer iltihap belirteçlerine ek olarak, verilen tedavi sırasında takip', 'Strict fasting is usually not required; about 15 minutes of rest before the draw is advisable and intense physical exercise should be avoided the day before', 'Strogo gladovanje obično nije potrebno; poželjno je petnaestak minuta mirovanja prije vađenja krvi, a dan ranije izbjegavati jake fizičke napore', 'Строго гладовање обично није потребно; пожељно је петнаестак минута мировања прије вађења крви, а дан раније избјегавати јаке физичке напоре', 'Строгого голодания обычно не требуется; перед забором желательно 15 минут покоя, накануне избегать интенсивных физических нагрузок', 'Striktes Nüchternsein ist meist nicht nötig; etwa 15 Minuten Ruhe vor der Entnahme sind sinnvoll, am Vortag starke körperliche Belastung meiden', 'Genellikle sıkı açlık gerekmez; kan alınmadan önce yaklaşık 15 dakika dinlenmek iyi olur, bir gün önce yoğun fiziksel efordan kaçınılmalıdır', 'An increase may be related to active inflammation of any origin, such as infection, injury or a flare of a chronic disease. The marker is not interpreted in isolation, the doctor assesses it together with the rest of the findings', 'Povišena vrijednost može biti povezana sa aktivnom upalom bilo kog porijekla, infekcijom, povredom ili pogoršanjem hronične bolesti. Pokazatelj se ne tumači izdvojeno, ljekar ga procjenjuje uz ostale nalaze', 'Повишена вриједност може бити повезана са активном упалом било ког поријекла, инфекцијом, повредом или погоршањем хроничне болести. Показатељ се не тумачи издвојено, љекар га процјењује уз остале налазе', 'Повышение может быть связано с активным воспалением любой природы — инфекцией, травмой, обострением хронического заболевания. Изолированно показатель не трактуется, врач оценивает его вместе с остальными данными', 'Ein Anstieg kann mit einer aktiven Entzündung jeder Ursache zusammenhängen, etwa Infektion, Verletzung oder Schub einer chronischen Erkrankung. Der Wert wird nicht isoliert gedeutet, der Arzt beurteilt ihn zusammen mit den übrigen Befunden', 'Yükseklik enfeksiyon, yaralanma ya da kronik bir hastalığın alevlenmesi gibi her türden etkin iltihapla ilişkili olabilir. Belirteç tek başına yorumlanmaz, hekim diğer bulgularla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ogtt-3-point'), 'A glucose load test: glucose is measured fasting and then 60 and 120 minutes after drinking a glucose solution', 'Test opterećenja šećerom: glukoza se mjeri našte, pa 60 i 120 minuta poslije ispijanja rastvora glukoze', 'Тест оптерећења шећером: глукоза се мјери наште, па 60 и 120 минута послије испијања раствора глукозе', 'Тест с сахарной нагрузкой: уровень глюкозы измеряют натощак, затем через 60 и 120 минут после приёма раствора глюкозы', 'Belastungstest mit Zucker: Glukose wird nüchtern sowie 60 und 120 Minuten nach dem Trinken einer Glukoselösung gemessen', 'Şeker yükleme testi: glukoz açken, ardından glukoz çözeltisi içildikten 60 ve 120 dakika sonra ölçülür', 'The first sample is taken fasting, the patient then drinks the solution prepared by the laboratory and stays at the clinic for two more hours, during which blood is drawn twice more', 'Prvo vađenje krvi je našte, zatim pacijent popije rastvor koji priprema laboratorija i ostaje u ustanovi još dva sata, tokom kojih se krv vadi još dva puta', 'Прво вађење крви је наште, затим пацијент попије раствор који припрема лабораторија и остаје у установи још два сата, током којих се крв вади још два пута', 'Первый забор крови натощак, затем пациент выпивает подготовленный лабораторией раствор и остаётся в клинике ещё на два часа, за это время кровь берут ещё дважды', 'Die erste Blutentnahme erfolgt nüchtern, danach trinkt die Patientin oder der Patient die vom Labor vorbereitete Lösung und bleibt zwei weitere Stunden in der Einrichtung, in denen noch zweimal Blut abgenommen wird', 'İlk kan açken alınır, sonra hasta laboratuvarın hazırladığı çözeltiyi içer ve iki saat daha kurumda kalır, bu süre içinde iki kez daha kan alınır', 'A borderline fasting glucose result, screening for gestational diabetes during pregnancy, assessment of carbohydrate metabolism disorders, excess weight and other risk factors on a doctor''s referral', 'Granična vrijednost glukoze našte, skrining gestacijskog dijabetesa tokom trudnoće, procjena poremećaja metabolizma ugljenih hidrata, prekomjerna težina i drugi faktori rizika po uputu ljekara', 'Гранична вриједност глукозе наште, скрининг гестацијског дијабетеса током трудноће, процјена поремећаја метаболизма угљених хидрата, прекомјерна тежина и други фактори ризика по упуту љекара', 'Пограничный результат глюкозы натощак, скрининг гестационного диабета во время беременности, оценка нарушений углеводного обмена, избыточный вес и другие факторы риска по направлению врача', 'Grenzwertiger Nüchternblutzucker, Screening auf Schwangerschaftsdiabetes während der Schwangerschaft, Abklärung von Störungen des Kohlenhydratstoffwechsels, Übergewicht und weitere Risikofaktoren nach ärztlicher Überweisung', 'Sınırda açlık glukoz sonucu, gebelik sırasında gebelik şekeri taraması, karbonhidrat metabolizması bozukluklarının değerlendirilmesi, hekim yönlendirmesiyle fazla kilo ve diğer risk etkenleri', 'Fasting for 8–12 hours, only water allowed; do not restrict carbohydrates in the three days before, and during the test do not eat, smoke or walk around, telling the staff at once if you feel unwell', 'Natašte 8–12 sati, dozvoljena samo voda; tri dana prije testa ne ograničavati unos ugljenih hidrata, tokom testa ne jesti, ne pušiti i ne hodati, a kod lošeg osjećaja odmah obavijestiti osoblje', 'Наташте 8–12 сати, дозвољена само вода; три дана прије теста не ограничавати унос угљених хидрата, током теста не јести, не пушити и не ходати, а код лошег осјећаја одмах обавијестити особље', 'Натощак 8–12 часов, разрешена только вода; за три дня до теста не ограничивать углеводы в питании, во время теста не есть, не курить и не ходить, при плохом самочувствии сразу сказать персоналу', 'Nüchtern seit 8–12 Stunden, nur Wasser erlaubt; in den drei Tagen davor Kohlenhydrate nicht einschränken, während des Tests nicht essen, nicht rauchen und nicht umhergehen, bei Unwohlsein sofort das Personal informieren', '8–12 saat açlık, sadece su içilebilir; testten önceki üç gün karbonhidratı kısıtlamamak, test sırasında yememek, sigara içmemek ve dolaşmamak, kötü hissedildiğinde hemen personele söylemek gerekir', 'Deviations at any of the three time points may be related to a carbohydrate metabolism disorder or to temporary factors such as a recent illness, stress or medicines. The conclusion is made by a doctor, who may order a repeat test', 'Odstupanja u bilo kojoj od tri tačke mogu biti povezana sa poremećajem metabolizma ugljenih hidrata ili sa privremenim faktorima, skorašnjom bolešću, stresom, lijekovima. Zaključak donosi ljekar i po potrebi određuje ponovni test', 'Одступања у било којој од три тачке могу бити повезана са поремећајем метаболизма угљених хидрата или са привременим факторима, скорашњом болешћу, стресом, лијековима. Закључак доноси љекар и по потреби одређује поновни тест', 'Отклонения в любой из трёх точек могут быть связаны с нарушением углеводного обмена или с временными факторами — недавней болезнью, стрессом, приёмом лекарств. Заключение делает врач и при необходимости назначает повторный тест', 'Abweichungen an einem der drei Messpunkte können mit einer Störung des Kohlenhydratstoffwechsels oder mit vorübergehenden Faktoren wie einer kürzlichen Erkrankung, Stress oder Medikamenten zusammenhängen. Die Beurteilung erfolgt durch den Arzt, der bei Bedarf eine Wiederholung veranlasst', 'Üç ölçümün herhangi birindeki sapma karbonhidrat metabolizması bozukluğuyla ya da yakın zamandaki hastalık, stres, ilaç gibi geçici etkenlerle ilişkili olabilir. Sonucu hekim değerlendirir, gerekirse testi yineletir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'valproic-acid'), 'Measurement of the valproic acid concentration in the blood of patients to whom this medicine has been prescribed', 'Mjerenje koncentracije valproične kiseline u krvi kod pacijenata kojima je ovaj lijek propisan', 'Мјерење концентрације валпроичне киселине у крви код пацијената којима је овај лијек прописан', 'Измерение концентрации вальпроевой кислоты в крови у пациентов, которым этот препарат назначен', 'Messung der Valproinsäure-Konzentration im Blut bei Patientinnen und Patienten, denen dieses Medikament verordnet wurde', 'Bu ilacın reçete edildiği hastalarda kandaki valproik asit düzeyinin ölçülmesi', 'Venous blood draw; the timing relative to the dose is set by the treating doctor, the sample is most often taken before the next dose', 'Uzimanje venske krvi; vrijeme vađenja u odnosu na uzimanje terapije određuje ljekar koji vodi liječenje, uzorak se najčešće uzima prije naredne doze', 'Узимање венске крви; вријеме вађења у односу на узимање терапије одређује љекар који води лијечење, узорак се најчешће узима прије наредне дозе', 'Забор венозной крови; время забора относительно приёма препарата задаёт лечащий врач, чаще всего кровь берут перед очередным приёмом', 'Venöse Blutentnahme; den Zeitpunkt im Verhältnis zur Einnahme legt die behandelnde Ärztin oder der behandelnde Arzt fest, meist wird vor der nächsten Gabe Blut entnommen', 'Venöz kan alınır; kanın ilaca göre hangi saatte alınacağını tedaviyi yürüten hekim belirler, örnek çoğunlukla bir sonraki dozdan önce alınır', 'Monitoring prescribed therapy, a change in how the patient feels during treatment, suspicion of insufficient effect or of unwanted reactions, concomitant liver or kidney disease, use of other medicines at the same time, pregnancy at the doctor''s discretion', 'Kontrola propisane terapije, promjena stanja tokom liječenja, sumnja na nedovoljan učinak ili na neželjene reakcije, prateće bolesti jetre i bubrega, istovremeno uzimanje drugih lijekova, trudnoća po odluci ljekara', 'Контрола прописане терапије, промјена стања током лијечења, сумња на недовољан учинак или на нежељене реакције, пратеће болести јетре и бубрега, истовремено узимање других лијекова, трудноћа по одлуци љекара', 'Контроль назначенной терапии, изменение самочувствия на фоне лечения, подозрение на недостаточный эффект или на нежелательные реакции, сопутствующие заболевания печени и почек, одновременный приём других препаратов, беременность по решению врача', 'Kontrolle der verordneten Therapie, Veränderung des Befindens unter Behandlung, Verdacht auf unzureichende Wirkung oder auf unerwünschte Reaktionen, begleitende Leber- oder Nierenerkrankungen, gleichzeitige Einnahme weiterer Medikamente, Schwangerschaft nach ärztlicher Entscheidung', 'Verilen tedavinin takibi, tedavi sırasında genel durumdaki değişiklik, etkinin yetersiz olduğu ya da istenmeyen tepkiler geliştiği kuşkusu, eşlik eden karaciğer ve böbrek hastalıkları, aynı anda başka ilaç kullanımı, hekim kararıyla gebelik', 'Do not change the dosing schedule on your own: a dose is skipped or moved before the test only on the doctor''s instruction; bring details of the medicine and the time of the last intake', 'Raspored uzimanja ne mijenjati na svoju ruku: doza se prije analize preskače ili pomjera isključivo po uputstvu ljekara; ponijeti podatke o terapiji i vremenu posljednjeg uzimanja', 'Распоред узимања не мијењати на своју руку: доза се прије анализе прескаче или помјера искључиво по упутству љекара; понијети податке о терапији и времену посљедњег узимања', 'Схему приёма самостоятельно не менять: пропустить или перенести дозу перед анализом можно только по указанию врача; при себе иметь сведения о препарате и времени последнего приёма', 'Das Einnahmeschema nicht eigenmächtig ändern: eine Dosis wird vor der Untersuchung nur auf ärztliche Anweisung ausgelassen oder verschoben; Angaben zum Medikament und zur Zeit der letzten Einnahme mitbringen', 'İlaç düzenini kendi başınıza değiştirmeyin: testten önce doz yalnızca hekimin talimatıyla atlanır ya da ertelenir; ilaç bilgisini ve son alım saatini yanınızda getirin', 'The result means nothing on its own, it is compared with the prescribed treatment schedule, the patient''s condition and other tests by the treating doctor only', 'Rezultat sam po sebi ništa ne znači, sa propisanom shemom liječenja, stanjem pacijenta i drugim nalazima poredi ga isključivo ljekar koji vodi liječenje', 'Резултат сам по себи ништа не значи, са прописаном схемом лијечења, стањем пацијента и другим налазима пореди га искључиво љекар који води лијечење', 'Результат сам по себе ничего не означает — его сопоставляет с назначенной схемой лечения, самочувствием и другими анализами только лечащий врач', 'Der Wert allein sagt nichts aus, er wird ausschließlich von der behandelnden Ärztin oder dem behandelnden Arzt mit dem verordneten Therapieschema, dem Befinden und weiteren Befunden abgeglichen', 'Sonuç tek başına bir anlam taşımaz, yalnızca tedaviyi yürüten hekim onu verilen tedavi şemasıyla, hastanın durumuyla ve diğer tetkiklerle karşılaştırır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'complete-urinalysis'), 'A comprehensive test of the physical and chemical properties of urine and its sediment', 'Sveobuhvatna analiza fizičkih, hemijskih svojstava mokraće i sedimenta', 'Свеобухватна анализа физичких, хемијских својстава мокраће и седимента', 'Комплексный анализ физических, химических свойств мочи и осадка', 'Eine umfassende Untersuchung der physikalischen und chemischen Eigenschaften des Urins und des Sediments', 'İdrarın fiziksel ve kimyasal özellikleri ile sedimentinin kapsamlı analizi', 'A single morning urine sample in a container, no needles or injections involved', 'Jednokratni uzorak jutarnje mokraće u posudi, bez igala i uboda', 'Једнократни узорак јутарње мокраће у посуди, без игала и убода', 'Разовая утренняя порция мочи в контейнер, без иглы и уколов', 'Eine einmalige Morgenurinprobe in einem Behälter, ohne Nadeln oder Injektionen', 'Bir kaba tek seferlik sabah idrarı örneği alınması, iğne veya enjeksiyon gerekmez', 'Preventive check-up, routine health screening, symptoms related to the kidneys/urinary tract, monitoring during pregnancy', 'Preventivni pregled, sistematski pregled, simptomi sa strane bubrega/mokraćnih puteva, kontrola tokom trudnoće', 'Превентивни преглед, систематски преглед, симптоми са стране бубрега/мокраћних путева, контрола током трудноће', 'Профилактический осмотр, диспансеризация, симптомы со стороны почек/мочевых путей, контроль при беременности', 'Vorsorgeuntersuchung, Routine-Gesundheitscheck, Beschwerden im Bereich der Nieren/Harnwege, Kontrolle während der Schwangerschaft', 'Rutin kontrol, genel sağlık taraması, böbrek/idrar yolları ile ilgili semptomlar, gebelikte takip', 'Morning urine after hygiene; for 1–2 days beforehand avoid beetroot and other coloring foods and heavy physical exertion; mention if menstruating', 'Jutarnja mokraća poslije higijene; 1–2 dana ranije izbjegavati cveklu i namirnice koje boje mokraću, kao i veće fizičke napore; napomenuti ako je menstruacija', 'Јутарња мокраћа послије хигијене; 1–2 дана раније избјегавати цвеклу и намирнице које боје мокраћу, као и веће физичке напоре; напоменути ако је менструација', 'Утренняя моча после гигиены; за 1–2 дня — без свёклы и красящих продуктов, без больших физических нагрузок; предупредить о менструации', 'Morgenurin nach der Hygiene; 1–2 Tage vorher rote Bete und andere färbende Lebensmittel sowie starke körperliche Anstrengung vermeiden; eine Menstruation sollte angegeben werden', 'Hijyen sonrası sabah idrarı; 1–2 gün öncesinden pancar ve idrarı renklendiren gıdalardan ve yoğun fiziksel efordan kaçınılmalı; adet dönemindeyseniz belirtin', 'Changes may be related to processes in the kidneys, urinary tract, metabolism, or temporary factors (exertion, diet). The exact cause is determined by a doctor based on the overall picture', 'Promjene mogu biti povezane sa procesima u bubrezima, mokraćnim putevima, metabolizmom ili privremenim faktorima (napor, ishrana). Tačan uzrok utvrđuje ljekar na osnovu cjelokupne slike', 'Промјене могу бити повезане са процесима у бубрезима, мокраћним путевима, метаболизмом или привременим факторима (напор, исхрана). Тачан узрок утврђује љекар на основу цјелокупне слике', 'Изменения могут быть связаны с процессами в почках, мочевых путях, обменом веществ или временными факторами (нагрузка, питание). Точную причину определяет врач по совокупности показателей', 'Veränderungen können mit Vorgängen in den Nieren, den Harnwegen, dem Stoffwechsel oder vorübergehenden Faktoren (Belastung, Ernährung) zusammenhängen. Die genaue Ursache wird vom Arzt anhand des Gesamtbilds festgestellt', 'Değişiklikler böbreklerdeki, idrar yollarındaki, metabolizmadaki süreçlerle veya geçici etkenlerle (efor, beslenme) ilişkili olabilir. Kesin nedeni hekim genel tabloya göre belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'glucose'), 'Blood test for blood sugar (glucose) level', 'Analiza krvi na nivo šećera (glukoze)', 'Анализа крви на ниво шећера (глукозе)', 'Анализ крови на уровень сахара (глюкозы)', 'Bluttest zur Bestimmung des Blutzuckerspiegels (Glukose)', 'Kandaki şeker (glukoz) düzeyini ölçen kan testi', 'Venous blood draw on an empty stomach', 'Uzimanje venske krvi natašte', 'Узимање венске крви наташте', 'Забор венозной крови натощак', 'Entnahme von venösem Blut nüchtern', 'Aç karnına toplardamardan kan alınması', 'Routine check-ups, monitoring diabetes mellitus, thirst/weakness, screening during pregnancy', 'Sistematski pregled, kontrola šećerne bolesti, žeđ/slabost, skrining tokom trudnoće', 'Систематски преглед, контрола шећерне болести, жеђ/слабост, скрининг током трудноће', 'Диспансеризация, контроль сахарного диабета, жажда/слабость, скрининг при беременности', 'Vorsorgeuntersuchung, Kontrolle bei Diabetes mellitus, Durst/Schwäche, Screening während der Schwangerschaft', 'Rutin kontrol, diyabetin takibi, susama/halsizlik, gebelikte tarama', 'Fasting for 8–12 hours, only water allowed; avoid alcohol and heavy food the day before', 'Natašte 8–12 sati, dozvoljena samo voda; dan ranije izbjegavati alkohol i tešku hranu', 'Наташте 8–12 сати, дозвољена само вода; дан раније избјегавати алкохол и тешку храну', 'Натощак 8–12 часов, разрешена только вода; накануне избегать алкоголя и тяжёлой пищи', 'Nüchtern seit 8–12 Stunden, nur Wasser erlaubt; am Vortag Alkohol und schwere Mahlzeiten vermeiden', '8–12 saat aç karnına, sadece su içilebilir; bir önceki gün alkol ve ağır yiyeceklerden kaçınılmalıdır', 'Changes in the level may be related to disturbances in carbohydrate metabolism or temporary factors (stress, food intake, medications). The diagnosis is made by a doctor based on several indicators', 'Promjene nivoa mogu biti povezane sa poremećajem metabolizma ugljenih hidrata ili privremenim faktorima (stres, uzimanje hrane, lijekovi). Dijagnozu postavlja ljekar na osnovu više pokazatelja', 'Промјене нивоа могу бити повезане са поремећајем метаболизма угљених хидрата или привременим факторима (стрес, узимање хране, лијекови). Дијагнозу поставља љекар на основу више показатеља', 'Изменения уровня могут быть связаны с нарушением углеводного обмена или временными факторами (стресс, приём пищи, лекарства). Диагноз ставит врач на основании нескольких показателей', 'Veränderungen des Werts können mit einer Störung des Kohlenhydratstoffwechsels oder vorübergehenden Faktoren (Stress, Nahrungsaufnahme, Medikamente) zusammenhängen. Die Diagnose wird vom Arzt anhand mehrerer Werte gestellt', 'Değerdeki değişiklikler karbonhidrat metabolizması bozukluğu veya geçici etkenlerle (stres, yemek yeme, ilaçlar) ilişkili olabilir. Tanı, birden fazla göstergeye dayanarak hekim tarafından konur')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'cholesterol'), 'Blood test for total cholesterol — one of the indicators of lipid metabolism', 'Analiza krvi na ukupni holesterol — jedan od pokazatelja lipidnog metabolizma', 'Анализа крви на укупни холестерол — један од показатеља липидног метаболизма', 'Анализ крови на общее содержание холестерина — один из показателей липидного обмена', 'Bluttest zur Bestimmung des Gesamtcholesterins — eines der Indikatoren des Fettstoffwechsels', 'Lipid metabolizmasının göstergelerinden biri olan toplam kolesterol için kan testi', 'Venous blood draw, usually together with the rest of the lipid profile', 'Uzimanje venske krvi, obično zajedno sa ostalim lipidnim profilom', 'Узимање венске крви, обично заједно са осталим липидним профилом', 'Забор венозной крови, обычно вместе с остальным липидным профилем', 'Entnahme von venösem Blut, meist zusammen mit dem restlichen Lipidprofil', 'Genellikle diğer lipid profili değerleriyle birlikte toplardamardan kan alınması', 'Cardiovascular risk screening, routine check-ups, monitoring during lipid-lowering therapy', 'Skrining kardiovaskularnog rizika, sistematski pregled, kontrola tokom uzimanja lijekova za snižavanje lipida', 'Скрининг кардиоваскуларног ризика, систематски преглед, контрола током узимања лијекова за снижавање липида', 'Скрининг сердечно-сосудистого риска, диспансеризация, контроль на фоне гиполипидемических препаратов', 'Screening des kardiovaskulären Risikos, Vorsorgeuntersuchung, Kontrolle während einer lipidsenkenden Therapie', 'Kardiyovasküler risk taraması, rutin kontrol, yağ düşürücü tedavi sırasında takip', 'Fasting for 9–12 hours; avoid fatty food and alcohol the day before', 'Natašte 9–12 sati; dan ranije izbjegavati masnu hranu i alkohol', 'Наташте 9–12 сати; дан раније избјегавати масну храну и алкохол', 'Натощак 9–12 часов; за сутки избегать жирной пищи и алкоголя', '9–12 Stunden nüchtern; am Vortag fettreiche Speisen und Alkohol vermeiden', '9–12 saat aç karnına; bir önceki gün yağlı yiyecekler ve alkolden kaçınılmalıdır', 'Changes may be related to diet, lifestyle, heredity, or metabolic disorders. The overall risk is assessed by a doctor together with other fractions (LDL, HDL, triglycerides) and the clinical picture', 'Promjene mogu biti povezane sa ishranom, načinom života, nasljeđem ili poremećajem metabolizma. Ukupan rizik ljekar procjenjuje zajedno sa ostalim frakcijama (LDL, HDL, trigliceridi) i kliničkom slikom', 'Промјене могу бити повезане са исхраном, начином живота, насљеђем или поремећајем метаболизма. Укупан ризик љекар процјењује заједно са осталим фракцијама (ЛДЛ, ХДЛ, триглицериди) и клиничком сликом', 'Изменения могут быть связаны с питанием, образом жизни, наследственностью или нарушением обмена веществ. Общий риск врач оценивает вместе с другими фракциями (ЛПНП, ЛПВП, триглицериды) и клинической картиной', 'Veränderungen können mit Ernährung, Lebensstil, erblichen Faktoren oder Stoffwechselstörungen zusammenhängen. Das Gesamtrisiko bewertet der Arzt zusammen mit den weiteren Werten (LDL, HDL, Triglyceride) und dem klinischen Bild', 'Değişiklikler beslenme, yaşam tarzı, kalıtım veya metabolizma bozukluğuyla ilişkili olabilir. Genel riski hekim, diğer değerlerle (LDL, HDL, trigliseritler) ve klinik tabloyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'creatinine'), 'Blood test reflecting kidney filtration function', 'Analiza krvi koja odražava filtracionu funkciju bubrega', 'Анализа крви која одражава филтрациону функцију бубрега', 'Анализ крови, отражающий фильтрационную функцию почек', 'Bluttest, der die Filtrationsfunktion der Nieren widerspiegelt', 'Böbreklerin filtrasyon fonksiyonunu yansıtan kan testi', 'Venous blood draw', 'Uzimanje venske krvi', 'Узимање венске крви', 'Забор венозной крови', 'Entnahme von venösem Blut', 'Toplardamardan kan alınması', 'Assessment of kidney function, preparation for surgery/procedures, monitoring during medications that put strain on the kidneys, routine check-ups', 'Procjena funkcije bubrega, priprema za operacije/procedure, kontrola tokom uzimanja lijekova koji opterećuju bubrege, sistematski pregled', 'Процјена функције бубрега, припрема за операције/процедуре, контрола током узимања лијекова који оптерећују бубреге, систематски преглед', 'Оценка функции почек, подготовка к операциям/процедурам, контроль на фоне препаратов с нагрузкой на почки, диспансеризация', 'Beurteilung der Nierenfunktion, Vorbereitung auf Operationen/Eingriffe, Kontrolle bei Medikamenten, die die Nieren belasten, Vorsorgeuntersuchung', 'Böbrek fonksiyonunun değerlendirilmesi, ameliyat/işlem öncesi hazırlık, böbrekleri yoran ilaçların kullanımında takip, rutin kontrol', 'No special preparation usually required; it is advisable to avoid intense physical exertion the day before', 'Obično nije potrebna posebna priprema; poželjno je izbjegavati intenzivne napore dan ranije', 'Обично није потребна посебна припрема; пожељно је избјегавати интензивне напоре дан раније', 'Специальной подготовки обычно не требуется; желательно избегать интенсивных нагрузок накануне', 'In der Regel keine besondere Vorbereitung erforderlich; intensive körperliche Anstrengung am Vortag sollte vermieden werden', 'Genellikle özel bir hazırlık gerekmez; bir önceki gün yoğun fiziksel efordan kaçınılması önerilir', 'Changes may be related to kidney function, muscle mass, dehydration, or certain medications. Interpretation by a doctor takes age, sex, and clinical picture into account', 'Promjene mogu biti povezane sa funkcijom bubrega, mišićnom masom, dehidracijom ili uzimanjem određenih lijekova. Ljekar tumači rezultat uzimajući u obzir godine, pol i kliničku sliku', 'Промјене могу бити повезане са функцијом бубрега, мишићном масом, дехидрацијом или узимањем одређених лијекова. Љекар тумачи резултат узимајући у обзир године, пол и клиничку слику', 'Изменения могут быть связаны с функцией почек, мышечной массой, обезвоживанием или приёмом некоторых препаратов. Интерпретирует врач с учётом возраста, пола и клинической картины', 'Veränderungen können mit der Nierenfunktion, der Muskelmasse, Dehydrierung oder bestimmten Medikamenten zusammenhängen. Der Arzt interpretiert das Ergebnis unter Berücksichtigung von Alter, Geschlecht und klinischem Bild', 'Değişiklikler böbrek fonksiyonu, kas kütlesi, sıvı kaybı veya bazı ilaçlarla ilişkili olabilir. Hekim, yaş, cinsiyet ve klinik tabloyu dikkate alarak yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'c-reactive-protein'), 'Blood test for a marker of acute inflammation', 'Analiza krvi na marker akutne upale', 'Анализа крви на маркер акутне упале', 'Анализ крови на маркер острого воспаления', 'Bluttest auf einen Marker für akute Entzündungen', 'Akut iltihabın bir belirtecine bakan kan testi', 'Venous blood draw', 'Uzimanje venske krvi', 'Узимање венске крви', 'Забор венозной крови', 'Entnahme von venösem Blut', 'Toplardamardan kan alınması', 'Suspected inflammatory/infectious process, monitoring treatment progress, follow-up after surgery', 'Sumnja na upalni/infektivni proces, kontrola toka liječenja, praćenje poslije operacije', 'Сумња на упални/инфективни процес, контрола тока лијечења, праћење послије операције', 'Подозрение на воспалительный/инфекционный процесс, контроль динамики лечения, наблюдение после операции', 'Verdacht auf einen entzündlichen/infektiösen Prozess, Verlaufskontrolle der Behandlung, Kontrolle nach einer Operation', 'İltihabi/enfeksiyöz süreç şüphesi, tedavi seyrinin takibi, ameliyat sonrası izlem', 'Fasting is preferable; avoid intense physical exertion the day before', 'Poželjno natašte; dan ranije izbjegavati intenzivne napore', 'Пожељно наташте; дан раније избјегавати интензивне напоре', 'Желательно натощак; накануне избегать интенсивных нагрузок', 'Nüchtern ist vorzuziehen; am Vortag intensive körperliche Anstrengung vermeiden', 'Aç karnına yapılması tercih edilir; bir önceki gün yoğun fiziksel efordan kaçınılmalıdır', 'An elevated result may be related to infection, inflammation, injury, or other processes in the body. The marker alone does not point to a specific disease — the cause is determined by a doctor', 'Povećanje može biti povezano sa infekcijom, upalom, povredom ili drugim procesima u organizmu. Sam pokazatelj ne ukazuje na konkretnu bolest — uzrok utvrđuje ljekar', 'Повећање може бити повезано са инфекцијом, упалом, повредом или другим процесима у организму. Сам показатељ не указује на конкретну болест — узрок утврђује љекар', 'Повышение может быть связано с инфекцией, воспалением, травмой или другими процессами в организме. Сам по себе показатель не указывает на конкретное заболевание — причину определяет врач', 'Ein erhöhter Wert kann mit einer Infektion, Entzündung, Verletzung oder anderen Vorgängen im Körper zusammenhängen. Der Wert allein weist nicht auf eine bestimmte Erkrankung hin — die Ursache wird vom Arzt bestimmt', 'Yükselme, enfeksiyon, iltihap, yaralanma veya vücuttaki başka süreçlerle ilişkili olabilir. Belirtecin kendisi belirli bir hastalığa işaret etmez — nedeni hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'triglycerides'), 'Blood test for triglycerides — one of the forms of fat circulating in the blood', 'Analiza krvi na nivo triglicerida — jednog od oblika masti koje cirkulišu u krvi', 'Анализа крви на ниво триглицерида — једног од облика масти које циркулишу у крви', 'Анализ крови на уровень триглицеридов — одной из форм жиров, циркулирующих в крови', 'Bluttest zur Bestimmung des Triglyceridspiegels — einer Form von Fetten, die im Blut zirkulieren', 'Kanda dolaşan yağ türlerinden biri olan trigliserit düzeyini ölçen kan testi', 'Venous blood draw, usually on an empty stomach', 'Uzimanje venske krvi, obično natašte', 'Узимање венске крви, обично наташте', 'Забор венозной крови, обычно натощак', 'Entnahme von venösem Blut, in der Regel nüchtern', 'Genellikle aç karnına toplardamardan kan alınması', 'Assessment of lipid metabolism, routine check-ups, monitoring cardiovascular risk, being overweight, taking medications that affect fat metabolism', 'Procjena lipidnog metabolizma, sistematski pregled, kontrola kardiovaskularnog rizika, prekomjerna tjelesna težina, uzimanje lijekova koji utiču na metabolizam masti', 'Процјена липидног метаболизма, систематски преглед, контрола кардиоваскуларног ризика, прекомјерна тјелесна тежина, узимање лијекова који утичу на метаболизам масти', 'Оценка липидного обмена, диспансеризация, контроль сердечно-сосудистых рисков, избыточный вес, приём препаратов, влияющих на обмен жиров', 'Beurteilung des Fettstoffwechsels, Vorsorgeuntersuchung, Kontrolle kardiovaskulärer Risiken, Übergewicht, Einnahme von Medikamenten, die den Fettstoffwechsel beeinflussen', 'Lipid metabolizmasının değerlendirilmesi, genel sağlık kontrolü, kardiyovasküler risklerin takibi, fazla kilo, yağ metabolizmasını etkileyen ilaç kullanımı', 'Fasting for 9–12 hours, only water allowed; avoid alcohol and fatty foods the day before', 'Natašte 9–12 sati, dozvoljena samo voda; dan ranije izbjegavati alkohol i masnu hranu', 'Наташте 9–12 сати, дозвољена само вода; дан раније избјегавати алкохол и масну храну', 'Натощак 9–12 часов, разрешена только вода; накануне избегать алкоголя и жирной пищи', '9–12 Stunden nüchtern, nur Wasser erlaubt; am Vortag Alkohol und fettreiche Speisen vermeiden', '9–12 saat aç karnına, sadece su içilebilir; bir önceki gün alkol ve yağlı yiyeceklerden kaçınılmalıdır', 'Changes in the level may be related to dietary habits, alcohol consumption, metabolic disorders, or temporary factors. The exact cause is determined by a doctor', 'Promjene nivoa mogu biti povezane sa navikama u ishrani, konzumiranjem alkohola, metaboličkim poremećajima ili privremenim faktorima. Tačan uzrok utvrđuje ljekar', 'Промјене нивоа могу бити повезане са навикама у исхрани, конзумирањем алкохола, метаболичким поремећајима или привременим факторима. Тачан узрок утврђује љекар', 'Изменения уровня могут быть связаны с особенностями питания, приёмом алкоголя, метаболическими нарушениями или временными факторами. Точную причину определяет врач', 'Veränderungen des Werts können mit Ernährungsgewohnheiten, Alkoholkonsum, Stoffwechselstörungen oder vorübergehenden Faktoren zusammenhängen. Die genaue Ursache wird vom Arzt festgestellt', 'Değerdeki değişiklikler beslenme alışkanlıkları, alkol tüketimi, metabolik bozukluklar veya geçici etkenlerle ilişkili olabilir. Kesin nedeni hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ldl-cholesterol'), 'Blood test for low-density lipoprotein (LDL), the so-called "bad" cholesterol', 'Analiza krvi na nivo lipoproteina niske gustine (LDL), takozvanog "lošeg" holesterola', 'Анализа крви на ниво липопротеина ниске густине (ЛДЛ), такозваног "лошег" холестерола', 'Анализ крови на уровень липопротеинов низкой плотности (ЛПНП), так называемого "плохого" холестерина', 'Bluttest zur Bestimmung des Low-Density-Lipoprotein-Spiegels (LDL), des sogenannten "schlechten" Cholesterins', 'Halk arasında "kötü" kolesterol olarak bilinen düşük yoğunluklu lipoprotein (LDL) düzeyini ölçen kan testi', 'Venous blood draw on an empty stomach', 'Uzimanje venske krvi natašte', 'Узимање венске крви наташте', 'Забор венозной крови натощак', 'Entnahme von venösem Blut nüchtern', 'Aç karnına toplardamardan kan alınması', 'Routine check-ups, assessment of cardiovascular risk, monitoring treatment for lipid metabolism disorders', 'Sistematski pregled, procjena kardiovaskularnog rizika, kontrola terapije kod poremećaja lipidnog metabolizma', 'Систематски преглед, процјена кардиоваскуларног ризика, контрола терапије код поремећаја липидног метаболизма', 'Диспансеризация, оценка сердечно-сосудистых рисков, контроль терапии при нарушениях липидного обмена', 'Vorsorgeuntersuchung, Beurteilung kardiovaskulärer Risiken, Kontrolle der Therapie bei Fettstoffwechselstörungen', 'Genel sağlık kontrolü, kardiyovasküler riskin değerlendirilmesi, lipid metabolizması bozukluklarında tedavi takibi', 'Fasting for 9–12 hours, only water allowed; avoid fatty foods and alcohol the day before', 'Natašte 9–12 sati, dozvoljena samo voda; dan ranije izbjegavati masnu hranu i alkohol', 'Наташте 9–12 сати, дозвољена само вода; дан раније избјегавати масну храну и алкохол', 'Натощак 9–12 часов, разрешена только вода; накануне избегать жирной пищи и алкоголя', '9–12 Stunden nüchtern, nur Wasser erlaubt; am Vortag fettreiche Speisen und Alkohol vermeiden', '9–12 saat aç karnına, sadece su içilebilir; bir önceki gün yağlı yiyecekler ve alkolden kaçınılmalıdır', 'Changes in the level may be related to dietary habits, heredity, or other factors affecting fat metabolism. Interpretation, taking other indicators into account, is carried out by a doctor', 'Promjene nivoa mogu biti povezane sa navikama u ishrani, nasljeđem ili drugim faktorima koji utiču na metabolizam masti. Tumačenje, uz uvid u druge pokazatelje, daje ljekar', 'Промјене нивоа могу бити повезане са навикама у исхрани, насљеђем или другим факторима који утичу на метаболизам масти. Тумачење, уз увид у друге показатеље, даје љекар', 'Изменения уровня могут быть связаны с особенностями питания, наследственностью или другими факторами, влияющими на обмен жиров. Интерпретацию с учётом других показателей проводит врач', 'Veränderungen des Werts können mit Ernährungsgewohnheiten, erblichen Faktoren oder anderen Einflüssen auf den Fettstoffwechsel zusammenhängen. Die Interpretation unter Berücksichtigung weiterer Werte erfolgt durch den Arzt', 'Değerdeki değişiklikler beslenme alışkanlıkları, kalıtım veya yağ metabolizmasını etkileyen diğer etkenlerle ilişkili olabilir. Diğer göstergeler de dikkate alınarak yorumlama hekim tarafından yapılır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'hdl-cholesterol'), 'Blood test for high-density lipoprotein (HDL), the so-called "good" cholesterol', 'Analiza krvi na nivo lipoproteina visoke gustine (HDL), takozvanog "dobrog" holesterola', 'Анализа крви на ниво липопротеина високе густине (ХДЛ), такозваног "доброг" холестерола', 'Анализ крови на уровень липопротеинов высокой плотности (ЛПВП), так называемого "хорошего" холестерина', 'Bluttest zur Bestimmung des High-Density-Lipoprotein-Spiegels (HDL), des sogenannten "guten" Cholesterins', 'Halk arasında "iyi" kolesterol olarak bilinen yüksek yoğunluklu lipoprotein (HDL) düzeyini ölçen kan testi', 'Venous blood draw on an empty stomach', 'Uzimanje venske krvi natašte', 'Узимање венске крви наташте', 'Забор венозной крови натощак', 'Entnahme von venösem Blut nüchtern', 'Aç karnına toplardamardan kan alınması', 'Routine check-ups, assessment of cardiovascular risk, comprehensive evaluation of the lipid profile', 'Sistematski pregled, procjena kardiovaskularnog rizika, sveobuhvatna procjena lipidnog profila', 'Систематски преглед, процјена кардиоваскуларног ризика, свеобухватна процјена липидног профила', 'Диспансеризация, оценка сердечно-сосудистых рисков, комплексная оценка липидного профиля', 'Vorsorgeuntersuchung, Beurteilung kardiovaskulärer Risiken, umfassende Bewertung des Lipidprofils', 'Genel sağlık kontrolü, kardiyovasküler riskin değerlendirilmesi, lipid profilinin kapsamlı değerlendirilmesi', 'Fasting for 9–12 hours, only water allowed', 'Natašte 9–12 sati, dozvoljena samo voda', 'Наташте 9–12 сати, дозвољена само вода', 'Натощак 9–12 часов, разрешена только вода', '9–12 Stunden nüchtern, nur Wasser erlaubt', '9–12 saat aç karnına, sadece su içilebilir', 'Changes in the level may be related to lifestyle, physical activity, diet, or other metabolic factors. The doctor provides the risk assessment and recommendations', 'Promjene nivoa mogu biti povezane sa načinom života, fizičkom aktivnošću, ishranom ili drugim metaboličkim faktorima. Procjenu rizika i preporuke daje ljekar', 'Промјене нивоа могу бити повезане са начином живота, физичком активношћу, исхраном или другим метаболичким факторима. Процјену ризика и препоруке даје љекар', 'Изменения уровня могут быть связаны с образом жизни, физической активностью, питанием или другими факторами обмена веществ. Оценку риска и рекомендации даёт врач', 'Veränderungen des Werts können mit dem Lebensstil, körperlicher Aktivität, der Ernährung oder anderen Stoffwechselfaktoren zusammenhängen. Die Risikobewertung und Empfehlungen erfolgen durch den Arzt', 'Değerdeki değişiklikler yaşam tarzı, fiziksel aktivite, beslenme veya diğer metabolik etkenlerle ilişkili olabilir. Risk değerlendirmesi ve öneriler hekim tarafından yapılır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urea'), 'Blood test for urea — a breakdown product of proteins that is eliminated by the kidneys', 'Analiza krvi na ureu — proizvod razgradnje proteina koji se izlučuje putem bubrega', 'Анализа крви на уреу — производ разградње протеина који се излучује путем бубрега', 'Анализ крови на мочевину — продукт распада белков, который выводится почками', 'Bluttest zur Bestimmung des Harnstoffwerts — eines Abbauprodukts von Proteinen, das über die Nieren ausgeschieden wird', 'Proteinlerin yıkım ürünü olan ve böbrekler yoluyla vücuttan atılan üre düzeyini ölçen kan testi', 'Venous blood draw, usually on an empty stomach', 'Uzimanje venske krvi, obično natašte', 'Узимање венске крви, обично наташте', 'Забор венозной крови, обычно натощак', 'Entnahme von venösem Blut, in der Regel nüchtern', 'Genellikle aç karnına toplardamardan kan alınması', 'Assessment of kidney function, routine check-ups, monitoring chronic kidney disease, preoperative preparation', 'Procjena rada bubrega, sistematski pregled, kontrola kod hroničnih bubrežnih oboljenja, priprema za operacije', 'Процјена рада бубрега, систематски преглед, контрола код хроничних бубрежних обољења, припрема за операције', 'Оценка работы почек, диспансеризация, контроль при хронических заболеваниях почек, подготовка к операциям', 'Beurteilung der Nierenfunktion, Vorsorgeuntersuchung, Kontrolle bei chronischen Nierenerkrankungen, Vorbereitung auf Operationen', 'Böbrek fonksiyonunun değerlendirilmesi, genel sağlık kontrolü, kronik böbrek hastalıklarında takip, ameliyat öncesi hazırlık', 'No special preparation is required, but fasting is preferable; avoid excessive protein intake the day before', 'Posebna priprema nije potrebna, ali je poželjno uzimanje uzorka natašte; dan ranije izbjegavati prekomjeran unos proteinske hrane', 'Посебна припрема није потребна, али је пожељно узимање узорка наташте; дан раније избјегавати прекомјеран унос протеинске хране', 'Специальной подготовки не требуется, но желателен забор натощак; накануне избегать чрезмерного употребления белковой пищи', 'Keine besondere Vorbereitung erforderlich, nüchterne Blutentnahme ist jedoch vorzuziehen; am Vortag übermäßigen Konsum eiweißreicher Nahrung vermeiden', 'Özel bir hazırlık gerekmez, ancak aç karnına alınması tercih edilir; bir önceki gün aşırı proteinli gıda tüketiminden kaçınılmalıdır', 'Changes in the level may be related to kidney function, dietary habits, dehydration, or certain medications. The cause is determined by a doctor based on examination results', 'Promjene nivoa mogu biti povezane sa radom bubrega, načinom ishrane, dehidracijom ili uzimanjem određenih lijekova. Uzrok utvrđuje ljekar na osnovu rezultata pregleda', 'Промјене нивоа могу бити повезане са радом бубрега, начином исхране, дехидрацијом или узимањем одређених лијекова. Узрок утврђује љекар на основу резултата прегледа', 'Изменения уровня могут быть связаны с работой почек, характером питания, обезвоживанием или приёмом некоторых препаратов. Причину устанавливает врач по результатам обследования', 'Veränderungen des Werts können mit der Nierenfunktion, den Ernährungsgewohnheiten, Dehydrierung oder bestimmten Medikamenten zusammenhängen. Die Ursache wird vom Arzt anhand der Untersuchungsergebnisse festgestellt', 'Değerdeki değişiklikler böbrek fonksiyonu, beslenme şekli, sıvı kaybı veya bazı ilaçların kullanımıyla ilişkili olabilir. Neden, muayene sonuçlarına göre hekim tarafından belirlenir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'potassium'), 'Blood test for potassium — an electrolyte important for heart and muscle function', 'Analiza krvi na nivo kalijuma — elektrolita važnog za rad srca i mišića', 'Анализа крви на ниво калијума — електролита важног за рад срца и мишића', 'Анализ крови на уровень калия — электролита, важного для работы сердца и мышц', 'Bluttest zur Bestimmung des Kaliumspiegels — eines Elektrolyts, das für die Herz- und Muskelfunktion wichtig ist', 'Kalp ve kas fonksiyonu için önemli bir elektrolit olan potasyum düzeyini ölçen kan testi', 'Venous blood draw', 'Uzimanje venske krvi', 'Узимање венске крви', 'Забор венозной крови', 'Entnahme von venösem Blut', 'Toplardamardan kan alınması', 'Assessment of fluid and electrolyte balance, monitoring during diuretic therapy, kidney disease, cardiovascular disorders', 'Procjena vodeno-elektrolitne ravnoteže, kontrola tokom uzimanja diuretika, kod bubrežnih oboljenja, kardiovaskularnih poremećaja', 'Процјена водено-електролитне равнотеже, контрола током узимања диуретика, код бубрежних обољења, кардиоваскуларних поремећаја', 'Оценка водно-электролитного баланса, контроль при приёме мочегонных препаратов, заболеваниях почек, сердечно-сосудистых нарушениях', 'Beurteilung des Flüssigkeits- und Elektrolythaushalts, Kontrolle bei Einnahme von Diuretika, Nierenerkrankungen, kardiovaskulären Störungen', 'Sıvı-elektrolit dengesinin değerlendirilmesi, diüretik kullanımı, böbrek hastalıkları, kardiyovasküler bozukluklarda takip', 'No special preparation is required, but fasting is preferable, without prolonged tourniquet application', 'Posebna priprema nije potrebna, ali je poželjno uzimanje uzorka natašte, bez dužeg stezanja vene podvezom', 'Посебна припрема није потребна, али је пожељно узимање узорка наташте, без дужег стезања вене подвезом', 'Специальной подготовки не требуется, но желателен забор натощак без длительного пережатия вены жгутом', 'Keine besondere Vorbereitung erforderlich, nüchterne Blutentnahme ohne längeres Abbinden der Vene ist jedoch vorzuziehen', 'Özel bir hazırlık gerekmez, ancak aç karnına ve turnikenin uzun süre sıkılmadan alınması tercih edilir', 'Changes in the level may be related to kidney function, medication use, diet, or fluid balance disturbances. The doctor evaluates the significance of the changes', 'Promjene nivoa mogu biti povezane sa radom bubrega, uzimanjem lijekova, ishranom ili poremećajem ravnoteže tečnosti. Značaj promjena procjenjuje ljekar', 'Промјене нивоа могу бити повезане са радом бубрега, узимањем лијекова, исхраном или поремећајем равнотеже течности. Значај промјена процјењује љекар', 'Изменения уровня могут быть связаны с работой почек, приёмом лекарств, питанием или нарушением баланса жидкости. Оценку значимости изменений проводит врач', 'Veränderungen des Werts können mit der Nierenfunktion, der Medikamenteneinnahme, der Ernährung oder Störungen des Flüssigkeitshaushalts zusammenhängen. Die Bedeutung der Veränderungen beurteilt der Arzt', 'Değerdeki değişiklikler böbrek fonksiyonu, ilaç kullanımı, beslenme veya sıvı dengesindeki bozukluklarla ilişkili olabilir. Değişikliklerin önemini hekim değerlendirir')
