INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'sodium'), 'Blood test for sodium — the main electrolyte regulating fluid balance in the body', 'Analiza krvi na nivo natrijuma — osnovnog elektrolita koji reguliše ravnotežu tečnosti u organizmu', 'Анализа крви на ниво натријума — основног електролита који регулише равнотежу течности у организму', 'Анализ крови на уровень натрия — основного электролита, регулирующего баланс жидкости в организме', 'Bluttest zur Bestimmung des Natriumspiegels — des wichtigsten Elektrolyts zur Regulierung des Flüssigkeitshaushalts im Körper', 'Vücuttaki sıvı dengesini düzenleyen temel elektrolit olan sodyum düzeyini ölçen kan testi', 'Venous blood draw', 'Uzimanje venske krvi', 'Узимање венске крви', 'Забор венозной крови', 'Entnahme von venösem Blut', 'Toplardamardan kan alınması', 'Assessment of fluid and electrolyte balance, monitoring during dehydration, kidney disease, use of certain medications', 'Procjena vodeno-elektrolitne ravnoteže, kontrola kod dehidracije, bubrežnih oboljenja, uzimanja određenih lijekova', 'Процјена водено-електролитне равнотеже, контрола код дехидрације, бубрежних обољења, узимања одређених лијекова', 'Оценка водно-электролитного баланса, контроль при обезвоживании, заболеваниях почек, приёме некоторых препаратов', 'Beurteilung des Flüssigkeits- und Elektrolythaushalts, Kontrolle bei Dehydrierung, Nierenerkrankungen, Einnahme bestimmter Medikamente', 'Sıvı-elektrolit dengesinin değerlendirilmesi, sıvı kaybı, böbrek hastalıkları, bazı ilaçların kullanımında takip', 'No special preparation is required, but fasting is preferable', 'Posebna priprema nije potrebna, ali je poželjno uzimanje uzorka natašte', 'Посебна припрема није потребна, али је пожељно узимање узорка наташте', 'Специальной подготовки не требуется, но желателен забор натощак', 'Keine besondere Vorbereitung erforderlich, nüchterne Blutentnahme ist jedoch vorzuziehen', 'Özel bir hazırlık gerekmez, ancak aç karnına alınması tercih edilir', 'Changes in the level may be related to fluid intake, kidney function, medication use, or other fluid-balance factors. The exact cause is determined by a doctor', 'Promjene nivoa mogu biti povezane sa unosom tečnosti, radom bubrega, uzimanjem lijekova ili drugim faktorima ravnoteže tečnosti. Tačan uzrok utvrđuje ljekar', 'Промјене нивоа могу бити повезане са уносом течности, радом бубрега, узимањем лијекова или другим факторима равнотеже течности. Тачан узрок утврђује љекар', 'Изменения уровня могут быть связаны с потреблением жидкости, работой почек, приёмом лекарств или другими факторами водного баланса. Точную причину определяет врач', 'Veränderungen des Werts können mit der Flüssigkeitsaufnahme, der Nierenfunktion, der Medikamenteneinnahme oder anderen Faktoren des Flüssigkeitshaushalts zusammenhängen. Die genaue Ursache wird vom Arzt festgestellt', 'Değerdeki değişiklikler sıvı alımı, böbrek fonksiyonu, ilaç kullanımı veya diğer sıvı dengesi etkenleriyle ilişkili olabilir. Kesin nedeni hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'calcium'), 'Blood test for total calcium — a mineral important for bones, muscles, and the nervous system', 'Analiza krvi na ukupni kalcijum — mineral važan za kosti, mišiće i nervni sistem', 'Анализа крви на укупни калцијум — минерал важан за кости, мишиће и нервни систем', 'Анализ крови на общий кальций — минерал, важный для костей, мышц и нервной системы', 'Bluttest zur Bestimmung des Gesamtcalciums — eines Minerals, das für Knochen, Muskeln und das Nervensystem wichtig ist', 'Kemikler, kaslar ve sinir sistemi için önemli bir mineral olan toplam kalsiyum düzeyini ölçen kan testi', 'Venous blood draw, usually on an empty stomach', 'Uzimanje venske krvi, obično natašte', 'Узимање венске крви, обично наташте', 'Забор венозной крови, обычно натощак', 'Entnahme von venösem Blut, in der Regel nüchtern', 'Genellikle aç karnına toplardamardan kan alınması', 'Assessment of bone metabolism, routine check-ups, examination for bone, kidney, or parathyroid disorders', 'Procjena koštanog metabolizma, sistematski pregled, ispitivanje kod oboljenja kostiju, bubrega, paratireoidnih žlijezda', 'Процјена коштаног метаболизма, систематски преглед, испитивање код обољења костију, бубрега, паратиреоидних жлијезда', 'Оценка костного обмена, диспансеризация, обследование при заболеваниях костей, почек, паращитовидных желёз', 'Beurteilung des Knochenstoffwechsels, Vorsorgeuntersuchung, Abklärung bei Knochen-, Nieren- oder Nebenschilddrüsenerkrankungen', 'Kemik metabolizmasının değerlendirilmesi, genel sağlık kontrolü, kemik, böbrek veya paratiroid bezi hastalıklarında inceleme', 'Fasting for 8–12 hours, only water allowed; avoid calcium supplements the day before unless approved by a doctor', 'Natašte 8–12 sati, dozvoljena samo voda; dan ranije izbjegavati uzimanje dodataka sa kalcijumom bez konsultacije sa ljekarom', 'Наташте 8–12 сати, дозвољена само вода; дан раније избјегавати узимање додатака са калцијумом без консултације са љекаром', 'Натощак 8–12 часов, разрешена только вода; накануне избегать приёма кальцийсодержащих добавок без согласования с врачом', '8–12 Stunden nüchtern, nur Wasser erlaubt; am Vortag calciumhaltige Nahrungsergänzungsmittel ohne ärztliche Rücksprache vermeiden', '8–12 saat aç karnına, sadece su içilebilir; bir önceki gün doktora danışılmadan kalsiyum içeren takviyelerden kaçınılmalıdır', 'Changes in the level may be related to parathyroid function, bone metabolism, diet, supplement use, or kidney disease. Interpretation is carried out by a doctor', 'Promjene nivoa mogu biti povezane sa radom paratireoidnih žlijezda, koštanim metabolizmom, ishranom, uzimanjem dodataka ishrani ili bubrežnim oboljenjima. Tumačenje daje ljekar', 'Промјене нивоа могу бити повезане са радом паратиреоидних жлијезда, коштаним метаболизмом, исхраном, узимањем додатака исхрани или бубрежним обољењима. Тумачење даје љекар', 'Изменения уровня могут быть связаны с работой паращитовидных желёз, костным обменом, питанием, приёмом добавок или заболеваниями почек. Интерпретацию проводит врач', 'Veränderungen des Werts können mit der Funktion der Nebenschilddrüsen, dem Knochenstoffwechsel, der Ernährung, der Einnahme von Nahrungsergänzungsmitteln oder Nierenerkrankungen zusammenhängen. Die Interpretation erfolgt durch den Arzt', 'Değerdeki değişiklikler paratiroid bezi fonksiyonu, kemik metabolizması, beslenme, takviye kullanımı veya böbrek hastalıklarıyla ilişkili olabilir. Yorumlama hekim tarafından yapılır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ast'), 'Blood test for AST (aspartate aminotransferase) — an enzyme found in the cells of the liver, heart, and muscles', 'Analiza krvi na AST (aspartat-aminotransferazu) — enzim koji se nalazi u ćelijama jetre, srca i mišića', 'Анализа крви на АСТ (аспартат-аминотрансферазу) — ензим који се налази у ћелијама јетре, срца и мишића', 'Анализ крови на АСТ (аспартатаминотрансферазу) — фермент, содержащийся в клетках печени, сердца и мышц', 'Bluttest zur Bestimmung von AST (Aspartat-Aminotransferase) — einem Enzym, das in den Zellen von Leber, Herz und Muskeln vorkommt', 'Karaciğer, kalp ve kas hücrelerinde bulunan bir enzim olan AST (aspartat aminotransferaz) düzeyini ölçen kan testi', 'Venous blood draw, usually on an empty stomach', 'Uzimanje venske krvi, obično natašte', 'Узимање венске крви, обично наташте', 'Забор венозной крови, обычно натощак', 'Entnahme von venösem Blut, in der Regel nüchtern', 'Genellikle aç karnına toplardamardan kan alınması', 'Assessment of liver function, routine check-ups, monitoring during certain medication use, examination for muscle or heart complaints', 'Procjena rada jetre, sistematski pregled, kontrola tokom uzimanja određenih lijekova, ispitivanje kod tegoba sa mišićima ili srcem', 'Процјена рада јетре, систематски преглед, контрола током узимања одређених лијекова, испитивање код тегоба са мишићима или срцем', 'Оценка работы печени, диспансеризация, контроль при приёме некоторых препаратов, обследование при мышечных или сердечных жалобах', 'Beurteilung der Leberfunktion, Vorsorgeuntersuchung, Kontrolle bei Einnahme bestimmter Medikamente, Abklärung bei Muskel- oder Herzbeschwerden', 'Karaciğer fonksiyonunun değerlendirilmesi, genel sağlık kontrolü, bazı ilaçların kullanımında takip, kas veya kalp yakınmalarında inceleme', 'Fasting is preferable; avoid intense physical exertion and alcohol the day before', 'Poželjno je uzimanje uzorka natašte; dan ranije izbjegavati intenzivan fizički napor i alkohol', 'Пожељно је узимање узорка наташте; дан раније избјегавати интензиван физички напор и алкохол', 'Желателен забор натощак; накануне избегать интенсивных физических нагрузок и алкоголя', 'Nüchterne Blutentnahme ist vorzuziehen; am Vortag intensive körperliche Anstrengung und Alkohol vermeiden', 'Aç karnına alınması tercih edilir; bir önceki gün yoğun fiziksel eforlardan ve alkolden kaçınılmalıdır', 'Changes in the level may be related to liver condition, muscle exertion, medication use, or alcohol. The exact cause is determined by a doctor, taking other indicators into account', 'Promjene nivoa mogu biti povezane sa stanjem jetre, mišićnim naporom, uzimanjem lijekova ili alkohola. Tačan uzrok, uz uvid u druge pokazatelje, utvrđuje ljekar', 'Промјене нивоа могу бити повезане са стањем јетре, мишићним напором, узимањем лијекова или алкохола. Тачан узрок, уз увид у друге показатеље, утврђује љекар', 'Изменения уровня могут быть связаны с состоянием печени, мышечной нагрузкой, приёмом препаратов или алкоголя. Точную причину определяет врач с учётом других показателей', 'Veränderungen des Werts können mit dem Zustand der Leber, körperlicher Belastung der Muskulatur, der Medikamenteneinnahme oder Alkohol zusammenhängen. Die genaue Ursache wird vom Arzt unter Berücksichtigung weiterer Werte festgestellt', 'Değerdeki değişiklikler karaciğerin durumu, kas yorgunluğu, ilaç kullanımı veya alkolle ilişkili olabilir. Kesin neden, diğer göstergeler de dikkate alınarak hekim tarafından belirlenir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'alt'), 'Blood test for ALT (alanine aminotransferase) — an enzyme found predominantly in liver cells', 'Analiza krvi na ALT (alanin-aminotransferazu) — enzim koji se pretežno nalazi u ćelijama jetre', 'Анализа крви на АЛТ (аланин-аминотрансферазу) — ензим који се претежно налази у ћелијама јетре', 'Анализ крови на АЛТ (аланинаминотрансферазу) — фермент, преимущественно содержащийся в клетках печени', 'Bluttest zur Bestimmung von ALT (Alanin-Aminotransferase) — einem Enzym, das überwiegend in Leberzellen vorkommt', 'Ağırlıklı olarak karaciğer hücrelerinde bulunan bir enzim olan ALT (alanin aminotransferaz) düzeyini ölçen kan testi', 'Venous blood draw, usually on an empty stomach', 'Uzimanje venske krvi, obično natašte', 'Узимање венске крви, обично наташте', 'Забор венозной крови, обычно натощак', 'Entnahme von venösem Blut, in der Regel nüchtern', 'Genellikle aç karnına toplardamardan kan alınması', 'Assessment of liver function, routine check-ups, monitoring during hepatotoxic medication use, examination for liver-related complaints', 'Procjena rada jetre, sistematski pregled, kontrola tokom uzimanja hepatotoksičnih lijekova, ispitivanje kod tegoba sa jetrom', 'Процјена рада јетре, систематски преглед, контрола током узимања хепатотоксичних лијекова, испитивање код тегоба са јетром', 'Оценка работы печени, диспансеризация, контроль при приёме гепатотоксичных препаратов, обследование при жалобах со стороны печени', 'Beurteilung der Leberfunktion, Vorsorgeuntersuchung, Kontrolle bei Einnahme leberschädigender Medikamente, Abklärung bei leberbezogenen Beschwerden', 'Karaciğer fonksiyonunun değerlendirilmesi, genel sağlık kontrolü, karaciğere zarar verebilecek ilaçların kullanımında takip, karaciğerle ilgili yakınmalarda inceleme', 'Fasting is preferable; avoid alcohol and fatty foods the day before', 'Poželjno je uzimanje uzorka natašte; dan ranije izbjegavati alkohol i masnu hranu', 'Пожељно је узимање узорка наташте; дан раније избјегавати алкохол и масну храну', 'Желателен забор натощак; накануне избегать алкоголя и жирной пищи', 'Nüchterne Blutentnahme ist vorzuziehen; am Vortag Alkohol und fettreiche Speisen vermeiden', 'Aç karnına alınması tercih edilir; bir önceki gün alkol ve yağlı yiyeceklerden kaçınılmalıdır', 'Changes in the level may be related to liver condition, medication use, alcohol, or other factors. The diagnosis is made by a doctor based on a comprehensive examination', 'Promjene nivoa mogu biti povezane sa stanjem jetre, uzimanjem lijekova, alkohola ili drugim faktorima. Dijagnozu postavlja ljekar na osnovu sveobuhvatnog pregleda', 'Промјене нивоа могу бити повезане са стањем јетре, узимањем лијекова, алкохола или другим факторима. Дијагнозу поставља љекар на основу свеобухватног прегледа', 'Изменения уровня могут быть связаны с состоянием печени, приёмом лекарств, алкоголя или другими факторами. Диагноз ставит врач на основании комплексного обследования', 'Veränderungen des Werts können mit dem Zustand der Leber, der Medikamenteneinnahme, Alkohol oder anderen Faktoren zusammenhängen. Die Diagnose wird vom Arzt anhand einer umfassenden Untersuchung gestellt', 'Değerdeki değişiklikler karaciğerin durumu, ilaç kullanımı, alkol veya diğer etkenlerle ilişkili olabilir. Tanı, kapsamlı bir muayene sonucunda hekim tarafından konur')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'hba1c'), 'Blood test for glycated hemoglobin (HbA1c), reflecting the average blood sugar level over the past 2–3 months', 'Analiza krvi na glikozilirani hemoglobin (HbA1c), koji odražava prosječan nivo šećera u posljednja 2–3 mjeseca', 'Анализа крви на гликозилирани хемоглобин (HbA1c), који одражава просјечан ниво шећера у посљедња 2–3 мјесеца', 'Анализ крови на гликированный гемоглобин (HbA1c), отражающий средний уровень сахара за последние 2–3 месяца', 'Bluttest zur Bestimmung des glykierten Hämoglobins (HbA1c), der den durchschnittlichen Blutzuckerspiegel der letzten 2–3 Monate widerspiegelt', 'Son 2-3 aylık ortalama kan şekeri düzeyini yansıtan glikozillenmiş hemoglobin (HbA1c) düzeyini ölçen kan testi', 'Venous blood draw, no special preparation required', 'Uzimanje venske krvi, posebna priprema nije potrebna', 'Узимање венске крви, посебна припрема није потребна', 'Забор венозной крови, специальная подготовка не требуется', 'Entnahme von venösem Blut, keine besondere Vorbereitung erforderlich', 'Toplardamardan kan alınması, özel bir hazırlık gerekmez', 'Diagnosis and monitoring of diabetes mellitus, assessment of carbohydrate metabolism during routine check-ups', 'Dijagnostika i kontrola dijabetesa, procjena metabolizma ugljenih hidrata u okviru sistematskog pregleda', 'Дијагностика и контрола дијабетеса, процјена метаболизма угљених хидрата у оквиру систематског прегледа', 'Диагностика и контроль сахарного диабета, оценка углеводного обмена при диспансеризации', 'Diagnose und Kontrolle von Diabetes mellitus, Beurteilung des Kohlenhydratstoffwechsels im Rahmen einer Vorsorgeuntersuchung', 'Diyabetin tanısı ve takibi, genel sağlık kontrolünde karbonhidrat metabolizmasının değerlendirilmesi', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'Changes in the level may be related to carbohydrate metabolism over an extended period. The exact interpretation and diagnosis are made by a doctor', 'Promjene nivoa mogu biti povezane sa metabolizmom ugljenih hidrata tokom dužeg perioda. Tačno tumačenje i dijagnozu daje ljekar', 'Промјене нивоа могу бити повезане са метаболизмом угљених хидрата током дужег периода. Тачно тумачење и дијагнозу даје љекар', 'Изменения уровня могут быть связаны с особенностями углеводного обмена за длительный период. Точную интерпретацию и диагноз даёт врач', 'Veränderungen des Werts können mit dem Kohlenhydratstoffwechsel über einen längeren Zeitraum zusammenhängen. Die genaue Interpretation und Diagnose erfolgt durch den Arzt', 'Değerdeki değişiklikler uzun bir dönem boyunca karbonhidrat metabolizmasıyla ilişkili olabilir. Kesin yorumlama ve tanı hekim tarafından yapılır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'total-protein'), 'Blood test for total protein — the combined content of plasma proteins in the blood', 'Analiza krvi na ukupne proteine — zbirni sadržaj proteina plazme u krvi', 'Анализа крви на укупне протеине — збирни садржај протеина плазме у крви', 'Анализ крови на общий белок — суммарное содержание белков плазмы крови', 'Bluttest zur Bestimmung des Gesamtproteins — des Gesamtgehalts an Plasmaproteinen im Blut', 'Kandaki plazma proteinlerinin toplam miktarını ölçen total protein testi', 'Venous blood draw on an empty stomach', 'Uzimanje venske krvi natašte', 'Узимање венске крви наташте', 'Забор венозной крови натощак', 'Entnahme von venösem Blut nüchtern', 'Aç karnına toplardamardan kan alınması', 'Routine check-ups, assessment of nutritional status, liver and kidney function, general examination for weakness or swelling', 'Sistematski pregled, procjena stanja uhranjenosti, rada jetre i bubrega, opšte ispitivanje kod slabosti ili otoka', 'Систематски преглед, процјена стања ухрањености, рада јетре и бубрега, опште испитивање код слабости или отока', 'Диспансеризация, оценка состояния питания, работы печени и почек, общее обследование при слабости или отёках', 'Vorsorgeuntersuchung, Beurteilung des Ernährungszustands, der Leber- und Nierenfunktion, allgemeine Abklärung bei Schwäche oder Ödemen', 'Genel sağlık kontrolü, beslenme durumunun, karaciğer ve böbrek fonksiyonunun değerlendirilmesi, halsizlik veya ödemde genel inceleme', 'Fasting for 8 hours, only water allowed', 'Natašte 8 sati, dozvoljena samo voda', 'Наташте 8 сати, дозвољена само вода', 'Натощак 8 часов, разрешена только вода', '8 Stunden nüchtern, nur Wasser erlaubt', '8 saat aç karnına, sadece su içilebilir', 'Changes in the level may be related to diet, liver and kidney condition, dehydration, or inflammatory processes. The cause is determined by a doctor', 'Promjene nivoa mogu biti povezane sa ishranom, stanjem jetre i bubrega, dehidracijom ili zapaljenskim procesima. Uzrok utvrđuje ljekar', 'Промјене нивоа могу бити повезане са исхраном, стањем јетре и бубрега, дехидрацијом или запаљенским процесима. Узрок утврђује љекар', 'Изменения уровня могут быть связаны с питанием, состоянием печени и почек, обезвоживанием или воспалительными процессами. Причину устанавливает врач', 'Veränderungen des Werts können mit der Ernährung, dem Zustand von Leber und Nieren, Dehydrierung oder Entzündungsprozessen zusammenhängen. Die Ursache wird vom Arzt festgestellt', 'Değerdeki değişiklikler beslenme, karaciğer ve böbreklerin durumu, sıvı kaybı veya iltihabi süreçlerle ilişkili olabilir. Neden hekim tarafından belirlenir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'total-bilirubin'), 'Blood test for total bilirubin — a pigment formed during the breakdown of red blood cells and neutralized by the liver', 'Analiza krvi na ukupni bilirubin — pigment koji nastaje razgradnjom eritrocita, a neutrališe ga jetra', 'Анализа крви на укупни билирубин — пигмент који настаје разградњом еритроцита, а неутралише га јетра', 'Анализ крови на общий билирубин — пигмент, образующийся при распаде эритроцитов и обезвреживаемый печенью', 'Bluttest zur Bestimmung des Gesamtbilirubins — eines Pigments, das beim Abbau roter Blutkörperchen entsteht und von der Leber verarbeitet wird', 'Alyuvarların yıkımı sırasında oluşan ve karaciğer tarafından zararsız hale getirilen bir pigment olan total bilirubin düzeyini ölçen kan testi', 'Venous blood draw, usually on an empty stomach', 'Uzimanje venske krvi, obično natašte', 'Узимање венске крви, обично наташте', 'Забор венозной крови, обычно натощак', 'Entnahme von venösem Blut, in der Regel nüchtern', 'Genellikle aç karnına toplardamardan kan alınması', 'Assessment of liver and bile duct function, examination for yellowing of the skin or sclera, routine check-ups', 'Procjena rada jetre i žučnih puteva, ispitivanje kod žutila kože ili bjeloočnica, sistematski pregled', 'Процјена рада јетре и жучних путева, испитивање код жутила коже или бјелоочница, систематски преглед', 'Оценка работы печени и желчевыводящих путей, обследование при желтухе кожи или склер, диспансеризация', 'Beurteilung der Leber- und Gallenwegsfunktion, Abklärung bei Gelbfärbung von Haut oder Skleren, Vorsorgeuntersuchung', 'Karaciğer ve safra yollarının fonksiyonunun değerlendirilmesi, ciltte veya göz akında sararma durumunda inceleme, genel sağlık kontrolü', 'Fasting for 4–8 hours, only water allowed; avoid fatty foods the day before', 'Natašte 4–8 sati, dozvoljena samo voda; dan ranije izbjegavati masnu hranu', 'Наташте 4–8 сати, дозвољена само вода; дан раније избјегавати масну храну', 'Натощак 4–8 часов, разрешена только вода; накануне избегать жирной пищи', '4–8 Stunden nüchtern, nur Wasser erlaubt; am Vortag fettreiche Speisen vermeiden', '4–8 saat aç karnına, sadece su içilebilir; bir önceki gün yağlı yiyeceklerden kaçınılmalıdır', 'Changes in the level may be related to liver function, bile duct function, or increased breakdown of red blood cells. The exact cause is determined by a doctor', 'Promjene nivoa mogu biti povezane sa radom jetre, žučnih puteva ili pojačanom razgradnjom eritrocita. Tačan uzrok utvrđuje ljekar', 'Промјене нивоа могу бити повезане са радом јетре, жучних путева или појачаном разградњом еритроцита. Тачан узрок утврђује љекар', 'Изменения уровня могут быть связаны с работой печени, желчевыводящих путей или повышенным распадом эритроцитов. Точную причину определяет врач', 'Veränderungen des Werts können mit der Leberfunktion, den Gallenwegen oder einem verstärkten Abbau roter Blutkörperchen zusammenhängen. Die genaue Ursache wird vom Arzt festgestellt', 'Değerdeki değişiklikler karaciğer fonksiyonu, safra yolları veya alyuvarların artmış yıkımıyla ilişkili olabilir. Kesin nedeni hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'gamma-gt'), 'Blood test for a liver enzyme, often linked to the function of the bile ducts', 'Analiza krvi na jetreni enzim, često povezan sa radom žučnih puteva', 'Анализа крви на јетрени ензим, често повезан са радом жучних путева', 'Анализ крови на фермент печени, часто связанный с работой желчевыводящих путей', 'Bluttest auf ein Leberenzym, das oft mit der Funktion der Gallenwege zusammenhängt', 'Sıklıkla safra yollarının işleyişiyle ilişkili bir karaciğer enzimine bakan kan testi', 'Venous blood draw', 'Uzimanje venske krvi', 'Узимање венске крви', 'Забор венозной крови', 'Entnahme von venösem Blut', 'Venöz kan alımı', 'Assessment of liver and bile duct function, monitoring during certain medications, monitoring with regular alcohol consumption', 'Procjena rada jetre i žučnih puteva, kontrola pri uzimanju određenih lijekova, praćenje kod redovne konzumacije alkohola', 'Процјена рада јетре и жучних путева, контрола при узимању одређених лијекова, праћење код редовне конзумације алкохола', 'Оценка работы печени и желчевыводящих путей, контроль при приёме некоторых препаратов, наблюдение при регулярном употреблении алкоголя', 'Beurteilung der Leber- und Gallenwegsfunktion, Kontrolle bei Einnahme bestimmter Medikamente, Überwachung bei regelmäßigem Alkoholkonsum', 'Karaciğer ve safra yolları işlevinin değerlendirilmesi, belirli ilaçların kullanımı sırasında kontrol, düzenli alkol tüketiminde izleme', 'Preferably fasting; avoid alcohol the day before', 'Poželjno natašte; dan ranije izbjegavati alkohol', 'Пожељно наташте; дан раније избјегавати алкохол', 'Желательно натощак; накануне избегать алкоголя', 'Vorzugsweise nüchtern; am Vortag auf Alkohol verzichten', 'Tercihen aç karnına; bir önceki gün alkolden kaçınılmalı', 'An elevated level may be related to liver or bile duct disorders, certain medications, or alcohol consumption. The exact cause is determined by a doctor.', 'Povećanje može biti povezano sa poremećajima rada jetre, žučnih puteva, uzimanjem određenih lijekova ili alkohola. Tačan uzrok određuje ljekar.', 'Повећање може бити повезано са поремећајима рада јетре, жучних путева, узимањем одређених лијекова или алкохола. Тачан узрок одређује љекар.', 'Повышение может быть связано с нарушениями работы печени, желчевыводящих путей, приёмом некоторых препаратов или алкоголя. Точную причину определяет врач', 'Ein erhöhter Wert kann mit Leber- oder Gallenwegserkrankungen, bestimmten Medikamenten oder Alkoholkonsum zusammenhängen. Die genaue Ursache wird vom Arzt bestimmt.', 'Yükselme, karaciğer veya safra yolu bozuklukları, belirli ilaçlar ya da alkol kullanımıyla ilişkili olabilir. Kesin nedeni hekim belirler.')
