INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'rheumatoid-factor'), 'Blood test for rheumatoid factor — antibodies checked when evaluating joint conditions', 'Analiza krvi na reumatoidni faktor — antitijela koja se određuju pri pregledu zglobova', 'Анализа крви на реуматоидни фактор — антитијела која се одређују при прегледу зглобова', 'Анализ крови на ревматоидный фактор — антитела, которые определяют при обследовании суставов', 'Bluttest auf den Rheumafaktor — Antikörper, die bei der Untersuchung der Gelenke bestimmt werden', 'Eklemlerin değerlendirilmesinde bakılan romatoid faktör antikorları için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Joint pain and swelling, morning stiffness, evaluation when an autoimmune condition is suspected', 'Bolovi i otok zglobova, jutarnja ukočenost, pregled pri sumnji na autoimune bolesti', 'Болови и оток зглобова, јутарња укоченост, преглед при сумњи на аутоимуне болести', 'Боли и припухлость суставов, утренняя скованность, обследование при подозрении на аутоиммунные заболевания', 'Gelenkschmerzen und -schwellungen, Morgensteifigkeit, Untersuchung bei Verdacht auf Autoimmunerkrankungen', 'Eklem ağrısı ve şişliği, sabah tutukluğu, otoimmün hastalık şüphesinde değerlendirme', 'No special preparation required; fasting is recommended', 'Nije potrebna posebna priprema, poželjno je doći natašte', 'Није потребна посебна припрема, пожељно је доћи наташте', 'Специальной подготовки не требуется, желательно сдавать натощак', 'Keine besondere Vorbereitung erforderlich, nüchtern wird empfohlen', 'Özel bir hazırlık gerekmez, aç karnına yaptırılması önerilir', 'Changes in the level may be related to autoimmune joint diseases, though they can sometimes occur with other conditions as well. The doctor interprets the result together with the clinical picture', 'Promjene nivoa mogu biti povezane sa autoimunim bolestima zglobova, a ponekad se javljaju i kod drugih stanja. Tumačenje zajedno sa kliničkom slikom vrši ljekar', 'Промјене нивоа могу бити повезане са аутоимуним болестима зглобова, а понекад се јављају и код других стања. Тумачење заједно са клиничком сликом врши љекар', 'Изменения уровня могут быть связаны с аутоиммунными заболеваниями суставов, а иногда встречаются и при других состояниях. Интерпретацию вместе с клинической картиной проводит врач', 'Veränderungen des Spiegels können mit Autoimmunerkrankungen der Gelenke zusammenhängen, treten aber gelegentlich auch bei anderen Zuständen auf. Die Interpretation zusammen mit dem klinischen Bild erfolgt durch den Arzt', 'Düzeydeki değişiklikler eklemlerin otoimmün hastalıklarıyla ilişkili olabilir, bazen başka durumlarda da görülebilir. Klinik tabloyla birlikte yorumlanması doktor tarafından yapılır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'anti-tpo'), 'Blood test for antibodies to thyroid peroxidase (Anti-TPO) — a marker used when evaluating the thyroid gland', 'Analiza krvi na antitijela na tireoperoksidazu (Anti-TPO) — marker koji se koristi pri pregledu štitne žlijezde', 'Анализа крви на антитијела на тиреопероксидазу (Анти-ТПО) — маркер који се користи при прегледу штитне жлијезде', 'Анализ крови на антитела к тиреопероксидазе (Anti-TPO) — маркер, используемый при обследовании щитовидной железы', 'Bluttest auf Antikörper gegen Thyreoperoxidase (Anti-TPO) — ein Marker zur Untersuchung der Schilddrüse', 'Tiroid bezinin değerlendirilmesinde kullanılan tiroid peroksidaz antikorları (Anti-TPO) için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Evaluation of an enlarged thyroid, changes in hormone levels, pregnancy planning', 'Pregled pri uvećanju štitne žlijezde, promjenama hormonskog statusa, planiranju trudnoće', 'Преглед при увећању штитне жлијезде, промјенама хормонског статуса, планирању трудноће', 'Обследование при увеличении щитовидной железы, изменениях гормонального фона, планировании беременности', 'Untersuchung bei vergrößerter Schilddrüse, Veränderungen des Hormonstatus, Schwangerschaftsplanung', 'Tiroid büyümesi, hormon düzeylerindeki değişiklikler, gebelik planlaması durumunda değerlendirme', 'No special preparation required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'An increased antibody level may be related to autoimmune thyroid involvement. The endocrinologist evaluates the result together with hormone levels and ultrasound', 'Povećanje nivoa antitijela može biti povezano sa autoimunim oštećenjem štitne žlijezde. Procjenu rezultata zajedno sa hormonima i ultrazvukom vrši endokrinolog', 'Повећање нивоа антитијела може бити повезано са аутоимуним оштећењем штитне жлијезде. Процјену резултата заједно са хормонима и ултразвуком врши ендокринолог', 'Повышение уровня антител может быть связано с аутоиммунным поражением щитовидной железы. Оценку результата вместе с гормонами и УЗИ проводит эндокринолог', 'Ein erhöhter Antikörperspiegel kann mit einer Autoimmunerkrankung der Schilddrüse zusammenhängen. Die Beurteilung des Ergebnisses zusammen mit den Hormonwerten und dem Ultraschall erfolgt durch den Endokrinologen', 'Antikor düzeyindeki artış tiroid bezinin otoimmün tutulumuyla ilişkili olabilir. Sonucun hormon düzeyleri ve ultrason ile birlikte değerlendirilmesi endokrinolog tarafından yapılır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'psa'), 'Blood test for prostate-specific antigen (PSA) — an indicator used when evaluating the prostate gland in men', 'Analiza krvi na prostata-specifični antigen (PSA) — pokazatelj koji se koristi pri pregledu prostate kod muškaraca', 'Анализа крви на простата-специфични антиген (PSA) — показатељ који се користи при прегледу простате код мушкараца', 'Анализ крови на простат-специфический антиген (PSA) — показатель, используемый при обследовании простаты у мужчин', 'Bluttest auf prostataspezifisches Antigen (PSA) — ein Wert zur Untersuchung der Prostata bei Männern', 'Erkeklerde prostat bezinin değerlendirilmesinde kullanılan prostata özgü antijen (PSA) için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Preventive check-up for older men, routine visit to a urologist', 'Preventivni pregled muškaraca starije životne dobi, redovna posjeta urologu', 'Превентивни преглед мушкараца старије животне доби, редовна посјета урологу', 'Профилактическое обследование мужчин старшего возраста, плановый визит к урологу', 'Vorsorgeuntersuchung bei älteren Männern, routinemäßiger Besuch beim Urologen', 'İleri yaştaki erkeklerde koruyucu kontrol, ürolog ile rutin muayene', 'It is recommended to avoid ejaculation and intense physical activity for 24–48 hours beforehand; the sample should be taken before a digital rectal exam or a few days after it', 'Preporučuje se uzdržavanje od ejakulacije i intenzivnog fizičkog napora 24–48 sati ranije; uzorak treba uzeti prije digitorektalnog pregleda ili nekoliko dana poslije njega', 'Препоручује се уздржавање од ејакулације и интензивног физичког напора 24–48 сати раније; узорак треба узети прије дигиторекталног прегледа или неколико дана послије њега', 'Рекомендуется воздержаться от эякуляции и интенсивной физической нагрузки за 24–48 часов; сдавать до пальцевого ректального осмотра или через несколько дней после него', 'Es wird empfohlen, 24–48 Stunden vorher auf Ejakulation und intensive körperliche Belastung zu verzichten; die Blutentnahme sollte vor einer digital-rektalen Untersuchung oder einige Tage danach erfolgen', 'Testten 24-48 saat önce ejakülasyondan ve yoğun fiziksel aktiviteden kaçınılması önerilir; numunenin parmakla rektal muayeneden önce veya birkaç gün sonra alınması gerekir', 'An increase may be related to various conditions of the prostate, including benign ones — the urologist decides on further evaluation', 'Povećanje može biti povezano sa različitim stanjima prostate, uključujući benigna — pitanje daljeg pregleda rješava urolog', 'Повећање може бити повезано са различитим стањима простате, укључујући бенигна — питање даљег прегледа рјешава уролог', 'Повышение может быть связано с разными состояниями простаты, включая доброкачественные — вопрос дальнейшего обследования решает уролог', 'Ein Anstieg kann mit verschiedenen Erkrankungen der Prostata zusammenhängen, einschließlich gutartiger — über die weitere Untersuchung entscheidet der Urologe', 'Yükselme, iyi huylu olanlar dahil olmak üzere prostatın çeşitli durumlarıyla ilişkili olabilir — ileri değerlendirme gerekip gerekmediğine ürolog karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'beta-hcg'), 'Blood test for the beta subunit of human chorionic gonadotropin (Beta hCG) — a hormone produced during pregnancy', 'Analiza krvi na beta-podjedinicu humanog horionskog gonadotropina (Beta HCG) — hormon koji se stvara tokom trudnoće', 'Анализа крви на бета-подјединицу хуманог хорионског гонадотропина (Бета HCG) — хормон који се ствара током трудноће', 'Анализ крови на бета-субъединицу хорионического гонадотропина человека (Beta HCG) — гормон, вырабатываемый при беременности', 'Bluttest auf die Beta-Untereinheit des humanen Choriongonadotropins (Beta-hCG) — ein während der Schwangerschaft gebildetes Hormon', 'Gebelik sırasında üretilen bir hormon olan insan koryonik gonadotropininin beta alt birimi (Beta hCG) için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Early pregnancy diagnosis, monitoring during the first trimester', 'Dijagnostika rane trudnoće, kontrola u prvom trimestru', 'Дијагностика ране трудноће, контрола у првом триместру', 'Диагностика ранней беременности, контроль в первом триместре', 'Diagnose einer frühen Schwangerschaft, Kontrolle im ersten Trimester', 'Erken gebelik tanısı, ilk trimesterde takip', 'No special preparation required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The result is interpreted by the doctor over time together with an ultrasound — interpreting a single value on its own does not give the full picture', 'Rezultat tumači ljekar u dinamici zajedno sa ultrazvukom — samostalno tumačenje jedne vrijednosti ne odražava potpunu sliku', 'Резултат тумачи љекар у динамици заједно са ултразвуком — самостално тумачење једне вриједности не одражава потпуну слику', 'Результат интерпретируется врачом в динамике вместе с УЗИ — самостоятельная трактовка одного значения не отражает полной картины', 'Das Ergebnis wird vom Arzt im Verlauf zusammen mit dem Ultraschall interpretiert — die eigenständige Deutung eines einzelnen Werts ergibt kein vollständiges Bild', 'Sonuç, doktor tarafından zaman içindeki seyriyle ve ultrason ile birlikte yorumlanır — tek bir değerin kendi başına yorumlanması tam tabloyu yansıtmaz')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'helicobacter-pylori-antigen-in-feces'), 'Stool test for Helicobacter pylori antigen', 'Test stolice na antigen bakterije Helicobacter pylori', 'Тест столице на антиген бактерије Хелицобацтер пyлори', 'Тест кала на антиген бактерии Helicobacter pylori', 'Stuhltest auf Helicobacter-pylori-Antigen', 'Helicobacter pylori bakterisi antijeni için dışkı testi', 'Collecting a small stool sample in a container at home, then delivering it to the laboratory', 'Uzimanje malog uzorka stolice u kontejner kod kuće, uz naknadnu dostavu u laboratoriju', 'Узимање малог узорка столице у контејнер код куће, уз накнадну доставу у лабораторију', 'Сбор небольшого образца кала в контейнер в домашних условиях с последующей доставкой в лабораторию', 'Zu Hause wird eine kleine Stuhlprobe in einem Behälter gesammelt und anschließend ins Labor gebracht', 'Evde küçük bir dışkı örneğinin kaba alınması ve ardından laboratuvara ulaştırılması', 'Stomach pain, heartburn, evaluation for gastritis or peptic ulcer disease, follow-up after treatment', 'Bolovi u stomaku, žgaravica, pregled pri gastritisu ili čirevima, kontrola poslije liječenja', 'Болови у стомаку, жгаравица, преглед при гастритису или чиревима, контрола послије лијечења', 'Боли в желудке, изжога, обследование при гастрите или язвенной болезни, контроль после лечения', 'Magenschmerzen, Sodbrennen, Untersuchung bei Gastritis oder Magengeschwür, Kontrolle nach der Behandlung', 'Mide ağrısı, mide ekşimesi, gastrit veya peptik ülser değerlendirmesi, tedavi sonrası kontrol', 'Two weeks before the test, in agreement with your doctor, stop antibiotics and acid-suppressing medications; the sample should not contain any traces of urine', 'Dvije sedmice prije testa, uz dogovor sa ljekarom, prekinuti uzimanje antibiotika i lijekova koji smanjuju kiselost; uzorak ne smije sadržati primjese urina', 'Двије седмице прије теста, уз договор са љекаром, прекинути узимање антибиотика и лијекова који смањују киселост; узорак не смије садржати примјесе урина', 'За 2 недели до теста по согласованию с врачом отменить антибиотики и препараты, подавляющие кислотность; образец не должен содержать примесей мочи', 'Zwei Wochen vor dem Test sollten nach Rücksprache mit dem Arzt Antibiotika und säurehemmende Medikamente abgesetzt werden; die Probe darf keine Urinbeimengungen enthalten', 'Testten 2 hafta önce doktora danışarak antibiyotikler ve asit baskılayıcı ilaçların kesilmesi gerekir; numune idrar bulaşığı içermemelidir', 'A positive result may indicate the presence of an infection in the stomach lining. The gastroenterologist determines the further course of action', 'Pozitivan rezultat može biti povezan sa prisustvom infekcije na sluzokoži stomaka. Dalju taktiku određuje ljekar-gastroenterolog', 'Позитиван резултат може бити повезан са присуством инфекције на слузокожи стомака. Даљу тактику одређује љекар-гастроентеролог', 'Положительный результат может быть связан с наличием инфекции в слизистой желудка. Дальнейшую тактику определяет врач-гастроэнтеролог', 'Ein positives Ergebnis kann auf eine Infektion der Magenschleimhaut hinweisen. Das weitere Vorgehen bestimmt der Gastroenterologe', 'Pozitif sonuç, mide mukozasında enfeksiyon varlığıyla ilişkili olabilir. İleri yaklaşımı gastroenterolog belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'papp-a'), 'Pregnancy-associated plasma protein A (PAPP-A) — one of the biochemical markers used in first-trimester prenatal screening', 'Protein plazme povezan sa trudnoćom (PAPP-A) — jedan od biohemijskih markera prenatalnog skrininga prvog trimestra', 'Протеин плазме повезан са трудноћом (ПАПП-А) — један од биохемијских маркера пренаталног скрининга првог триместра', 'Белок плазмы, ассоциированный с беременностью (PAPP-A) — один из биохимических маркеров пренатального скрининга первого триместра', 'Schwangerschaftsassoziiertes Plasmaprotein A (PAPP-A) — einer der biochemischen Marker des pränatalen Screenings im ersten Trimester', 'Gebelikle ilişkili plazma proteini A (PAPP-A) — birinci trimester prenatal taramasının biyokimyasal göstergelerinden biri', 'Venous blood draw', 'Uzimanje venske krvi', 'Узимање венске крви', 'Забор венозной крови', 'Entnahme von venösem Blut', 'Toplardamardan kan alınması', 'Combined first-trimester screening (usually 11–13 weeks of pregnancy), together with an ultrasound and other markers', 'Kombinovani skrining prvog trimestra trudnoće (obično 11–13 nedjelja), zajedno sa ultrazvukom i drugim pokazateljima', 'Комбиновани скрининг првог триместра трудноће (обично 11–13 недјеља), заједно са ултразвуком и другим показатељима', 'Комбинированный скрининг первого триместра беременности (обычно 11–13 недель) вместе с УЗИ и другими показателями', 'Kombiniertes Ersttrimester-Screening (in der Regel 11.–13. Schwangerschaftswoche), zusammen mit Ultraschall und weiteren Markern', 'Birinci trimester kombine tarama (genellikle 11–13. gebelik haftaları), ultrason ve diğer göstergelerle birlikte', 'No special preparation is usually required', 'Posebna priprema obično nije potrebna', 'Посебна припрема обично није потребна', 'Специальной подготовки обычно не требуется', 'In der Regel keine besondere Vorbereitung erforderlich', 'Genellikle özel bir hazırlık gerekmez', 'The value is assessed by a doctor only together with ultrasound markers, the free beta-hCG level, and gestational age; this test''s result does not diagnose anything on its own and should not be interpreted separately from the other screening markers', 'Vrijednost procjenjuje ljekar isključivo zajedno sa ultrazvučnim markerima, nivoom slobodnog beta-HCG i gestacijskom starošću; rezultat ovog testa sam po sebi ništa ne dijagnostikuje i ne treba ga tumačiti odvojeno od ostalih pokazatelja skrininga', 'Вриједност процјењује љекар искључиво заједно са ултразвучним маркерима, нивоом слободног бета-HCG и гестацијском старошћу; резултат овог теста сам по себи ништа не дијагностикује и не треба га тумачити одвојено од осталих показатеља скрининга', 'Значение оценивается врачом только в комплексе с УЗИ-маркерами, уровнем свободного бета-ХГЧ и сроком беременности; результат этого теста сам по себе ничего не диагностирует и не должен интерпретироваться отдельно от остальных показателей скрининга', 'Der Wert wird vom Arzt nur zusammen mit den Ultraschallmarkern, dem freien Beta-hCG-Spiegel und dem Schwangerschaftsalter beurteilt; das Ergebnis dieses Tests allein diagnostiziert nichts und sollte nicht getrennt von den übrigen Screening-Werten interpretiert werden', 'Değer, yalnızca ultrason bulguları, serbest beta-hCG düzeyi ve gebelik haftası ile birlikte hekim tarafından değerlendirilir; bu testin sonucu tek başına hiçbir şeyi teşhis etmez ve diğer tarama göstergelerinden ayrı yorumlanmamalıdır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'free-beta-hcg'), 'Free beta subunit of human chorionic gonadotropin — one of the biochemical markers used in first-trimester prenatal screening', 'Slobodna beta-podjedinica humanog horionskog gonadotropina (slobodni beta-HCG) — jedan od biohemijskih markera prenatalnog skrininga prvog trimestra', 'Слободна бета-подјединица хуманог хорионског гонадотропина (слободни бета-HCG) — један од биохемијских маркера пренаталног скрининга првог триместра', 'Свободная бета-субъединица хорионического гонадотропина человека — один из биохимических маркеров пренатального скрининга первого триместра', 'Freie Beta-Untereinheit des humanen Choriongonadotropins — einer der biochemischen Marker des pränatalen Screenings im ersten Trimester', 'İnsan koryonik gonadotropininin serbest beta alt birimi — birinci trimester prenatal taramasının biyokimyasal göstergelerinden biri', 'Venous blood draw', 'Uzimanje venske krvi', 'Узимање венске крви', 'Забор венозной крови', 'Entnahme von venösem Blut', 'Toplardamardan kan alınması', 'Combined first-trimester screening, together with PAPP-A, an ultrasound, and other markers', 'Kombinovani skrining prvog trimestra trudnoće, zajedno sa PAPP-A, ultrazvukom i drugim pokazateljima', 'Комбиновани скрининг првог триместра трудноће, заједно са ПАПП-А, ултразвуком и другим показатељима', 'Комбинированный скрининг первого триместра беременности вместе с PAPP-A, УЗИ и другими показателями', 'Kombiniertes Ersttrimester-Screening, zusammen mit PAPP-A, Ultraschall und weiteren Markern', 'PAPP-A, ultrason ve diğer göstergelerle birlikte birinci trimester kombine tarama', 'No special preparation is usually required', 'Posebna priprema obično nije potrebna', 'Посебна припрема обично није потребна', 'Специальной подготовки обычно не требуется', 'In der Regel keine besondere Vorbereitung erforderlich', 'Genellikle özel bir hazırlık gerekmez', 'The value is assessed by a doctor only together with the other screening markers (PAPP-A, ultrasound findings, gestational age); this test''s result does not diagnose anything on its own', 'Vrijednost procjenjuje ljekar isključivo zajedno sa ostalim pokazateljima skrininga (PAPP-A, ultrazvučni markeri, gestacijska starost); rezultat ovog testa sam po sebi ništa ne dijagnostikuje', 'Вриједност процјењује љекар искључиво заједно са осталим показатељима скрининга (ПАПП-А, ултразвучни маркери, гестацијска старост); резултат овог теста сам по себи ништа не дијагностикује', 'Значение оценивается врачом только в комплексе с остальными показателями скрининга (PAPP-A, УЗИ-маркеры, срок беременности); результат этого теста сам по себе ничего не диагностирует', 'Der Wert wird vom Arzt nur zusammen mit den übrigen Screening-Werten (PAPP-A, Ultraschallbefunde, Schwangerschaftsalter) beurteilt; das Ergebnis dieses Tests allein diagnostiziert nichts', 'Değer, yalnızca diğer tarama göstergeleri (PAPP-A, ultrason bulguları, gebelik haftası) ile birlikte hekim tarafından değerlendirilir; bu testin sonucu tek başına hiçbir şeyi teşhis etmez')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'tooth-extraction-complex'), 'Removal of a tooth that cannot be taken out with forceps alone — the roots are separated or some bone is removed', 'Vađenje zuba koje se ne može uraditi običnim kliještima — uz razdvajanje korijena ili uklanjanje dijela kosti', 'Вађење зуба које се не може урадити обичним клијештима — уз раздвајање коријена или уклањање дијела кости', 'Удаление зуба, которое нельзя выполнить обычными щипцами — с разделением корней или снятием части кости', 'Zahnentfernung, die mit der üblichen Zange nicht möglich ist — mit Trennung der Wurzeln oder Abtragung von Knochen', 'Yalnızca pense ile yapılamayan diş çekimi — kökler ayrılarak veya bir miktar kemik alınarak yapılır', 'Under local anesthesia the tooth is sectioned and taken out in fragments, the gum is lifted and sutured if needed; 30-60 minutes', 'U lokalnoj anesteziji zub se razdvaja na dijelove i vadi u fragmentima, po potrebi se podigne režanj desni i postave konci; 30-60 minuta', 'У локалној анестезији зуб се раздваја на дијелове и вади у фрагментима, по потреби се подигне режањ десни и поставе конци; 30-60 минута', 'Под местной анестезией зуб разделяют на фрагменты и извлекают по частям, при необходимости отслаивают десну и накладывают швы; 30-60 минут', 'In Lokalanästhesie wird der Zahn zerteilt und in Fragmenten entfernt, bei Bedarf wird das Zahnfleisch gelöst und genäht; 30-60 Minuten', 'Lokal anestezi altında diş parçalara ayrılıp parça parça çıkarılır, gerekirse diş eti kaldırılır ve dikiş atılır; 30-60 dakika', 'A destroyed crown, curved or fused roots, a root left in the bone, a brittle tooth after root canal treatment', 'Razrušena kruna, savijeni ili srasli korijeni, korijen zaostao u kosti, krt zub poslije liječenja kanala', 'Разрушена круна, савијени или срасли коријени, коријен заостао у кости, крт зуб послије лијечења канала', 'Разрушенная коронка, искривлённые или сросшиеся корни, оставшийся в кости корень, хрупкий зуб после лечения каналов', 'Zerstörte Zahnkrone, gekrümmte oder verwachsene Wurzeln, im Knochen verbliebene Wurzel, brüchiger Zahn nach Wurzelbehandlung', 'Harap olmuş kron, eğri veya kaynaşmış kökler, kemik içinde kalmış kök, kanal tedavisi sonrası kırılgan diş', 'Eat before the visit, report chronic conditions and blood thinners, bring any existing X-ray', 'Jesti prije dolaska, prijaviti hronične bolesti i lijekove za razrjeđivanje krvi, ponijeti postojeći snimak', 'Јести прије доласка, пријавити хроничне болести и лијекове за разрјеђивање крви, понијети постојећи снимак', 'Поесть перед визитом, сообщить о хронических болезнях и препаратах, разжижающих кровь, взять с собой имеющийся снимок', 'Vor dem Termin essen, chronische Erkrankungen und blutverdünnende Medikamente mitteilen, vorhandene Röntgenaufnahmen mitbringen', 'Randevudan önce yemek yemek, kronik hastalıkları ve kan sulandırıcı ilaçları bildirmek, varsa röntgeni yanında getirmek', 'Swelling, pain and limited mouth opening in the first 2-3 days are expected. If pain increases after the third day, fever appears or bleeding does not stop, see a dentist', 'Otok, bol i otežano otvaranje usta prvih 2-3 dana su očekivani. Ako bol jača poslije trećeg dana, javi se temperatura ili krvarenje ne prestaje, treba se javiti stomatologu', 'Оток, бол и отежано отварање уста првих 2-3 дана су очекивани. Ако бол јача послије трећег дана, јави се температура или крварење не престаје, треба се јавити стоматологу', 'Отёк, боль и ограниченное открывание рта в первые 2-3 дня ожидаемы. Если боль нарастает после третьего дня, поднимается температура или кровотечение не останавливается, нужно показаться стоматологу', 'Schwellung, Schmerzen und eine eingeschränkte Mundöffnung in den ersten 2-3 Tagen sind zu erwarten. Nehmen die Schmerzen nach dem dritten Tag zu, tritt Fieber auf oder stoppt die Blutung nicht, sollte der Zahnarzt aufgesucht werden', 'İlk 2-3 gün şişlik, ağrı ve ağzı açmakta zorlanma beklenen durumlardır. Ağrı üçüncü günden sonra artıyorsa, ateş çıkarsa veya kanama durmuyorsa diş hekimine başvurmak gerekir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'intraoral-abscess-incision'), 'Opening a pus collection in the mouth through an incision in the mucosa so that it can drain', 'Otvaranje gnojne kolekcije u ustima rezom kroz sluzokožu radi otjecanja gnoja', 'Отварање гнојне колекције у устима резом кроз слузокожу ради отјецања гноја', 'Вскрытие гнойного очага в полости рта разрезом со стороны слизистой, чтобы дать отток гною', 'Eröffnung einer Eiteransammlung im Mund über einen Schnitt in der Schleimhaut zur Entlastung', 'Ağız içindeki iltihap birikintisinin mukozadan kesi yapılarak boşaltılması', 'Under local anesthesia a small incision is made in the mucosa, the pus is drained, the cavity is rinsed and a drain is placed if needed; 15-30 minutes', 'U lokalnoj anesteziji napravi se mali rez sluzokože, gnoj se isprazni, šupljina ispere i po potrebi postavi dren; 15-30 minuta', 'У локалној анестезији направи се мали рез слузокоже, гној се испразни, шупљина испере и по потреби постави дрен; 15-30 минута', 'Под местной анестезией делают небольшой разрез слизистой, эвакуируют гной, промывают полость и при необходимости ставят дренаж; 15-30 минут', 'In Lokalanästhesie wird die Schleimhaut kurz eingeschnitten, der Eiter entleert, die Höhle gespült und bei Bedarf eine Drainage eingelegt; 15-30 Minuten', 'Lokal anestezi altında mukozada küçük bir kesi yapılır, iltihap boşaltılır, boşluk yıkanır ve gerekirse dren konur; 15-30 dakika', 'Purulent inflammation near a tooth root or under the mucosa with swelling and pain, a complication of periodontitis or pericoronitis, an infected cyst', 'Gnojna upala uz korijen zuba ili ispod sluzokože sa otokom i bolom, komplikacija parodontitisa ili perikoronitisa, inficirana cista', 'Гнојна упала уз коријен зуба или испод слузокоже са отоком и болом, компликација пародонтитиса или перикоронитиса, инфицирана циста', 'Гнойное воспаление у корня зуба или под слизистой с отёком и болью, осложнение периодонтита или перикоронита, нагноившаяся киста', 'Eitrige Entzündung an einer Zahnwurzel oder unter der Schleimhaut mit Schwellung und Schmerzen, Komplikation einer Parodontitis oder Perikoronitis, infizierte Zyste', 'Diş kökü çevresinde veya mukoza altında şişlik ve ağrıyla seyreden iltihap, periodontit ya da perikoronit komplikasyonu, enfekte kist', 'No special preparation; report allergies to anesthetics and medications taken, and do not postpone the visit if the swelling is growing', 'Posebna priprema nije potrebna; prijaviti alergiju na anestetike i lijekove koje uzimate, ne odlagati dolazak ako otok raste', 'Посебна припрема није потребна; пријавити алергију на анестетике и лијекове које узимате, не одлагати долазак ако оток расте', 'Специальной подготовки нет; сообщить об аллергии на анестетики и принимаемых препаратах, не откладывать визит при нарастающем отёке', 'Keine besondere Vorbereitung; Allergien gegen Betäubungsmittel und eingenommene Medikamente mitteilen, den Termin bei zunehmender Schwellung nicht aufschieben', 'Özel hazırlık gerekmez; anestezi alerjisi ve kullanılan ilaçlar bildirilmeli, şişlik büyüyorsa başvuru ertelenmemelidir', 'After drainage the pain usually eases quickly, with swelling and slight discharge for a few days. If the swelling grows, fever appears or swallowing and opening the mouth become difficult, seek medical help urgently', 'Poslije otjecanja gnoja bol obično brzo popušta, a otok i oskudan iscjedak mogu trajati nekoliko dana. Ako otok raste, javi se temperatura ili otežano gutanje i otvaranje usta, treba se hitno javiti ljekaru', 'Послије отјецања гноја бол обично брзо попушта, а оток и оскудан исцједак могу трајати неколико дана. Ако оток расте, јави се температура или отежано гутање и отварање уста, треба се хитно јавити љекару', 'После оттока гноя боль обычно быстро уменьшается, несколько дней возможны отёк и скудное отделяемое. Если отёк растёт, поднимается температура или затрудняются глотание и открывание рта, нужно срочно обратиться к врачу', 'Nach der Entlastung lassen die Schmerzen meist rasch nach, Schwellung und geringe Sekretion können einige Tage bestehen. Nimmt die Schwellung zu, tritt Fieber auf oder werden Schlucken und Mundöffnung schwierig, ist umgehend ärztliche Hilfe nötig', 'Boşaltmadan sonra ağrı genellikle hızla azalır, birkaç gün şişlik ve hafif akıntı olabilir. Şişlik artarsa, ateş çıkarsa ya da yutma ve ağzı açma güçleşirse acilen hekime başvurulmalıdır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'cystectomy'), 'Surgical removal of a jaw cyst together with its lining', 'Hirurško uklanjanje ciste vilice zajedno sa njenom ovojnicom', 'Хируршко уклањање цисте вилице заједно са њеном овојницом', 'Операция по удалению кисты челюсти вместе с её оболочкой', 'Operative Entfernung einer Kieferzyste samt ihrer Hülle', 'Çene kistinin zarıyla birlikte cerrahi olarak çıkarılması', 'Under local anesthesia a gum flap is raised, the bone is opened, the cyst is removed with its lining and the wound is sutured; 30-60 minutes, sutures out after 7-10 days', 'U lokalnoj anesteziji podiže se režanj desni, otvori pristup kosti, cista se odstrani sa ovojnicom, a rana zašije; 30-60 minuta, konci se skidaju nakon 7-10 dana', 'У локалној анестезији подиже се режањ десни, отвори приступ кости, циста се одстрани са овојницом, а рана зашије; 30-60 минута, конци се скидају након 7-10 дана', 'Под местной анестезией отслаивают лоскут десны, открывают доступ к кости, удаляют кисту с оболочкой, рану ушивают; 30-60 минут, швы снимают через 7-10 дней', 'In Lokalanästhesie wird ein Zahnfleischlappen gebildet, der Knochen freigelegt, die Zyste mit Hülle entfernt und die Wunde genäht; 30-60 Minuten, Fadenentfernung nach 7-10 Tagen', 'Lokal anestezi altında diş eti flebi kaldırılır, kemiğe ulaşılır, kist zarıyla birlikte alınır ve yara dikilir; 30-60 dakika, dikişler 7-10 gün sonra alınır', 'A cyst at a tooth root seen on an X-ray, a cyst that is growing or has become infected, preparation for implants or prosthetics', 'Cista uz korijen zuba viđena na snimku, cista koja raste ili se inficirala, priprema za implantaciju ili protetiku', 'Циста уз коријен зуба виђена на снимку, циста која расте или се инфицирала, припрема за имплантацију или протетику', 'Киста у корня зуба, выявленная на снимке, киста, которая растёт или нагноилась, подготовка к имплантации или протезированию', 'Im Röntgenbild entdeckte Zyste an einer Zahnwurzel, wachsende oder infizierte Zyste, Vorbereitung auf Implantate oder Zahnersatz', 'Röntgende görülen diş kökü kisti, büyüyen veya enfekte olan kist, implant ya da protez öncesi hazırlık', 'An X-ray or CT scan as ordered by the dentist, eat before the visit, report medications being taken, especially blood thinners', 'Potreban je snimak ili skener po nalogu stomatologa, jesti prije dolaska, prijaviti lijekove koje uzimate, posebno one za razrjeđivanje krvi', 'Потребан је снимак или скенер по налогу стоматолога, јести прије доласка, пријавити лијекове које узимате, посебно оне за разрјеђивање крви', 'Нужен снимок или КТ по назначению врача, поесть перед визитом, сообщить о принимаемых препаратах, особенно разжижающих кровь', 'Röntgen- oder DVT-Aufnahme nach Anweisung des Zahnarztes, vor dem Termin essen, eingenommene Medikamente mitteilen, insbesondere Blutverdünner', 'Hekimin istediği röntgen veya tomografi, randevudan önce yemek yemek, kullanılan ilaçların, özellikle kan sulandırıcıların bildirilmesi', 'Swelling and tenderness in the first days are expected; the bone at the site fills in over months. Increasing pain, fever or discharge from the wound is a reason to come in sooner; healing is assessed by the dentist on a follow-up X-ray', 'Otok i osjetljivost prvih dana su očekivani, a kost na mjestu šupljine popunjava se mjesecima. Bol koji jača, temperatura ili iscjedak iz rane razlog su za raniji dolazak; zarastanje stomatolog procjenjuje na kontrolnom snimku', 'Оток и осјетљивост првих дана су очекивани, а кост на мјесту шупљине попуњава се мјесецима. Бол који јача, температура или исцједак из ране разлог су за ранији долазак; зарастање стоматолог процјењује на контролном снимку', 'Отёк и болезненность в первые дни ожидаемы, кость на месте полости восстанавливается месяцами. Нарастающая боль, температура или выделения из раны — повод обратиться раньше срока; заживление стоматолог оценивает по контрольному снимку', 'Schwellung und Druckempfindlichkeit in den ersten Tagen sind zu erwarten, der Knochen füllt den Hohlraum über Monate auf. Zunehmende Schmerzen, Fieber oder Sekret aus der Wunde sind ein Grund für einen früheren Termin; die Heilung beurteilt der Zahnarzt auf einer Kontrollaufnahme', 'İlk günlerde şişlik ve hassasiyet beklenir, boşluktaki kemik aylar içinde dolar. Artan ağrı, ateş veya yaradan akıntı erken başvuru nedenidir; iyileşmeyi hekim kontrol röntgeniyle değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'dental-calculus-removal-and-air-flow'), 'Removal of hardened deposits with an ultrasonic scaler followed by Air-Flow treatment that clears stained plaque', 'Skidanje tvrdih naslaga ultrazvukom i naknadni tretman Air-Flow aparatom koji uklanja pigmentne naslage', 'Скидање тврдих наслага ултразвуком и накнадни третман Air-Flow апаратом који уклања пигментне наслаге', 'Снятие твёрдых зубных отложений ультразвуком и последующая обработка аппаратом Air-Flow, убирающим пигментный налёт', 'Entfernung harter Beläge mit Ultraschall und anschließende Air-Flow-Reinigung, die Verfärbungen löst', 'Sert birikintilerin ultrasonla temizlenmesi ve ardından renklenmeleri gideren Air-Flow uygulaması', 'The scaler removes calculus above and at the gum margin, then a jet of water with fine powder cleans plaque between the teeth and in the fissures, finishing with polishing; 30-45 minutes', 'Ultrazvučnim skalerom uklanja se kamenac iznad i uz rub desni, zatim mlaz vode sa finim prahom čisti naslage u međuzubnim prostorima i fisurama, na kraju slijedi poliranje; 30-45 minuta', 'Ултразвучним скалером уклања се каменац изнад и уз руб десни, затим млаз воде са финим прахом чисти наслаге у међузубним просторима и фисурама, на крају слиједи полирање; 30-45 минута', 'Ультразвуковым скейлером снимают камень над десной и у её края, затем струёй воды с мелким порошком очищают налёт в промежутках и фиссурах, в конце полируют; 30-45 минут', 'Mit dem Ultraschallscaler wird Zahnstein über und am Zahnfleischrand entfernt, danach reinigt ein Wasser-Pulver-Strahl Beläge in den Zwischenräumen und Fissuren, zum Schluss wird poliert; 30-45 Minuten', 'Ultrasonik aletle diş eti kenarındaki ve üstündeki taşlar alınır, sonra su ve ince toz püskürtülerek ara yüzlerdeki ve fissürlerdeki birikinti temizlenir, işlem cilalamayla biter; 30-45 dakika', 'Visible calculus, staining from coffee, tea and smoking, bleeding gums, routine hygiene, preparation for whitening, prosthetics or braces', 'Vidljiv zubni kamenac, naslage od kafe, čaja i duvana, krvarenje desni, redovna higijena, priprema za bijeljenje, protetiku ili fiksni aparatić', 'Видљив зубни каменац, наслаге од кафе, чаја и дувана, крварење десни, редовна хигијена, припрема за бијељење, протетику или фиксни апаратић', 'Видимый зубной камень, налёт от кофе, чая и курения, кровоточивость дёсен, плановая гигиена, подготовка к отбеливанию, протезированию или брекетам', 'Sichtbarer Zahnstein, Verfärbungen durch Kaffee, Tee und Rauchen, Zahnfleischbluten, regelmäßige Prophylaxe, Vorbereitung auf Bleaching, Zahnersatz oder feste Zahnspange', 'Görünür diş taşı, kahve, çay ve sigara lekeleri, diş eti kanaması, rutin ağız bakımı, beyazlatma, protez veya ortodontik tedavi öncesi hazırlık', 'No preparation needed; mention sensitive teeth, gum disease and a pacemaker if you have one', 'Priprema nije potrebna; napomenuti osjetljivost zuba, bolesti desni i postojanje pejsmejkera', 'Припрема није потребна; напоменути осјетљивост зуба, болести десни и постојање пејсмејкера', 'Подготовка не нужна; предупредить о чувствительности зубов, заболеваниях дёсен и наличии кардиостимулятора', 'Keine Vorbereitung nötig; empfindliche Zähne, Zahnfleischerkrankungen und einen Herzschrittmacher vorher mitteilen', 'Hazırlık gerekmez; diş hassasiyeti, diş eti hastalığı ve kalp pili varsa bildirilmelidir', 'Sensitivity to cold and slight gum bleeding may last a day or two. If bleeding and tenderness persist longer, it may be linked to gum inflammation — the dentist assesses this', 'Dan ili dva mogući su osjetljivost na hladno i blago krvarenje desni. Ako krvarenje i osjetljivost potraju duže, to može biti povezano sa upalom desni — stanje procjenjuje stomatolog', 'Дан или два могући су осјетљивост на хладно и благо крварење десни. Ако крварење и осјетљивост потрају дуже, то може бити повезано са упалом десни — стање процјењује стоматолог', 'День-два возможны чувствительность к холодному и лёгкая кровоточивость дёсен. Если кровоточивость и болезненность держатся дольше, это может быть связано с воспалением дёсен — состояние оценивает стоматолог', 'Ein bis zwei Tage können Kälteempfindlichkeit und leichtes Zahnfleischbluten auftreten. Halten Blutung und Empfindlichkeit länger an, kann das mit einer Zahnfleischentzündung zusammenhängen — die Beurteilung übernimmt der Zahnarzt', 'Bir iki gün soğuğa karşı hassasiyet ve hafif diş eti kanaması olabilir. Kanama ve hassasiyet daha uzun sürerse bu diş eti iltihabıyla ilişkili olabilir — değerlendirmeyi diş hekimi yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'filling-retention-with-metal-post'), 'Rebuilding a heavily damaged tooth with a filling held by a metal post set in the root canal', 'Nadogradnja jako oštećenog zuba plombom koju drži metalni kočić u korijenskom kanalu', 'Надоградња јако оштећеног зуба пломбом коју држи метални кочић у коријенском каналу', 'Восстановление сильно разрушенного зуба пломбой, которую удерживает металлический штифт в корневом канале', 'Aufbau eines stark zerstörten Zahns mit einer Füllung, die ein Metallstift im Wurzelkanal hält', 'Çok harap olmuş dişin, kök kanalına yerleştirilen metal post ile tutturulan dolguyla onarılması', 'The canal is reopened to the required depth, a metal post is selected and cemented, and the filling is built over it; one visit, 30-60 minutes', 'Kanal se otvori do potrebne dubine, izabere se i cementira metalni kočić, a preko njega se oblikuje plomba; jedna posjeta, 30-60 minuta', 'Канал се отвори до потребне дубине, изабере се и цементира метални кочић, а преко њега се обликује пломба; једна посјета, 30-60 минута', 'Канал распломбировывают на нужную глубину, подбирают и фиксируют металлический штифт, поверх него формируют пломбу; один визит, 30-60 минут', 'Der Kanal wird bis zur nötigen Tiefe freigelegt, ein Metallstift ausgewählt und einzementiert, darüber wird die Füllung modelliert; ein Termin, 30-60 Minuten', 'Kanal gereken derinlikte açılır, uygun metal post seçilip simante edilir ve üzerine dolgu şekillendirilir; tek seans, 30-60 dakika', 'A root-treated tooth that has lost most of its crown and offers nothing for a filling to hold on to, a build-up before a future crown', 'Zub sa liječenim kanalima koji je izgubio veći dio krune, pa plomba nema uporište, nadogradnja prije izrade krunice', 'Зуб са лијеченим каналима који је изгубио већи дио круне, па пломба нема упориште, надоградња прије израде крунице', 'Зуб с пролеченными каналами и потерей большей части коронки, когда пломбе не за что держаться, восстановление культи под будущую коронку', 'Wurzelbehandelter Zahn mit Verlust des größten Teils der Krone, wenn die Füllung keinen Halt findet, Aufbau vor einer geplanten Krone', 'Kanal tedavisi yapılmış ve kronunun büyük kısmını kaybetmiş, dolgunun tutunacağı doku kalmamış diş, kron öncesi altyapı hazırlığı', 'The root canals must be treated beforehand; no preparation on the day, bringing a previous X-ray is useful', 'Kanali moraju biti prethodno liječeni; na dan zahvata priprema nije potrebna, korisno je ponijeti raniji snimak', 'Канали морају бити претходно лијечени; на дан захвата припрема није потребна, корисно је понијети ранији снимак', 'Каналы должны быть пролечены заранее; в день процедуры подготовка не требуется, полезно взять предыдущий снимок', 'Die Wurzelkanäle müssen zuvor behandelt sein; am Behandlungstag ist keine Vorbereitung nötig, eine frühere Röntgenaufnahme ist hilfreich', 'Kanal tedavisi önceden tamamlanmış olmalıdır; işlem günü hazırlık gerekmez, önceki röntgeni getirmek yararlıdır', 'Sensitivity when biting may last a few days. If pain, a loose filling, a chip or a crack in the tooth appears, see the dentist — the build-up is checked and redone if needed', 'Nekoliko dana moguća je osjetljivost pri zagrizu. Ako se jave bol, klimanje plombe, odlom ili pukotina zuba, treba se javiti stomatologu — nadogradnja se provjerava i po potrebi ponavlja', 'Неколико дана могућа је осјетљивост при загризу. Ако се јаве бол, климање пломбе, одлом или пукотина зуба, треба се јавити стоматологу — надоградња се провјерава и по потреби понавља', 'Несколько дней возможна чувствительность при накусывании. Если появляются боль, подвижность пломбы, скол или трещина зуба, нужно показаться стоматологу — конструкцию проверяют и при необходимости переделывают', 'Einige Tage kann der Zahn beim Zubeißen empfindlich sein. Treten Schmerzen, eine lockere Füllung, ein Abplatzen oder ein Riss auf, sollte der Zahnarzt den Aufbau prüfen und bei Bedarf erneuern', 'Birkaç gün ısırırken hassasiyet olabilir. Ağrı, dolguda oynama, kırık veya dişte çatlak görülürse hekime başvurulmalı; yapı kontrol edilir ve gerekirse yenilenir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'gingivectomy'), 'Surgical trimming of excess or inflamed gum tissue with reshaping of its contour', 'Hirurško uklanjanje viška ili upaljenog tkiva desni uz oblikovanje njihove konture', 'Хируршко уклањање вишка или упаљеног ткива десни уз обликовање њихове контуре', 'Хирургическое иссечение избыточной или воспалённой ткани десны с формированием её контура', 'Chirurgisches Abtragen von überschüssigem oder entzündetem Zahnfleisch mit Formung der Kontur', 'Fazla veya iltihaplı diş eti dokusunun cerrahi olarak alınması ve konturunun şekillendirilmesi', 'Under local anesthesia the surplus gum is removed with a scalpel, laser or electrosurgery, the margin is shaped and sometimes covered with a protective dressing; 20-40 minutes per area', 'U lokalnoj anesteziji višak desni uklanja se skalpelom, laserom ili elektronožem, rub se poravna, ponekad se stavi zaštitni zavoj; 20-40 minuta po regiji', 'У локалној анестезији вишак десни уклања се скалпелом, ласером или електроножем, руб се поравна, понекад се стави заштитни завој; 20-40 минута по регији', 'Под местной анестезией лишнюю десну убирают скальпелем, лазером или электроножом, край выравнивают, иногда накладывают защитную повязку; 20-40 минут на участок', 'In Lokalanästhesie wird das überschüssige Zahnfleisch mit Skalpell, Laser oder Elektrochirurgie entfernt, der Rand geformt und manchmal mit einem Schutzverband abgedeckt; 20-40 Minuten pro Bereich', 'Lokal anestezi altında fazla diş eti bistüri, lazer veya elektrocerrahi ile alınır, kenar düzeltilir, bazen koruyucu pat uygulanır; bölge başına 20-40 dakika', 'Overgrown gums, including with certain medications or braces, gum pockets, exposing the tooth margin before a filling or crown, a very visible gum line when smiling', 'Uvećane desni, uključujući one uz pojedine lijekove ili fiksni aparatić, parodontalni džepovi, otkrivanje ruba zuba prije plombe ili krunice, previše vidljive desni pri osmijehu', 'Увећане десни, укључујући оне уз поједине лијекове или фиксни апаратић, пародонтални џепови, откривање руба зуба прије пломбе или крунице, превише видљиве десни при осмијеху', 'Разросшаяся десна, в том числе на фоне приёма некоторых лекарств или ношения брекетов, десневые карманы, открытие края зуба перед пломбой или коронкой, слишком заметная десна при улыбке', 'Wucherndes Zahnfleisch, auch unter bestimmten Medikamenten oder einer festen Spange, Zahnfleischtaschen, Freilegen des Zahnrandes vor Füllung oder Krone, beim Lächeln stark sichtbares Zahnfleisch', 'Büyümüş diş etleri, bazı ilaçlara veya ortodontik tedaviye bağlı büyümeler dahil, diş eti cepleri, dolgu ya da kron öncesi diş kenarının açığa çıkarılması, gülerken diş etinin fazla görünmesi', 'Professional cleaning is usually done beforehand; report blood thinners and chronic conditions', 'Prije zahvata se obično uradi profesionalno čišćenje; prijaviti lijekove za razrjeđivanje krvi i hronične bolesti', 'Прије захвата се обично уради професионално чишћење; пријавити лијекове за разрјеђивање крви и хроничне болести', 'Перед вмешательством обычно проводят профессиональную чистку; сообщить о препаратах, разжижающих кровь, и хронических болезнях', 'Vorher wird meist eine professionelle Zahnreinigung durchgeführt; Blutverdünner und chronische Erkrankungen mitteilen', 'İşlemden önce genellikle profesyonel temizlik yapılır; kan sulandırıcı ilaçlar ve kronik hastalıklar bildirilmelidir', 'The gum is tender for the first days and may bleed slightly; the final contour settles over several weeks. Increasing pain, swelling or continuing bleeding is a reason to contact the dentist', 'Prvih dana desni su osjetljive i mogu blago krvariti, konačna kontura se formira kroz nekoliko sedmica. Jači bol, otok ili krvarenje koje ne prestaje razlog su za javljanje stomatologu', 'Првих дана десни су осјетљиве и могу благо крварити, коначна контура се формира кроз неколико седмица. Јачи бол, оток или крварење које не престаје разлог су за јављање стоматологу', 'Первые дни десна чувствительна и может немного кровить, окончательный контур формируется за несколько недель. Усиление боли, отёк или продолжающееся кровотечение — повод обратиться к стоматологу', 'In den ersten Tagen ist das Zahnfleisch empfindlich und kann leicht bluten, die endgültige Kontur bildet sich über einige Wochen. Zunehmende Schmerzen, Schwellung oder anhaltende Blutung sind ein Grund, den Zahnarzt aufzusuchen', 'İlk günlerde diş eti hassastır ve hafif kanayabilir, nihai kontur birkaç haftada oturur. Ağrının artması, şişlik veya durmayan kanama hekime başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'impacted-tooth-extraction'), 'Removal of a tooth that has not erupted and remains fully or partly in the bone or under the gum', 'Vađenje zuba koji nije nikao i ostaje potpuno ili djelimično u kosti ili ispod desni', 'Вађење зуба који није никао и остаје потпуно или дјелимично у кости или испод десни', 'Удаление зуба, который не прорезался и полностью или частично остаётся в кости либо под десной', 'Entfernung eines Zahns, der nicht durchgebrochen ist und ganz oder teilweise im Knochen oder unter dem Zahnfleisch liegt', 'Sürmemiş, tamamen veya kısmen kemik içinde ya da diş eti altında kalmış dişin çıkarılması', 'Under local anesthesia a gum flap is raised, bone over the tooth is removed, the tooth is sectioned if needed and the wound is sutured; 40-90 minutes, sutures out after 7-10 days', 'U lokalnoj anesteziji podiže se režanj desni, uklanja se dio kosti iznad zuba, zub se po potrebi razdvoji na dijelove, a rana zašije; 40-90 minuta, konci se skidaju nakon 7-10 dana', 'У локалној анестезији подиже се режањ десни, уклања се дио кости изнад зуба, зуб се по потреби раздвоји на дијелове, а рана зашије; 40-90 минута, конци се скидају након 7-10 дана', 'Под местной анестезией отслаивают лоскут десны, снимают часть кости над зубом, при необходимости делят зуб на фрагменты, рану ушивают; 40-90 минут, швы снимают через 7-10 дней', 'In Lokalanästhesie wird ein Zahnfleischlappen gebildet, Knochen über dem Zahn abgetragen, der Zahn bei Bedarf zerteilt und die Wunde genäht; 40-90 Minuten, Fadenentfernung nach 7-10 Tagen', 'Lokal anestezi altında diş eti flebi kaldırılır, dişin üzerindeki kemik alınır, gerekirse diş parçalara ayrılır ve yara dikilir; 40-90 dakika, dikişler 7-10 gün sonra alınır', 'Impacted wisdom teeth with inflammation or pressure on the neighbouring tooth, impacted canines before orthodontic treatment, a cyst around an unerupted tooth', 'Impaktirani umnjaci sa upalom ili pritiskom na susjedni zub, impaktirani očnjaci prije ortodontske terapije, cista oko neizniklog zuba', 'Импактирани умњаци са упалом или притиском на сусједни зуб, импактирани очњаци прије ортодонтске терапије, циста око неизниклог зуба', 'Ретинированные зубы мудрости с воспалением или давлением на соседний зуб, ретинированные клыки перед ортодонтическим лечением, киста вокруг непрорезавшегося зуба', 'Verlagerte Weisheitszähne mit Entzündung oder Druck auf den Nachbarzahn, verlagerte Eckzähne vor kieferorthopädischer Behandlung, Zyste um einen nicht durchgebrochenen Zahn', 'İltihaplanan veya komşu dişe baskı yapan gömülü yirmi yaş dişleri, ortodontik tedavi öncesi gömülü kanin dişler, sürmemiş diş çevresindeki kist', 'A panoramic X-ray or CT scan is needed, eat before the visit, report medications and chronic conditions, and keep the day of surgery free of exertion and travel', 'Potreban je panoramski snimak ili skener, jesti prije dolaska, prijaviti lijekove i hronične bolesti, na dan operacije ne planirati napore i putovanja', 'Потребан је панорамски снимак или скенер, јести прије доласка, пријавити лијекове и хроничне болести, на дан операције не планирати напоре и путовања', 'Нужен панорамный снимок или КТ, поесть перед визитом, сообщить о препаратах и хронических болезнях, на день операции не планировать нагрузок и поездок', 'Panoramaaufnahme oder DVT erforderlich, vor dem Termin essen, Medikamente und chronische Erkrankungen mitteilen, am Operationstag Anstrengung und Reisen vermeiden', 'Panoramik röntgen veya tomografi gerekir, randevudan önce yemek yenmeli, ilaçlar ve kronik hastalıklar bildirilmeli, ameliyat günü efor ve seyahat planlanmamalıdır', 'Cheek swelling, limited mouth opening and soreness in the first 3-5 days are expected. Numbness of the lip or tongue, increasing pain, fever or a foul smell from the wound is a reason to see the dentist', 'Otok obraza, otežano otvaranje usta i bolna osjetljivost prvih 3-5 dana su očekivani. Utrnulost usne ili jezika, bol koji jača, temperatura ili neprijatan miris iz rane razlog su za javljanje stomatologu', 'Оток образа, отежано отварање уста и болна осјетљивост првих 3-5 дана су очекивани. Утрнулост усне или језика, бол који јача, температура или непријатан мирис из ране разлог су за јављање стоматологу', 'Отёк щеки, ограниченное открывание рта и болезненность первые 3-5 дней ожидаемы. Онемение губы или языка, нарастающая боль, температура или неприятный запах из раны — повод обратиться к врачу', 'Wangenschwellung, eingeschränkte Mundöffnung und Druckschmerz in den ersten 3-5 Tagen sind zu erwarten. Taubheitsgefühl an Lippe oder Zunge, zunehmende Schmerzen, Fieber oder übler Geruch aus der Wunde sind ein Grund, den Zahnarzt aufzusuchen', 'İlk 3-5 gün yanakta şişlik, ağzı açmada kısıtlılık ve hassasiyet beklenir. Dudak veya dilde uyuşma, artan ağrı, ateş ya da yarada kötü koku hekime başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'specialist-dental-examination'), 'An appointment with a dentist of a narrow specialty — surgeon, periodontist, orthodontist or prosthodontist — for a specific question', 'Pregled kod stomatologa uže specijalnosti — hirurga, parodontologa, ortodonta ili protetičara — zbog konkretnog pitanja', 'Преглед код стоматолога уже специјалности — хирурга, пародонтолога, ортодонта или протетичара — због конкретног питања', 'Приём у стоматолога узкой специализации — хирурга, пародонтолога, ортодонта или протезиста — по конкретному вопросу', 'Untersuchung bei einem Zahnarzt mit Spezialisierung — Chirurg, Parodontologe, Kieferorthopäde oder Prothetiker — zu einer konkreten Fragestellung', 'Belirli bir sorun için cerrah, periodontolog, ortodontist veya protez uzmanı gibi dal uzmanı bir diş hekimine muayene', 'Review of complaints and existing images, examination of the mouth and bite, additional diagnostics if needed, ending with a report and a proposed plan; 20-40 minutes', 'Razgovor o tegobama i uvid u postojeće snimke, pregled usne duplje i zagrižaja, po potrebi dodatna dijagnostika, na kraju nalaz i predloženi plan; 20-40 minuta', 'Разговор о тегобама и увид у постојеће снимке, преглед усне дупље и загрижаја, по потреби додатна дијагностика, на крају налаз и предложени план; 20-40 минута', 'Разбор жалоб и имеющихся снимков, осмотр полости рта и прикуса, при необходимости дополнительная диагностика, в конце заключение и предложенный план; 20-40 минут', 'Besprechung der Beschwerden und vorhandener Aufnahmen, Untersuchung von Mundhöhle und Biss, bei Bedarf weitere Diagnostik, abschließend Befund und vorgeschlagener Plan; 20-40 Minuten', 'Şikâyetlerin ve mevcut görüntülerin değerlendirilmesi, ağız ve kapanış muayenesi, gerekirse ek tetkik, sonunda rapor ve önerilen tedavi planı; 20-40 dakika', 'Referral from a general dentist, planning implants, prosthetics or orthodontics, gum disease, a second opinion on a proposed treatment plan', 'Uput od stomatologa opšte prakse, planiranje implantacije, protetike ili ortodoncije, bolesti desni, drugo mišljenje o predloženom planu liječenja', 'Упут од стоматолога опште праксе, планирање имплантације, протетике или ортодонције, болести десни, друго мишљење о предложеном плану лијечења', 'Направление от стоматолога общей практики, планирование имплантации, протезирования или ортодонтии, заболевания дёсен, второе мнение по предложенному плану лечения', 'Überweisung vom Hauszahnarzt, Planung von Implantaten, Zahnersatz oder Kieferorthopädie, Zahnfleischerkrankungen, Zweitmeinung zu einem vorgeschlagenen Behandlungsplan', 'Genel diş hekiminden sevk, implant, protez veya ortodonti planlaması, diş eti hastalıkları, önerilen tedavi planı için ikinci görüş', 'No preparation needed; bring previous X-rays, reports and a list of medications taken', 'Priprema nije potrebna; ponijeti ranije snimke, nalaze i spisak lijekova koje uzimate', 'Припрема није потребна; понијети раније снимке, налазе и списак лијекова које узимате', 'Подготовка не требуется; взять предыдущие снимки, заключения и список принимаемых лекарств', 'Keine Vorbereitung nötig; frühere Aufnahmen, Befunde und eine Liste der eingenommenen Medikamente mitbringen', 'Hazırlık gerekmez; önceki röntgenler, raporlar ve kullanılan ilaçların listesi getirilmelidir', 'Not applicable — this is a diagnostic appointment. Based on it the specialist proposes further tests, treatment or monitoring and sets the timing of the follow-up visit', 'Nije primjenjivo — riječ je o dijagnostičkom pregledu. Na osnovu njega specijalista predlaže dalju dijagnostiku, liječenje ili praćenje i određuje rok kontrole', 'Није примјењиво — ријеч је о дијагностичком прегледу. На основу њега специјалиста предлаже даљу дијагностику, лијечење или праћење и одређује рок контроле', 'Не применимо — это диагностический приём. По его итогам врач предлагает дальнейшее обследование, лечение или наблюдение и сам определяет срок контрольного визита', 'Nicht zutreffend — es handelt sich um eine diagnostische Untersuchung. Auf ihrer Grundlage schlägt der Spezialist weitere Diagnostik, Behandlung oder Kontrolle vor und legt den Termin der Nachkontrolle fest', 'Uygulanmaz — bu bir teşhis muayenesidir. Sonucuna göre uzman ileri tetkik, tedavi veya izlem önerir ve kontrol zamanını belirler')
