INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'ceramic-veneer'), 'A thin ceramic shell bonded to the front surface of a tooth to change its shape or color', 'Tanka keramička ljuska koja se lijepi na prednju površinu zuba radi promjene oblika ili boje', 'Танка керамичка љуска која се лијепи на предњу површину зуба ради промјене облика или боје', 'Тонкая керамическая накладка на переднюю поверхность зуба для изменения его формы или цвета', 'Eine dünne Keramikschale, die auf die Vorderseite eines Zahns geklebt wird, um Form oder Farbe zu verändern', 'Şeklini veya rengini değiştirmek için dişin ön yüzeyine yapıştırılan ince seramik kaplama', 'Minimal removal of enamel, taking an impression or digital scan, laboratory fabrication, and bonding with composite cement; usually 2 visits', 'Minimalno brušenje cakline, uzimanje otiska ili skeniranje, izrada u laboratoriji i fiksiranje kompozitnim cementom; obično 2 posjete', 'Минимално брушење цаклине, узимање отиска или скенирање, израда у лабораторији и фиксирање композитним цементом; обично 2 посјете', 'Минимальное сошлифовывание эмали, снятие слепка или сканирование, изготовление в лаборатории и фиксация на композитный цемент; обычно 2 визита', 'Minimales Abschleifen des Zahnschmelzes, Abdrucknahme oder digitaler Scan, Anfertigung im Labor und Befestigung mit Kompositzement; in der Regel 2 Termine', 'Minimum düzeyde mine aşındırma, ölçü alma veya dijital tarama, laboratuvarda üretim ve kompozit çimento ile yapıştırma; genellikle 2 seans', 'Correcting the shape, color, chips, or gaps of front teeth for aesthetic reasons', 'Korekcija oblika, boje, okrnjenih ivica ili razmaka između prednjih zuba iz estetskih razloga', 'Корекција облика, боје, окрњених ивица или размака између предњих зуба из естетских разлога', 'Коррекция формы, цвета, сколов или щелей между передними зубами по эстетическим показаниям', 'Korrektur von Form, Farbe, Absplitterungen oder Lücken der Frontzähne aus ästhetischen Gründen', 'Estetik nedenlerle ön dişlerin şeklinin, renginin, kırıklarının veya aralarındaki boşlukların düzeltilmesi', 'No special preparation is required; an additional consultation to assess the bite is sometimes needed', 'Posebna priprema nije potrebna; ponekad je potrebna dodatna konsultacija radi procjene zagriza', 'Посебна припрема није потребна; понекад је потребна додатна консултација ради процјене загриза', 'Специальной подготовки не требуется; иногда нужна дополнительная консультация для оценки прикуса', 'Keine besondere Vorbereitung erforderlich; manchmal ist eine zusätzliche Beratung zur Beurteilung des Bisses nötig', 'Özel bir hazırlık gerekmez; bazen kapanışı değerlendirmek için ek konsültasyon gerekebilir', 'Mild tooth sensitivity in the first few days is a normal reaction; if the veneer shifts, chips, or biting becomes uncomfortable, see a dentist', 'Blaga osjetljivost zuba prvih dana je uobičajena reakcija; ako se vinir pomjeri, okrnji ili se javi nelagodnost pri zagrizanju, treba se obratiti stomatologu', 'Блага осјетљивост зуба првих дана је уобичајена реакција; ако се винир помјери, окрњи или се јави нелагодност при загризању, треба се обратити стоматологу', 'Небольшая чувствительность зубов в первые дни — обычная реакция; если винир сместился, откололся или появился дискомфорт при накусывании, следует обратиться к стоматологу', 'Leichte Zahnempfindlichkeit in den ersten Tagen ist eine normale Reaktion; wenn sich das Veneer löst, absplittert oder das Zubeißen unangenehm wird, sollte ein Zahnarzt aufgesucht werden', 'İlk günlerde hafif diş hassasiyeti normal bir tepkidir; laminate yerinden oynarsa, kırılırsa veya ısırırken rahatsızlık hissedilirse diş hekimine başvurulmalıdır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'metal-ceramic-crown'), 'A crown with a metal framework veneered with ceramic', 'Kruna sa metalnim okvirom obloženim keramikom', 'Круна са металним оквиром обложеним керамиком', 'Коронка с металлическим каркасом, облицованным керамикой', 'Eine Krone mit Metallgerüst, das mit Keramik verblendet ist', 'Seramikle kaplanmış metal alt yapıya sahip kron', 'Tooth preparation, taking an impression or digital scan, laboratory fabrication with a temporary crown worn in the meantime; usually 2 visits', 'Brušenje zuba, uzimanje otiska ili skeniranje, izrada u laboratoriji uz privremenu krunu za period čekanja; obično 2 posjete', 'Брушење зуба, узимање отиска или скенирање, израда у лабораторији уз привремену круну за период чекања; обично 2 посјете', 'Обтачивание зуба, снятие слепка или сканирование, изготовление в лаборатории с временной коронкой на период ожидания; обычно 2 визита', 'Beschleifen des Zahns, Abdrucknahme oder digitaler Scan, Anfertigung im Labor mit einer provisorischen Krone für die Wartezeit; in der Regel 2 Termine', 'Dişin aşındırılması, ölçü alınması veya dijital tarama, bekleme süresi için geçici kronla birlikte laboratuvarda üretim; genellikle 2 seans', 'Restoration of a badly damaged or root-canal-treated tooth, including molars where the strength of the construction matters', 'Obnova oštećenog ili depulpiranog zuba, uključujući bočne zube kod kojih je važna čvrstoća konstrukcije', 'Обнова оштећеног или депулпираног зуба, укључујући бочне зубе код којих је важна чврстоћа конструкције', 'Восстановление разрушенного или депульпированного зуба, в том числе жевательных, где важна прочность конструкции', 'Wiederherstellung eines stark geschädigten oder wurzelbehandelten Zahns, auch im Seitenzahnbereich, wo die Stabilität der Konstruktion wichtig ist', 'Özellikle yapının dayanıklılığının önemli olduğu azı dişleri dahil, çürük veya kanal tedavisi görmüş dişin restorasyonu', 'No special preparation is required; if needed, the tooth is treated with a root canal beforehand', 'Posebna priprema nije potrebna; po potrebi se zub prethodno liječi kanalno', 'Посебна припрема није потребна; по потреби се зуб претходно лијечи канално', 'Специальной подготовки не требуется; при необходимости зуб предварительно лечат по каналу', 'Keine besondere Vorbereitung erforderlich; bei Bedarf wird der Zahn vorab wurzelbehandelt', 'Özel bir hazırlık gerekmez; gerekirse diş önceden kanal tedavisinden geçirilir', 'Mild sensitivity after cementation is normal; if there is pain, the crown becomes loose, or the gum around its edge becomes inflamed, see a dentist', 'Blaga osjetljivost nakon fiksiranja je normalna; u slučaju bola, klimanja krune ili upale desni uz njenu ivicu treba se javiti stomatologu', 'Блага осјетљивост након фиксирања је нормална; у случају бола, климања круне или упале десни уз њену ивицу треба се јавити стоматологу', 'Небольшая чувствительность после фиксации — норма; при боли, расшатывании коронки или воспалении десны у её края нужно показаться стоматологу', 'Leichte Empfindlichkeit nach dem Einsetzen ist normal; bei Schmerzen, einer lockeren Krone oder einer Entzündung des Zahnfleischs am Kronenrand sollte ein Zahnarzt aufgesucht werden', 'Yapıştırma sonrası hafif hassasiyet normaldir; ağrı, kronun gevşemesi veya kron kenarındaki diş etinde iltihaplanma durumunda diş hekimine görünülmelidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'surgical-tooth-extraction'), 'Tooth removal involving an incision in the gum and/or sectioning the tooth into fragments — used in complex cases', 'Vađenje zuba uz rez desni i/ili rasijecanje zuba na dijelove — primjenjuje se u složenim slučajevima', 'Вађење зуба уз рез десни и/или расијецање зуба на дијелове — примјењује се у сложеним случајевима', 'Удаление зуба с разрезом десны и/или распилом зуба на фрагменты — применяется в сложных случаях', 'Zahnentfernung mit Schnitt im Zahnfleisch und/oder Zerteilen des Zahns in mehrere Teile — wird in komplexen Fällen angewendet', 'Diş etinde kesi yapılarak ve/veya diş parçalara ayrılarak yapılan diş çekimi — karmaşık vakalarda uygulanır', 'Local anesthesia, incision of soft tissue and, if needed, sectioning the tooth, followed by suturing; 30-60 minutes, one visit plus suture removal after 7-10 days', 'Lokalna anestezija, rez mekog tkiva i po potrebi rasijecanje zuba, postavljanje šavova; 30-60 minuta, jedna posjeta plus skidanje šavova poslije 7-10 dana', 'Локална анестезија, рез меког ткива и по потреби расијецање зуба, постављање шавова; 30-60 минута, једна посјета плус скидање шавова послије 7-10 дана', 'Местная анестезия, разрез мягких тканей и при необходимости фрагментация зуба, наложение швов; 30-60 минут, один визит плюс снятие швов через 7-10 дней', 'Lokalanästhesie, Einschnitt des Weichgewebes und bei Bedarf Zerteilen des Zahns, anschließendes Nähen; 30-60 Minuten, ein Termin plus Fadenentfernung nach 7-10 Tagen', 'Lokal anestezi, yumuşak dokuda kesi ve gerekirse dişin parçalara ayrılması, ardından dikiş atılması; 30-60 dakika, bir seans artı 7-10 gün sonra dikiş alınması', 'Impacted or partially impacted wisdom teeth, broken roots, teeth with curved or fused roots', 'Impaktirani ili djelimično impaktirani umnjaci, slomljeni korijeni, zubi sa savijenim ili sraslim korijenima', 'Импактирани или дјелимично импактирани умњаци, сломљени коријени, зуби са савијеним или сраслим коријенима', 'Ретинированные или полуретинированные зубы мудрости, сломанные корни, зубы с изогнутыми или сросшимися корнями', 'Retinierte oder teilretinierte Weisheitszähne, gebrochene Wurzeln, Zähne mit gekrümmten oder verwachsenen Wurzeln', 'Gömülü veya yarı gömülü yirmi yaş dişleri, kırık kökler, eğri veya kaynaşmış köklü dişler', 'Eat a full meal before the procedure, inform the dentist about any medications being taken (especially blood thinners), avoid physical exertion on the day of surgery', 'Dobro se najesti prije zahvata, obavijestiti stomatologa o lijekovima koje uzimate (naročito onim za razrjeđivanje krvi), ne planirati fizičke napore na dan operacije', 'Добро се најести прије захвата, обавијестити стоматолога о лијековима које узимате (нарочито оним за разрјеђивање крви), не планирати физичке напоре на дан операције', 'Плотно поесть перед процедурой, сообщить о принимаемых препаратах (особенно разжижающих кровь), не планировать физические нагрузки в день операции', 'Vor dem Eingriff eine vollständige Mahlzeit einnehmen, den Zahnarzt über eingenommene Medikamente informieren (insbesondere Blutverdünner), am Operationstag keine körperliche Anstrengung planen', 'İşlemden önce doyurucu bir öğün yemek, kullanılan ilaçları (özellikle kan sulandırıcıları) bildirmek, ameliyat günü fiziksel efor planlamamak', 'Swelling, mild pain, and bruising on the cheek in the first 2-3 days are a normal reaction; heavy bleeding, fever, or pain that worsens after the third day is a reason to contact a dentist urgently', 'Oticanje, blaga bol i modrica na obrazu prvih 2-3 dana su uobičajena reakcija; jako krvarenje, povišena temperatura ili bol koja se pojačava poslije trećeg dana razlog su za hitno obraćanje stomatologu', 'Отицање, блага бол и модрица на образу првих 2-3 дана су уобичајена реакција; јако крварење, повишена температура или бол која се појачава послије трећег дана разлог су за хитно обраћање стоматологу', 'Отёк, лёгкая боль и синяк на щеке в первые 2-3 дня — обычная реакция; сильное кровотечение, температура или боль, нарастающая после третьего дня, — повод срочно обратиться к стоматологу', 'Schwellung, leichte Schmerzen und ein Bluterguss an der Wange in den ersten 2-3 Tagen sind eine normale Reaktion; starke Blutung, Fieber oder Schmerzen, die sich nach dem dritten Tag verstärken, sind ein Grund, umgehend einen Zahnarzt aufzusuchen', 'İlk 2-3 gün şişlik, hafif ağrı ve yanakta morluk normal bir tepkidir; şiddetli kanama, ateş veya üçüncü günden sonra artan ağrı acilen diş hekimine başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'tooth-extraction'), 'Removal of a whole tooth through its socket, without incisions', 'Vađenje cijelog zuba kroz alveolu, bez rezova', 'Вађење цијелог зуба кроз алвеолу, без резова', 'Удаление зуба целиком через лунку, без разрезов', 'Entfernung eines ganzen Zahns aus dem Zahnfach, ohne Einschnitte', 'Kesi yapılmadan dişin soketinden bütün olarak çıkarılması', 'Local anesthesia, loosening and extracting the tooth with forceps; usually 10-20 minutes, one visit', 'Lokalna anestezija, klimanje i izvlačenje zuba kliještima; obično 10-20 minuta, jedna posjeta', 'Локална анестезија, климање и извлачење зуба клијештима; обично 10-20 минута, једна посјета', 'Местная анестезия, расшатывание и извлечение зуба щипцами; обычно 10-20 минут, один визит', 'Lokalanästhesie, Lockern und Herausziehen des Zahns mit einer Zange; in der Regel 10-20 Minuten, ein Termin', 'Lokal anestezi, dişin gevşetilip pensle çekilmesi; genellikle 10-20 dakika, bir seans', 'A tooth beyond repair due to decay or mobility, indications for orthodontic treatment, a chronic source of infection', 'Zub se ne može liječiti zbog oštećenja ili pokretljivosti, indikacije za ortodontsku terapiju, hronično žarište infekcije', 'Зуб се не може лијечити због оштећења или покретљивости, индикације за ортодонтску терапију, хронично жариште инфекције', 'Зуб не подлежит лечению из-за разрушения или подвижности, показания к ортодонтическому лечению, хронический очаг инфекции', 'Ein durch Zerstörung oder Lockerung nicht mehr erhaltungswürdiger Zahn, Indikationen für eine kieferorthopädische Behandlung, ein chronischer Infektionsherd', 'Çürük veya hareketlilik nedeniyle tedavi edilemeyen diş, ortodontik tedavi endikasyonu, kronik enfeksiyon odağı', 'Eat a full meal before the procedure, inform the dentist about chronic conditions and medications being taken', 'Dobro se najesti prije zahvata, obavijestiti o hroničnim bolestima i lijekovima koje uzimate', 'Добро се најести прије захвата, обавијестити о хроничним болестима и лијековима које узимате', 'Плотно поесть перед процедурой, сообщить о хронических заболеваниях и принимаемых лекарствах', 'Vor dem Eingriff eine vollständige Mahlzeit einnehmen, über chronische Erkrankungen und eingenommene Medikamente informieren', 'İşlemden önce doyurucu bir öğün yemek, kronik hastalıkları ve kullanılan ilaçları bildirmek', 'Slight bleeding and swelling in the first 24 hours are normal; if bleeding does not stop, severe pain develops, or there is an unpleasant smell from the socket, see a dentist', 'Blago krvarenje i oticanje prvog dana su uobičajeni; ako se krvarenje ne zaustavlja, javi se jaka bol ili neprijatan miris iz alveole, treba se obratiti stomatologu', 'Благо крварење и отицање првог дана су уобичајени; ако се крварење не зауставља, јави се јака бол или непријатан мирис из алвеоле, треба се обратити стоматологу', 'Небольшая кровоточивость и отёк в первые сутки — норма; если кровотечение не останавливается, появляется сильная боль или неприятный запах из лунки, нужно обратиться к стоматологу', 'Leichte Blutung und Schwellung im ersten Tag sind normal; wenn die Blutung nicht aufhört, starke Schmerzen auftreten oder ein unangenehmer Geruch aus dem Zahnfach entsteht, sollte ein Zahnarzt aufgesucht werden', 'İlk 24 saatte hafif kanama ve şişlik normaldir; kanama durmazsa, şiddetli ağrı gelişirse veya soketten kötü koku gelirse diş hekimine başvurulmalıdır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'root-canal-retreatment'), 'Repeated root canal treatment when inflammation persists or returns after the initial treatment', 'Ponovljeno liječenje korijenskog kanala kada se upala održava ili se ponovo javi nakon prvobitnog liječenja', 'Поновљено лијечење коријенског канала када се упала одржава или се поново јави након првобитног лијечења', 'Повторное лечение корневого канала при сохранении или возобновлении воспаления после первичного лечения', 'Erneute Wurzelkanalbehandlung, wenn eine Entzündung nach der ersten Behandlung fortbesteht oder wiederkehrt', 'İlk tedaviden sonra iltihabın devam etmesi veya tekrarlaması durumunda kök kanalının yeniden tedavi edilmesi', 'Removing the old filling material from the canal, re-cleaning and disinfecting, and refilling the canal; usually 1-2 visits', 'Uklanjanje starog materijala za punjenje iz kanala, ponovno čišćenje i dezinfekcija, novo punjenje kanala; obično 1-2 posjete', 'Уклањање старог материјала за пуњење из канала, поновно чишћење и дезинфекција, ново пуњење канала; обично 1-2 посјете', 'Удаление старого пломбировочного материала из канала, повторная очистка и дезинфекция, новое пломбирование; обычно 1-2 визита', 'Entfernen des alten Füllmaterials aus dem Kanal, erneute Reinigung und Desinfektion, neue Füllung des Kanals; in der Regel 1-2 Termine', 'Kanaldan eski dolgu maddesinin çıkarılması, yeniden temizlik ve dezenfeksiyon, kanalın yeniden doldurulması; genellikle 1-2 seans', 'Pain or inflammation in a previously treated tooth, a cyst or granuloma visible on an X-ray, a poorly sealed old root canal filling', 'Bol ili upala u ranije liječenom zubu, cista ili granulom vidljivi na snimku, nedovoljno zaptiveno staro punjenje kanala', 'Бол или упала у раније лијеченом зубу, циста или гранулом видљиви на снимку, недовољно заптивено старо пуњење канала', 'Боль или воспаление в ранее леченном зубе, киста или гранулема на снимке, негерметичная старая пломбировка канала', 'Schmerzen oder Entzündung in einem zuvor behandelten Zahn, eine auf Röntgenbildern sichtbare Zyste oder ein Granulom, eine undichte alte Wurzelkanalfüllung', 'Daha önce tedavi edilmiş dişte ağrı veya iltihap, röntgende görülen kist veya granülom, sızdıran eski kanal dolgusu', 'No special preparation is required; it is helpful to provide the dentist with X-rays from the previous treatment', 'Posebna priprema nije potrebna; poželjno je stomatologu donijeti snimke prethodnog liječenja', 'Посебна припрема није потребна; пожељно је стоматологу донијети снимке претходног лијечења', 'Специальной подготовки не требуется; желательно предоставить стоматологу снимки предыдущего лечения', 'Keine besondere Vorbereitung erforderlich; es ist hilfreich, dem Zahnarzt Röntgenbilder der vorherigen Behandlung mitzubringen', 'Özel bir hazırlık gerekmez; önceki tedaviye ait röntgenlerin diş hekimine getirilmesi faydalıdır', 'A dull sensitivity when biting in the first few days is a normal occurrence; worsening pain, swelling, or fever is a reason for an unscheduled visit', 'Tupa osjetljivost pri zagrizanju prvih dana je uobičajena pojava; pojačana bol, oticanje ili povišena temperatura razlog su za vanredni pregled', 'Тупа осјетљивост при загризању првих дана је уобичајена појава; појачана бол, отицање или повишена температура разлог су за ванредни преглед', 'Ноющая чувствительность при накусывании в первые дни — обычное явление; усиливающаяся боль, отёк или температура — повод для внепланового визита', 'Ein dumpfes Gefühl beim Zubeißen in den ersten Tagen ist normal; zunehmende Schmerzen, Schwellung oder Fieber sind ein Grund für einen außerplanmäßigen Termin', 'İlk günlerde ısırırken hissedilen künt hassasiyet normal bir durumdur; artan ağrı, şişlik veya ateş plansız bir ziyareti gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'teeth-whitening'), 'Lightening the color of tooth enamel using a peroxide-based whitening gel', 'Posvjetljivanje boje cakline pomoću gela za izbjeljivanje na bazi peroksida', 'Посвјетљивање боје цаклине помоћу гела за избјељивање на бази пероксида', 'Осветление цвета эмали с помощью отбеливающего геля на основе пероксида', 'Aufhellung der Zahnschmelzfarbe mit einem peroxidhaltigen Bleichgel', 'Peroksit bazlı beyazlatma jeli kullanılarak diş minesinin renginin açılması', 'Applying the gel to the teeth in-office under a lamp or activator light, or wearing custom trays with gel at home; the in-office procedure takes 45-60 minutes per visit, the at-home method takes several days to weeks', 'Nanošenje gela na zube u ordinaciji uz lampu ili aktivator, ili nošenje individualnih kapa sa gelom kod kuće; ordinacijska procedura traje 45-60 minuta po posjeti, kućna nekoliko dana do nekoliko sedmica', 'Наношење гела на зубе у ординацији уз лампу или активатор, или ношење индивидуалних капа са гелом код куће; ординацијска процедура траје 45-60 минута по посјети, кућна неколико дана до неколико седмица', 'Нанесение геля на зубы в кабинете под лампой или активатором, либо ношение индивидуальных кап с гелем дома; кабинетная процедура — 45-60 минут за визит, домашняя — несколько дней-недель', 'Auftragen des Gels auf die Zähne in der Praxis unter einer Lampe oder einem Aktivator, oder Tragen individueller Schienen mit Gel zu Hause; die Behandlung in der Praxis dauert 45-60 Minuten pro Termin, die Anwendung zu Hause mehrere Tage bis Wochen', 'Jelin klinikte bir lamba veya aktivatör altında dişlere uygulanması ya da evde jelli özel plaklar takılması; klinik uygulaması seans başına 45-60 dakika, evde uygulama birkaç gün ile birkaç hafta sürer', 'Wanting to lighten the natural tooth color or remove staining caused by age, coffee, tea, or smoking', 'Želja za posvjetljivanjem prirodne boje zuba ili uklanjanjem potamnjenja usljed starosti, kafe, čaja ili pušenja', 'Жеља за посвјетљивањем природне боје зуба или уклањањем потамњења усљед старости, кафе, чаја или пушења', 'Желание осветлить естественный цвет зубов или устранить потемнение от возраста, кофе, чая, курения', 'Wunsch, die natürliche Zahnfarbe aufzuhellen oder Verfärbungen durch Alter, Kaffee, Tee oder Rauchen zu entfernen', 'Doğal diş renginin açılması veya yaş, kahve, çay ya da sigaraya bağlı renk koyulaşmasının giderilmesi isteği', 'A professional teeth cleaning before whitening is recommended; treatment of cavities and cracks should be completed beforehand', 'Poželjno je uraditi profesionalno čišćenje zuba prije izbjeljivanja; liječenje karijesa i pukotina treba biti završeno unaprijed', 'Пожељно је урадити професионално чишћење зуба прије избјељивања; лијечење каријеса и пукотина треба бити завршено унапријед', 'Желательна профессиональная чистка зубов до отбеливания; лечение кариеса и трещин должно быть завершено заранее', 'Eine professionelle Zahnreinigung vor dem Bleaching wird empfohlen; die Behandlung von Karies und Rissen sollte vorher abgeschlossen sein', 'Beyazlatmadan önce profesyonel diş temizliği yapılması önerilir; çürük ve çatlak tedavilerinin önceden tamamlanmış olması gerekir', 'Increased tooth sensitivity and mild gum irritation in the first few days are a common and usually temporary reaction; if sensitivity is severe or persists for a long time, it is worth seeing a dentist', 'Pojačana osjetljivost zuba i blaga iritacija desni prvih dana su česta i obično prolazna reakcija; ako je osjetljivost jaka ili se dugo ne povlači, treba se obratiti stomatologu', 'Појачана осјетљивост зуба и блага иритација десни првих дана су честа и обично пролазна реакција; ако је осјетљивост јака или се дуго не повлачи, треба се обратити стоматологу', 'Повышенная чувствительность зубов и лёгкое раздражение дёсен в первые дни — частая и обычно временная реакция; если чувствительность сильная или долго не проходит, стоит обратиться к стоматологу', 'Erhöhte Zahnempfindlichkeit und leichte Zahnfleischreizung in den ersten Tagen sind eine häufige und meist vorübergehende Reaktion; ist die Empfindlichkeit stark oder hält sie lange an, sollte ein Zahnarzt aufgesucht werden', 'İlk günlerde artan diş hassasiyeti ve hafif diş eti tahrişi yaygın ve genellikle geçici bir tepkidir; hassasiyet şiddetliyse veya uzun süre geçmiyorsa diş hekimine başvurmakta fayda vardır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'dental-consultation'), 'An initial examination by a dentist to assess the condition of the teeth and draw up a treatment plan', 'Prvi pregled kod stomatologa sa procjenom stanja zuba i izradom plana liječenja', 'Први преглед код стоматолога са процјеном стања зуба и израдом плана лијечења', 'Первичный осмотр стоматологом с оценкой состояния зубов и составлением плана лечения', 'Eine erste Untersuchung durch den Zahnarzt zur Beurteilung des Zahnzustands und Erstellung eines Behandlungsplans', 'Diş hekimi tarafından dişlerin durumunun değerlendirildiği ve tedavi planının oluşturulduğu ilk muayene', 'A discussion of symptoms, visual examination of the mouth, X-rays if needed; usually 20-30 minutes, one visit', 'Razgovor o tegobama, vizuelni pregled usne duplje, po potrebi snimci; obično 20-30 minuta, jedna posjeta', 'Разговор о тегобама, визуелни преглед усне дупље, по потреби снимци; обично 20-30 минута, једна посјета', 'Опрос, визуальный осмотр полости рта, при необходимости — снимки; обычно 20-30 минут, один визит', 'Anamnesegespräch, visuelle Untersuchung der Mundhöhle, bei Bedarf Röntgenaufnahmen; in der Regel 20-30 Minuten, ein Termin', 'Şikayetlerin sorulması, ağız içinin görsel muayenesi, gerekirse röntgen; genellikle 20-30 dakika, bir seans', 'A routine check-up, pain or discomfort, planning prosthetic or orthodontic treatment, a first visit to a new dentist', 'Redovni pregled, bol ili nelagodnost, planiranje protetike ili ortodontske terapije, prvi odlazak kod novog stomatologa', 'Редовни преглед, бол или нелагодност, планирање протетике или ортодонтске терапије, први одлазак код новог стоматолога', 'Плановый осмотр, боль или дискомфорт, планирование протезирования или ортодонтического лечения, первое обращение к новому стоматологу', 'Routineuntersuchung, Schmerzen oder Beschwerden, Planung von Zahnersatz oder einer kieferorthopädischen Behandlung, erster Besuch bei einem neuen Zahnarzt', 'Rutin kontrol, ağrı veya rahatsızlık, protez veya ortodontik tedavi planlaması, yeni bir diş hekimine ilk başvuru', 'No special preparation is required; it is helpful to bring previous X-rays and a list of medications being taken', 'Posebna priprema nije potrebna; korisno je ponijeti prethodne snimke i spisak lijekova koje uzimate', 'Посебна припрема није потребна; корисно је понијети претходне снимке и списак лијекова које узимате', 'Специальной подготовки не требуется; полезно взять с собой предыдущие снимки и список принимаемых лекарств', 'Keine besondere Vorbereitung erforderlich; es ist hilfreich, vorhandene Röntgenbilder und eine Liste der eingenommenen Medikamente mitzubringen', 'Özel bir hazırlık gerekmez; önceki röntgenleri ve kullanılan ilaçların listesini getirmek faydalıdır', 'Not applicable — this is a diagnostic visit; based on it the dentist will suggest further examination or treatment', 'Nije primjenjivo — riječ je o dijagnostičkom pregledu; na osnovu njega stomatolog će predložiti dalju dijagnostiku ili liječenje', 'Није примјењиво — ријеч је о дијагностичком прегледу; на основу њега стоматолог ће предложити даљу дијагностику или лијечење', 'Не применимо — это диагностический приём; по его итогам стоматолог предложит дальнейшее обследование или лечение', 'Nicht zutreffend — es handelt sich um einen diagnostischen Termin; auf dessen Grundlage schlägt der Zahnarzt weitere Untersuchungen oder eine Behandlung vor', 'Uygulanamaz — bu tanısal bir ziyarettir; sonucuna göre diş hekimi ileri inceleme veya tedavi önerecektir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'periodontal-scaling-root-planing'), 'Deep cleaning below the gumline with smoothing of the root surface for gum disease', 'Duboko čišćenje ispod desni sa izravnavanjem površine korijena kod bolesti desni', 'Дубоко чишћење испод десни са изравнавањем површине коријена код болести десни', 'Глубокая чистка под десной с выравниванием поверхности корня при заболеваниях дёсен', 'Tiefenreinigung unterhalb des Zahnfleischrands mit Glättung der Wurzeloberfläche bei Zahnfleischerkrankungen', 'Diş eti hastalıklarında diş eti altının derinlemesine temizlenmesi ve kök yüzeyinin düzleştirilmesi', 'Removing tartar and plaque from periodontal pockets with hand instruments or ultrasound, followed by root smoothing; under local anesthesia, usually 1-2 visits (half the jaw at a time)', 'Uklanjanje kamenca i naslaga iz parodontalnih džepova ručnim instrumentima ili ultrazvukom uz poliranje korijena; u lokalnoj anesteziji, obično 1-2 posjete (po polovina vilice odjednom)', 'Уклањање каменца и наслага из пародонталних џепова ручним инструментима или ултразвуком уз полирање коријена; у локалној анестезији, обично 1-2 посјете (по половина вилице одједном)', 'Удаление зубного камня и налёта из пародонтальных карманов ручными инструментами или ультразвуком с полировкой корня; под местной анестезией, обычно 1-2 визита (по половине челюсти за раз)', 'Entfernen von Zahnstein und Belag aus den Parodontaltaschen mit Handinstrumenten oder Ultraschall, anschließendes Glätten der Wurzel; unter Lokalanästhesie, in der Regel 1-2 Termine (jeweils eine Kieferhälfte)', 'Periodontal ceplerden diş taşı ve plağın el aletleri veya ultrasonla temizlenmesi ve kök yüzeyinin düzleştirilmesi; lokal anestezi altında, genellikle 1-2 seans (her seferinde çenenin yarısı)', 'Periodontitis, bleeding and inflamed gums, periodontal pockets deeper than 3-4 mm', 'Parodontitis, krvarenje i upala desni, parodontalni džepovi dublji od 3-4 mm', 'Пародонтитис, крварење и упала десни, пародонтални џепови дубљи од 3-4 мм', 'Пародонтит, кровоточивость и воспаление дёсен, пародонтальные карманы глубже 3-4 мм', 'Parodontitis, blutendes und entzündetes Zahnfleisch, Parodontaltaschen tiefer als 3-4 mm', 'Periodontitis, diş etinde kanama ve iltihaplanma, 3-4 mm''den derin periodontal cepler', 'No special preparation is required; inform the dentist about any anticoagulants being taken', 'Posebna priprema nije potrebna; obavijestiti o uzimanju antikoagulansa', 'Посебна припрема није потребна; обавијестити о узимању антикоагуланса', 'Специальной подготовки не требуется; сообщить о приёме антикоагулянтов', 'Keine besondere Vorbereitung erforderlich; über eingenommene Blutgerinnungshemmer informieren', 'Özel bir hazırlık gerekmez; kullanılan kan sulandırıcı ilaçlar hakkında bilgi verilmelidir', 'Tooth sensitivity, mild bleeding, and sore gums in the first few days are an expected reaction; if inflammation does not subside within 1-2 weeks or the pockets do not shrink, a follow-up examination with a periodontist is needed', 'Osjetljivost zuba, blago krvarenje i bolna desni prvih dana su očekivana reakcija; ako se upala ne povuče za 1-2 sedmice ili se džepovi ne smanje, potreban je kontrolni pregled kod parodontologa', 'Осјетљивост зуба, благо крварење и болна десни првих дана су очекивана реакција; ако се упала не повуче за 1-2 седмице или се џепови не смање, потребан је контролни преглед код пародонтолога', 'Чувствительность зубов, лёгкая кровоточивость и болезненность дёсен в первые дни — ожидаемая реакция; если воспаление не спадает через 1-2 недели или карманы не уменьшаются, нужен повторный осмотр у пародонтолога', 'Zahnempfindlichkeit, leichte Blutung und schmerzendes Zahnfleisch in den ersten Tagen sind eine zu erwartende Reaktion; klingt die Entzündung nicht innerhalb von 1-2 Wochen ab oder verkleinern sich die Taschen nicht, ist eine Nachuntersuchung beim Parodontologen erforderlich', 'İlk günlerde diş hassasiyeti, hafif kanama ve diş etinde ağrı beklenen bir tepkidir; iltihap 1-2 hafta içinde gerilemezse veya cepler küçülmezse periodontologla kontrol muayenesi gereklidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'fixed-braces-metal-per-jaw'), 'A fixed orthodontic system of metal brackets and an archwire for one jaw, used to correct the bite and tooth position', 'Fiksni ortodontski aparat od metalnih bravica i žice za jednu vilicu, za ispravljanje zagriza i položaja zuba', 'Фиксни ортодонтски апарат од металних бравица и жице за једну вилицу, за исправљање загриза и положаја зуба', 'Несъёмная ортодонтическая система из металлических брекетов и дуги на одну челюсть для исправления прикуса и положения зубов', 'Eine festsitzende kieferorthopädische Apparatur aus Metallbrackets und einem Bogen für einen Kiefer zur Korrektur von Biss und Zahnstellung', 'Isırma ve diş konumunu düzeltmek için tek bir çene için metal braketler ve teldan oluşan sabit ortodontik sistem', 'Bonding the brackets to the teeth with composite adhesive and placing the archwire; the placement itself takes 1-1.5 hours, followed by monthly visits to adjust the archwire throughout treatment', 'Lijepljenje bravica na zube kompozitnim ljepilom i postavljanje žice; samo postavljanje traje 1-1,5 sat, a zatim slijede mjesečne posjete radi korekcije žice tokom cijelog liječenja', 'Лијепљење бравица на зубе композитним љепилом и постављање жице; само постављање траје 1-1,5 сат, а затим слиједе мјесечне посјете ради корекције жице током цијелог лијечења', 'Фиксация брекетов на зубы композитным клеем и установка дуги; сама установка занимает 1-1.5 часа, далее — ежемесячные визиты для коррекции дуги на протяжении лечения', 'Kleben der Brackets auf die Zähne mit Kompositkleber und Einsetzen des Bogens; das Einsetzen selbst dauert 1-1,5 Stunden, danach folgen monatliche Termine zur Anpassung des Bogens während der gesamten Behandlung', 'Braketlerin kompozit yapıştırıcıyla dişlere yapıştırılması ve telin takılması; takma işlemi 1-1,5 saat sürer, ardından tedavi boyunca telin ayarlanması için aylık ziyaretler yapılır', 'Crowded teeth, malocclusion, gaps between teeth, preparation for prosthetic treatment', 'Zbijenost zuba, nepravilan zagriz, razmaci između zuba, priprema za protetiku', 'Збијеност зуба, неправилан загриз, размаци између зуба, припрема за протетику', 'Скученность зубов, неправильный прикус, промежутки между зубами, подготовка к протезированию', 'Zahnengstand, Fehlbiss, Zahnlücken, Vorbereitung auf Zahnersatz', 'Diş sıkışıklığı, kapanış bozukluğu, dişler arası boşluklar, protez tedavisine hazırlık', 'Oral health should ideally be addressed beforehand — treating cavities and a professional cleaning', 'Poželjna je sanacija usne duplje — liječenje karijesa i profesionalno čišćenje — prije postavljanja', 'Пожељна је санација усне дупље — лијечење каријеса и професионално чишћење — прије постављања', 'Желательна санация полости рта — лечение кариеса и профессиональная чистка — до установки', 'Eine Sanierung der Mundhöhle — Behandlung von Karies und professionelle Zahnreinigung — vor dem Einsetzen ist empfehlenswert', 'Takmadan önce ağız sağlığının düzenlenmesi — çürük tedavisi ve profesyonel temizlik — önerilir', 'Discomfort and tooth soreness when biting in the first few days after placement and after each adjustment are normal; the archwire rubbing against the cheeks or lips, or a bracket coming loose, are reasons to see an orthodontist', 'Nelagodnost i bolna osjetljivost zuba pri zagrizanju prvih dana nakon postavljanja i poslije svake korekcije su normalni; nažuljena obraza ili usne od žice, kao i odlijepljena bravica, razlog su za obraćanje ortodontu', 'Нелагодност и болна осјетљивост зуба при загризању првих дана након постављања и послије сваке корекције су нормални; нажуљена образа или усне од жице, као и одлијепљена бравица, разлог су за обраћање ортодонту', 'Дискомфорт и болезненность зубов при накусывании в первые дни после установки и после каждой коррекции — норма; натирание щёк или губ дугой, а также отклеившийся брекет — повод обратиться к ортодонту', 'Unbehagen und Druckempfindlichkeit der Zähne beim Zubeißen in den ersten Tagen nach dem Einsetzen und nach jeder Anpassung sind normal; wenn der Bogen an Wangen oder Lippen reibt oder sich ein Bracket löst, sollte ein Kieferorthopäde aufgesucht werden', 'Takıldıktan sonraki ilk günlerde ve her ayardan sonra ısırırken hissedilen rahatsızlık ve diş hassasiyeti normaldir; telin yanakları veya dudakları tahriş etmesi ya da bir braketin yerinden çıkması durumunda ortodontiste başvurulmalıdır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'ultrasound-therapy'), 'A physiotherapy procedure in which ultrasound waves act on tissue to relieve pain and reduce inflammation', 'Fizioterapeutska procedura kod koje ultrazvučni talasi djeluju na tkivo radi ublažavanja bola i upale', 'Физиотерапеутска процедура код које ултразвучни таласи дјелују на ткиво ради ублажавања бола и упале', 'Физиотерапевтическая процедура, при которой ультразвуковые волны воздействуют на ткани для снятия боли и воспаления', 'Eine physiotherapeutische Behandlung, bei der Ultraschallwellen auf das Gewebe einwirken, um Schmerzen und Entzündungen zu lindern', 'Ultrason dalgalarının ağrı ve iltihabı azaltmak için dokuya uygulandığı bir fizyoterapi yöntemi', 'The doctor applies gel to the skin and moves a special applicator over the affected area; the session lasts 5–10 minutes', 'Ljekar nanosi gel na kožu i vodi posebnim aplikatorom preko problematične zone; seansa traje 5–10 minuta', 'Љекар наноси гел на кожу и води посебним апликатором преко проблематичне зоне; сеанса траје 5–10 минута', 'Врач наносит гель на кожу и водит специальным аппликатором по проблемной зоне; сеанс длится 5–10 минут', 'Der Arzt trägt Gel auf die Haut auf und führt einen speziellen Applikator über die betroffene Stelle; die Sitzung dauert 5–10 Minuten', 'Hekim cilde jel uygular ve özel bir uygulayıcıyı sorunlu bölge üzerinde gezdirir; seans 5–10 dakika sürer', 'Muscle and joint pain, tendon inflammation, sprains, rehabilitation after injuries', 'Bolovi u mišićima i zglobovima, upala tetiva, uganuća, rehabilitacija poslije povreda', 'Болови у мишићима и зглобовима, упала тетива, уганућа, рехабилитација послије повреда', 'Боли в мышцах и суставах, воспаление сухожилий, растяжения, реабилитация после травм', 'Muskel- und Gelenkschmerzen, Sehnenentzündungen, Verstauchungen, Rehabilitation nach Verletzungen', 'Kas ve eklem ağrıları, tendon iltihabı, burkulmalar, yaralanma sonrası rehabilitasyon', 'No special preparation is required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Es ist keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'This is a treatment, not a diagnostic procedure — the physiotherapist assesses effectiveness and course length based on how symptoms progress; if there is no improvement, a follow-up visit is recommended', 'Ovo je terapijska, a ne dijagnostička procedura — efikasnost i trajanje tretmana procjenjuje fizioterapeut prema toku simptoma; ako nema poboljšanja, treba se ponovo obratiti ljekaru', 'Ово је терапијска, а не дијагностичка процедура — ефикасност и трајање третмана процјењује физиотерапеут према току симптома; ако нема побољшања, треба се поново обратити љекару', 'Это лечебная, а не диагностическая процедура — эффективность и длительность курса оценивает врач-физиотерапевт по динамике симптомов; при отсутствии улучшения стоит обратиться к нему повторно', 'Dies ist eine Behandlung, keine diagnostische Untersuchung — Wirksamkeit und Dauer der Behandlung beurteilt der Physiotherapeut anhand des Symptomverlaufs; bei ausbleibender Besserung wird ein erneuter Termin empfohlen', 'Bu tanısal değil tedavi amaçlı bir işlemdir — etkinliği ve tedavi süresini fizyoterapist semptomların seyrine göre değerlendirir; iyileşme olmazsa hekime tekrar başvurulması önerilir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'laser-therapy'), 'Physiotherapy treatment using low-intensity laser light to relieve pain and speed up tissue healing', 'Fizioterapeutski tretman niskointenzivnim laserskim zračenjem radi ublažavanja bola i ubrzanja zarastanja tkiva', 'Физиотерапеутски третман нискоинтензивним ласерским зрачењем ради ублажавања бола и убрзања зарастања ткива', 'Физиотерапевтическое лечение низкоинтенсивным лазерным излучением для снятия боли и ускорения заживления тканей', 'Physiotherapeutische Behandlung mit niedrig dosiertem Laserlicht zur Schmerzlinderung und Beschleunigung der Gewebeheilung', 'Ağrıyı azaltmak ve doku iyileşmesini hızlandırmak için düşük yoğunluklu lazer ışığı kullanan fizyoterapi yöntemi', 'The doctor or physiotherapist directs a laser applicator at the target area of skin; the procedure is painless and takes 5–15 minutes', 'Ljekar ili fizioterapeut usmjerava laserski aplikator na odgovarajuću zonu kože; procedura je bezbolna i traje 5–15 minuta', 'Љекар или физиотерапеут усмјерава ласерски апликатор на одговарајућу зону коже; процедура је безболна и траје 5–15 минута', 'Врач или физиотерапевт направляет лазерный аппликатор на нужную зону кожи; процедура безболезненна и занимает 5–15 минут', 'Der Arzt oder Physiotherapeut richtet einen Laserapplikator auf die betroffene Hautstelle; der Vorgang ist schmerzlos und dauert 5–15 Minuten', 'Hekim veya fizyoterapist lazer uygulayıcısını ilgili cilt bölgesine yöneltir; işlem ağrısızdır ve 5–15 dakika sürer', 'Joint and muscle pain, inflammatory processes, slow wound healing, rehabilitation after injuries', 'Bolovi u zglobovima i mišićima, upalni procesi, usporeno zarastanje rana, rehabilitacija poslije povreda', 'Болови у зглобовима и мишићима, упални процеси, успорено зарастање рана, рехабилитација послије повреда', 'Боли в суставах и мышцах, воспалительные процессы, замедленное заживление ран, реабилитация после травм', 'Gelenk- und Muskelschmerzen, entzündliche Prozesse, verzögerte Wundheilung, Rehabilitation nach Verletzungen', 'Eklem ve kas ağrıları, iltihabi süreçler, yara iyileşmesinde gecikme, yaralanma sonrası rehabilitasyon', 'No special preparation is required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Es ist keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'If there is no improvement after a course of treatment, see a doctor to reassess the diagnosis and treatment plan', 'Ako poslije niza procedura ne dođe do poboljšanja, treba se obratiti ljekaru radi preciziranja dijagnoze i plana liječenja', 'Ако послије низа процедура не дође до побољшања, треба се обратити љекару ради прецизирања дијагнозе и плана лијечења', 'Если после курса процедур улучшения не наступает, необходимо обратиться к врачу для уточнения диагноза и плана лечения', 'Tritt nach einer Behandlungsserie keine Besserung ein, sollte ein Arzt zur Abklärung der Diagnose und des Behandlungsplans aufgesucht werden', 'Bir dizi seans sonrasında iyileşme görülmezse, tanının ve tedavi planının gözden geçirilmesi için hekime başvurulmalıdır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'shock-wave-therapy'), 'A physiotherapy method that uses acoustic shock waves to treat chronic pain in muscles and tendons', 'Metoda fizioterapije koja koristi akustične udarne talase za liječenje hroničnih bolova u mišićima i tetivama', 'Метода физиотерапије која користи акустичне ударне таласе за лијечење хроничних болова у мишићима и тетивама', 'Метод физиотерапии, использующий акустические ударные волны для лечения хронических болей в мышцах и сухожилиях', 'Ein physiotherapeutisches Verfahren, das akustische Stoßwellen zur Behandlung chronischer Schmerzen in Muskeln und Sehnen einsetzt', 'Kas ve tendonlardaki kronik ağrıları tedavi etmek için akustik şok dalgaları kullanan bir fizyoterapi yöntemi', 'The doctor applies an applicator to the painful area and delivers wave pulses; the sensation can be slightly uncomfortable, and the procedure lasts 10–20 minutes', 'Ljekar prislanja aplikator na bolno mjesto i emituje impulse talasa; osjećaj može biti pomalo neprijatan, procedura traje 10–20 minuta', 'Љекар прислања апликатор на болно мјесто и емитује импулсе таласа; осјећај може бити помало непријатан, процедура траје 10–20 минута', 'Врач прикладывает аппликатор к болезненной зоне и подаёт импульсы волн; ощущения могут быть слегка неприятными, процедура длится 10–20 минут', 'Der Arzt setzt einen Applikator auf die schmerzende Stelle und gibt Wellenimpulse ab; das Gefühl kann leicht unangenehm sein, die Behandlung dauert 10–20 Minuten', 'Hekim ağrılı bölgeye bir uygulayıcı yerleştirir ve dalga darbeleri verir; his hafif rahatsız edici olabilir, işlem 10–20 dakika sürer', 'Heel spur, tendinitis, ligament inflammation, chronic musculoskeletal pain syndromes', 'Peta ostruga, tendinitis, upala ligamenata, hronični bolni sindromi lokomotornog sistema', 'Пета оструга, тендинитис, упала лигамената, хронични болни синдроми локомоторног система', 'Пяточная шпора, тендиниты, воспаление связок, хронические болевые синдромы опорно-двигательного аппарата', 'Fersensporn, Sehnenentzündungen, Bänderentzündungen, chronische Schmerzsyndrome des Bewegungsapparats', 'Topuk dikeni, tendinit, bağ iltihabı, kas-iskelet sisteminin kronik ağrı sendromları', 'No special preparation is required; the doctor may recommend avoiding painkillers before the session', 'Nije potrebna posebna priprema; ljekar može preporučiti da se prije seanse ne uzimaju analgetici', 'Није потребна посебна припрема; љекар може препоручити да се прије сеансе не узимају аналгетици', 'Специальной подготовки не требуется; врач может рекомендовать не принимать обезболивающие перед сеансом', 'Es ist keine besondere Vorbereitung erforderlich; der Arzt kann empfehlen, vor der Sitzung keine Schmerzmittel einzunehmen', 'Özel bir hazırlık gerekmez; hekim seanstan önce ağrı kesici alınmamasını önerebilir', 'If pain persists after several sessions, a follow-up consultation is needed to reconsider the treatment approach', 'Ako bol potraje i nakon nekoliko seansi, potrebna je nova konsultacija sa ljekarom radi izmjene taktike liječenja', 'Ако бол потраје и након неколико сеанси, потребна је нова консултација са љекаром ради измјене тактике лијечења', 'Если боль сохраняется после нескольких сеансов, нужна повторная консультация врача для пересмотра тактики лечения', 'Hält der Schmerz nach mehreren Sitzungen an, ist eine erneute ärztliche Beratung notwendig, um die Behandlungsstrategie zu überdenken', 'Ağrı birkaç seans sonrasında da devam ederse, tedavi yaklaşımının gözden geçirilmesi için hekimle tekrar görüşülmelidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'kinesiotherapy'), 'Therapeutic exercise — a set of exercises to restore mobility, strength and coordination', 'Kineziterapija — skup vježbi za obnavljanje pokretljivosti, snage i koordinacije', 'Кинезитерапија — скуп вјежби за обнављање покретљивости, снаге и координације', 'Лечебная физкультура — комплекс упражнений для восстановления подвижности, силы и координации', 'Bewegungstherapie — ein Übungsprogramm zur Wiederherstellung von Beweglichkeit, Kraft und Koordination', 'Terapötik egzersiz — hareket kabiliyeti, kuvvet ve koordinasyonu yeniden kazandırmaya yönelik egzersiz programı', 'The patient performs exercises under the supervision of an instructor or physiotherapist, individually or in a group; a session lasts 30–60 minutes', 'Pacijent izvodi vježbe pod nadzorom instruktora ili ljekara-fizioterapeuta, individualno ili u grupi; termin traje 30–60 minuta', 'Пацијент изводи вјежбе под надзором инструктора или љекара-физиотерапеута, индивидуално или у групи; термин траје 30–60 минута', 'Пациент выполняет упражнения под контролем инструктора или врача-физиотерапевта, индивидуально или в группе; занятие длится 30–60 минут', 'Der Patient führt die Übungen unter Anleitung eines Trainers oder Physiotherapeuten einzeln oder in der Gruppe durch; eine Einheit dauert 30–60 Minuten', 'Hasta, bir eğitmen veya fizyoterapist gözetiminde bireysel ya da grup halinde egzersizler yapar; seans 30–60 dakika sürer', 'Rehabilitation after injuries and surgery, musculoskeletal conditions, posture problems, chronic back pain', 'Rehabilitacija poslije povreda i operacija, oboljenja lokomotornog sistema, poremećaji držanja tijela, hronični bolovi u leđima', 'Рехабилитација послије повреда и операција, обољења локомоторног система, поремећаји држања тијела, хронични болови у леђима', 'Реабилитация после травм и операций, заболевания опорно-двигательного аппарата, нарушения осанки, хронические боли в спине', 'Rehabilitation nach Verletzungen und Operationen, Erkrankungen des Bewegungsapparats, Haltungsschäden, chronische Rückenschmerzen', 'Yaralanma ve ameliyat sonrası rehabilitasyon, kas-iskelet sistemi hastalıkları, duruş bozuklukları, kronik sırt ağrıları', 'Comfortable clothing and shoes for exercising; no special preparation is required', 'Udobna odjeća i obuća za vježbanje; nije potrebna posebna priprema', 'Удобна одјећа и обућа за вјежбање; није потребна посебна припрема', 'Удобная одежда и обувь для занятий; специальной подготовки не требуется', 'Bequeme Kleidung und Schuhe zum Üben; es ist keine besondere Vorbereitung erforderlich', 'Egzersiz için rahat kıyafet ve ayakkabı; özel bir hazırlık gerekmez', 'If exercises cause increased pain or discomfort, this should be reported to the doctor or instructor so the program can be adjusted', 'Ako vježbe izazivaju pojačan bol ili nelagodu, o tome treba obavijestiti ljekara ili instruktora radi prilagođavanja programa', 'Ако вјежбе изазивају појачан бол или нелагоду, о томе треба обавијестити љекара или инструктора ради прилагођавања програма', 'Если упражнения вызывают усиление боли или дискомфорт, об этом нужно сообщить врачу или инструктору для корректировки программы', 'Verursachen die Übungen verstärkte Schmerzen oder Beschwerden, sollte dies dem Arzt oder Trainer gemeldet werden, damit das Programm angepasst werden kann', 'Egzersizler ağrı veya rahatsızlığı artırıyorsa, programın uyarlanması için bu durum hekime veya eğitmene bildirilmelidir')
